DROP TABLE IF EXISTS `ep_book_questions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `ep_book_questions` (
  `bq_id` int(11) NOT NULL,
  `book_id` int(11) NOT NULL,
  `chapter_id` int(11) DEFAULT NULL,
  `standard` tinyint(4) NOT NULL,
  `subject` varchar(80) NOT NULL,
  `lang` char(2) NOT NULL,
  `page` int(11) NOT NULL,
  `block` varchar(100) DEFAULT '',
  `instruction` varchar(400) DEFAULT '',
  `qtype` varchar(20) NOT NULL,
  `text` text NOT NULL,
  `item_no` int(11) DEFAULT NULL,
  `needs_figure` tinyint(1) DEFAULT 0,
  `page_image` varchar(80) DEFAULT NULL,
  `options_json` text DEFAULT NULL,
  `answer` text DEFAULT NULL,
  `ai_cleaned` tinyint(1) NOT NULL DEFAULT 0,
  `figure_image` varchar(80) DEFAULT NULL,
  `pairs_json` text DEFAULT NULL,
  PRIMARY KEY (`bq_id`),
  KEY `standard` (`standard`,`subject`),
  KEY `chapter_id` (`chapter_id`,`qtype`),
  FULLTEXT KEY `text` (`text`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

