INSERT INTO `ep_book_questions` VALUES (1,1,16188,1,'English','en',18,'','Fill in the blank','fill_blank','The word that starts with the letter ‘b’ is ______.',1,1,'1/017.jpg',NULL,'bat',1,NULL,NULL),(2,1,16188,1,'English','en',18,'','True or False','true_false','The word ‘bus’ starts with the letter ‘b’.',6,1,'1/017.jpg','[\"True\",\"False\"]','0',1,NULL,NULL),(3,1,16188,1,'English','en',18,'','Match the letters to the words','match','Match the first letter to the correct word.',8,1,'1/017.jpg','[\"A: b – ______ | B: c – ______ | C: p – ______ | D: t – ______ | E: a – ______\"]','b – bat, c – cat, p – pen, t – tiger, a – apple',1,NULL,NULL),(4,1,16188,1,'English','en',18,'','Describe the picture','short_answer','Describe what you see in the picture of the word ‘teddy’.',9,1,'1/017.jpg',NULL,'A teddy bear that can be pulled or hugged.',1,NULL,NULL),(6,1,16189,1,'English','en',20,'','Answer the following','fill_blank','Teacher : Can you ______ ? Student : No, I can’t ______',1,0,NULL,NULL,'sing',1,NULL,NULL),(7,1,16191,1,'English','en',24,'','Fill in the blanks with the correct word that starts with the given letter.','fill_blank','The word that starts with /d/ is ______.',1,0,NULL,NULL,'duck',1,NULL,NULL),(8,1,16194,1,'English','en',30,'','Answer the following','fill_blank','I like ______.',1,1,'1/029.jpg',NULL,'carrot',1,NULL,NULL),(9,1,16194,1,'English','en',30,'','Answer the following','one_word','Name a vegetable from the list.',3,1,'1/029.jpg',NULL,'carrot',1,NULL,NULL),(10,1,16195,1,'English','en',32,'','Answer the following','short_answer','Describe the five fingers of the hand.',1,0,NULL,NULL,'The hand has five fingers: thumb, index, middle, ring, and little finger. The thumb can touch the other four fingers, the index finger is used for pointing, the middle finger is the longest, the ring finger is used for rings, and the little finger is the smallest. Each finger has three small bones and helps us touch, hold, and feel things.',1,NULL,NULL),(11,1,16197,1,'