INSERT INTO `ep_book_questions` VALUES (5026,25,16811,5,'EVS Part 2','en',29,'','Answer each question in one sentence','short_answer','(a) What do we call animals which live in water and also on land? (b) Where did the first humans appear?',1,0,NULL,NULL,'(a) Amphibians (b) Africa',1,NULL,NULL),(5027,25,16811,5,'EVS Part 2','en',29,'','Give reasons for the following','reason','The species of dinosaurs, which were enormous in size, suddenly became extinct.',2,0,NULL,NULL,'They were wiped out by a sudden environmental change such as a meteor impact or volcanic eruption.',1,NULL,NULL),(5028,25,16811,5,'EVS Part 2','en',29,'','Give reasons for the following','reason','Mammals are the most evolved animals among vertebrates. In the course of time, a new species is created from the original species.',3,0,NULL,NULL,'Mammals evolved advanced features like warm blood, hair, and live birth, making them highly adapted; over time, natural selection leads to new species.',1,NULL,NULL),(5029,25,16811,5,'EVS Part 2','en',29,'','Fill in the blanks in the concept chart given below','fill_blank','Evolution of animals: Living things → Vertebrates → Animals without a backbone → Worms, Mosquito, Aquatic, Reptiles ______.',4,1,'25/028.jpg',NULL,'Living things → Vertebrates → Animals without a backbone → Worms, Mosquito, Aquatic, Reptiles',1,'25/028_2.jpg',NULL),(5032,25,16812,5,'EVS Part 2','en',34,'','Fill in the blanks.','short_answer','What is heredity?',1,0,NULL,NULL,'The passing of traits from parents to offspring.',1,NULL,NULL),(5035,25,16812,5,'EVS Part 2','en',34,'','Answer each question in one sentence.','short_answer','Who is said to have first made tools like the hand-axe?',2,0,NULL,NULL,'Homo erectus.',1,NULL,NULL),(5042,25,16813,5,'EVS Part 2','en',36,'','Fill in the blanks','fill_blank','The four factors that determine tools are availability of resources, minimal use of time and energy, maximum ______, and skill of handling tools.',1,0,NULL,NULL,'efficiency',1,NULL,NULL),(50