,'1. लिखित साधने लेखी असतात, मौखिक साधने तोंडी पिढ्यान् पिढ्या जतन होतात. 2. नाणी, शिलालेख, वास्तू – या भौतिक साधनांनी त्या काळातील अर्थव्यवस्था, तंत्रज्ञान व संस्कृती समजते. 3. डिजिटल संग्रह, ऑडिओ‑व्हिडिओ रेकॉर्डिंग, मोबाइल अॅप्स व ऑनलाइन डेटाबेस.',1,NULL,NULL),(9296,40,17044,6,'History & Civics','mr',21,'','चित्रतक्‍ता करा','one_sentence','महाराष्ट्रातील \'बारसास्थळांचा\' चित्रतक्‍ता करा',1,1,'40/020.jpg',NULL,NULL,1,NULL,NULL),(9297,40,17044,6,'History & Civics','mr',28,'','योग्य जोड्या जुळवा','match','योग्य जोड्या जुळवा',2,0,NULL,'[\"पुराश्मयुग | मोठे धारदार हत्यार\",\"मध्याश्मयुग | चाकाचा शोध\",\"नवाश्मयुग | शेती तंत्रात प्रगती\",\"ताम्रपाषाणयुग | अग्नीचा शोध\"]','पुराश्मयुग – मोठे धारदार हत्यार; मध्याश्मयुग – चाकाचा शोध; नवाश्मयुग – शेती तंत्रात प्रगती; ताम्रपाषाणयुग – अग्नीचा शोध',1,NULL,'[[\"पुराश्मयुग\",\"मोठे धारदार हत्यार\"],[\"मध्याश्मयुग\",\"चाकाचा शोध\"],[\"नवाश्मयुग\",\"शेती तंत्रात प्रगती\"],[\"ताम्रपाषाणयुग\",\"अग्नीचा शोध\"]]'),(9298,40,17044,6,'History & Civics','mr',28,'','योग्य जोड्या जुळवा','mcq','लिपींचा उगम किंवा विकास झालेला नव्हता तो',3,0,NULL,'[\"A: ताम्रपाषाणयुग\",\"B: अग्नीचा शोध\",\"C: लिपींचा उगम\",\"D: ताम्रपाषाणयुग\"]','C',1,NULL,NULL),(9299,40,17044,6,'History & Civics','mr',28,'','योग्य जोड्या जुळवा','mcq','दायमाबाद या उत्खननस्थळाचा शोध लावणारे भारतीय पुरातत्त्व सर्वेक्षक',4,0,NULL,'[\"A: डॉ. एम. एन. देशपांडे\",\"B: डॉ. ह. धी. सांकलिया\",\"C: डॉ. झेड. डी.\",\"D: डॉ. ह. धी. सांकलिया\"]','A',1,NULL,NULL),(9310,40,17045,6,'History & Civics','mr',38,'','रिकाम्या जागा भरा','fill_blank','हडप्पा संस्कृतीतील महास्नानगृह ______ या ठिकाणी सापडले.',1,1,'40/037.jpg',NULL,'मोहेंजोदडो',1,'40/037_3.jpg',NULL),(9311,40,17045,6,'History & Civics','mr',38,'','रिकाम्या जागा भरा','fill_blank','कालीबंगन ड) मोहेंजोदडो या ठिकाणी ______ सापडले.',2,1,'40/037.jpg',NULL,'महास्नानगृह',1,'40/037_3.jpg',NULL),(9312,40,17045,6,'History & Civics','mr',38,'','रिकाम्या जागा भरा','fill_blank','हडप्पा संस्कृतीतील ______ या शहराच्या',3,1,'40/037.jpg',NULL,'लोथल',1,'40