सोडवलेली उदाहरणे','solve','28 सेमी',2,0,NULL,NULL,'28',1,NULL,NULL),(14633,56,17313,8,'Maths','mr',114,'','सोडवलेली उदाहरणे','solve','5 सेमी',3,0,NULL,NULL,'5',1,NULL,NULL),(14634,56,17313,8,'Maths','mr',114,'','सोडवलेली उदाहरणे','solve','5 सेमी',4,0,NULL,NULL,'5',1,NULL,NULL),(14635,56,17313,8,'Maths','mr',114,'','सोडवलेली उदाहरणे','solve','176 चौसेमी',5,0,NULL,NULL,'176',1,NULL,NULL),(14636,56,17313,8,'Maths','mr',114,'','सोडवलेली उदाहरणे','solve','394.24 चौसेमी',6,0,NULL,NULL,'394.24',1,NULL,NULL),(14637,56,17313,8,'Maths','mr',114,'','सोडवलेली उदाहरणे','solve','12474 चौसेमी',7,0,NULL,NULL,'12474',1,NULL,NULL),(14638,56,17313,8,'Maths','mr',114,'','सोडवलेली उदाहरणे','solve','एका वर्तुळाकार बागेचा व्यास 42 मी आहे. त्या बागेभोवती 3.5 मी रुंदीचा रस्ता आहे, तर त्या ग्स्ता रस्त्याचे क्षेत्रफळ काढा',8,0,NULL,NULL,'बागेचा त्रिज्या = 21 मी. बागेचा क्षेत्रफळ = π×21² ≈ 1385.44 चौमी. रस्त्यासह बाहेरील त्रिज्या = 21+3.5 = 24.5 मी. बाहेरील क्षेत्रफळ = π×24.5² ≈ 1886.66 चौमी. रस्त्याचे क्षेत्रफळ = 1886.66 – 1385.44 ≈ 501.22 चौमी.',1,NULL,NULL),(14639,56,17313,8,'Maths','mr',114,'','सोडवलेली उदाहरणे','explain','एका वर्तुळाचा परीघ 88 सेमी आहे, तर त्या वर्तुळाचे क्षेत्रफळ काढा अनियमित आकाराच्या आकृतीचे अंदाजे क्षेत्रफळ काढणे आलेख कागदाच्या साहाय्याने कोणत्याही बंदिस्त आकृतीचे क्षेत्रफळ काढता येते. दिलेली आकृती किंवा वस्तूचे एखादे पृष्ठ आलेख कागदावर ठेवून त्याच्या कडेने पेन्सिल फिरवा. आलेख कागदावरील आकृतीचे क्षेत्रफळ काढण्यासाठी चौरसांची संख्या कशी मोजायची व क्षेत्रफळ कसे काढायचे ते खालील कृतीवरून समजून घ्या',9,1,'56/113.jpg',NULL,'वर्तुळाचा परीघ 88 सेमी असल्यास त्रिज्या r = 88/(2π) ≈ 14.0 सेमी. क्षेत्रफळ = πr² ≈ 615.75 चौसेमी. अनियमित आकृतीचे क्षेत्रफळ अंदाजे चौरस मोजून काढता येते.',1,'56/113_2.jpg',NULL),(14640,56,17313,8,'Maths','mr',114,'','सोडवलेली उदाहरणे','explain','आकृतीतील ; चौसेमी क्षेत्रफळ असणाऱ्या भागांची संख्या > 0 *, त्यांचे क्षेत्रफळ > 0 चौसेमी अ 10 11 12 13',10,1,'56/113.jpg',NULL,'हे निर्देश अनियमित आकृतीच्या भागांचे क्षेत्रफळ मोजण्यासाठी आलेख कागदावर चौरस मोजण्या