DROP TABLE IF EXISTS `ep_questions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `ep_questions` (
  `question_id` int(11) NOT NULL,
  `chapter_id` int(11) NOT NULL,
  `question_type` varchar(30) NOT NULL,
  `question_number` varchar(10) NOT NULL,
  `marks` int(11) DEFAULT 1,
  `difficulty` tinyint(4) DEFAULT 2,
  `source` varchar(50) DEFAULT NULL,
  `passage` text DEFAULT NULL,
  `markup` text DEFAULT NULL,
  `markup2` text DEFAULT NULL,
  `markup3` text DEFAULT NULL,
  `answer_markup` text DEFAULT NULL,
  `answer_markup2` text DEFAULT NULL,
  `has_image` tinyint(1) DEFAULT 0,
  `has_image2` tinyint(1) DEFAULT 0,
  `has_answer_image` tinyint(1) DEFAULT 0,
  `sub_questions` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`sub_questions`)),
  PRIMARY KEY (`question_id`),
  KEY `idx_pick` (`chapter_id`,`question_type`,`question_number`),
  CONSTRAINT `fk_ep_question_chapter` FOREIGN KEY (`chapter_id`) REFERENCES `ep_chapters` (`chapter_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

