s :  \ni) al_ne            ii) bos_m            iii) cr_el            iv) expe_t \n\nAns. : ----------------------------------------------------------------------------','','','i) alone             ii) bosom            iii) cruel                iv) expert','',0,0,0,NULL),(36876,185,'descriptive','1a',2,2,'Out of Text Book','','Complete the word by using correct letters :  \ni) pr_blem             ii) sea_ch            iii) st_dy            iv) tr_nd\n\nAns. : ----------------------------------------------------------------------------','','','i) problem           ii) search             iii) study             iv) trend','',0,0,0,NULL),(36877,185,'descriptive','1a',2,2,'Out of Text Book','','Complete the word by using correct letters :  \ni) all_w             ii) b_ard           iii) c_ver           iv) e_ual\n\nAns. : ----------------------------------------------------------------------------','','','i) allow           ii) board             iii) cover            iv) equal','',0,0,0,NULL),(36878,186,'descriptive','1a',2,2,'Out of Text Book','','Complete the word by using correct letters :  \ni) ex_ct            ii) he_rt           iii) pa_se            iv) s_ster\n\nAns. : -----------------------------------------------------------------------------','','','i) exact           ii) heart             iii) pause           iv) sister ','',0,0,0,NULL),(36879,186,'descriptive','1a',2,2,'Out of Text Book','','Complete the word by using correct letters :  \ni) al_ud             ii) b_und               iii) co_rt             iv) ent_r\n\nAns. : -----------------------------------------------------------------------------','','','i) aloud             ii) bound             iii) court              iv) enter','',0,0,0,NULL),(36880,186,'descriptive','1a',2,2,'Out of Text Book','','Complete the word by using correct letters :  \ni) any_ne                ii) ca_kle             iii) diz_y           iv) f_und\n\nAns. : -------------------------------------------------------------------