                      ii) -5/-315 = 1/63','',0,0,0,NULL),(38514,548,'descriptive','2',2,2,'Out of Text Book','','Write any three divisions whose fractional form is -2/5.\n\nAns. : -------------------------------------------------------------------------------------\n\n          ------------------------------------------------------------------------------------','','','-4/10, -6/15, -8/20, -10/25, -12/30, -----','',0,0,0,NULL),(38515,548,'descriptive','2',2,2,'Out of Text Book','','Solve: 15 × (-25) × (-4) × (-10)\n\nAns. : -------------------------------------------------------------------------------------\n\n          ------------------------------------------------------------------------------------\n','','','-15000','',0,0,0,NULL),(38516,548,'descriptive','2',2,2,'Out of Text Book','','Solve: -39 × (-15) + (-5) × 39\n\nAns. : -------------------------------------------------------------------------------------\n\n          ------------------------------------------------------------------------------------','','','-39 × (-15) + (-5) × 39 = (-39)[-15 + 5] = (-39) × (-10) = 390','',0,0,0,NULL),(38517,548,'descriptive','2',2,2,'Out of Text Book','','If a = 3, b = -2 and c = -1, verify that: b × c = c × b\n\nAns. : -------------------------------------------------------------------------------------\n\n          ------------------------------------------------------------------------------------\n \n          -------------------------------------------------------------------------------------','','','Here, a = 3, b = -2 and c = -1\nLHS = b × c = (-2) × (-1) = 2\nRHS = c × b = (-1) × (-2) = 2\nLHS = RHS','',0,0,0,NULL),(38518,548,'descriptive','2',2,2,'Out of Text Book','','The product of two integers is -182. If one of the integer is 13, then find the other integer.\n\nAns. : -------------------------------------------------------------------------------------\n\n          ------------------------------------------------------------------------------------\n \n          -------------------------------------------------------------------------------------','','','Let other integer be x\n∴ 13 × x = -182    \n∴ x = -182/13 = -14','',0,0,0,NULL),(38519,548,'descriptive','2',2,2,'Out of Text Book','','Multiply: (-12) × (-11) × (10)\n\nAns. : -------------------------------------------------------------------------','','','1320','',0,0,0,NULL),(38520,548,'descriptive','2',2,2,'Out of Text Book','','Multiply: (-3) × (-6) × (-2) × (-1) \n\nAns. : ----------------------------------------------------------------------------------','','','36','',0,0,0,NULL),(38521,548,'descriptive','2',2,2,'Out of Text Book','','Find the product of 26 × (-48) + (-48) × (-36)\n\nAns. : -------------------------------------------------------------------------------------\n\n          ------------------------------------------------------------------------------------\n \n          -------------------------------------------------------------------------------------','','','26 × (-48) + (-48) × (-36) = (-48)[26 – 36] = (-48)[-10] = 480','',0,0,0,NULL),(38522,548,'descriptive','2',2,2,'Out of Text Book','','Find: (-57) × (-19) + 57\n\nAns. : -------------------------------------------------------------------------------------\n\n          ------------------------------------------------------------------------------------\n \n          -------------------------------------------------------------------------------------','','','(-57) × (-19) + 57 = 57 × [(-1 × (-19) + 1] = 57 × [19 + 1] = 57 × 20 = 1140','',0,0,0,NULL),(38523,548,'descriptive','2',2,2,'Out of Text Book','','Determine the integer whose product with (-1) is a) -22 	b) 37 		c) 0\n\nAns. : -------------------------------------------------------------------------------------\n\n          ------------------------------------------------------------------------------------\n \n          -------------------------------------------------------------------------------------','','','a) (-22) × (-1) = 22\nb) 37 × (-1) = -37\nc) 0 × (-1) = 0','',0,0,0,NULL),(38524,548,'descriptive','2',2,2,'Out of Text Book','','Verify that, a ÷ b ≠ b ÷ a, if a = -15, b = 3.\n\nAns. : -------------------------------------------------------------------------------------\n\n          ------------------------------------------------------------------------------------\n \n          -------------------------------------------------------------------------------------','','','Here, a = -15, b = 3\nLHS = a ÷ b = (-15)/3 = -5\nRHS = b ÷ a = 3/(-15) = -1/5\n∴ LHS ≠ RHS','',0,0,0,NULL),(38525,548,'descriptive','3',3,2,'Out of Text Book','','Write three divisions of integers such that the fractional form of each will be 24/5.\n\nAns. : -------------------------------------------------------------------------------------\n\n          ------------------------------------------------------------------------------------\n \n          -------------------------------------------------------------------------------------','','','24/5, 48/10, 72/15, 96/20, 120/25, -----','',0,0,0,NULL),(38526,548,'descriptive','3',3,2,'Out of Text Book','','Write three divisions of integers such that the fractional form of each will be -5/7.\n\nAns. : -------------------------------------------------------------------------------------\n\n          ------------------------------------------------------------------------------------\n','','','5/7, -10/14, -15/21, -20/28, -25/35, ------','',0,0,0,NULL),(38527,548,'descriptive','3',3,2,'Out of Text Book','','Solve: i) (-98) ÷ 7 		ii) (-8) × (-3) 		iii) (-821) × (-1)\n\nAns. : -------------------------------------------------------------------------------------\n\n          ------------------------------------------------------------------------------------\n \n          -------------------------------------------------------------------------------------','','','i) -14	ii) 24		iii) 821','',0,0,0,NULL),(38528,548,'descriptive','3',3,2,'Out of Text Book','','Solve: i) (-51) ÷ 68 		ii) (-63) × (-7) 	iii) (98) ÷ (-28)\n\nAns. : -------------------------------------------------------------------------------------\n\n          ------------------------------------------------------------------------------------\n \n          -------------------------------------------------------------------------------------','','','i) -51/68 = -3/4    	ii) -63/-7 = 9 	iii) 98/-28 = -7/2','',0,0,0,NULL),(38529,548,'descriptive','3',3,2,'Out of Text Book','','If a = 3, b = -2 and c = -1, verify that: b × (a + c) = b × a + b × c\n\nAns. : -------------------------------------------------------------------------------------\n\n          ------------------------------------------------------------------------------------\n \n          -------------------------------------------------------------------------------------\n\n         -----------------------------------------------------------------------------------------','','','Here, a = 3, b = -2 and c = -1\nLHS = b × (a + c) = (-2) × (3 + (-1)) = (-2) × (3 – 1) = (-2) × 2 = -4\nRHS = b × a + b × c = (-2) × 3 + (-2) × (-1) = -6 + 2 = -4\nLHS = RHS','',0,0,0,NULL),(38530,548,'descriptive','3',3,2,'Out of Text Book','','Simplify: {(-24) ÷ (-6)} + 5\n\nAns. : -------------------------------------------------------------------------------------\n\n          ------------------------------------------------------------------------------------','','','{(-24) ÷ (-6)} + 5 = {4} + 5 = 4 + 5 = 9','',0,0,0,NULL),(38531,548,'descriptive','3',3,2,'Out of Text Book','','Mohan bought 25 candies. He kept 13 candies with him and distributed the remaining equally among his three friends. How many candies did each of his friends get?\n\nAns. : -------------------------------------------------------------------------------------\n\n          ------------------------------------------------------------------------------------\n \n          -------------------------------------------------------------------------------------','','','Total candy = 25\nMohan kept itself = 13 candies \n∴ remaining candies = 25 – 13 = 12\n12 candies equally distributed 3 friends  = 12/3 = 4 candies each friend.','',0,0,0,NULL),(38532,548,'descriptive','3',3,2,'Out of Text Book','','Simplify: (25 × 4) + [(-25) × (-6)]\n\nAns. : -------------------------------------------------------------------------------------\n\n          ------------------------------------------------------------------------------------','','','(25 × 4) + [(-25) × (-6)] = 100 + 150 = 250','',0,0,0,NULL),(38533,548,'descriptive','3',3,2,'Out of Text Book','','Verify: 18 × [7 + (-3)] = [18 × 7] + [18 × (-3)]\n\nAns. : -------------------------------------------------------------------------------------\n\n          ------------------------------------------------------------------------------------\n \n          -------------------------------------------------------------------------------------','','','LHS = 18 × [7 + (-3)] = 18 × [7 – 3] = 18 × 4 = 72\nRHS = [18 × 7] + [18 × (-3)] = 126 – 54 = 72\nLHS = RHS','',0,0,0,NULL),(38534,548,'descriptive','3',3,2,'Out of Text Book','','Find the additive inverse of the number obtained by subtracting -9 from the additive inverse of -23.\n\nAns. : -------------------------------------------------------------------------------------\n\n          ------------------------------------------------------------------------------------\n \n          -------------------------------------------------------------------------------------','','','Additive inverse of -23 is 23\n∴ Required number obtained from = 23 – (-9) = 23 + 9 = 32\nAdditive inverse of 32 is -32.','',0,0,0,NULL),(38535,548,'descriptive','4',4,2,'Out of Text Book','','The fish in the pond below, carry some numbers. Choose any four pairs and carry out four multiplications with those numbers. Now, choose four others pairs and carry out divisions with these numbers.','Ans. : -------------------------------------------------------------------------------------\n\n          ------------------------------------------------------------------------------------\n \n          -------------------------------------------------------------------------------------\n\n        ---------------------------------------------------------------------------------------','','Multiplication :\ni) (-13) × (-27) = 351	ii) (-24) × (9) = -216\niii) (12) × (-8) = -96		iv) (41) × (9) = 369\nDivision :\ni) -8/-28 = 2/7	ii) -27/9 = -3\niii) 9/12 = 3/4	iv) 12/-18 = -2/3 ','',1,0,0,NULL),(38536,548,'descriptive','4',4,2,'Out of Text Book','','Solve: i) 15 × (-6) 		ii) (38) ÷ (-19) 		iii) (105) ÷ (-15) 		iv) 78 ÷ 65\n\nAns. : -------------------------------------------------------------------------------------\n\n          ------------------------------------------------------------------------------------\n \n          -------------------------------------------------------------------------------------','','','i) -90	ii) -2		iii) -7 		iv) 6/5','',0,0,0,NULL),(38537,548,'descriptive','4',4,2,'Out of Text Book','','Verify: (-40) × [136 + (-36)] = (-40 × 136) + [(-40) × (-36)]\n\nAns. : -------------------------------------------------------------------------------------\n\n          ------------------------------------------------------------------------------------\n \n          -------------------------------------------------------------------------------------','','','LHS = (-40) × [136 + (-36)] = (-40) × [136 – 36] = (-40) × 100= -4000\nRHS = (-40 × 136) + [(-40) × (-36)] = -5440 + 1440 = -4000\nLHS = RHS','',0,0,0,NULL),(38538,548,'descriptive','4',4,2,'Out of Text Book','','Solve: i) 26 ÷ {(-13) ÷ 1} 		ii) {(-20) + 5} ÷ {(-5) + 2}\n\nAns. : -------------------------------------------------------------------------------------\n\n          ------------------------------------------------------------------------------------\n \n          -------------------------------------------------------------------------------------','','','i) 26 ÷ {(-13) ÷ 1} = 26 ÷ (-13) = -2\nii) {(-20) + 5} ÷ {(-5) + 2} = {-15} ÷ {-3} = -15 ÷ (-3) = 5\n','',0,0,0,NULL),(38539,548,'descriptive','4',4,2,'Out of Text Book','','Verify: (-21) × [(-4) + (-6)] = [(-21) × (-4)] + [(-21) × (-6)]\n\nAns. : -------------------------------------------------------------------------------------\n\n          ------------------------------------------------------------------------------------\n \n          -------------------------------------------------------------------------------------','','','LHS = (-21) × [(-4) + (-6)] = (-21) × [-4 – 6] = (-21) × (-10) = 210\nRHS = [(-21) × (-4)] + [(-21) × (-6)] = [84] + [126] = 210\nLHS = RHS','',0,0,0,NULL),(38540,548,'descriptive','4',4,2,'Out of Text Book','','Solve: i) 13 ÷ [(-2) + 1] 		ii) [(-36) ÷ 12] ÷ 3\n\nAns. : -------------------------------------------------------------------------------------\n\n          ------------------------------------------------------------------------------------\n \n          -------------------------------------------------------------------------------------','','','i) 13 ÷ [(-2) + 1] = 13 ÷ [-1] = -13\nii) [(-36) ÷ 12] ÷ 3 = [-3] ÷ 3 = -1\n','',0,0,0,NULL),(38541,548,'descriptive','4',4,2,'Out of Text Book','','Solve: i) [(-6) + 5] ÷ [(-2) + 1] 		ii) (-31) ÷ [(-30) + (-1)]\n\nAns. : -------------------------------------------------------------------------------------\n\n          ------------------------------------------------------------------------------------\n \n          -------------------------------------------------------------------------------------','','','i) [(-6) + 5] ÷ [(-2) + 1] = [-1] ÷ [-1] = 1\nii) (-31) ÷ [(-30) + (-1)] = (-31) ÷ [-30 – 1] = (-31) ÷ [-31] = 1\n','',0,0,0,NULL),(38542,548,'descriptive','4',4,2,'Out of Text Book','','Find the value of X in -19 × (4 + (-2)) = -19 × 4 + (-19) × X\n\nAns. : -------------------------------------------------------------------------------------\n\n          ------------------------------------------------------------------------------------\n \n          -------------------------------------------------------------------------------------','','','X = -2','',0,0,0,NULL),(38543,548,'descriptive','4',4,2,'Out of Text Book','','Find the value of x in (10 ÷ 2) + (20 ÷ 4) + (40 ÷ 8) = 60 ÷ x.\n\nAns. : -------------------------------------------------------------------------------------\n\n          ------------------------------------------------------------------------------------\n \n          -------------------------------------------------------------------------------------','','','(10 ÷ 2) + (20 ÷ 4) + (40 ÷ 8) = 60 ÷ x\n= 5 + 5 + 5 = 60 ÷ x\n∴ 15 = 60/x\n∴ x = 60/15 = 4','',0,0,0,NULL),(38544,548,'descriptive','4',4,2,'Out of Text Book','','If a = -4, b = -2, c = 5 then verify that, a × (b + c) = (a × b) + (a × c)\n\nAns. : -------------------------------------------------------------------------------------\n\n          ------------------------------------------------------------------------------------\n \n          -------------------------------------------------------------------------------------','','','Here, a = -4, b = -2, c = 5\nLHS = a × (b + c) = (-4) × [-2 + 5] = (-4) × (3) = -12\nRHS = (a × b) + (a × c) = (-4 × (-2)) + (-4 × 5) = 8 – 20 = -12\n∴ LHS = RHS ','',0,0,0,NULL),(38545,549,'mcq','1a',1,2,'Out of Text Book','','Which of the following is not a prime factor of 2250.\na) 5 		b) 2 		c) 3 		d) 7\n\nAns. : ------------------------------','','','d) 7','',0,0,0,NULL),(38546,549,'mcq','1a',1,2,'Out of Text Book','','The HCF of two consecutive natural numbers is ----\na) 1 		b) 2 		c) 3 		d) 0\n\nAns. : ------------------------------','','','a) 1','',0,0,0,NULL),(38547,549,'mcq','1a',1,2,'Out of Text Book','','The HCF of two consecutive even natural number is ----\na) 1 		b) 2 		c) 3 		d) 0\n\nAns. : ------------------------------','','','b) 2 ','',0,0,0,NULL),(38548,549,'mcq','1a',1,2,'Out of Text Book','','Product of two number