417,826,'mcq','1a',1,2,'Out of Text Book','','Which of the following equality is false?\na) 18 + 4 = 88 ÷ 4 		b) 21 × 3 = 9 × 7 		c) 22 ÷ 2 = 9 + 3 		d) 25 – 7 = 12 + 6\n\nAns. : -----------------------------------','','','c) 22 ÷ 2 = 9 + 3 ','',0,0,0,NULL),(49418,826,'mcq','1a',1,2,'Out of Text Book','','Which of the following expressions has the same answer as the expression : 33 + 22 ÷ 11?\na) 33 ÷ 11 + 22		b) 11 × 5 	c) 33 + 2 × 1 		d) 50 ÷ 10\n\nAns. : -----------------------------------','','','c) 33 + 2 × 1 ','',0,0,0,NULL),(49419,826,'mcq','1a',1,2,'Out of Text Book','','‘The quotient of any number divided by 1 is the number itself’. How is this statement written in short?\na) n ÷ 1 = n		b) n ÷ n = 1 		c) n × n = 1 	d) 1 ÷ n = n\n\nAns. : -----------------------------------','','','a) n ÷ 1 = n','',0,0,0,NULL),(49420,826,'mcq','1a',1,2,'Out of Text Book','','If b × 1/8 = 8 then b = ?\na) 1 			b) 16 		c) 64 		d) 72\n\nAns. : -----------------------------------','','','c) 64 	','',0,0,0,NULL),(49421,826,'mcq','1a',1,2,'Out of Text Book','','9999 + 9999 = x × 18. For what value of x is the given equality true?\na) 1001 		b) 1010		c) 1111		d) 1100\n\nAns. : -----------------------------------','','','c) 1111	','',0,0,0,NULL),(49422,826,'mcq','1a',1,2,'Out of Text Book','','If a = 15 and b = 4, then 8a ÷ b = ?\na) 20 		b) 30 		c) 15 		d) 10\n\nAns. : -----------------------------------','','','b) 30 ','',0,0,0,NULL),(49423,826,'mcq','1a',1,2,'Out of Text Book','','If p = 3, t = 2 then p × p + 2 × p × t + t × t = ?\na) 21 		b) 25 		c) 24 		d) 17\n\nAns. : -----------------------------------','','','b) 25 	','',0,0,0,NULL),(49424,826,'descriptive','1b',1,2,'Text Book','','Name a number which is square as well as triangular.\n\nAns. : ----------------------------------------------------------------------------','','','‘36’ is the number which is square as well as triangular.','',0,0,0,NULL),(49425,826,'descriptive','1b',1,2,'Text Book','','If 4 is the first square n