mo>\n          <mi>P</mi>\n          <mo>[</mo>\n          <msup>\n            <mfenced>\n              <mrow>\n                <mn>1</mn>\n                <mo>+</mo>\n                <mfrac>\n                  <mi>R</mi>\n                  <mn>100</mn>\n                </mfrac>\n              </mrow>\n            </mfenced>\n            <mi>N</mi>\n          </msup>\n          <mo>]</mo>\n        </mrow>\n      </mtd>\n\n      <!-- Option (b) -->\n      <mtd>\n        <mrow>\n          <mtext>b)</mtext>\n          <mo>&nbsp;</mo>\n          <mi>C.I.</mi>\n          <mo>=</mo>\n          <mi>P</mi>\n          <mo>[</mo>\n          <msup>\n            <mfenced>\n              <mrow>\n                <mn>1</mn>\n                <mo>+</mo>\n                <mi>R</mi>\n                <mo>&#x00D7;</mo>\n                <mn>0.01</mn>\n              </mrow>\n            </mfenced>\n            <mi>N</mi>\n          </msup>\n          <mo>]</mo>\n        </mrow>\n      </mtd>\n    </mtr>\n\n    <!-- Second row: c and d -->\n    <mtr>\n      <!-- Option (c) -->\n      <mtd>\n        <mrow>\n          <mtext>c)</mtext>\n          <mo>&nbsp;</mo>\n          <mi>A</mi>\n          <mo>=</mo>\n          <mi>P</mi>\n          <mo>&#x00D7;</mo>\n          <mo>[</mo>\n          <mrow>\n            <msup>\n              <mfenced>\n                <mrow>\n                  <mn>1</mn>\n                  <mo>+</mo>\n                  <mi>r</mi>\n                </mrow>\n              </mfenced>\n              <mi>n</mi>\n            </msup>\n            <mo>-</mo>\n            <mn>1</mn>\n          </mrow>\n          <mo>]</mo>\n        </mrow>\n      </mtd>\n\n      <!-- Option (d) -->\n      <mtd>\n        <mrow>\n          <mtext>d)</mtext>\n          <mo>&nbsp;</mo>\n          <mi>C.I.</mi>\n          <mo>=</mo>\n          <mi>P</mi>\n          <mo>[</mo>\n          <mrow>\n            <msup>\n              <mfenced>\n                <mrow>\n                  <mn>1</mn>\n          