;</mo>\n    <mfrac>\n      <mn>1</mn>\n      <mn>3</mn>\n    </mfrac>\n    <mo>&emsp;</mo>\n    <mtext>b)</mtext>\n    <mo>&nbsp;</mo>\n    <mfrac>\n      <mn>2</mn>\n      <mn>3</mn>\n    </mfrac>\n    <mo>&emsp;</mo>\n    <mtext>c)</mtext>\n    <mo>&nbsp;</mo>\n    <mn>1</mn>\n    <mo>&emsp;</mo>\n    <mtext>d)</mtext>\n    <mo>&nbsp;</mo>\n    <mfrac>\n      <mn>7</mn>\n      <mn>3</mn>\n    </mfrac>\n  </mrow>\n</math>','','','a) 1/3','',0,0,0,NULL),(55525,284,'descriptive','2',2,2,'Out of Text Book','','Solve : <math xmlns=\"http://www.w3.org/1998/Math/MathML\">\n  <mrow>\n    <mfrac>\n      <mi>y</mi>\n      <mn>7</mn>\n    </mfrac>\n    <mo>+</mo>\n    <mfrac>\n      <mrow>\n        <mi>y</mi>\n        <mo>-</mo>\n        <mn>4</mn>\n      </mrow>\n      <mn>3</mn>\n    </mfrac>\n    <mo>=</mo>\n    <mn>2</mn>\n  </mrow>\n</math>','','','3y + 7(y – 4) = 2 × 21\n∴ 3y + 7y – 28 = 42 \n∴ 10y = 42 + 28 = 70\n∴ y = 70/10 = 7 ','',0,0,0,NULL),(55526,284,'descriptive','2',2,2,'Text Book','','Solve : <math xmlns=\"http://www.w3.org/1998/Math/MathML\">\n  <mrow>\n    <mfrac>\n      <mrow>\n        <mi>x</mi>\n        <mo>-</mo>\n        <mn>9</mn>\n      </mrow>\n      <mrow>\n        <mi>x</mi>\n        <mo>-</mo>\n        <mn>5</mn>\n      </mrow>\n    </mfrac>\n    <mo>=</mo>\n    <mfrac>\n      <mn>5</mn>\n      <mn>7</mn>\n    </mfrac>\n  </mrow>\n</math>','','','Simplifying the equation, we get,\n7(x – 9) = 5(x – 5)\n∴ 7x – 63 = 5x – 25 \n∴ 7x – 5x = -25 + 63\n∴ 2x = 38\n∴ x = 38/2 = 19','',0,0,0,NULL),(55527,284,'descriptive','2',2,2,'Text Book','','Solve : <math xmlns=\"http://www.w3.org/1998/Math/MathML\">\n  <mrow>\n    <mfrac>\n      <mrow>\n        <mi>y</mi>\n        <mo>-</mo>\n        <mn>4</mn>\n      </mrow>\n      <mn>3</mn>\n    </mfrac>\n    <mo>+</mo>\n    <mn>3</mn><mi>y</mi>\n    <mo>=</mo>\n    <mn>4</mn>\n  </mrow>\n</math>','','','Simplifying the equation we get,\n∴ y – 4 + 9y = 12 \n∴ 10y = 12 + 4 = 16 \n∴ y = 16/10 = 8/5 \n','',0,0,0,NULL),(55528,284,'descriptive','2',2,2,'Text Book','','Solve : <math xmlns=\"http://www.w3.org/1998/Math/MathML\">\n  <mrow>\n    <mfrac>\n      <mrow>\n        <mo>(</mo>\n        <mi>b</mi>\n        <mo>+</mo>\n        <mo>(</mo>\n        <mi>b</mi>\n        <mo>+</mo>\n        <mn>1</mn>\n        <mo>)</mo>\n        <mo>+</mo>\n        <mo>(</mo>\n        <mi>b</mi>\n        <mo>+</mo>\n        <mn>2</mn>\n        <mo>)</mo>\n        <mo>)</mo>\n      </mrow>\n      <mn>4</mn>\n    </mfrac>\n    <mo>=</mo>\n    <mn>21</mn>\n  </mrow>\n</math>','','','Simplifying the equation we get,\n∴ b + b + 1 + b + 2 = 21 × 4\n∴ 3b + 3 = 84\n∴ 3b = 84 – 3 = 81 \n∴ b = 81/3 = 27\n','',0,0,0,NULL),(55529,284,'descriptive','2',2,2,'Out of Text Book','','Solve : <math xmlns=\"http://www.w3.org/1998/Math/MathML\">\n  <mrow>\n    <mi>x</mi>\n    <mo>=</mo>\n    <mfrac>\n      <mn>4</mn>\n      <mn>5</mn>\n    </mfrac>\n    <mo>(</mo>\n    <mi>x</mi>\n    <mo>+</mo>\n    <mn>10</mn>\n    <mo>)</mo>\n  </mrow>\n</math>','','','Simplifying the given equation we get,\n∴ 5x = 4(x + 10)\n∴ 5x = 4x + 40\n∴ 5x – 4x = 40\n∴ x = 40\n','',0,0,0,NULL),(55530,284,'descriptive','3',3,2,'Out of Text Book','','Check whether x = 4 is a solution of   <math xmlns=\"http://www.w3.org/1998/Math/MathML\">\n  <mrow>\n    <mfrac>\n      <mrow>\n        <mn>2</mn><mi>x</mi>\n        <mo>+</mo>\n        <mn>1</mn>\n      </mrow>\n      <mrow>\n        <mn>3</mn><mi>x</mi>\n        <mo>-</mo>\n        <mn>2</mn>\n      </mrow>\n    </mfrac>\n    <mo>=</mo>\n    <mfrac>\n      <mn>9</mn>\n      <mn>10</mn>\n    </mfrac>\n  </mrow>\n</math>','','','LHS = (2x+ 1)/(3x – 2)\nPut x = 4 \nLHS = [2(4) + 1]/[3(4) – 2] = 9/ 10 = RHS \n∴ LHS = RHS\n∴ x = 4 is the solution of the given equation. \n','',0,0,0,NULL),(55531,284,'descriptive','4',4,2,'Out of Text Book','','Solve : <math xmlns=\"http://www.w3.org/1998/Math/MathML\">\n  <mrow>\n    <mfrac>\n      <mrow>\n        <mn>3</mn><mi>x</mi>\n        <mo>+</mo>\n        <mn>5</mn>\n      </mrow>\n      <mrow>\n        <mn>4</mn><mi>x</mi>\n        <mo>+</mo>\n        <mn>2</mn>\n      </mrow>\n    </mfrac>\n    <mo>=</mo>\n    <mfrac>\n      <mrow>\n        <mn>3</mn><mi>x</mi>\n        <mo>+</mo>\n        <mn>4</mn>\n      </mrow>\n      <mrow>\n        <mn>4</mn><mi>x</mi>\n        <mo>+</mo>\n        <mn>7</mn>\n      </mrow>\n    </mfrac>\n  </mrow>\n</math>','','','Simplifying the given equation, we get, \n(3x + 5)(4x + 7) = (3x + 4)(4x + 2)\n∴ 12x² + 21x + 20x + 35 = 12x² + 6x+ 16x + 8\n∴ 41x + 35 = 22x + 8 \n∴ 41x – 22x = 8 – 35 \n∴ 19x = -27 \n∴ x = -27/19\n','',0,0,0,NULL),(55532,284,'descriptive','4',4,2,'Out of Text Book','','Solve : <math xmlns=\"http://www.w3.org/1998/Math/MathML\">\n  <mrow>\n    <mfrac>\n      <mn>1</mn>\n      <mrow>\n        <mi>x</mi>\n        <mo>+</mo>\n        <mn>5</mn>\n      </mrow>\n    </mfrac>\n    <mo>+</mo>\n    <mfrac>\n      <mn>1</mn>\n      <mrow>\n        <mi>x</mi>\n        <mo>+</mo>\n        <mn>2</mn>\n      </mrow>\n    </mfrac>\n    <mo>=</mo>\n    <mfrac>\n      <mn>2</mn>\n      <mrow>\n        <mi>x</mi>\n        <mo>+</mo>\n        <mn>10</mn>\n      </mrow>\n    </mfrac>\n  </mrow>\n</math>','','','Simplifying the given equation, we get,\n[(x + 2) + (x + 5)]/(x + 5)(x + 2) = 2/x + 10\n∴ 2x + 7/[x² + 7x+ 10] = 2/x + 10\n∴ (2x + 7)(x + 10) = 2(x² + 7x + 10)\n∴ 2x² + 27x + 70 = 2x² + 14x + 20\n∴ 27x – 14x = 20 – 70 \n∴ 13x = -50 \n∴ x = -50/13 \n','',0,0,0,NULL),(55533,284,'descriptive','4',4,2,'Text Book','','Sudhir’s present age is 5 more than three times the age of Viru. Anil’s age is half the age of Sudhir. If the ratio of the sum of Sudhir’s and Viru’s age to three times Anil’s age is 5 : 6, then find Viru’s age.','','','Let Viru’s present age = x years\n∴ Sudhir’s present age = 3x + 5 and Anil’s age = (3x + 5)/2\nNow given that ratio of sum of ages of Sudhir and Viru to three times Anils age = 5 : 6.\n  <math xmlns=\"http://www.w3.org/1998/Math/MathML\">\n    <mrow>\n      <mfrac>\n        <mrow>\n          <mi>x</mi>\n          <mo>+</mo>\n          <mn>3</mn><mi>x</mi>\n          <mo>+</mo>\n          <mn>5</mn>\n        </mrow>\n        <mrow>\n          <mn>3</mn>\n          <mo>&#x2062;</mo>\n          <mo>(</mo>\n          <mfrac>\n            <mrow>\n              <mn>3</mn><mi>x</mi>\n              <mo>+</mo>\n              <mn>5</mn>\n            </mrow>\n            <mn>2</mn>\n          </mfrac>\n          <mo>)</mo>\n        </mrow>\n      </mfrac>\n      <mo>=</mo>\n      <mfrac>\n        <mn>5</mn>\n        <mn>6</mn>\n      </mfrac>\n    </mrow>\n  </math>\n\n  <math xmlns=\"http://www.w3.org/1998/Math/MathML\">\n    <mrow>\n      <mo>&#x2234;</mo>\n      <mfrac>\n        <mrow>\n          <mn>4</mn><mi>x</mi>\n          <mo>+</mo>\n          <mn>5</mn>\n        </mrow>\n        <mrow>\n          <mo>(</mo>\n          <mfrac>\n            <mrow>\n              <mn>9</mn><mi>x</mi>\n              <mo>+</mo>\n              <mn>15</mn>\n            </mrow>\n            <mn>2</mn>\n          </mfrac>\n          <mo>)</mo>\n        </mrow>\n      </mfrac>\n      <mo>=</mo>\n      <mfrac>\n        <mn>5</mn>\n        <mn>6</mn>\n      </mfrac>\n    </mrow>\n  </math>\n\n  <math xmlns=\"http://www.w3.org/1998/Math/MathML\">\n    <mrow>\n      <mo>&#x2234;</mo>\n      <mfrac>\n        <mrow>\n          <mn>2</mn>\n          <mo>(</mo>\n          <mn>4</mn><mi>x</mi>\n          <mo>+</mo>\n          <mn>5</mn>\n          <mo>)</mo>\n        </mrow>\n        <mrow>\n          <mn>9</mn><mi>x</mi>\n          <mo>+</mo>\n          <mn>15</mn>\n        </mrow>\n      </mfrac>\n      <mo>=</mo>\n      <mfrac>\n        <mn>5</mn>\n        <mn>6</mn>\n      </mfrac>\n    </mrow>\n  </math>\n∴ 6 × 2(4x + 5) = 5(9x + 15)\n∴ 48x + 60 = 45x + 75\n∴ 48x – 45x = 75 – 60 \n∴ 3x = 15\n∴ x = 5\n∴ Viru’s present age = 5 years.\n','',0,0,0,NULL),(55534,284,'descriptive','4',4,2,'Text Book','','Ratna has Rs. 200 more than three times the amount Rafik has. If Rs. 300 from the amount with Ratna are given to Rafik, amount with Ratna will be 7/4 times the amount with Rafik. Find the initial amount with Rafik. To find the initial amount, complete the following activity :\nSolution: The amount with Ratna is Rs. 200 more than three times the amount with Rafik. \nLet the initial amount with Rafik be Rs. x\n∴ Ratna has Rs. ▯\n∴ Rs. 300 from Ratna are given to Rafik. Remaining amount with Ratna is ▯.\n∴ Now, Rafik has Rs. ▯. Now, he amounts with Ratna is 7/4 times the amount with Rafik.\n  <math xmlns=\"http://www.w3.org/1998/Math/MathML\">\n    <mrow>\n      <mo>&#x2234;</mo> <!-- ∴ -->\n      <mfrac>\n        <mrow>\n          <mn>3</mn><mi>x</mi>\n          <mo>-</mo>\n          <mn>100</mn>\n        </mrow>\n        <mrow>\n          <mi>x</mi>\n          <mo>+</mo>\n          <mn>300</mn>\n        </mrow>\n      </mfrac>\n      <mo>=</mo>\n      <mo>&#x25A1;</mo>\n      <mo>/</mo>\n      <mo>&#x25A1;</mo>\n    </mrow>\n  </math>\n  <math xmlns=\"http://www.w3.org/1998/Math/MathML\">\n    <mrow>\n      <mo>&#x27F9;</mo> <!-- ⟹ -->\n      <mn>4</mn>\n      <mo>&#x25A1;</mo>\n      <mo>=</mo>\n      <mn>7</mn>\n      <mo>&#x25A1;</mo>\n    </mrow>\n  </math>\n  <math xmlns=\"http://www.w3.org/1998/Math/MathML\">\n    <mrow>\n      <mo>&#x27F9;</mo> <!-- ⟹ -->\n      <mn>12</mn><mi>x</mi>\n      <mo>-</mo>\n      <mn>400</mn>\n      <mo>=</mo>\n      <mn>7</mn><mi>x</mi>\n      <mo>+</mo>\n      <mn>2100</mn>\n    </mrow>\n  </math>\n∴ x = ▯\n∴ Rafik initially has Rs. ▯ with him.','','','Solution: The amount with Ratna is Rs. 200 more than three times the amount with Rafik. \nLet the initial amount with Rafik be Rs. x\n∴ Ratna has Rs. 3x + 200\n∴ Rs. 300 from Ratna are given to Rafik. Remaining amount with Ratna is 3x + 200 – 300 = 3x – 100.\n∴ Now, Rafik has Rs. (x + 300). Now, he amounts with Ratna is 7/4 times the amount with Rafik.\n  <math xmlns=\"http://www.w3.org/1998/Math/MathML\">\n    <mrow>\n      <mo>&#x2234;</mo> <!-- ∴ -->\n      <mfrac>\n        <mrow>\n          <mn>3</mn><mi>x</mi>\n          <mo>-</mo>\n          <mn>100</mn>\n        </mrow>\n        <mrow>\n          <mi>x</mi>\n          <mo>+</mo>\n          <mn>300</mn>\n        </mrow>\n      </mfrac>\n      <mo>=</mo>\n      <mfrac>\n        <mn>7</mn>\n        <mn>4</mn>\n      </mfrac>\n    </mrow>\n  </math>\n  <math xmlns=\"http://www.w3.org/1998/Math/MathML\">\n    <mrow>\n      <mo>&#x27F9;</mo> <!-- ⟹ -->\n      <mn>4</mn>\n      <mo>(</mo>\n      <mn>3</mn><mi>x</mi>\n      <mo>-</mo>\n      <mn>100</mn>\n      <mo>)</mo>\n      <mo>=</mo>\n      <mn>7</mn>\n      <mo>(</mo>\n      <mi>x</mi>\n      <mo>+</mo>\n      <mn>300</mn>\n      <mo>)</mo>\n    </mrow>\n  </math>\n  <math xmlns=\"http://www.w3.org/1998/Math/MathML\">\n    <mrow>\n      <mo>&#x27F9;</mo> <!-- ⟹ -->\n      <mn>12</mn><mi>x</mi>\n      <mo>-</mo>\n      <mn>400</mn>\n      <mo>=</mo>\n      <mn>7</mn><mi>x</mi>\n      <mo>+</mo>\n      <mn>2100</mn>\n    </mrow>\n  </math>\n∴ x = 500\n∴ Rafik initially has Rs. 500 with him.\n','',0,0,0,NULL),(55535,1123,'mcq','1a',1,2,'Out of Text Book','','The area of rhombus = <math xmlns=\"http://www.w3.org/1998/Math/MathML\">\n  <mfrac>\n    <mn>1</mn>\n    <mn>2</mn>\n  </mfrac>\n</math> × Product of lengths of ------ \na) sides           b) diagonal             c) hypotenuse          d) median\n','\nAns. : -------------------------','','','',0,0,0,NULL),(55536,1123,'mcq','1a',1,2,'Out of Text Book','','The formula to find out compound interest is ------ \n<math xmlns=\"http://www.w3.org/1998/Math/MathML\">\n  <mtable columnalign=\"left\">\n    <!-- First row: a and b -->\n    <mtr>\n      <!-- Option (a) -->\n      <mtd>\n        <mrow>\n          <mtext>a)</mtext>\n          <mo>&#xA0;</mo>\n          <mi>A</mi>\n          <mo>=</mo>\n          <mi>P</mi>\n          <mo>&#x2061;</mo>\n          <mo>(</mo>\n          <msup>\n            <mrow>\n              <mn>1</mn>\n              <mo>+</mo>\n              <mfrac>\n                <mi>R</mi>\n                <mn>100</mn>\n              </mfrac>\n            </mrow>\n            <mi>N</mi>\n          </msup>\n          <mo>)</mo>\n        </mrow>\n      </mtd>\n\n      <!-- Option (b) -->\n      <mtd>\n        <mrow>\n          <mtext>b)</mtext>\n          <mo>&#xA0;</mo>\n          <mi>C</mi><mo>.</mo><mi>I</mi><mo>.</mo>\n          <mo>=</mo>\n          <mi>P</mi>\n          <mo>&#x2061;</mo>\n          <mo>(</mo>\n          <msup>\n            <mrow>\n              <mn>1</mn>\n              <mo>+</mo>\n              <mi>R</mi>\n              <mo>&#xD7;</mo>\n              <mn>0.01</mn>\n            </mrow>\n            <mi>N</mi>\n          </msup>\n          <mo>)</mo>\n        </mrow>\n      </mtd>\n    </mtr>\n\n    <!-- Second row: c and d -->\n    <mtr>\n      <!-- Option (c) -->\n      <mtd>\n        <mrow>\n          <mtext>c)</mtext>\n          <mo>&#xA0;</mo>\n          <mi>A</mi>\n          <mo>=</mo>\n          <mi>P</mi>\n          <mo>&#xD7;</mo>\n          <mo>(</mo>\n          <msup>\n            <mrow>\n              <mn>1</mn>\n              <mo>+</mo>\n              <mi>r</mi>\n            </mrow>\n            <mi>n</mi>\n          </msup>\n          <mo>-</mo>\n          <mn>1</mn>\n          <mo>)</mo>\n        </mrow>\n      </mtd>\n\n      <!-- Option (d) -->\n      <mtd>\n        <mrow>\n          <mtext>d)</mtext>\n          <mo>&#xA0;</mo>\n          <mi>C</mi><mo>.</mo><mi>I</mi><mo>.</mo>\n          <mo>=</mo>\n          <mi>P</mi>\n          <mo>&#x2061;</mo>\n          <mo>(</mo>\n          <msup>\n            <mrow>\n              <mn>1</mn>\n              <mo>+</mo>\n              <mi>R</mi>\n              <mo>&#xD7;</mo>\n              <mn>0.01</mn>\n            </mrow>\n            <mi>n</mi>\n          </msup>\n          <mo>-</mo>\n          <mn>1</mn>\n          <mo>)</mo>\n        </mrow>\n      </mtd>\n    </mtr>\n  </mtable>\n</math>','\nAns. : --------------------------------','','','',0,0,0,NULL),(55537,1123,'mcq','1a',1,2,'Out of Text Book','','ΔWXZ ≅ ΔWYZ by ------ test. ','a) Hypotenuse – side          b) ASA             c) SAS                d) AAS\n\n','Ans. : -------------------','','',1,0,0,NULL),(55542,1123,'mcq','1a',1,2,'Out of Text Book','','ΔABC ≅ ΔPQR. If ∠ Q = 60⁰, ∠ R = 40⁰ then ∠ A = -------- \na) 80⁰            b) 40⁰             c) 60⁰              d) None of these \n\nAns. : -----------------\n','','','','',0,0,0,NULL),(55543,1123,'mcq','1a',1,2,'Out of Text Book','','If radius of a circle is 21 cm, then its area is ----- cm². \na) 1386                b) 42              c) 132           d) 441\n\nAns. : -----------------\n','','','','',0,0,0,NULL),(55544,1123,'descriptive','1b',1,2,'Out of Text Book','','Write the formula for total surface area of cylinder. \nAns. : \n\n','','','','',0,0,0,NULL),(55545,1123,'descriptive','1b',1,2,'Out of Text Book','','What is the average of the numbers 1, 2, 3, 4, 5? \nAns. : \n\n\n','','','','',0,0,0,NULL),(55547,1123,'descriptive','1b',1,2,'Out of Text Book','','Find the volume of cuboid with length 7 m, breadth 4.5 m and height 5 m. \nAns. : \n\n\n','','','','',0,0,0,NULL),(55548,1123,'descriptive','1b',1,2,'Out of Text Book','','Find the compound interest if Rs. 1000 are invested for 2 years at the rate of 10 p. c. p. a. \nAns. : \n\n\n','','','','',0,0,0,NULL),(55549,1123,'descriptive','1b',1,2,'Out of Text Book','','What is the average of the numbers 110, 114, 118, 122, 126, 130? \nAns. : \n\n\n','','','','',0,0,0,NULL),(55550,1123,'descriptive','1b',1,2,'Out of Text Book','','In the figure, if l(PM) = 4 cm then l(PQ) = ---','Ans. :\n\n','','','',1,0,0,NULL),(55551,1123,'descriptive','2',2,2,'Out of Text Book','','In each pair of triangles in the following figures, parts bearing identical marks are congruent. State the test and correspondence of vertices by which triangles in each pair are congruent.','\nAns. : ---------------------------------------