--
-- Table structure for table `ep_topic_packs`
--

DROP TABLE IF EXISTS `ep_topic_packs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `ep_topic_packs` (
  `chapter_id` int(11) NOT NULL,
  `book_id` int(11) NOT NULL,
  `standard` tinyint(4) NOT NULL,
  `subject` varchar(80) NOT NULL,
  `lang` char(2) NOT NULL,
  `title` varchar(255) NOT NULL,
  `notes_json` mediumtext NOT NULL,
  `quiz_json` mediumtext NOT NULL,
  `model` varchar(60) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`chapter_id`),
  KEY `book_id` (`book_id`),
  KEY `standard` (`standard`,`subject`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

