tions\":[\"भोजन देणे\",\"भिक्षा मागणे\",\"भिक्षा देणे\",\"भिक्षा व मदत करणे\"],\"answer\":3,\"explain\":\"त्यांची देवपूजा म्हणजे गरीब व अपंग लोकांची सेवा करणे.\"},{\"q\":\"गाडगेबाबांनी दुष्काळात काय केले?\",\"options\":[\"काही केले नाही\",\"अन्न व वस्त्र दिले\",\"फक्त पाणी दिले\",\"फक्त दवाखाने उघडली\"],\"answer\":1,\"explain\":\"दुष्काळात त्यांनी अन्न व वस्त्र दिले.\"},{\"q\":\"गाडगेबाबांनी कोणत्या शाळा उभ्या केल्या?\",\"options\":[\"किंडरगार्टन\",\"प्राथमिक शाळा\",\"माध्यमिक शाळा\",\"सर्व वसतिगृहे\"],\"answer\":3,\"explain\":\"त्यांनी शाळा व वसतिगृहे उभी केली.\"},{\"q\":\"गाडगेबाबांनी जात मानली का?\",\"options\":[\"होय\",\"नाही\",\"कधीकधी\",\"कधीच नाही\"],\"answer\":1,\"explain\":\"त्यांनी जात मानली नाही.\"},{\"q\":\"गाडगेबाबांनी पायांखाली काय घातले?\",\"options\":[\"कपडे\",\"पायवाट\",\"काहीही नाही\",\"पायांखाली घातले नाही\"],\"answer\":2,\"explain\":\"पायांखाली घालून सर्वत्र फिरले.\"},{\"q\":\"गाडगेबाबांनी पळ काढून निघून जाणाऱ्या लोकांना काय केले?\",\"options\":[\"भिक्षा मागितली\",\"भोजन दिले\",\"भिक्षा दिली\",\"भिक्षा व मदत केली\"],\"answer\":3,\"explain\":\"पळ काढून निघून जाणाऱ्या लोकांना मदत केली.\"},{\"q\":\"गाडगेबाबांनी कोणती पद्धत वापरली?\",\"options\":[\"कष्ट करून\",\"फक्त मदत मागून\",\"दोन्ही\",\"काहीही नाही\"],\"answer\":2,\"explain\":\"त्यांनी कष्ट करून व मदत मागून कार्य केले.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16524,12,3,'Marathi','mr','आमचा शब्दकोश 1','[\"कचरा म्हणजे नको असलेले वस्तू ज्यांना आपण टाकतो.\",\"कचरा वेगवेगळा करण्याचे कारण म्हणजे त्याचा प्रवास वेगळा असतो.\",\"कचरा वेगवेगळा केल्याने तो पुन्हा वापरता येतो – कागद, खेळणी, इंधन इत्यादी बनवता येतात.\",\"कचरा डब्यात टाकताना फळांच्या साली, कागदाचे तुकडे, पुठ्ठे, वाळलेले गवत इत्यादी वेगवेगळ्या डब्यांत ठेवायचे.\",\"ओला कचरा आणि सुका कचरा वेगळे ठेवणे महत्त्वाचे आहे.\",\"कचरा सडल्यावर वायू तयार होतो ज्याचा इंधन म्हणून वापर करता येतो.\",\"कचऱ्याचे उत्तम खत बनवता येते ज्याने शेतीला फायदा होतो.\",\"घरात कचरा नीट पाहून त्याची यादी करा आणि तो वेगवेगळ्या डब्यांत ठेवा.\",\"कचरा वर्गीकरण केल्याने पर्यावरण स्वच्छ आणि आरोग्यदायी राहते.\",\"कचरा टाकताना स्वच्छतेची काळजी घ्यावी – हात धुणे, डब्यांची स्वच्छता इत्यादी.\",\"कचरा वर्गीकरण केल्याने पुनर्वापर आणि ऊर्जा बचत होते.\",\"कचरा टाकताना डब्यांची ओळख पटवण्यासाठी रंग किंवा चिन्हे वापरू शकतो.\",\"कचरा टाकताना डब्यांची जागा स्वच्छ ठेवणे आवश्यक आहे.\",\"कचरा वर्गीकरण केल्याने कचरा व्यवस्थापन सोपे होते.\"]','[{\"q\":\"कचरा वेगवेगळा करण्याचं मुख्य कारण काय आहे?\",\"options\":[\"कचरा स्वच्छ होतो\",\"कचरा कमी होतो\",\"कचऱ्याचा प्रवास वेगवेगळा असतो\",\"कचरा सुगंधी होतो\"],\"answer\":2,\"explain\":\"कचऱ्याचा प्रवास वेगवेगळा असतो, म्हणून वेगवेगळा करणे आवश्यक आहे.\"},{\"q\":\"कागदाचे तुकडे, पुठ्ठे आणि वाळलेले गवत यांना काय बनवता येते?\",\"options\":[\"पाण्याचे स्रोत\",\"पुन्हा कागद\",\"इंधन\",\"सुगंधी तेल\"],\"answer\":1,\"explain\":\"या वस्तूंचा पुनर्वापर करून पुन्हा कागद बनवता येतो.\"},{\"q\":\"सडलेल्या कचर्‍यातून कोणता उपयोगी उत्पादन तयार होतो?\",\"options\":[\"सुगंधी तेल\",\"इंधन\",\"खत\",\"पाणी\"],\"answer\":2,\"explain\":\"सडलेल्या कचर्‍यातून खत तयार होऊ शकते.\"},{\"q\":\"कचरा डब्यात भरून ठेवला तर त्याचा प्रवास कसा होतो?\",\"options\":[\"कचरा नष्ट होतो\",\"कचरा जळतो\",\"कचरा नवीन वस्तू बनतो\",\"कचरा नष्ट होतो आणि नंतर जळतो\"],\"answer\":2,\"explain\":\"कचरा नवीन वस्तू बनवण्यासाठी प्रवास करतो.\"},{\"q\":\"कचरा वेगवेगळा ठेवण्यासाठी कोणते डबे वापरले जातात?\",\"options\":[\"सर्वसाधारण डबा\",\"कागदाचा डबा\",\"ओला कचरा डबा आणि सुका कचरा डबा\",\"पाणी डबा\"],\"answer\":2,\"explain\":\"ओला आणि सुका कचरा वेगवेगळे डबे वापरले जातात.\"},{\"q\":\"कचरा वेगवेगळा करण्याने काय फायदा होतो?\",\"options\":[\"कचरा कमी होतो\",\"कचरा सुगंधी होतो\",\"कचरा नष्ट होतो\",\"कचरा पुनर्वापर होतो\"],\"answer\":3,\"explain\":\"कचरा वेगवेगळा केल्याने पुनर्वापर शक्य होतो.\"},{\"q\":\"कचरा वाहून नेण्यासाठी स्थानिक संस्था कोणती व्यवस्था करते?\",\"options\":[\"पाणीपुरवठा\",\"शाळा\",\"घंटागाड्या\",\"सुगंधी तेल उत्पादन\"],\"answer\":2,\"explain\":\"स्थानिक संस्था घंटागाड्यांची व्यवस्था करते.\"},{\"q\":\"कचरा डब्यात ठेवताना ओला आणि सुका कचरा कसा विभाजित करावा?\",\"options\":[\"दोन्ही एकत्र\",\"ओला कचरा सुका कचरा\",\"सुका कचरा ओला कचरा\",\"कचरा न ठेवता\"],\"answer\":1,\"explain\":\"ओला आणि सुका कचरा वेगवेगळे डब्यांत ठेवावा.\"},{\"q\":\"कचरा वेगवेगळा केल्याने कोणता वायू तयार होतो?\",\"options\":[\"सुगंधी वायू\",\"इंधन वायू\",\"पाणी वायू\",\"कचरा वायू\"],\"answer\":1,\"explain\":\"सडलेल्या कचर्‍यातून इंधन म्हणून वापरता येणारा वायू तयार होतो.\"},{\"q\":\"कचरा वेगवेगळा केल्याने शेतात काय उपयोगी ठरते?\",\"options\":[\"पाणी मिळते\",\"इंधन मिळते\",\"खत मिळते\",\"सुगंधी तेल मिळते\"],\"answer\":2,\"explain\":\"सडलेल्या कचर्‍यातून खत तयार होते, जे शेतात उपयोगी ठरते.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16525,12,3,'Marathi','mr','आम्ही गोष्ट पूर्ण करतो 2','[\"- प्रकाशातले तारे म्हणजे आनंदाचे प्रतीक.\",\"- अंधारावर रुसणे म्हणजे दुःख न मानणे.\",\"- हसणे हे जीवनातील सर्वात महत्त्वाचे साधन.\",\"- आनंदाच्या शिखरावर पोहोचण्यासाठी प्रयत्न करणे.\",\"- चिंता न करता जीवन जगणे.\",\"- खुणावणे म्हणजे एखाद्या गोष्टीकडे लक्ष वेधणे.\",\"- मनावर ठसा उमटणे म्हणजे चांगले अनुभव लक्षात ठेवणे.\",\"- हसण्यासाठी जन्म घेतला हे म्हणणे म्हणजे हसणे हे नैसर्गिक आहे.\",\"- भारतभूच्या आदर्शांना अनुसरून वागणे.\",\"- आनंदाचे शिखर म्हणजे खूप खूप आनंद.\",\"- चिंता म्हणजे काळजी.\",\"- अरुण म्हणजे सूर्योदय किंवा नवीन सुरुवात.\",\"- खेळ खेळणे म्हणजे आनंद वाढवणे.\",\"- आनंदाच्या शिखरावरून बसा म्हणजे शांततेने राहणे.\",\"- रडणे हा धर्म नाही, हसणे हे धर्म आहे.\",\"- सर्व मागचा विसरा म्हणजे भूतकाळ विसरणे.\",\"- भविष्याची चिंता न करणे.\",\"- आनंदाचे शिखर म्हणजे आनंदाची उंची.\",\"- हसणे हे जीवनाचे आधार.\",\"- आनंदाचे शिखर म्हणजे सर्वात उंच आनंद.\",\"- आनंदाचे शिखरावरून बसा म्हणजे शांतता.\",\"- आनंदाचे शिखरावरून बसा म्हणजे आनंदी रहा.\",\"- आनंदाचे शिखरावरून बसा म्हणजे आनंदी रहा.\"]','[{\"q\":\"प्रकाशातले तारे काय दर्शवतात?\",\"options\":[\"दुःख\",\"आनंद\",\"चिंता\",\"रडणे\"],\"answer\":1,\"explain\":\"तारे म्हणजे आनंदाचे प्रतीक.\"},{\"q\":\"हसणे हे काय दर्शवते?\",\"options\":[\"धर्म\",\"चिंता\",\"रडणे\",\"आनंद\"],\"answer\":3,\"explain\":\"हसणे हे आनंद दर्शवते.\"},{\"q\":\"खुशाल जाऊन बसा म्हणजे काय?\",\"options\":[\"चिंता करणे\",\"रडणे\",\"आनंदाने राहणे\",\"मागचा विसरणे\"],\"answer\":2,\"explain\":\"खुशाल जाऊन बसा म्हणजे आनंदाने राहणे.\"},{\"q\":\"अंधारावर रुसणे म्हणजे काय?\",\"options\":[\"चिंता करणे\",\"दुःख न मानणे\",\"रडणे\",\"आनंद करणे\"],\"answer\":1,\"explain\":\"अंधारावर रुसणे म्हणजे दुःख न मानणे.\"},{\"q\":\"मनावर ठसा उमटणे म्हणजे काय?\",\"options\":[\"चिंता करणे\",\"आनंद पसरवणे\",\"काळजी करणे\",\"मागचा विसरणे\"],\"answer\":1,\"explain\":\"ठसा उमटणे म्हणजे आनंद पसरवणे.\"},{\"q\":\"अरुण म्हणजे काय?\",\"options\":[\"सूर्योदय\",\"चंद्र\",\"तारा\",\"वारा\"],\"answer\":0,\"explain\":\"अरुण म्हणजे सूर्योदय.\"},{\"q\":\"खेळ खेळणे म्हणजे काय?\",\"options\":[\"चिंता करणे\",\"आनंद वाढवणे\",\"रडणे\",\"मागचा विसरणे\"],\"answer\":1,\"explain\":\"खेळ खेळणे म्हणजे आनंद वाढवणे.\"},{\"q\":\"रडणे हा धर्म नाही, हसणे हे धर्म आहे. याचा अर्थ काय?\",\"options\":[\"रडणे चांगले आहे\",\"हसणे चांगले आहे\",\"दोन्ही चांगले आहेत\",\"दोन्ही वाईट आहेत\"],\"answer\":1,\"explain\":\"हसणे हे चांगले आणि धर्मासारखे आहे.\"},{\"q\":\"सर्व मागचा विसरा म्हणजे काय?\",\"options\":[\"भूतकाळ विसरणे\",\"भविष्याची चिंता करणे\",\"चिंता करणे\",\"रडणे\"],\"answer\":0,\"explain\":\"सर्व मागचा विसरा म्हणजे भूतकाळ विसरणे.\"},{\"q\":\"आनंदाचे शिखर म्हणजे काय?\",\"options\":[\"खूप खूप आनंद\",\"काळजी\",\"चिंता\",\"रडणे\"],\"answer\":0,\"explain\":\"आनंदाचे शिखर म्हणजे खूप खूप आनंद.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16526,12,3,'Marathi','mr','स्वच्छतेचे प्रसारक संत गाडगेबाबा वामन चोरघडे','[\"स्वच्छतेचे प्रसारक संत गाडगेबाबा वामन चोरघडे हे महाराष्ट्रातील प्रसिद्ध संत आहेत.\",\"ते स्वच्छतेचे महत्त्व सांगत आणि लोकांना स्वच्छ राहण्यास प्रोत्साहित करत.\",\"संत गाडगेबाबा यांनी स्वच्छतेबद्दल अनेक गोष्टी सांगितल्या जसे की कचरा न टाकणे, हात धुणे आणि स्वच्छ पाणी पिणे.\",\"त्यांच्या शिकवणीत स्वच्छतेला एक पवित्र कर्तव्य मानले आहे.\",\"संत गाडगेबाबा यांनी स्वच्छतेची साधी पद्धती सांगितल्या जसे की दररोज घर स्वच्छ करणे, कचरा वर्गीकरण करणे आणि शाळा व पब्लीक ठिकाणी स्वच्छता राखणे.\",\"स्वच्छतेने आरोग्य चांगले राहते आणि आजार टाळता येतात.\",\"संत गाडगेबाबा यांनी स्वच्छतेच्या महत्त्वावर भर दिला की स्वच्छता म्हणजे स्वच्छ मन आणि स्वच्छ शरीर.\",\"त्यांच्या शिकवणीत स्वच्छतेला समाजातील एक जबाबदारी मानले आहे.\",\"संत गाडगेबाबा यांच्या स्वच्छतेच्या संदेशाने महाराष्ट्रात स्वच्छता मोहिमांना चालना मिळाली.\",\"संत गाडगेबाबा यांच्या स्वच्छतेच्या शिकवणीने स्वच्छता अभियान ‘स्वच्छ भारत अभियान’ ला प्रेरणा दिली.\",\"संत गाडगेबाबा यांनी स्वच्छतेसाठी साधे नियम सांगितले जसे की कचरा न टाकणे, स्वच्छ पाणी पिणे, हात धुणे आणि स्वच्छता राखणे.\",\"संत गाडगेबाबा यांनी स्वच्छतेच्या महत्त्वावर भर दिला की स्वच्छता म्हणजे स्वच्छ मन आणि स्वच्छ शरीर.\",\"संत गाडगेबाबा यांनी स्वच्छतेच्या महत्त्वावर भर दिला की स्वच्छता म्हणजे स्वच्छ मन आणि स्वच्छ शरीर.\",\"संत गाडगेबाबा यांनी स्वच्छतेच्या महत्त्वावर भर दिला की स्वच्छता म्हणजे स्वच्छ मन आणि स्वच्छ शरीर.\",\"संत गाडगेबाबा यांनी स्वच्छतेच्या महत्त्वावर भर दिला की स्वच्छता म्हणजे स्वच्छ मन आणि स्वच्छ शरीर.\"]','[{\"q\":\"संत गाडगेबाबा यांनी स्वच्छतेबद्दल काय सांगितले?\",\"options\":[\"स्वच्छता म्हणजे स्वच्छ मन आणि शरीर\",\"स्वच्छता फक्त घरातच महत्त्वाची\",\"स्वच्छता फक्त शाळेतच महत्त्वाची\",\"स्वच्छता फक्त स्वच्छ पाण्यानेच होते\"],\"answer\":0,\"explain\":\"संत गाडगेबाबा यांनी स्वच्छतेला एक पवित्र कर्तव्य मानले.\"},{\"q\":\"स्वच्छतेचे महत्त्व काय आहे?\",\"options\":[\"आरोग्य चांगले राहते\",\"फक्त घर स्वच्छ ठेवणे पुरेसे\",\"फक्त कचरा टाकू नये\",\"फक्त हात धुणे महत्त्वाचे\"],\"answer\":0,\"explain\":\"स्वच्छतेने आजार टाळता येतात.\"},{\"q\":\"संत गाडगेबाबा यांनी स्वच्छतेसाठी कोणती साधी पद्धत सांगितली?\",\"options\":[\"कचरा वर्गीकरण\",\"कचरा टाकणे\",\"कचरा न टाकणे\",\"कचरा जाळणे\"],\"answer\":0,\"explain\":\"कचरा वर्गीकरण ही स्वच्छतेची एक साधी पद्धत आहे.\"},{\"q\":\"संत गाडगेबाबा यांच्या शिकवणीत स्वच्छतेला काय मानले आहे?\",\"options\":[\"समाजातील जबाबदारी\",\"फक्त वैयक्तिक गोष्ट\",\"फक्त धार्मिक गोष्ट\",\"फक्त शाळेतील गोष्ट\"],\"answer\":0,\"explain\":\"संत गाडगेबाबा यांनी स्वच्छतेला समाजातील जबाबदारी मानले.\"},{\"q\":\"संत गाडगेबाबा यांच्या स्वच्छतेच्या संदेशाने कोणत्या मोहिमेला प्रेरणा दिली?\",\"options\":[\"स्वच्छ भारत अभियान\",\"स्वच्छता दिवस\",\"संत गाडगेबाबा दिवस\",\"स्वच्छता कार्यक्रम\"],\"answer\":0,\"explain\":\"संत गाडगेबाबा यांच्या शिकवणीने स्वच्छ भारत अभियानाला प्रेरणा दिली.\"},{\"q\":\"संत गाडगेबाबा यांनी स्वच्छतेबद्दल कोणती गोष्ट सांगितली?\",\"options\":[\"कचरा न टाकणे\",\"कचरा जाळणे\",\"कचरा टाकणे\",\"कचरा पाण्यात टाकणे\"],\"answer\":0,\"explain\":\"कचरा न टाकणे हे स्वच्छतेचे एक महत्त्वाचे नियम आहे.\"},{\"q\":\"संत गाडगेबाबा यांनी स्वच्छतेच्या महत्त्वावर काय भर दिला?\",\"options\":[\"स्वच्छ मन आणि शरीर\",\"फक्त स्वच्छ पाणी\",\"फक्त स्वच्छ पेन\",\"फक्त स्वच्छ पाणी आणि पेन\"],\"answer\":0,\"explain\":\"संत गाडगेबाबा यांनी स्वच्छ मन आणि शरीर हे स्वच्छतेचे महत्त्व मानले.\"},{\"q\":\"संत गाडगेबाबा यांनी स्वच्छतेसाठी कोणते साधे नियम सांगितले?\",\"options\":[\"हात धुणे\",\"कचरा न टाकणे\",\"दोन्ही\",\"काहीही नाही\"],\"answer\":2,\"explain\":\"संत गाडगेबाबा यांनी हात धुणे आणि कचरा न टाकणे हे नियम सांगितले.\"},{\"q\":\"संत गाडगेबाबा यांच्या शिकवणीत स्वच्छतेचे महत्त्व काय आहे?\",\"options\":[\"आरोग्य चांगले राहते\",\"फक्त शाळेतच महत्त्वाचे\",\"फक्त घरातच महत्त्वाचे\",\"फक्त पाण्यानेच स्वच्छता होते\"],\"answer\":0,\"explain\":\"संत गाडगेबाबा यांच्या शिकवणीत स्वच्छतेने आरोग्य चांगले राहते.\"},{\"q\":\"संत गाडगेबाबा यांनी स्वच्छतेच्या महत्त्वावर काय भर दिला?\",\"options\":[\"स्वच्छ मन आणि शरीर\",\"फक्त स्वच्छ पाणी\",\"फक्त स्वच्छ पेन\",\"फक्त स्वच्छ पाणी आणि पेन\"],\"answer\":0,\"explain\":\"संत गाडगेबाबा यांनी स्वच्छ मन आणि शरीर हे स्वच्छतेचे महत्त्व मानले.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16527,12,3,'Marathi','mr','प्रकाशातले तारे तुम्ही (कविता) उमाकांत काणेकर ¥','[\"आनंदाच्या शिखरावर बसणे म्हणजे मनात सर्व सुख आणि समाधान वाटणे.\",\"कवितेत मुलांना आनंदाने बसायला सांगितले आहे.\",\"कवी म्हणतो की मुलांच्या मनावर चांगल्या गोष्टींचा ठसा असावा.\",\"मुलांना चिंता न करता खेळायला आणि शिकायला हवे.\",\"आई, बाबा, आजी, आजोबा, मित्र, शिक्षक हे सर्व आपल्या भावनांना स्पर्श करतात.\",\"आईला आपण रुसलो तर ती आपल्याला सांत्वना देते.\",\"बाबा बाहेरगावी गेले असता आपण थोडी चिंता करतो.\",\"ताईने सुंदर पेन दिले असता आपण आनंदी होतो.\",\"शाळेचा अभ्यास पूर्ण झाला नाही असता आपण निराश होतो.\",\"रस्त्यावर पाय घसरून पडलात असता आपण घाबरतो.\",\"वर्गाने खेळ जिंकलात असता आपण आनंदी होतो.\",\"गुंता झालेली दोरी सोडवण्यासाठी धीर आणि प्रयत्न आवश्यक आहेत.\",\"शिखरावर आणि आकाशात हे शब्द \'उंच\' आणि \'उच्च\' दर्शवतात.\",\"अंधारावर आणि पाऊसधारावर शब्द \'गडद\' आणि \'पाऊस\' दर्शवतात.\",\"बसा आणि गुंता या शब्दांमध्ये समान अक्षर \'स\' आहे.\",\"शब्द तयार करताना अक्षरांची क्रमवारी बदलून नवीन शब्द बनवता येतात.\",\"सर्व शब्द वाचून लिहा: कार्य, धैर्य, सूर्य, शौर्य, नर्मदा, पर्यंत, पर्यावरण, सर्व, धर्म, आदर्श.\",\"शब्द तयार करताना \'भार\', \'भात\', \'तर\' हे उदाहरणे आहेत.\",\"थोर व्यक्तींची छायाचित्रे पाहून त्यांच्या कार्याबद्दल जाणून घ्या.\",\"शब्द तयार करताना अक्षरांची जोडणी करून नवीन अर्थ शोधा.\",\"गुंता सोडवताना दोरीची लांबी आणि ताण लक्षात घ्या.\",\"शब्दांतील समान अक्षर शोधून कविता अधिक समजून घ्या.\",\"मुलांना आनंदाने बसायला सांगणे हे कवीचे उद्दिष्ट आहे.\",\"मुलांच्या मनावर चांगल्या गोष्टींचा ठसा असावा हे कवीचे मत आहे.\"]','[{\"q\":\"आनंदाच्या शिखरावर बसणे म्हणजे काय?\",\"options\":[\"सुख आणि समाधान वाटणे\",\"दुःख वाटणे\",\"चिंता वाटणे\",\"उदास होणे\"],\"answer\":0,\"explain\":\"शिखरावर बसणे म्हणजे मनात सर्व सुख आणि समाधान वाटणे.\"},{\"q\":\"कवीने मुलांना कोठे बसायला सांगितले आहे?\",\"options\":[\"शाळेत\",\"घरात\",\"बाहेर\",\"कुठेही नाही\"],\"answer\":0,\"explain\":\"कवीने मुलांना शाळेत बसायला सांगितले आहे.\"},{\"q\":\"मुलांच्या मनावर कशाचा ठसा असावा?\",\"options\":[\"चांगल्या गोष्टींचा\",\"वाईट गोष्टींचा\",\"काहीच नाही\",\"अंधाराचा\"],\"answer\":0,\"explain\":\"मुलांच्या मनावर चांगल्या गोष्टींचा ठसा असावा.\"},{\"q\":\"बाबा बाहेरगावी गेले असता काय वाटते?\",\"options\":[\"चिंता वाटते\",\"आनंद वाटतो\",\"उदास वाटते\",\"काहीच वाटत नाही\"],\"answer\":0,\"explain\":\"बाबा बाहेरगावी गेले असता चिंता वाटते.\"},{\"q\":\"ताईने सुंदर पेन दिले असता काय वाटते?\",\"opt