 दाखवली.\",\"पुरंदरचा वेढा आणि तह हे मराठ्यांच्या स्वराज्याच्या इतिहासात महत्त्वाचे आहेत.\",\"मुरारबाजीने दिलेरखानाला दाखवले की तो मुघलांना पराभूत करू शकतो.\",\"शिवरायांनी मुघलांना काही किल्ले आणि मुलूख दिले.\",\"पुरंदरचा तह मुघलांना पराभव मान्य करण्यास भाग पाडला.\",\"मुरारबाजीचे शौर्य आणि दिलेरखानाची लढाई मराठ्यांच्या आत्मविश्वासाला बळकटी दिली.\",\"पुरंदरचा वेढा आणि तह हे मराठ्यांच्या स्वराज्याच्या इतिहासात एक महत्त्वाचे पाऊल होते.\"]','[{\"q\":\"पुरंदरचा तह कोणत्या वर्षी झाला?\",\"options\":[\"१६५५\",\"१६६५\",\"१६७५\",\"१६८५\"],\"answer\":1,\"explain\":\"पुरंदरचा तह १६६५ साली झाला.\"},{\"q\":\"पुरंदरचा किल्लेदार कोण होता?\",\"options\":[\"मुरारबाजी\",\"जयसिंग\",\"दिलेरखान\",\"अंबारी\"],\"answer\":0,\"explain\":\"मुरारबाजी हा पुरंदरचा किल्लेदार होता.\"},{\"q\":\"मुरारबाजीने दिलेरखानाला काय सांगितले?\",\"options\":[\"शिवरायांची माणसे आहेत\",\"मुघलांना पराभूत करेन\",\"मुरारबाजी नाही\",\"मुरारबाजी नाही\"],\"answer\":0,\"explain\":\"मुरारबाजीने दिलेरखानाला सांगितले की तो शिवरायांची माणसे आहेत.\"},{\"q\":\"मुरारबाजीचे शौर्य पाहून दिलेरखानाने काय केले?\",\"options\":[\"त्याला मारले\",\"त्याला आव्हान दिले\",\"त्याला दिलेरखानाला दिले\",\"त्याला दिलेरखानाला दिले\"],\"answer\":1,\"explain\":\"मुरारबाजीचे शौर्य पाहून दिलेरखानाने त्याला आव्हान दिले.\"},{\"q\":\"पुरंदरच्या तहात मुघलांना काय दिले?\",\"options\":[\"काही किल्ले\",\"काही मुलूख\",\"दोन्ही\",\"काहीही नाही\"],\"answer\":2,\"explain\":\"पुरंदरच्या तहात मुघलांना काही किल्ले आणि मुलूख दिले.\"},{\"q\":\"मुरारबाजीने दिलेरखानाला कोणते उत्तर दिले?\",\"options\":[\"शिवरायांची निष्ठा दाखवली\",\"मुघलांना पराभूत केले\",\"मुरारबाजी नाही\",\"मुरारबाजी नाही\"],\"answer\":0,\"explain\":\"मुरारबाजीने दिलेरखानाला शिवरायांची निष्ठा दाखवली.\"},{\"q\":\"पुरंदरचा वेढा कोणाने घातला?\",\"options\":[\"मुरारबाजी\",\"जयसिंग\",\"दिलेरखान\",\"अंबारी\"],\"answer\":2,\"explain\":\"पुरंदरचा वेढा दिलेरखानाने घातला.\"},{\"q\":\"मुरारबाजीने दिलेरखानाला काय सांगितले?\",\"options\":[\"मुरारबाजी नाही\",\"मुरारबाजी नाही\",\"मुरारबाजी नाही\",\"मुरारबाजी नाही\"],\"answer\":0,\"explain\":\"मुरारबाजीने दिलेरखानाला सांगितले की तो शिवरायांची माणसे आहेत.\"},{\"q\":\"पुरंदरचा तह कोणत्या कारणाने झाला?\",\"options\":[\"मुरारबाजीच्या शौर्यामुळे\",\"मुरारबाजीच्या पराभवामुळे\",\"मुरारबाजीच्या पराभवामुळे\",\"मुरारबाजीच्या पराभवामुळे\"],\"answer\":0,\"explain\":\"पुरंदरचा तह मुरारबाजीच्या शौर्यामुळे झाला.\"},{\"q\":\"मुरारबाजीने दिलेरखानाला दिलेले उत्तर काय होते?\",\"options\":[\"शिवरायांची निष्ठा\",\"मुरारबाजी नाही\",\"मुरारबाजी नाही\",\"मुरारबाजी नाही\"],\"answer\":0,\"explain\":\"मुरारबाजीने दिलेरखानाला शिवरायांची निष्ठा दाखवली.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16643,18,4,'EVS Part 2','mr','बादशाहाच्या हातावर तुरी दिल्या','[\"बादशाहाच्या हातावर तुरी दिल्या या गोष्टीत शिवाजी महाराजांनी आणि संभाजीराजांनी आणि इतर मराठा सरदारांनी बादशाहाच्या दरबारात घुसून तुरी दिली.\",\"बादशाहाचा पन्नासावा वाढदिवस होता, ज्यावेळी आणिंगजेब बादशाहाने आग्र्‍हाला जाण्याची तयारी केली.\",\"शिवरायांनी स्वराज्याचा कारभार बादशाहाच्या दरबारात सोपवला आणि आपल्या सरदारांना मागील रांगेत उभे केले.\",\"शिवरायांनी बादशाहाच्या दरबारात तुरी दिली, ज्यामुळे बादशाहाला अपमान वाटला.\",\"शिवरायांनी बादशाहाच्या कैदेतून सुटण्यासाठी विविध युक्त्या वापरल्या, जसे की सुरक्षित ठिकाणी ठेवणे आणि फसवणूक करणे.\",\"बादशाहाच्या हातावर तुरी दिल्यानंतर शिवरायांनी बादशाहाला अपमानित केले आणि त्याला पळवून नेले.\",\"या घटनेमुळे मराठा सैन्याला आत्मविश्वास मिळाला आणि बादशाहाच्या शक्तीला धक्का बसला.\",\"बादशाहाच्या हातावर तुरी दिली ही घटना १६६६ मध्ये घडली.\",\"शिवरायांनी बादशाहाच्या दरबारात तुरी दिली तेव्हा बादशाहाने रागाने प्रतिक्रिया दिली.\",\"शिवरायांनी बादशाहाच्या कैदेतून सुटण्यासाठी विविध युक्त्या वापरल्या, जसे की सुरक्षित ठिकाणी ठेवणे आणि फसवणूक करणे.\",\"शिवरायांनी बादशाहाच्या दरबारात तुरी दिली, ज्यामुळे बादशाहाला अपमान वाटला.\",\"शिवरायांनी बादशाहाच्या कैदेतून सुटण्यासाठी विविध युक्त्या वापरल्या, जसे की सुरक्षित ठिकाणी ठेवणे आणि फसवणूक करणे.\",\"बादशाहाच्या हातावर तुरी दिली ही घटना मराठा इतिहासात महत्त्वाची मानली जाते.\",\"शिवरायांनी बादशाहाच्या दरबारात तुरी दिली तेव्हा बादशाहाने रागाने प्रतिक्रिया दिली.\",\"शिवरायांनी बादशाहाच्या कैदेतून सुटण्यासाठी विविध युक्त्या वापरल्या, जसे की सुरक्षित ठिकाणी ठेवणे आणि फसवणूक करणे.\"]','[{\"q\":\"बादशाहाचा पन्नासावा वाढदिवस कोणत्या वर्षी होता?\",\"options\":[\"1656\",\"1666\",\"1676\",\"1686\"],\"answer\":1,\"explain\":\"बादशाहाचा पन्नासावा वाढदिवस १६६६ मध्ये होता.\"},{\"q\":\"शिवरायांनी स्वराज्याचा कारभार कोणाच्या हाती सोपवला?\",\"options\":[\"बादशाहाला\",\"शिवरायांना\",\"सर्व सरदारांना\",\"सल्लागारांना\"],\"answer\":0,\"explain\":\"शिवरायांनी स्वराज्याचा कारभार बादशाहाच्या दरबारात सोपवला.\"},{\"q\":\"बादशाहाच्या दरबारात तुरी दिल्यानंतर काय झाले?\",\"options\":[\"बादशाहाने राग दाखवला\",\"बादशाहाने शांत राहिला\",\"बादशाहाने शिवरायांना माफ केले\",\"बादशाहाने शिवरायांना दंड दिला\"],\"answer\":0,\"explain\":\"बादशाहाला अपमान वाटला आणि रागाने प्रतिक्रिया दिली.\"},{\"q\":\"शिवरायांनी बादशाहाच्या कैदेतून सुटण्यासाठी कोणती युक्ती वापरली?\",\"options\":[\"सुरक्षित ठिकाणी ठेवणे\",\"मदारीसह पळणे\",\"सर्व सरदारांना बोलावणे\",\"बादशाहाला फसवणे\"],\"answer\":0,\"explain\":\"सुरक्षित ठिकाणी ठेवणे ही युक्ती होती.\"},{\"q\":\"बादशाहाच्या हातावर तुरी दिली ही घटना कोणत्या वर्षी घडली?\",\"options\":[\"1656\",\"1666\",\"1676\",\"1686\"],\"answer\":1,\"explain\":\"ही घटना १६६६ मध्ये घडली.\"},{\"q\":\"शिवरायांनी बादशाहाच्या दरबारात तुरी दिली तेव्हा बादशाहाने काय प्रतिक्रिया दिली?\",\"options\":[\"रागाने\",\"शांततेने\",\"आनंदाने\",\"भयाने\"],\"answer\":0,\"explain\":\"बादशाहाने रागाने प्रतिक्रिया दिली.\"},{\"q\":\"शिवरायांनी बादशाहाच्या कैदेतून सुटण्यासाठी कोणत्या ठिकाणी ठेवले?\",\"options\":[\"झाशीत\",\"मथुरेत\",\"दिल्ली\",\"आग्रा\"],\"answer\":1,\"explain\":\"मथुरेत सुरक्षित ठिकाणी ठेवले.\"},{\"q\":\"बादशाहाच्या हातावर तुरी दिल्यानंतर शिवरायांना काय वाटले?\",\"options\":[\"अपमान वाटला\",\"आनंद वाटला\",\"भय वाटले\",\"उदास वाटले\"],\"answer\":0,\"explain\":\"बादशाहाला अपमान वाटला.\"},{\"q\":\"बादशाहाच्या दरबारात तुरी दिल्यानंतर शिवरायांनी काय केले?\",\"options\":[\"बादशाहाला पळवून नेले\",\"बादशाहाला माफ केले\",\"बादशाहाला दंड दिला\",\"बादशाहाला बोलावले\"],\"answer\":0,\"explain\":\"बादशाहाला पळवून नेले.\"},{\"q\":\"शिवरायांनी बादशाहाच्या कैदेतून सुटण्यासाठी कोणती युक्ती वापरली?\",\"options\":[\"सुरक्षित ठिकाणी ठेवणे\",\"बादशाहाला फसवणे\",\"सर्व सरदारांना बोलावणे\",\"मदारीसह पळणे\"],\"answer\":0,\"explain\":\"सुरक्षित ठिकाणी ठेवणे ही युक्ती होती.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16644,18,4,'EVS Part 2','mr','गड आला, पण सिंह गेला','[\"गड म्हणजे किल्ला, ज्याला रक्षण आणि आक्रमण दोन्ही करता येते.\",\"गड आला पण सिंह गेला या कथेत तानाजी आणि सूर्याजी यांनी कोंढाणा किल्ला जिंकला.\",\"कोंढाणा किल्ला मुघलांच्या ताब्यात होता, परंतु शिवरायांनी तो परत घेतला.\",\"शिवरायांनी कोंढाणा घेण्यासाठी योजना आखली आणि तानाजीने चढाई केली.\",\"तानाजीने किल्ल्यावर चढताना उभ्या दगडावरून उडी मारली आणि शत्रूला पराभूत केले.\",\"सूर्याजीने तानाजीच्या मदतीने किल्ल्याचा दरवाजा उघडला.\",\"गड जिंकताना शत्रूच्या मावळ्यांना पराभूत केले.\",\"साहस आणि धैर्य हे या कथेत महत्त्वाचे गुण आहेत.\",\"किल्ल्याचे दरवाजे दोन असतात – कल्याण दरवाजा आणि दुसरा दरवाजा.\",\"गडात शत्रूची तलवार आणि ढाल यांची लढाई झाली.\",\"साहसिक कथा वाचताना आपण धैर्य आणि योजना करण्याचे महत्त्व समजतो.\",\"गड जिंकण्यासाठी शत्रूच्या कमकुवत बाजू शोधणे आवश्यक असते.\",\"सूर्याजी आणि तानाजी यांनी एकत्र काम करून किल्ला जिंकला.\",\"किल्ला जिंकताना शत्रूच्या मावळ्यांना चुकवून आत जाणे महत्त्वाचे असते.\",\"गड जिंकताना शत्रूच्या तलवारींचा सामना करावा लागतो.\",\"गड जिंकताना शत्रूच्या धैर्याला पराभूत करणे आवश्यक असते.\"]','[{\"q\":\"गड आला, पण सिंह गेला या कथेत तानाजी कोणत्या किल्ल्याला जिंकण्यासाठी गेला?\",\"options\":[\"महाराज\",\"कोंढाणा\",\"सुरजगड\",\"रायगड\"],\"answer\":1,\"explain\":\"तानाजी कोंढाणा किल्ला जिंकण्यासाठी गेला.\"},{\"q\":\"कथा अनुसार, तानाजीला कोंढाणा किल्ला जिंकण्यासाठी कोणाने मदत मागितली?\",\"options\":[\"जिजामाता\",\"शिवराय\",\"रायबाचे पती\",\"सूर्याजी\"],\"answer\":0,\"explain\":\"जिजामाता तानाजीला मदत मागितली.\"},{\"q\":\"गडाच्या दरवाज्यांपैकी एकाचे नाव काय होते?\",\"options\":[\"कल्याण दरवाजा\",\"सुरज दरवाजा\",