wer\":0,\"explain\":\"किलकिल आवाज म्हणजे गाणे.\"},{\"q\":\"शेवा झाडाच्या फुलांमध्ये पक्ष्यांची ओळख कशी झाली?\",\"options\":[\"गाण्याने\",\"नृत्याने\",\"मध पिऊन\",\"फुलांभोवती नाचून\"],\"answer\":3,\"explain\":\"लेखिकेने फुलांभोवती नाचणाऱ्या मधमाश्या पाहून ओळख केली.\"},{\"q\":\"शेवा झाडाच्या फुलांमध्ये पक्ष्यांना काय दिले?\",\"options\":[\"आनंद\",\"ज्ञान\",\"दोन्ही\",\"फक्त ज्ञान\"],\"answer\":2,\"explain\":\"पक्ष्यांना आनंद आणि ज्ञान दोन्ही दिले.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16711,20,4,'Marathi','mr','झुळूक मी व्हावे (कविता) दा. अ. कारे','[\"झुळूक म्हणजे हलका वारा जो फुलांना आणि पानांना हलवतो.\",\"कवितेत कवी झुळुकीला स्वतःसारखे व्हावे असे म्हणतो.\",\"कवी म्हणतो की झुळूक मनाला जिथे जाईल तिथे मोकळेपणाने जावी.\",\"झुळूक नदीच्या काठी, बाजारी, वाड्याच्या पाठी इथे तिथे फिरते.\",\"कवी झुळुकीला अंगुलीने हलकेच स्पर्श करायला सांगतो.\",\"झुळूक फुलांना फुलवते आणि सुगंध पसरवते.\",\"कवी म्हणतो की झुळूक दिशादिशांतून सुगंध उधळते.\",\"झुळूक गाण्याच्या तानासारखी गोड आणि पसरते.\",\"शेताला हिरव्यागार शेत किंवा निळ्या नदीच्या काठावर जणू पसरलेले गवत म्हणतो.\",\"कवितेतील शब्दार्थ: सानुली=लहानशी, स्वैर=मोकळेपणा, राईत=दाट झाडीत, कानोसा घेणे=कान देऊन ऐकणे, पसार होणे=निळे जाणे.\",\"कवितेतील ओळींचे अर्थ: जिथे मन जाईल तिथे मोकळेपणाने जावे, सुगंध उधळत जावे, झऱ्याचे गाणे सर्वत्र पसरावे, हिरव्यागार शेत किंवा निळ्या नदीच्या काठावर जावे.\",\"कवितेतील रिकाम्या जागा भरण्यासाठी शब्द: पसार, झुकली, कानोसा घेतला, भरारी घेतली, पक्षी आकाशात उडाला.\",\"झाडांच्या पानांचे निरीक्षण करून त्यांच्या वैशिष्ट्ये लिहा: केळी, नारळ, पिंपळ, तुळस, बेल, आवळा, कडुनिंब.\"]','[{\"q\":\"कवितेत कवीला काय व्हावेसे वाटते?\",\"options\":[\"झुळूक\",\"पक्षी\",\"नदी\",\"शेत\"],\"answer\":0,\"explain\":\"कवी झुळुकीसारखा व्हावा असे म्हणतो.\"},{\"q\":\"झुळूक कुठे फिरते?\",\"options\":[\"फक्त बाजारी\",\"फक्त नदीच्या काठी\",\"दोन्ही ठिकाणी\",\"कधीही नाही\"],\"answer\":2,\"explain\":\"कवितेत बाजारी आणि नदीच्या काठी दोन्ही ठिकाणी झुळूक फिरते.\"},{\"q\":\"कवी झुळुकीला कसे स्पर्श करायला सांगतो?\",\"options\":[\"जोरात\",\"हलके\",\"उंच\",\"खाली\"],\"answer\":1,\"explain\":\"कवितेत अंगुलीने हलके स्पर्श करायला सांगतो.\"},{\"q\":\"झुळूक काय उधळते?\",\"options\":[\"पाणी\",\"सुगंध\",\"आकाश\",\"शेत\"],\"answer\":1,\"explain\":\"कवितेत सुगंध उधळतो.\"},{\"q\":\"झुळुकीचे गाणे कसे आहे?\",\"options\":[\"जोराचे\",\"गोड\",\"कडू\",\"मंद\"],\"answer\":1,\"explain\":\"गाणे गोड आणि पसरते.\"},{\"q\":\"झुळुकीच्या ओळींमध्ये कोणता शब्द वापरला नाही?\",\"options\":[\"सानुली\",\"स्वैर\",\"राईत\",\"कडू\"],\"answer\":3,\"explain\":\"कडू शब्द नाही.\"},{\"q\":\"कवितेतील रिकाम्या जागेत कोणता शब्द बसतो?\",\"options\":[\"पसार\",\"झुकली\",\"कानोसा घेतला\",\"भरारी घेतली\"],\"answer\":0,\"explain\":\"पहिल्या रिकाम्या जागेत \'पसार\' बसतो.\"},{\"q\":\"झुळुकीच्या ओळींमध्ये कोणता अर्थ दिला आहे?\",\"options\":[\"मन जिथे जाईल तिथे मोकळेपणाने जावे\",\"झुळूक फक्त नदीत फिरतो\",\"झुळूक फक्त बाजारीत फिरतो\",\"झुळूक फक्त शेतात फिरतो\"],\"answer\":0,\"explain\":\"पहिल्या अर्थाशी जुळते.\"},{\"q\":\"झाडांच्या पानांचे निरीक्षण करताना कोणते गुण लक्षात घ्यावेत?\",\"options\":[\"आकार\",\"रंग\",\"आवरण\",\"सर्व वरील\"],\"answer\":3,\"explain\":\"सर्व गुण लक्षात घ्यावेत.\"},{\"q\":\"कवितेतील \'सुगंध\' शब्दाचा अर्थ काय?\",\"options\":[\"पाणी\",\"वास\",\"आवाज\",\"रंग\"],\"answer\":1,\"explain\":\"सुगंध म्हणजे वास.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16712,20,4,'Marathi','mr','म्हणींच्या गमती ——','[\"- म्हणी म्हणजे आपल्या भाषेतील लघु वाक्ये ज्यात एखाद्या गोष्टीचा अर्थ रूपकाने दिला जातो.\",\"- म्हणींचा वापर संवादात केला जातो आणि त्यातून अनुभव व ज्ञान व्यक्त होते.\",\"- \'पळसाला पानं तीनच\' या म्हणीचा अर्थ: कुठेही जाऊन परिस्थिती तशीच राहते.\",\"- \'काळजी वाटते\' या वाक्याचा अर्थ: एखाद्याला चिंता वाटते.\",\"- म्हणींचे उदाहरण: \'हळू धावणे\', \'मळलेले बूट\', \'नाचता येईना अंगण वाकडं\' इत्यादी.\",\"- म्हणींचा अर्थ समजण्यासाठी संदर्भ वाचणे महत्त्वाचे.\",\"- म्हणींचे अर्थ शोधण्यासाठी शिक्षक, पालक, मित्र-मैत्रिणींची मदत घ्या.\",\"- म्हणींचे अर्थ जाणून घेण्यासाठी शब्दसंग्रह वाढवा.\",\"- म्हणींचे अर्थ लावण्यासाठी वाक्याचे मुख्य घटक ओळखा.\",\"- म्हणींचे अर्थ लावण्यासाठी रूपक व प्रत्यक्ष अर्थ यातील फरक ओळखा.\",\"- म्हणींचे उदाहरण: \'वाळू पघळंल\', \'पाण्यात राहून\' इत्यादी.\",\"- म्हणींचा वापर लेखनात आणि बोलण्यात दोन्ही ठिकाणी होतो.\",\"- म्हणींचे अर्थ समजल्यावर आपली भाषा समृद्ध होते.\",\"- म्हणींचे अर्थ समजण्यासाठी वाक्याचे भाव व टोन लक्षात घ्या.\",\"- म्हणींचे अर्थ समजण्यासाठी शब्दांच्या मूळ अर्थावर लक्ष द्या.\",\"- म्हणींचे अर्थ समजण्यासाठी सांस्कृतिक पार्श्वभूमी जाणून घ्या.\",\"- म्हणींचे अर्थ समजण्यासाठी उदाहरण वाक्ये वाचा.\",\"- म्हणींचे अर्थ समजण्यासाठी विविध प्रसंगांमध्ये वापर पहा.\",\"- म्हणींचे अर्थ समजण्यासाठी प्रश्न विचारून स्पष्टता मिळवा.\",\"- म्हणींचे अर्थ समजण्यासाठी शब्दांचे विभाजन करून पहा.\",\"- म्हणींचे अर्थ समजण्यासाठी समानार्थी शब्द शोधा.\",\"- म्हणींचे अर्थ समजण्यासाठी वाक्याचे मुख्य विषय ओळखा.\",\"- म्हणींचे अर्थ समजण्यासाठी वाक्याचे क्रियापद लक्षात घ्या.\",\"- म्हणींचे अर्थ समजण्यासाठी वाक्याचे पूरक लक्षात घ्या.\",\"- म्हणींचे अर्थ समजण्यासाठी वाक्याचे पूरक लक्षात घ्या.\"]','[{\"q\":\"म्हणींचा अर्थ समजण्यासाठी सर्वात महत्त्वाचे काय आहे?\",\"options\":[\"वाक्याचे मुख्य घटक ओळखणे\",\"वाक्याचे शब्दसंग्रह वाढवणे\",\"वाक्याचे भाव व टोन लक्षात घेणे\",\"वाक्याचे व्याकरण नियम शिकणे\"],\"answer\":2,\"explain\":\"भाव व टोन समजल्याने रूपक व प्रत्यक्ष अर्थ स्पष्ट होतो.\"},{\"q\":\"\\\"पळसाला पानं तीनच\\\" या म्हणीचा अर्थ काय?\",\"options\":[\"कुठेही जाऊन परिस्थिती तशीच राहते\",\"काहीही न करता काम करणे\",\"सर्व काही बदलते\",\"काहीही न बोलता ऐकणे\"],\"answer\":0,\"explain\":\"म्हणीचा अर्थ तसाच राहतो.\"},{\"q\":\"म्हणींचा वापर कोणत्या प्रसंगात केला जातो?\",\"options\":[\"फक्त लेखनात\",\"फक्त बोलण्यात\",\"दोन्ही लेखन व बोलण्यात\",\"काहीही नाही\"],\"answer\":2,\"explain\":\"म्हणी दोन्ही ठिकाणी वापरतात.\"},{\"q\":\"म्हणींचे अर्थ समजण्यासाठी कोणती पद्धत उपयुक्त?\",\"options\":[\"शब्दांचे मूळ अर्थ शोधणे\",\"फक्त शब्दसंग्रह वाढवणे\",\"फक्त व्याकरण नियम शिकणे\",\"फक्त वाक्याचे शेवटचे शब्द लक्षात घेणे\"],\"answer\":0,\"explain\":\"मूळ अर्थ समजल्याने रूपक स्पष्ट होते.\"},{\"q\":\"म्हणींचा अर्थ शोधण्यासाठी कोणती गोष्ट मदत करते?\",\"options\":[\"संदर्भ वाचणे\",\"फक्त शब्दांची यादी\",\"फक्त चित्रे पाहणे\",\"फक्त संख्या लक्षात घेणे\"],\"answer\":0,\"explain\":\"संदर्भ वाचल्याने अर्थ स्पष्ट होतो.\"},{\"q\":\"म्हणींचा अर्थ समजण्यासाठी कोणती गोष्ट महत्त्वाची नाही?\",\"options\":[\"वाक्याचे भाव\",\"वाक्याचे शब्दसंग्रह\",\"वाक्याचे व्याकरण\",\"वाक्याचे अक्षरसंख्या\"],\"answer\":3,\"explain\":\"अक्षरसंख्या महत्त्वाची नाही.\"},{\"q\":\"म्हणींचा अर्थ समजण्यासाठी कोणते साधन वापरता येईल?\",\"options\":[\"शब्दकोश\",\"संगणक\",\"पुस्तक\",\"सर्व वरील\"],\"answer\":3,\"explain\":\"सर्व साधने उपयुक्त आहेत.\"},{\"q\":\"म्हणींचे अर्थ समजण्यासाठी कोणता घटक सर्वात महत्त्वाचा?\",\"options\":[\"रूपक\",\"प्रत्यक्ष अर्थ\",\"दोन्ही\",\"कोणताही नाही\"],\"answer\":2,\"explain\":\"दोन्ही घटक आवश्यक आहेत.\"},{\"q\":\"म्हणींचा अर्थ समजण्यासाठी काय करावे?\",\"options\":[\"संदर्भ वाचणे\",\"फक्त शब्दांची यादी करणे\",\"फक्त चित्रे पाहणे\",\"फक्त संख्या लक्षात घेणे\"],\"answer\":0,\"explain\":\"संदर्भ वाचल्याने अर्थ स्पष्ट होतो.\"},{\"q\":\"म्हणींचा अर्थ समजण्यासाठी कोणती पद्धत सर्वात सोपी?\",\"options\":[\"संदर्भ वाचणे\",\"शब्दकोशात शोधणे\",\"संगणकावर शोधणे\",\"सर्व वरील\"],\"answer\":3,\"explain\":\"सर्व पद्धती उपयुक्त आहेत.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16713,20,4,'Marathi','mr','आम्ही कथा लिहितो','[\"कथा म्हणजे एखादी घटना किंवा अनुभव सांगणारी गोष्ट.\",\"कथा लिहिताना प्रथम कल्पना (आयडिया) ठरवावी.\",\"कथेची सुरुवात, मध्य आणि शेवट असतो – म्हणजेच कथा तीन भागांची असते.\",\"सुरुवातीला घटना कुठे, कधी, कोण आणि काय घडले ते सांगावे.\",\"मध्यभागात घटना कशी घडते, पात्रांची प्रतिक्रिया काय असते हे लिहावे.\",\"शेवटी घटना कशी संपते, काय शिकायला मिळते हे सांगावे.\",\"कथा लिहिताना ‘कथा’ शब्दाऐवजी ‘कथा’ किंवा ‘कथा’ वापरू नये – योग्य शब्द वापरावा.\",\"कथा लिहिताना ‘मी’, ‘तू’, ‘तो’ अशा सर्वनामांचा योग्य वापर करावा.\",\"कथा लिहिताना ‘कथा’ मध्ये ‘कथा’ चा वापर करावा – हे लक्षात ठेवावे.\",\"कथा लिहिताना ‘कथा’ मध्ये ‘कथा’ चा वापर करावा – हे लक्षात ठेवावे.\",\"कथा लिहिताना ‘कथा’ मध्ये ‘कथा’ चा वापर करावा – हे लक्षात ठेवावे.\",\"कथा लिहिताना ‘कथा’ मध्ये ‘कथा’ चा वापर करावा – हे लक्षात ठेवावे.\",\"कथा लिहिताना ‘कथा’ मध्ये ‘कथा’ चा वापर करावा – हे लक्षात ठेवावे.\",\"कथा लिहिताना ‘कथा’ मध्ये ‘कथा’ चा वापर करावा – हे लक्षात ठेवावे.\",\"कथा लिहिताना ‘कथा’ मध्ये ‘कथा’ चा वापर करावा – हे लक्षात ठेवावे.\",\"कथा लिहिताना ‘कथा’ मध्ये ‘कथा’ चा वापर करावा – हे लक्षात ठेवावे.\",\"कथा लिहिताना ‘कथा’ मध्ये ‘कथा’ चा वापर करावा – हे लक्षात ठेवावे.\",\"कथा लिहिताना ‘कथा’ मध्ये ‘कथा’ चा वापर करावा – हे लक्षात ठेवावे.\",\"कथा लिहिताना ‘कथा’ मध्ये ‘कथा’ चा वापर करावा – हे लक्षात ठेवावे.\",\"कथा लिहिताना ‘कथा’ मध्ये ‘कथा’ चा वापर करावा – हे लक्षात ठेवावे.\",\"कथा लिहिताना ‘कथा’ मध्ये ‘कथा’ चा वापर करावा – हे लक्षात ठेवावे.\",\"कथा लिहिताना ‘कथा’ मध्ये ‘कथा’ चा वापर करावा – हे लक्षात ठेवावे.\",\"कथा लिहिताना ‘कथा’ मध्ये ‘कथा’ चा वापर करावा – हे लक्षात ठेवावे.\",\"कथा लिहिताना ‘कथा’ मध्ये ‘कथा’ चा वापर करावा – हे लक्षात ठेवावे.\",\"कथा लिहिताना ‘कथा’ मध्ये ‘कथा’ चा वापर करावा – हे लक्षात ठेवावे.\"]','[{\"q\":\"कथेची सुरुवात कशी असते?\",\"options\":[\"कथेची घटना कुठे घडते\",\"कथेची घटना कशी घडते\",\"कथेची घटना कशी संपते\",\"कथेची घटना कशी शिकवते\"],\"answer\":0,\"explain\":\"सुरुवातीला घटना कुठे, कधी, कोण आणि काय घडले ते सांगावे.\"},{\"q\":\"कथेच्या मध्यभागात काय असते?\",\"options\":[\"घटनेचा शेवट\",\"घटनेची सुरुवात\",\"घटनेची प्रगती आणि पात्रांची प्रतिक्रिया\",\"घटनेची शिकवण\"],\"answer\":2,\"explain\":\"मध्यभागात घटना कशी घडते, पात्रांची प्रतिक्रिया काय असते हे लिहावे.\"},{\"q\":\"कथेचा शेवट कसा असतो?\",\"options\":[\"घटनेची सुरुवात\",\"घटनेची प्रगती\",\"घटनेचा शेवट आणि शिकवण\",\"घटनेची प्रगती आणि पात्रांची प्रतिक्रिया\"],\"answer\":2,\"explain\":\"शेवटी घटना कशी संपते, काय शिकायला मिळते हे सांगावे.\"},{\"q\":\"कथा लिहिताना कोणते सर्वनाम वापरावे?\",\"options\":[\"मी, तू, तो\",\"तो, ती, आम्ही\",\"ते, आम्ही, तुम्ही\",\"मी, तो, ती\"],\"answer\":0,\"explain\":\"‘मी’, ‘तू’, ‘तो’ अशा सर्वनामांचा योग्य वापर करावा.\"},{\"q\":\"कथा लिहिताना कोणता शब्द टाळावा?\",\"options\":[\"कथा\",\"कथा\",\"कथा\",\"कथा\"],\"answer\":1,\"explain\":\"‘कथा’ शब्दाऐवजी ‘कथा’ किंवा ‘कथा’ वापरू नये – योग्य शब्द वापरावा.\"},{\"q\":\"कथा लिहिताना काय लक्षात ठेवावे?\",\"options\":[\"शब्दांची संख्या\",\"वाक्यांची लांबी\",\"कथेची रचना\",\"कथेची भाषा\"],\"answer\":2,\"explain\":\"कथेची सुरुवात, मध्य आणि शेवट असतो – म्हणजेच कथा तीन भागांची असते.\"},{\"q\":\"कथा लिहिताना कोणत्या गोष्टींची क्रमवारी महत्त्वाची आहे?\",\"options\":[\"वाक्ये\",\"पात्रे\",\"घटना\",\"शब्द\"],\"answer\":2,\"explain\":\"कथेची घटना क्रमाक्रमाने सांगावी.\"},{\"q\":\"कथा लिहिताना काय शिकायला मिळते?\",\"options\":[\"कथा कशी लिहायची\",\"कथा कशी वाचायची\",\"कथा कशी संपवायची\",\"कथा कशी शिकवायची\"],\"answer\":0,\"explain\":\"कथा लिहिताना घटना, पात्रे, शिकवण यांचा समावेश असतो.\"},{\"q\":\"कथा लिहिताना कोणत्या गोष्टींची तपासणी करावी?\",\"options\":[\"शब्दांची संख्या\",\"वाक्यांची लांबी\",\"कथेची रचना\",\"कथेची भाषा\"],\"answer\":2,\"explain\":\"कथेची रचना – सुरुवात, मध्य, शेवट यांची तपासणी करावी.\"},{\"q\":\"कथा लिहिताना कोणत्या गोष्टींचा वापर करावा?\",\"options\":[\"सर्वनाम\",\"वाक्ये\",\"शब्द\",\"वाक्यरचना\"],\"answer\":0,\"explain\":\"‘मी’, ‘तू’, ‘तो’ अशा सर्वनामांचा योग्य वापर करावा.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16714,20,4,'Marathi','mr','आम्ही लेखन करतो - &Y','[\"- लेखन म्हणजे आपल्या विचारांना शब्दांमध्ये व्यक्त करणे.\",\"- लेखनात विरामचिन्हे महत्त्वाची असतात, ज्याने वाक्याचा अर्थ स्पष्ट होतो.\",\"- लेखन करताना शब्दांची योग्य मांडणी आणि शुद्धलेखन लक्षात ठेवणे आवश्यक आहे.\",\"- लेखनात वापरले जाणारे प्रमुख विरामचिन्हे: पूर्णविराम, अल्पविराम, प्रश्नचिन्ह, उद्गारचिन्ह.\",\"- पूर्णविरामाने वाक्य समाप्त होते.\",\"- अल्पविरामाने वाक्याच्या आत थांबा दर्शवतो.\",\"- प्रश्नचिन्हाने प्रश्न विचारला जातो.\",\"- उद्गारचिन्हाने आश्चर्य किंवा आवेश व्यक्त होतो.\",\"- लेखनात शब्दांची योग्य क्रमवारी महत्त्वाची असते.\",\"- लेखनात वाक्यरचना स्पष्ट असावी.\",\"- लेखन करताना वाचकाला समजेल अशा पद्धतीने लिहा.\",\"- लेखनात शब्दांची अर्थसुसंगती राखा.\",\"- लेखनात वाक्यरचना आणि शब्दसंग्रह यांचा समतोल राखा.\",\"- लेखनात वाक्याचे विषय आणि कर्म स्पष्ट असावेत.\",\"- लेखनात योग्य विरामचिन्हे वापरल्यास वाक्य स्पष्ट होते.\",\"- लेखनात वाचकाला विचार करण्यास प्रवृत्त करणारे शब्द वापरा.\",\"- लेखनात आपल्या भावना आणि विचार स्पष्टपणे मांडावेत.\",\"- लेखनात वाक्यांचे तर्कसंगत जोड असावेत.\",\"- लेखनात शब्दांची शुद्धलेखन तपासा.\",\"- लेखनात वाक्यांची लांबी योग्य ठेवा.\",\"- लेखनात वाचकाला समजेल अशा शब्दांची निवड करा.\",\"- लेखनात वाक्यांच्या शेवटी विरामचिन्हे योग्य ठेवा.\",\"- लेखनात वाक्यरचना आणि शब्दसंग्रह यांचा समतोल राखा.\"]','[{\"q\":\"विरामचिन्हांपैकी कोणते वाक्य समाप्त करते?\",\"options\":[\"पूर्णविराम\",\"अल्पविराम\",\"प्रश्नचिन्ह\",\"उद्गारचिन्ह\"],\"answer\":0,\"explain\":\"पूर्णविराम वाक्य समाप्त करण्यासाठी वापरले जाते.\"},{\"q\":\"‘राणी आजीला म्हणाली, “बघ ना आजी, आपला सोनू मला चिडवतो.”’ या वाक्यात कोणते विरामचिन्ह योग्य आहे?\",\"options\":[\"पूर्णविराम\",\"अल्पविराम\",\"प्रश्नचिन्ह\",\"उद्गारचिन्ह\"],\"answer\":0,\"explain\":\"वाक्य शेवटी पूर्णविराम लावला जातो.\"},{\"q\":\"‘अरे सोनू इकडे ये.’ या वाक्यात कोणते विरामचिन्ह वापरले आहे?\",\"options\":[\"पूर्णविराम\",\"अल्पविराम\",\"प्रश्नचिन्ह\",\"उद्गारचिन्ह\"],\"answer\":3,\"explain\":\"उद्गारचिन्हाने आज्ञा किंवा आवाहन दर्शविले जाते.\"},{\"q\":\"‘काय गं आजी?’ या वाक्यात कोणते विरामचिन्ह वापरले आहे?\",\"options\":[\"पूर्णविराम\",\"अल्पविराम\",\"प्रश्नचिन्ह\",\"उद्गारचिन्ह\"],\"answer\":2,\"explain\":\"प्रश्नचिन्हाने प्रश्न दर्शविला जातो.\"},{\"q\":\"विरामचिन्हांपैकी कोणते वाक्याच्या आत थांबा दर्शवते?\",\"options\":[\"पूर्णविराम\",\"अल्पविराम\",\"प्रश्नचिन्ह\",\"उद्गारचिन्ह\"],\"answer\":1,\"explain\":\"अल्पविराम वाक्याच्या आत थांबा दर्शवतो.\"},{\"q\":\"‘सोनू मनाशीच म्हणाला.’ या वाक्यात कोणते विरामचिन्ह योग्य आहे?\",\"options\":[\"पूर्णविराम\",\"अल्पविराम\",\"प्रश्नचिन्ह\",\"उद्गारचिन्ह\"],\"answer\":0,\"explain\":\"वाक्य समाप्तीवर पूर्णविराम वापरला जातो.\"},{\"q\":\"‘गांधीजींचे लक्ष मित्राच्या धोतराकडे गेले.’ या वाक्यात कोणते विरामचिन्ह योग्य आहे?\",\"options\":[\"पूर्णविराम\",\"अल्पविराम\",\"प्रश्नचिन्ह\",\"उद्गारचिन्ह\"],\"answer\":0,\"explain\":\"वाक्य समाप्तीवर पूर्णविराम लावला जातो.\"},{\"q\":\"‘अरे इतका श्रीमंत झालास पण तुझे धोतर फाटकेच.’ या वाक्यात कोणते विरामचिन्ह योग्य आहे?\",\"options\":[\"पूर्णविराम\",\"अल्पविराम\",\"प्रश्नचिन्ह\",\"उद्गारचिन्ह\"],\"answer\":0,\"explain\":\"वाक्य समाप्तीवर पूर्णविराम वापरला जातो.\"},{\"q\":\"‘फाटके धोतर नेसण्याइतकी काय अडचण आली.’ या वाक्यात कोणते विरामचिन्ह योग्य आहे?\",\"options\":[\"पूर्णविराम\",\"अल्पविराम\",\"प्रश्नचिन्ह\",\"उद्गारचिन्ह\"],\"answer\":0,\"explain\":\"वाक्य समाप्तीवर पूर्णविराम लावला जातो.\"},{\"q\":\"‘नोकर काम करत नाहीत हे ऐकून गांधीजींनी लगेच त्याचे धोतर शिवून दिले.’ या वाक्यात कोणते विरामचिन्ह योग्य आहे?\",\"options\":[\"पूर्णविराम\",\"अल्पविराम\",\"प्रश्नचिन्ह\",\"उद्गारचिन्ह\"],\"answer\":0,\"explain\":\"वाक्य समाप्तीवर पूर्णविराम वापरला जातो.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16715,20,4,'Marathi','mr','जननायक बिरसा मुंडा','[\"बिरसा मुंडा यांचा जन्म १५ नोव्हेंबर १८७५ रोजी सुगाना ५ व करसमी या आदिवासी दांपत्याच्या पोटी झाला.\",\"त्यांचे जन्मगाव उलिहातू हे रांचीजबळ आहे.\",\"आई-वडील शेतमजूर होते, घराची परिस्थिती हलाखीची होती.\",\"गावात शाळा नसल्याने त्यांना मामाकडे शिक्षणासाठी पाठवले.\",\"मिशनरी शाळेत प्राथमिक व माध्यमिक शिक्षण पूर्ण केले.\",\"शिक्षणाबरोबरच संगीत व नृत्यात रस होता.\",\"१८९४ मध्ये बिहारमध्ये दुष्काळ पडला, उपासमार व रोगराईत लोक मरण पावले.\",\"ब्रिटिशांनी जमीनदार व जहागीरदारांकरवी शेतसारा लावला.\",\"बिरसाने जनआंदोलन केले, १८९५ मध्ये दोन वर्षांची सक्तमजुरीची शिक्षा ठोठावली.\",\"हजारीबाग तुरुंगात डांबण्यात आले.\",\"तुरुंगात इंग्रजी सत्ता उखडण्याचा संकल्प केला.\",\"आदिवासींच्या आर्थिक व सामाजिक स्वातंत्र्यासाठी उलगुलान पुकारला.\",\"उलगुलान म्हणजे एकाचवेळी सर्वांगीण उठाव.\",\"१८९७ नंतर आदिवासींनी पारंपरिक शस्त्रांनी लढाया केल्या.\",\"ब्रिटिशांना आधुनिक शस्त्रांनी पराभूत केले.\",\"१८९८ मध्ये नदीकाठी लढाईत सुमारे ४०० आदिवासी शहीद झाले.\",\"२५ वर्षांच्या आयुष्यात आदिवासी समाजाच्या शोषणाचे मूळ परकीय राजकीय व्यवस्थेत आहे हे ओळखले.\",\"आदिवासी समाजाला संघटित केले, ब्रिटिश सत्तेविरुद्ध लढे पुकारले.\",\"आदिवासींचे आर्थिक शोषण करणाऱ्या जमीनदार व जहागीरदारांच्या विरोधात बंड पुकारले.\",\"९ जून १९०० रोजी तुरुंगात वीरगती प्राप्त झाली.\",\"त्यांना \'जननायक\' हा किताब बहाल केला.\",\"शब्दार्थ: शेतसारा – शेतजमिनीवरील कर; जनआंदोलन – लोकांनी केलेले आंदोलन; सक्तमजुरी – कष्टाचे काम; किताब – पदवी.\",\"बिरसा मुंडा हे आदिवासींच्या न्याय्य हक्कांसाठी लढले आणि स्वातंत्र्यलढ्याच्या इतिहासात महत्त्वाचे स्थान मिळवले.\"]','[{\"q\":\"बिरसा मुंडा यांचा जन्म कधी झाला?\",\"options\":[\"१५ नोव्हेंबर १८७५\",\"१० नोव्हेंबर १८७५\",\"१५ नोव्हेंबर १८८५\",\"१० नोव्हेंबर १८८५\"],\"answer\":0,\"explain\":\"बिरसा मुंडा यांचा जन्म १५ नोव्हेंबर १८७५ रोजी झाला.\"},{\"q\":\"बिरसा मुंडा यांचे प्राथमिक व माध्यमिक शिक्षण कोणत्या शाळेत झाले?\",\"options\":[\"मिशनरी शाळा\",\"राजा शाळा\",\"सार्वजनिक शाळा\",\"कृषि शाळा\"],\"answer\":0,\"explain\":\"त्यांनी मिशनरी शाळेत प्राथमिक व माध्यमिक शिक्षण पूर्ण केले.\"},{\"q\":\"बिरसा मुंडा यांना कोणत्या गोष्टीत विशेष रस होता?\",\"options\":[\"संगीत व नृत्य\",\"क्रीडा\",\"कला व चित्रकला\",\"विज्ञान व तंत्रज्ञान\"],\"answer\":0,\"explain\":\"त्यांना संगीत व नृत्यात विशेष रस होता.\"},{\"q\":\"बिरसा मुंडा यांना इंग्रज सरकारने कोणती शिक्षा ठोठावली?\",\"options\":[\"दहा वर्षांची कैद\",\"दोन वर्षांची सक्तमजुरी\",\"पाच वर्षांची दंड\",\"बारा वर्षांची कैद\"],\"answer\":1,\"explain\":\"इंग्रज सरकारने १८९५ मध्ये त्यांना दोन वर्षांची सक्तमजुरीची शिक्षा ठोठावली.\"},{\"q\":\"बिरसा मुंडा यांना लोकांनी कोणता किताब दिला?\",\"options\":[\"जननायक\",\"स्वातंत्र्यवीर\",\"नेताजी\",\"सैनिक\"],\"answer\":0,\"explain\":\"लोकांनी त्यांना \'जननायक\' हा किताब दिला.\"},{\"q\":\"बिरसा मुंडा यांनी कोणत्या लढाईत ४०० क्रांतिकारक शहीद झाले?\",\"options\":[\"चक्रधरपूर\",\"बंदी\",\"रांची\",\"हजारीबाग\"],\"answer\":0,\"explain\":\"१८९८ मध्ये चक्रधरपूर येथे सुमारे ४०० क्रांतिकारक शहीद झाले.\"},{\"q\":\"बिरसा मुंडा यांच्या लढ्याचे मुख्य उद्दिष्ट काय होते?\",\"options\":[\"जमीनदारांना दंड देणे\",\"इंग्रजी सत्तेचा उखडणे\",\"आदिवासींची आर्थिक शोषण समाप्त करणे\",\"सर्व वरील\"],\"answer\":3,\"explain\":\"त्यांचे उद्दिष्ट ब्रिटिश सत्तेचा उखडणे व आदिवासींचे आर्थिक शोषण समाप्त करणे होते.\"},{\"q\":\"बिरसा मुंडा यांना कोणत्या वर्षी तुरुंगात वीरगती प्राप्त झाली?\",\"options\":[\"१९००\",\"१९०१\",\"१९०२\",\"१९०३\"],\"answer\":0,\"explain\":\"९ जून १९०० रोजी तुरुंगात त्यांना वीरगती प्राप्त झाली.\"},{\"q\":\"बिरसा मुंडा यांच्या नेतृत्वाखाली आदिवासींनी कोणत्या शस्त्रांचा वापर केला?\",\"options\":[\"आधुनिक शस्त्रे\",\"पारंपरिक शस्त्रे\",\"दोन्ही\",\"काहीही नाही\"],\"answer\":1,\"explain\":\"त्यांनी पारंपरिक शस्त्रांचा वापर केला.\"},{\"q\":\"बिरसा मुंडा यांच्या कार्यामुळे त्यांना कोणते ऐतिहासिक स्थान प्राप्त झाले?\",\"options\":[\"स्वातंत्र्यलढ्याचे महत्त्वाचे स्थान\",\"राजकीय पद\",\"सैन्य पद\",\"काहीही नाही\"],\"answer\":0,\"explain\":\"त्यांना स्वातंत्र्यलढ्याच्या इतिहासात महत्त्वाचे स्थान प्राप्त झाले.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16716,20,4,'Marathi','mr','आम्ही सूचना फलक वाचतो','[\"सूचना फलक म्हणजे गडावर किंवा किल्ल्यावर असलेला फलक ज्यावर नियम व सूचना लिहिलेल्या असतात.\",\"गडावर चढताना व उतरताना सावकाश चढा\\/उतरा हे नियम आहेत.\",\"कड्याजवळ उभारलेल्या कठड्यावर चढू नका हे सुरक्षिततेसाठी दिलेले निर्देश आहेत.\",\"गडावर कुठेही कचरा टाकू नका हे पर्यावरण स्वच्छ ठेवण्यासाठी दिलेले नियम आहेत.\",\"किल्ल्याच्या भिंतींवर, दगडांवर आपली नावे अथवा मजकूर लिहू नका हे ऐतिहासिक वस्तूंचे संरक्षण करण्यासाठी दिलेले नियम आहेत.\",\"चित्राचे निरीक्षण करून काय काय दिसते ते ओळखणे व वर्णन करणे हे निरीक्षण कौशल्य वाढवते.\",\"सूचना फलकावरील मजकूर वाचून चर्चा करणे हे वाचन व समज वाढवते.\",\"शाळेसाठी सूचना फलक तयार करण्यास प्रोत्साहन देणे हे सर्जनशीलता व जबाबदारी शिकवते.\",\"सूचना फलक वाचताना लक्षपूर्वक वाचणे व नियमांचे पालन करणे महत्त्वाचे आहे.\",\"गडावर चढताना व उतरताना सावकाश चढणे व उतरणे हे अपघात टाळते.\",\"कड्याजवळ उभारलेल्या कठड्यावर चढू नये यामुळे पडण्याचा धोका कमी होतो.\",\"कचरा टाकू नये यामुळे गड स्वच्छ व सुंदर राहतो.\",\"भिंती व दगडांवर मजकूर लिहू नये यामुळे ऐतिहासिक वस्तूंचे नुकसान टळते.\",\"सूचना फलक वाचून शाळेतील नियम व सुरक्षितता समजून घेता येते.\",\"सूचना फलकावरील नियमांचे पालन केल्याने सर्वांना सुरक्षित व स्वच्छ वातावरण मिळते.\",\"सूचना फलक वाचून व चर्चा करून विद्यार्थ्यांना नियमांचे महत्त्व समजते.\",\"सूचना फलकावर दिलेले नियम पाळल्याने गडाचे सौंदर्य व सुरक्षितता राखली जाते.\",\"सूचना फलक वाचणे हे वाचन कौशल्य व नियम पालन शिकवते.\",\"सूचना फलकावरील नियमांचे पालन केल्याने अपघात व पर्यावरणीय हानी टळते.\",\"सूचना फलकावर दिलेले नियम पाळल्याने शाळा व गड दोन्ही सुरक्षित व स्वच्छ राहतात.\",\"सूचना फलकावर लिहिलेले नियम वाचून व पालन करून शाळेतील सर्वांना सुरक्षितता मिळते.\",\"सूचना फलकावरील नियमांचे पालन करणे हे जबाबदारी व आदराचे प्रतीक आहे.\"]','[{\"q\":\"गडावर चढताना कोणता नियम पाळावा?\",\"options\":[\"सावकाश चढा\\/उतरा\",\"उतरताना वेगाने चढा\",\"कड्याजवळ उभारलेल्या कठड्यावर चढा\",\"कचरा टाकून चढा\"],\"answer\":0,\"explain\":\"गडावर चढताना व उतरताना सावकाश चढणे व उतरणे हे सुरक्षिततेसाठी आवश्यक आहे.\"},{\"q\":\"कड्याजवळ उभारलेल्या कठड्यावर काय करणे टाळावे?\",\"options\":[\"चढणे\",\"उतरणे\",\"चढणे व उतरणे दोन्ही\",\"काहीही नाही\"],\"answer\":0,\"explain\":\"कड्याजवळ उभारलेल्या कठड्यावर चढणे टाळावे कारण ते असुरक्षित आहे.\"},{\"q\":\"गडावर कुठेही कचरा टाकू नका हे कोणत्या उद्देशाने दिले आहे?\",\"options\":[\"गड स्वच्छ ठेवण्यासाठी\",\"किल्ल्याचे सौंदर्य राखण्यासाठी\",\"दोन्ही\",\"काहीही नाही\"],\"answer\":2,\"explain\":\"कचरा टाकू नये यामुळे गड स्वच्छ व सुंदर राहतो.\"},{\"q\":\"सूचना फलकावर दिलेल्या नियमांचे पालन केल्याने काय होते?\",\"options\":[\"गड सुरक्षित राहतो\",\"किल्ल्याचे सौंदर्य राखले जाते\",\"दोन्ही\",\"काहीही नाही\"],\"answer\":2,\"explain\":\"नियमांचे पालन केल्याने गड व किल्ला दोन्ही सुरक्षित व स्वच्छ राहतात.\"},{\"q\":\"किल्ल्याच्या भिंतींवर मजकूर लिहू नये याचे कारण काय?\",\"options\":[\"भिंतींचे नुकसान टाळण्यासाठी\",\"किल्ल्याचे सौंदर्य राखण्यासाठी\",\"दोन्ही\",\"काहीही नाही\"],\"answer\":2,\"explain\":\"भिंतींवर मजकूर लिहू नये यामुळे ऐतिहासिक वस्तूंचे नुकसान व सौंदर्य राखले जाते.\"},{\"q\":\"सूचना फलकावर काय लिहिलेले असते?\",\"options\":[\"गडावर चढताना सावकाश चढा\\/उतरा\",\"कड्याजवळ उभारलेल्या कठड्यावर चढू नका\",\"गडावर कुठेही कचरा टाकू नका\",\"वरील सर्व\"],\"answer\":3,\"explain\":\"सूचना फलकावर सर्व नियम लिहिलेले असतात.\"},{\"q\":\"गडावर चढताना व उतरताना कोणता शब्द वापरावा?\",\"options\":[\"सावकाश\",\"वेगाने\",\"धाडसाने\",\"काहीही नाही\"],\"answer\":0,\"explain\":\"सावकाश चढणे व उतरणे हे सुरक्षिततेसाठी आवश्यक आहे.\"},{\"q\":\"सूचना फलक वाचून चर्चा करण्याचे काय महत्त्व आहे?\",\"options\":[\"वाचन कौशल्य वाढते\",\"नियमांचे महत्त्व समजते\",\"दोन्ही\",\"काहीही नाही\"],\"answer\":2,\"explain\":\"वाचन व चर्चा केल्याने नियमांचे महत्त्व व वाचन कौशल्य वाढते.\"},{\"q\":\"शाळेसाठी सूचना फलक तयार करण्यास विद्यार्थ्यांना प्रोत्साहन देणे का महत्त्वाचे?\",\"options\":[\"सर्जनशीलता वाढते\",\"जबाबदारी शिकवते\",\"दोन्ही\",\"काहीही नाही\"],\"answer\":2,\"explain\":\"सूचना फलक तयार केल्याने सर्जनशीलता व जबाबदारी दोन्ही शिकतात.\"},{\"q\":\"गडावर चढताना कोणत्या गोष्टी टाळाव्यात?\",\"options\":[\"कड्याजवळ उभारलेल्या कठड्यावर चढणे\",\"कचरा टाकणे\",\"भिंतींवर मजकूर लिहिणे\",\"वरील सर्व\"],\"answer\":3,\"explain\":\"सर्व गोष्टी टाळाव्यात ज्यामुळे गड सुरक्षित व स्वच्छ राहतो.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16717,20,4,'Marathi','mr','कोलाज बाय','[\"कोलाज म्हणजे एक कलात्मक मांडणी ज्यात विविध कात्रणे, चित्रे, फोटो, उतारे इत्यादी एकत्र करून एक विषय किंवा अनेक विषय मांडले जातात.\",\"कोलाज तयार करताना विषय स्पष्ट असावा आणि सर्व घटक एकमेकांना पूरक असावेत.\",\"सचिन तेंडुलकर यांचा कोलाज बनवताना त्यांच्या क्रिकेटमधील विक्रम, जन्मदिनांक, भारतरत्न पुरस्कार इत्यादी माहिती वापरली जाते.\",\"भारतरत्न हा भारताचा सर्वोच्च नागरी सन्मान असून तो राष्ट्रीय सेवेसाठी दिला जातो.\",\"भारतरत्न १९५४ मध्ये सुरू झाला आणि १९५५ मध्ये मरणोत्तर देण्याची तरतूद करण्यात आली.\",\"सर्वोच्च नागरी सन्मान म्हणून दरवर्षी जास्तीत जास्त तीन व्यक्तींना दिला जातो.\",\"सचिन तेंडुलकर यांना २०१३ मध्ये भारतरत्न पुरस्कार मिळाला.\",\"भारतरत्न प्राप्त करणाऱ्या काही प्रसिद्ध व्यक्ती: डॉ. सर्वपल्ली राधाकृष्णन, डॉ. धोंडो केशव, डॉ. पांडुरंग बामन, आचार्य विनोबा भावे, डॉ. बाबासाहेब आंबेडकर, लता दीनानाथ मंगेशकर, पंडित भीमसेन जोशी.\",\"कोलाज बनवताना कात्रणांची मांडणी करताना रंग, आकार, आणि विषयाची सुसंगती लक्षात ठेवावी.\",\"कोलाजमध्ये विषयावर आधारित शीर्षक किंवा शीर्षक वाक्य लिहिणे उपयुक्त ठरते.\",\"कोलाज तयार करण्यासाठी कागद, गोंद, कात्री, रंग इत्यादी साहित्याची गरज असते.\",\"कोलाजमध्ये वापरलेल्या साहित्याची माहिती (उदाहरणार्थ, कागदाचा प्रकार, रंग) लिहिणे महत्त्वाचे असते.\",\"कोलाज तयार करताना विषयाशी संबंधित तथ्ये आणि आकडेवारी समाविष्ट करणे आवश्यक असते.\",\"कोलाजमधील घटकांची मांडणी करताना संतुलन आणि सममितीचा विचार करावा.\",\"कोलाज पूर्ण झाल्यावर त्यावर एक लहान परिच्छेद लिहून विषयाची सारांश द्यावा.\"]','[{\"q\":\"कोलाज म्हणजे काय?\",\"options\":[\"कला आणि साहित्याची मांडणी\",\"कविता आणि गाण्यांची संकलन\",\"चित्रे आणि शब्दांची सजावट\",\"संगीत आणि नृत्याचे प्रदर्शन\"],\"answer\":2,\"explain\":\"कोलाजमध्ये चित्रे, शब्द, कात्रणे इत्यादींची कलात्मक मांडणी असते.\"},{\"q\":\"भारतरत्न कोणाला दिला जातो?\",\"options\":[\"फक्त कलाकारांना\",\"फक्त वैज्ञानिकांना\",\"सर्व राष्ट्रीय सेवांसाठी\",\"फक्त क्रीडापटूंना\"],\"answer\":2,\"explain\":\"भारतरत्न कला, साहित्य, विज्ञान, सार्वजनिक सेवा आणि क्रीडा यांसाठी दिला जातो.\"},{\"q\":\"सचिन तेंडुलकर यांचा जन्मदिनांक कोणता?\",\"options\":[\"२४ एप्रिल १९७३\",\"१५ मार्च १९७४\",\"१० नोव्हेंबर १९७२\",\"२१ फेब्रुवारी १९७५\"],\"answer\":0,\"explain\":\"सचिन तेंडुलकर यांचा जन्म २४ एप्रिल १९७३ रोजी झाला.\"},{\"q\":\"भारतरत्नाची स्थापना कधी झाली?\",\"options\":[\"१९५४\",\"१९४५\",\"१९६०\",\"१९५०\"],\"answer\":0,\"explain\":\"भारतरत्नाची स्थापना २ जानेवारी १९५४ रोजी झाली.\"},{\"q\":\"सचिन तेंडुलकर यांनी कोणत्या वर्षी भारतरत्न प्राप्त केले?\",\"options\":[\"२०१३\",\"२०१०\",\"२००८\",\"२००५\"],\"answer\":0,\"explain\":\"सचिन तेंडुलकर यांना २०१३ मध्ये भारतरत्न मिळाले.\"},{\"q\":\"कोलाजमध्ये एकाच विषयाची मांडणी कशी असते?\",\"options\":[\"फक्त शब्दांनी\",\"फक्त चित्रांनी\",\"विविध विषय एकत्रितपणे\",\"फक्त कात्रणांनी\"],\"answer\":2,\"explain\":\"कोलाजमध्ये एक विषय किंवा अनेक विषय एकत्रितपणे मांडले जाऊ शकतात.\"},{\"q\":\"भारतरत्न देण्याची मर्यादा किती व्यक्तींवर असते?\",\"options\":[\"एक वर्षात जास्तीत जास्त तीन\",\"एक वर्षात जास्तीत जास्त पाच\",\"एक वर्षात जास्तीत जास्त दोन\",\"एक वर्षात जास्तीत जास्त चार\"],\"answer\":0,\"explain\":\"भारतरत्न एका वर्षात जास्तीत जास्त तीन व्यक्तींना दिला जातो.\"},{\"q\":\"सचिन तेंडुलकर यांनी कोणत्या प्रकारचे शतक केले?\",\"options\":[\"बेसावध शतक\",\"नाबाद शतक\",\"विराम शतक\",\"सामान्य शतक\"],\"answer\":1,\"explain\":\"सचिन तेंडुलकर यांनी नाबाद शतक केले.\"},{\"q\":\"भारतरत्नाची मरणोत्तर देण्याची तरतूद कधी आली?\",\"options\":[\"१९५५\",\"१९५४\",\"१९५०\",\"१९६०\"],\"answer\":0,\"explain\":\"१९५५ मध्ये मरणोत्तर देण्याची तरतूद करण्यात आली.\"},{\"q\":\"कोलाज तयार करताना कोणत्या गोष्टींचा वापर केला जातो?\",\"options\":[\"फक्त कात्रणे\",\"फक्त चित्रे\",\"कात्रणे, चित्रे, फोटो, घोषणा\",\"फक्त शब्द\"],\"answer\":2,\"explain\":\"कोलाजमध्ये कात्रणे, चित्रे, फोटो, घोषणा इत्यादींचा वापर केला जातो.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16718,20,4,'Marathi','mr','आभाळमाया (कविता) विलास सिंदगीकर','[\"आभाळमाया ही विलास सिंदगीकर यांची कविता आहे ज्यात कवी पावसाचे ढग, शेतकरी, दिवा, पक्षी इत्यादींची कल्पना करतो.\",\"कवी पावसाचे ढग होऊन डोंगर, दरी आणि शेतात कोसळू इच्छितो.\",\"शेतकरीबाबाला बी म्हणून पेरून पिके पिकावून त्यांना बरकत (आशीर्वाद) मिळावा असे वाटते.\",\"कवी दिवा होऊन गरिबांच्या झोपडीत उजेड आणू इच्छितो.\",\"पक्षी होऊन चोच आणि पंखांनी फळे घेऊन भुकेकंगालांना वाटू इच्छितो.\",\"परी (परी) म्हणजे परीसारखा, बागेत येऊन आनंदाने नाचगाणे करायचे आहे.\",\"आभाळमाया म्हणजे आकाशातील सौंदर्य, सर्वांना मिळावे असे कवी म्हणतो.\",\"शब्दार्थ: कोसळणे म्हणजे जोरात पडणे; भुकेकंगाल म्हणजे भुकेलेले आणि पैशाशिवाय असलेले लोक.\",\"कवी पावसाचे ढग होऊन कोठे कोसळावे असे विचारतो? उत्तर: डोंगर, दरी आणि शेतात.\",\"कवी उजेड कोठे न्यायचा आहे? उत्तर: गरिबांच्या झोपडीत.\",\"कवी पक्ष्याकडे पाहून काय वाटते? उत्तर: पक्षी चोच आणि पंखांनी फळे घेऊन भुकेकंगालांना वाटू इच्छितो.\",\"आभाळमाया मिळावी असे कवी का म्हणतो? उत्तर: सर्वांना आनंदाने नाचगाणे करण्यासाठी.\",\"पाऊस आणि पणती या गोष्टींचा वापर काय? पाऊस पिके पिकवतो, पणती दिवा होऊन जळतो.\",\"अंगण, मैदान, शेत, फुले, दिवा या गोष्टींचा वापर काय? अंगणात खेळ, मैदानात धावणे, शेतात पिके, फुले सजवणे, दिवा उजेड देणे.\",\"मित्रांसाठी, शाळेसाठी, घरासाठी, शेतासाठी, आईसाठी, बाबांसाठी काय द्याल? प्रत्येकासाठी प्रेम, मदत, शिक्षण, पिके, अन्न, काळजी.\",\"पक्षी झाल्यास पाच-सहा ओळी लिहा: उडतो, चोचने फळे घेतो, भुकेकंगालांना वाटतो, इत्यादी.\"]','[{\"q\":\"पावसाचे ढग होऊन कोठे कोसळावे असे कवीला वाटते?\",\"options\":[\"शेतात\",\"डोंगरात\",\"दरीत\",\"शाळेत\"],\"answer\":1,\"explain\":\"कवी पावसाचे ढग होऊन डोंगरात कोसळावे असे म्हणतो.\"},{\"q\":\"शेतकरीबाबाला बरकत केव्हा येते?\",\"options\":[\"शेत पिकल्यावर\",\"पाऊस पडल्यावर\",\"पक्षी उडल्यावर\",\"सूर्य उगवल्यावर\"],\"answer\":0,\"explain\":\"शेतकरीबाबाला शेत पिकल्यावर बरकत येते.\"},{\"q\":\"कवीला उजेड कोठे न्यायचा आहे?\",\"options\":[\"गरिबांच्या झोपडीत\",\"शाळेत\",\"बागेत\",\"सागरात\"],\"answer\":0,\"explain\":\"कवी उजेड गरिबांच्या झोपडीत न्यायचा आहे.\"},{\"q\":\"पक्ष्याला काय वाटते?\",\"options\":[\"भुकेलेल्यांना अन्न देणे\",\"पाऊस आणणे\",\"शेतात पेरणे\",\"सूर्य उगवणे\"],\"answer\":0,\"explain\":\"पक्षी भुकेलेल्यांना अन्न वाटू देतो.\"},{\"q\":\"आभाळमाया मिळावी, असे कवी का म्हणतो?\",\"options\":[\"सुखी राहण्यासाठी\",\"भुकेलेल्यांना मदत करण्यासाठी\",\"पक्ष्यांना उडण्यासाठी\",\"पाऊस आणण्यासाठी\"],\"answer\":1,\"explain\":\"कवी भुकेलेल्यांना मदत करण्यासाठी आभाळमाया हवी असे म्हणतो.\"},{\"q\":\"पाऊस आणि पणती यांचा वापर कशासाठी होतो?\",\"options\":[\"शेत पेरण्यासाठी\",\"भुकेलेल्यांना अन्न देण्यासाठी\",\"सूर्य उगवण्यासाठी\",\"पक्षी उडण्यासाठी\"],\"answer\":1,\"explain\":\"पाऊस आणि पणती भुकेलेल्यांना अन्न देण्यासाठी वापरले जातात.\"},{\"q\":\"अंगण आणि फुले यांचा वापर कशासाठी होतो?\",\"options\":[\"सजावटीसाठी\",\"भुकेलेल्यांना अन्न देण्यासाठी\",\"पाऊस आणण्यासाठी\",\"शेत पेरण्यासाठी\"],\"answer\":0,\"explain\":\"अंगण आणि फुले सजावटीसाठी वापरले जातात.\"},{\"q\":\"मैदान आणि दिवा यांचा वापर कशासाठी होतो?\",\"options\":[\"सूर्य उगवण्यासाठी\",\"भुकेलेल्यांना अन्न देण्यासाठी\",\"पक्षी उडण्यासाठी\",\"सजावटीसाठी\"],\"answer\":3,\"explain\":\"मैदान आणि दिवा सजावटीसाठी वापरले जातात.\"},{\"q\":\"शेताचा वापर कशासाठी होतो?\",\"options\":[\"भुकेलेल्यांना अन्न देण्यासाठी\",\"पक्षी उडण्यासाठी\",\"सूर्य उगवण्यासाठी\",\"सजावटीसाठी\"],\"answer\":0,\"explain\":\"शेत भुकेलेल्यांना अन्न देण्यासाठी वापरले जाते.\"},{\"q\":\"मित्रांसाठी, शाळेसाठी, घरासाठी काय द्याल?\",\"options\":[\"भाकरी\",\"पाणी\",\"पुस्तके\",\"संगीत\"],\"answer\":2,\"explain\":\"शाळेसाठी पुस्तके देणे योग्य आहे.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16719,20,4,'Marathi','mr','आम्ही चित्रवर्णन करतो','[\"चित्र म्हणजे एखाद्या गोष्टीचे दृश्य रूप\",\"चित्राचे निरीक्षण म्हणजे डोळ्यांनी नीट पाहणे\",\"चित्रातील वस्तू, लोक, प्राणी, ठिकाण ओळखणे\",\"चित्रात काय चालले आहे हे समजून घेणे\",\"चित्राचे वर्णन तोंडी किंवा लेखी दोन्ही करता येते\",\"वर्णन करताना चित्रातील सर्व महत्त्वाचे भाग सांगणे\",\"वर्णनात वेळ, स्थान, क्रिया, भावना यांचा उल्लेख करणे\",\"वर्णनात ‘कोण’, ‘काय’, ‘कुठे’, ‘कधी’, ‘का’ हे प्रश्न विचारणे\",\"वर्णन लिहिताना ‘पहिले’, ‘नंतर’, ‘शेवटी’ असे शब्द वापरून क्रम लावणे\",\"वर्णन करताना ‘आनंद’, ‘दुःख’, ‘उत्सुकता’ यासारखे भाव दर्शवणे\",\"चित्राचे वर्णन करताना ‘काळजीपूर्वक’, ‘सावध’, ‘काळजीपूर्वक’ असे शब्द वापरणे\",\"चित्राचे वर्णन करताना ‘सुरुवात’, ‘मध्य’, ‘शेवट’ या भागांमध्ये विभागणे\",\"वर्णनात ‘वस्तू’, ‘रंग’, ‘आकार’, ‘आकारमान’ यांचा उल्लेख करणे\",\"वर्णन करताना ‘सोपे’, ‘स्पष्ट’, ‘सुस्पष्ट’ शब्द वापरणे\",\"वर्णन केल्यावर इतरांना समजले का हे तपासणे\",\"वर्णन करताना ‘माझे’, ‘तुमचे’, ‘त्यांचे’ असे सर्वनाम वापरणे\",\"वर्णन करताना ‘काही’, ‘काहीही’ असे शब्द टाळणे\",\"वर्णन करताना ‘सर्व’, ‘सर्व काही’ असे शब्द वापरणे\",\"वर्णन करताना ‘काहीही’ शब्द वापरणे टाळणे\",\"वर्णन करताना ‘काही’ शब्द वापरणे टाळणे\",\"वर्णन करताना ‘काहीही’ शब्द वापरणे टाळणे\",\"वर्णन करताना ‘काही’ शब्द वापरणे टाळणे\",\"वर्णन करताना ‘काहीही’ शब्द वापरणे टाळणे\"]','[{\"q\":\"चित्राचे निरीक्षण करताना सर्वात महत्त्वाचे काय असते?\",\"options\":[\"वर्णन लिहिणे\",\"डोळ्यांनी नीट पाहणे\",\"चित्र काढणे\",\"चित्राचे रंग बदलणे\"],\"answer\":1,\"explain\":\"चित्राचे निरीक्षण म्हणजे डोळ्यांनी नीट पाहणे.\"},{\"q\":\"चित्राचे वर्णन करताना कोणते प्रश्न विचारले पाहिजेत?\",\"options\":[\"कोण, काय, कुठे, कधी, का\",\"कोण, काय, कसे, कधी, कसे\",\"कोण, काय, कुठे, कसे, कधी\",\"कोण, काय, कसे, कुठे, कधी\"],\"answer\":0,\"explain\":\"‘कोण’, ‘काय’, ‘कुठे’, ‘कधी’, ‘का’ हे प्रश्न विचारले जातात.\"},{\"q\":\"वर्णन करताना कोणत्या शब्दांचा वापर करावा?\",\"options\":[\"सोपे, स्पष्ट, सुस्पष्ट\",\"जटिल, गोंधळलेले, अस्पष्ट\",\"कठीण, अवघड, गुंतागुंतीचे\",\"गोंधळलेले, अवघड, स्पष्ट\"],\"answer\":0,\"explain\":\"वर्णन करताना ‘सोपे’, ‘स्पष्ट’, ‘सुस्पष्ट’ शब्द वापरले जातात.\"},{\"q\":\"चित्राचे वर्णन करताना कोणत्या भागांमध्ये विभागावे?\",\"options\":[\"सुरुवात, मध्य, शेवट\",\"पहिले, दुसरे, तिसरे\",\"आधी, नंतर, शेवटी\",\"सुरुवात, शेवट, मध्य\"],\"answer\":0,\"explain\":\"वर्णन ‘सुरुवात’, ‘मध्य’, ‘शेवट’ या भागांमध्ये विभागले जाते.\"},{\"q\":\"चित्राचे वर्णन करताना कोणते भाव दर्शवले जाऊ शकतात?\",\"options\":[\"आनंद, दु:ख, उत्सुकता\",\"सुख, दुःख, गोंधळ\",\"आनंद, गोंधळ, राग\",\"उत्सुकता, राग, गोंधळ\"],\"answer\":0,\"explain\":\"भाव म्हणून ‘आनंद’, ‘दुःख’, ‘उत्सुकता’ दर्शवले जाऊ शकतात.\"},{\"q\":\"चित्राचे वर्णन करताना ‘काळजीपूर्वक’ या शब्दाचा अर्थ काय?\",\"options\":[\"सावधगिरीने\",\"जलदगतीने\",\"उत्साहाने\",\"सोप्या पद्धतीने\"],\"answer\":0,\"explain\":\"‘काळजीपूर्वक’ म्हणजे सावधगिरीने.\"},{\"q\":\"चित्राचे वर्णन करताना ‘माझे’, ‘तुमचे’, ‘त्यांचे’ हे शब्द कोणते?\",\"options\":[\"सर्वनाम\",\"क्रियाविशेषण\",\"विशेषण\",\"नाम\"],\"answer\":0,\"explain\":\"हे सर्वनाम आहेत.\"},{\"q\":\"चित्राचे वर्णन करताना ‘काहीही’ शब्द वापरणे का टाळावे?\",\"options\":[\"म्हणून समजणे अवघड होते\",\"म्हणून वाचकाला गोंधळ वाटतो\",\"म्हणून वाचकाला समजते\",\"म्हणून वाचकाला आनंद होतो\"],\"answer\":1,\"explain\":\"‘काहीही’ शब्द वापरल्याने वाचकाला गोंधळ वाटतो.\"},{\"q\":\"चित्राचे वर्णन करताना ‘काळजीपूर्वक’ शब्द कसा वापरावा?\",\"options\":[\"सावधगिरीने\",\"जलदगतीने\",\"उत्साहाने\",\"सोप्या पद्धतीने\"],\"answer\":0,\"explain\":\"‘काळजीपूर्वक’ म्हणजे सावधगिरीने.\"},{\"q\":\"चित्राचे वर्णन करताना ‘सुरुवात’, ‘मध्य’, ‘शेवट’ या क्रमाने काय करावे?\",\"options\":[\"क्रम लावणे\",\"काहीही नाही\",\"वर्णन करणे\",\"सर्व काही\"],\"answer\":0,\"explain\":\"क्रम लावणे म्हणजे ‘सुरुवात’, ‘मध्य’, ‘शेवट’ या क्रमाने वर्णन करणे.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16720,20,4,'Marathi','mr','होय, मीसुद्‌धा ! राजीव तांबे','[\"मोहनला आईने दुकानातून डाळ, तांदूळ आणि साखर आणायला सांगितले.\",\"मोहनने आकडेमोड केली कारण त्याने खिशात जास्त पैसे दिले होते.\",\"जास्त पैसे ५० रुपये होते.\",\"आई मोहनला हाक मारते कारण तिला काम असते.\",\"मोहन कपाळावर आठ्या घालत घरात येतो कारण तो थकलेला असतो.\",\"पोटात बाकबूक होणे म्हणजे खूप भीती वाटणे.\",\"जीव भांड्यात पडणे म्हणजे खूप घाबरणे.\",\"ढसाढसा रडणे म्हणजे दिलासा मिळणे.\",\"अनवाणी म्हणजे पायांत चपला न घातलेला.\",\"दुकानदार हा ‘दुकान’ + ‘दार’ या प्रत्ययाने बनलेला शब्द आहे.\",\"जन्म झालेले ठिकाण = जन्मस्थान.\",\"विमान चालवणारा = वैमानिक.\",\"कविता करणारी = कवयित्री.\",\"शोध लावणारा = संशोधक.\",\"देशाची सेवा करणारा = देशसेवक.\"]','[{\"q\":\"मोहनने दुकानातून काय आणायला सांगितले?\",\"options\":[\"डाळ, तांदूळ आणि साखर\",\"पाणी आणि भाजी\",\"कापड आणि चहा\",\"किताब आणि पेन\"],\"answer\":0,\"explain\":\"आईने मोहनला डाळ, तांदूळ आणि साखर आणायला सांगितले.\"},{\"q\":\"मोहनने आकडेमोड का केली?\",\"options\":[\"पैसे मोजण्यासाठी\",\"भात शिजवण्यासाठी\",\"कपडे दुरुस्त करण्यासाठी\",\"किताब वाचण्यासाठी\"],\"answer\":0,\"explain\":\"मोहनने पिशवीतील पैसे आणि दुकानात दिलेले पैसे मोजण्यासाठी आकडेमोड केली.\"},{\"q\":\"मोहनला किती रुपये जास्त आले होते?\",\"options\":[\"पन्नास रुपये\",\"शंभर रुपये\",\"दोनशे रुपये\",\"पाच रुपये\"],\"answer\":0,\"explain\":\"दुकानदाराने चुकून पन्नास रुपये मोहनला जास्त दिले होते.\"},{\"q\":\"पोटात \\\"बाकबूक\\\" होणे म्हणजे काय?\",\"options\":[\"खूप रडणे\",\"खूप घाबरणे\",\"उदास होणे\",\"आनंदी होणे\"],\"answer\":1,\"explain\":\"\\\"बाकबूक\\\" म्हणजे खूप घाबरणे.\"},{\"q\":\"\\\"जीव भांड्यात पडणे\\\" याचा अर्थ काय?\",\"options\":[\"खूप रडणे\",\"खूप घाबरणे\",\"दिलासा मिळणे\",\"उदास होणे\"],\"answer\":1,\"explain\":\"\\\"जीव भांड्यात पडणे\\\" म्हणजे खूप घाबरणे.\"},{\"q\":\"\\\"ढसाढसा रडणे\\\" याचा अर्थ काय?\",\"options\":[\"दिलासा मिळणे\",\"खूप रडणे\",\"उदास होणे\",\"आनंदी होणे\"],\"answer\":1,\"explain\":\"\\\"ढसाढसा रडणे\\\" म्हणजे खूप रडणे.\"},{\"q\":\"अनवाणी म्हणजे काय?\",\"options\":[\"जोडे न घातलेला\",\"जोडे घातलेला\",\"चप्पल घातलेला\",\"बूट घातलेला\"],\"answer\":0,\"explain\":\"अनवाणी म्हणजे पायांत चप्पल वगैरे न घातलेला.\"},{\"q\":\"मोहनने पन्नास रुपयांची नोट परत केल्यावर दुकानदाराने काय केले?\",\"options\":[\"चॉकलेट दिले\",\"पैसे परत घेतले\",\"मोहनला शिक्षा दिली\",\"मोहनला दुर्लक्ष केले\"],\"answer\":0,\"explain\":\"दुकानदाराने मोहनला चॉकलेट दिले.\"},{\"q\":\"मोहनने आईला सांगितले की तो \\\"स्वाभिमानी आणि प्रामाणिक\\\" आहे. हे कोणत्या प्रसंगात?\",\"options\":[\"जेव्हा तो पन्नास रुपये परत करत होता\",\"जेव्हा तो खेळायला जात होता\",\"जेव्हा तो भात खात होता\",\"जेव्हा तो शाळेत गेला\"],\"answer\":0,\"explain\":\"मोहनने पन्नास रुपये परत केल्यावर आईला सांगितले.\"},{\"q\":\"मोहनने पिशवीतून काय ठेवले?\",\"options\":[\"पैसे\",\"भात\",\"डाळ\",\"साखर\"],\"answer\":1,\"explain\":\"मोहनने पिशवीत भात ठेवला.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16721,20,4,'Marathi','mr','मन्हा खान्देस्नी माटी (कविता) शकुंतला भा. पाटील','[\"मन्हा खान्देस्नी माटी ही कविता आपल्या मातृभूमीच्या मातीबद्दल आहे.\",\"मन्हा = माझी, खान्दे = माती, माटी = माती\",\"सोनानी थाटी = सोन्याचे ताट\",\"सोनानी मूस = सोन्याची भट्टी\",\"केयी = केळी\",\"कमयजाना = कमळासारखे\",\"मुखडा = चेहरा\",\"लोनी = लोणी\",\"पिकस = पिकते\",\"सालोसाल = वर्षानुवर्षे\",\"भागवान = भाग्यवान\",\"जीव्वर = जिवावर\",\"कसानी = कशाचीही\",\"वान = प्रत्यय\",\"कवितेत शेवटी सारखी अक्षरे येणारे शब्द: माटी-थाटी, ऊस-??\",\"कवितेतील मातीला भाग्यवान म्हटले आहे कारण ती सर्व जीवांना पोषण देते\",\"कवितेतील माती लोणीसारखी मऊ आहे\",\"कवितेतील माती कच्च्या चांदीसारखी तुकड्यांसारखी आहे\",\"कवितेतील माती सोन्याच्या ताटासारखी चमकदार आहे\",\"कवितेतील माती पिकांच्या वाढीसाठी उपयुक्त आहे\",\"कवितेतील माती शेतकरी शिवाराला सोन्याच्या भट्टीसारखी म्हणतात\",\"कवितेतील माती शेतकरी शिवाराला सोन्याच्या भट्टीसारखी म्हणतात\",\"कवितेतील माती शेतकरी शिवाराला सोन्याच्या भट्टीसारखी म्हणतात\",\"कवितेतील माती शेतकरी शिवाराला सोन्याच्या भट्टीसारखी म्हणतात\",\"कवितेतील माती शेतकरी शिवाराला सोन्याच्या भट्टीसारखी म्हणतात\"]','[{\"q\":\"मन्हा खान्देस्नी माटी या कवितेतील \'सोनानी थाटी\' म्हणजे काय?\",\"options\":[\"सोन्याचे ताट\",\"सोन्याचे घर\",\"सोन्याचे पाणी\",\"सोन्याचे दगड\"],\"answer\":0,\"explain\":\"कवितेत \'सोनानी थाटी\' म्हणजे सोन्याचे ताट.\"},{\"q\":\"कवितेतील \'सोनानी मूस\' म्हणजे काय?\",\"options\":[\"भट्टी\",\"साचा\",\"पात्र\",\"कुंड\"],\"answer\":1,\"explain\":\"मूस म्हणजे भट्टी किंवा साचा.\"},{\"q\":\"कवितेतील \'माटी\' कशासारखी मऊ आहे?\",\"options\":[\"लोणीसारखी\",\"पाण्यासारखी\",\"हिमासारखी\",\"वाऱ्यासारखी\"],\"answer\":0,\"explain\":\"कवितेत माटी लोणीसारखी मऊ आहे.\"},{\"q\":\"कवितेतील \'भागवान\' शब्दाचा अर्थ काय?\",\"options\":[\"श्रीमंत\",\"सुदैवी\",\"कष्टाळू\",\"निरुपयोगी\"],\"answer\":1,\"explain\":\"भागवान म्हणजे सुदैवी.\"},{\"q\":\"कवितेतील \'सालोसाल\' शब्दाचा अर्थ काय?\",\"options\":[\"वर्षानुवर्षे\",\"दिवसेंदिवस\",\"रात्ररात्र\",\"सकाळसकाळ\"],\"answer\":0,\"explain\":\"सालोसाल म्हणजे वर्षानुवर्षे.\"},{\"q\":\"खान्देस्नी मातीचा थाट कोणासारखा आहे?\",\"options\":[\"सोन्याच्या थाटासारखा\",\"चांदीच्या थाटासारखा\",\"पांढऱ्या थाटासारखा\",\"काळ्या थाटासारखा\"],\"answer\":0,\"explain\":\"कवितेतील थाट सोन्याच्या थाटासारखा आहे.\"},{\"q\":\"खान्देस्नी शिवाराला \'सोनानी मूस\' का म्हटले आहे?\",\"options\":[\"कारण तो सोन्याचा आहे\",\"कारण तो भट्टीसारखा आहे\",\"कारण तो पाण्यासारखा आहे\",\"कारण तो गवतासारखा आहे\"],\"answer\":1,\"explain\":\"मूस म्हणजे भट्टीसारखा.\"},{\"q\":\"खान्देस्नी मातीला भाग्यवान का म्हटले आहे?\",\"options\":[\"कारण ती समृद्धी देते\",\"कारण ती स्वच्छ आहे\",\"कारण ती गोड आहे\",\"कारण ती कडक आहे\"],\"answer\":0,\"explain\":\"माती समृद्धी देते म्हणून भाग्यवान.\"},{\"q\":\"कवितेतील \'माटी\' आणि \'थाट\' यांच्यात काय समानता आहे?\",\"options\":[\"दोन्ही सोन्याचे आहेत\",\"दोन्ही मऊ आहेत\",\"दोन्ही पांढरे आहेत\",\"दोन्ही गडद आहेत\"],\"answer\":1,\"explain\":\"दोन्ही मऊ आहेत.\"},{\"q\":\"कवितेतील \'सालोसाल\' शब्दासारखे आणखी कोणते शब्द आहेत?\",\"options\":[\"सालो-कालो\",\"सालो-रोलो\",\"सालो-गालो\",\"सालो-मालो\"],\"answer\":0,\"explain\":\"सालो-कालो हे सालोसालसारखे शब्द आहेत.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16722,20,4,'Marathi','mr','आमचे गाव (नकाशा)','[\"आमचे गाव म्हणजे गावातील विविध ठिकाणे आणि त्यांच्या स्थानांची माहिती\",\"नकाशा म्हणजे गावाचे चित्र ज्यावर घर, शाळा, बसस्थानक, वाचनालय इत्यादी चिन्हांकित असतात\",\"ग्रामपंचायत म्हणजे गावातील लोकांची सभा जिथे निर्णय घेतले जातात\",\"रस्त्यांची दिशा: पूर्व, पश्चिम, उत्तर, दक्षिण\",\"रस्त्यावरून जाण्यासाठी मार्ग निवडताना घर, शाळा, बसस्थानक इत्यादींची स्थिती लक्षात घेतली जाते\",\"रस्त्यावरून जाण्याचे मार्ग एकापेक्षा जास्त असू शकतात\",\"ग्रामपंचायत, शाळा, वाचनालय इत्यादींचे स्थान नकाशावरून ओळखता येते\",\"काळजीपूर्वक नकाशा पाहून रस्त्यांची दिशा आणि मार्ग समजून घेता येतो\",\"रस्त्यावरून जाण्याचे मार्ग लिहिताना दिशा (पूर्व, पश्चिम, उत्तर, दक्षिण) नमूद करणे आवश्यक\",\"नकाशावरून मार्ग काढण्यासाठी पेन्सिलने रेषा काढून दाखवणे\",\"ग्रामपंचायत कोणाच्या घराजवळ आहे हे ओळखण्यासाठी नकाशावरून जवळचे घर शोधा\",\"रमेशच्या घरापासून गोपाळकडे जाणारा मार्ग ओळखा आणि मार्गावर काय येते ते लिहा\",\"जोसेफच्या घरापासून बसस्थानकापर्यंत जाणारा मार्ग आणि मार्गावर काय येते ते लिहा\",\"जोसेफच्या घरापासून ग्रामपंचायतपर्यंत जाणारे विविध मार्ग आणि दिशा लिहा\",\"बसस्थानकावरून वाचनालयाकडे जाणारा मार्ग आणि मार्गावर काय येते ते लिहा\",\"मंदारच्या घरापासून शाळेपर्यंत सर्वात जवळचा मार्ग ओळखा\",\"शाळेत जाण्याचा मार्ग रेखाचित्रात दाखवा\",\"मुलांनी खाणाखुणा करून बोलणे हे शब्द न वापरता संवाद साधण्याचे उदाहरण\",\"खाणाखुणा म्हणजे हात, पाय, डोळे इत्यादींचा वापर\",\"खाणाखुणा शिकून संवाद साधणे मजेदार आणि उपयुक्त आहे\",\"नकाशा वाचून मार्ग काढणे हे विद्यार्थ्यांना भूगोलाची ओळख करून देते\"]','[{\"q\":\"ग्रामपंचायत कोणाच्या घराजवळ आहे?\",\"options\":[\"रमेशचे घर\",\"जोसेफचे घर\",\"मंदारचे घर\",\"शाळेचे घर\"],\"answer\":2,\"explain\":\"नकाशावरून ग्रामपंचायत शाळेजवळ आहे.\"},{\"q\":\"रमेशच्या घरापासून गोपाळकडे जाणाऱ्या मार्गावर काय काय येते?\",\"options\":[\"बाग\",\"तळे\",\"बाजार\",\"पुल\"],\"answer\":1,\"explain\":\"रमेशच्या घरापासून गोपाळकडे जाताना तळे येते.\"},{\"q\":\"जोसेफच्या घरापासून बसस्थानकापर्यंत कोणता मार्ग सर्वात सोपा आहे?\",\"options\":[\"उत्तर दिशेने\",\"पूर्व दिशेने\",\"दक्षिण दिशेने\",\"पश्चिम दिशेने\"],\"answer\":0,\"explain\":\"नकाशावरून उत्तर दिशेने जाणारा मार्ग सर्वात लहान आहे.\"},{\"q\":\"जोसेफच्या घरापासून ग्रामपंचायतपर्यंत जाणाऱ्या मार्गावर कोणती दिशा सर्वात योग्य आहे?\",\"options\":[\"उत्तर-पूर्व\",\"दक्षिण-पूर्व\",\"उत्तर-पश्चिम\",\"दक्षिण-पश्चिम\"],\"answer\":0,\"explain\":\"ग्रामपंचायत उत्तर-पूर्व दिशेने आहे.\"},{\"q\":\"बसस्थानकावरून वाचनालयाकडे जाणाऱ्या मार्गावर काय काय येते?\",\"options\":[\"पुस्तकालय\",\"शाळा\",\"बाजार\",\"पूल\"],\"answer\":0,\"explain\":\"वाचनालय बसस्थानकाच्या जवळ आहे.\"},{\"q\":\"मंदारच्या घरापासून शाळेपर्यंत सर्वात जवळचा मार्ग कोणता?\",\"options\":[\"पूर्व\",\"पश्चिम\",\"उत्तर\",\"दक्षिण\"],\"answer\":1,\"explain\":\"मंदारच्या घरापासून शाळेपर्यंत पश्चिम दिशेने सर्वात जवळचा मार्ग आहे.\"},{\"q\":\"खाणाखुणा म्हणजे काय?\",\"options\":[\"हाताने बोलणे\",\"डोळ्यांनी बोलणे\",\"शब्द न वापरता संवाद साधणे\",\"हातांनी लिहिणे\"],\"answer\":2,\"explain\":\"खाणाखुणा म्हणजे शब्द न वापरता संवाद साधणे.\"},{\"q\":\"खाणाखुणा शिकण्यासाठी काय करावे?\",\"options\":[\"शब्द बोलणे\",\"हात आणि पाय वापरणे\",\"कागदावर लिहिणे\",\"संगीत ऐकणे\"],\"answer\":1,\"explain\":\"खाणाखुणा शिकण्यासाठी हात आणि पाय वापरतात.\"},{\"q\":\"नकाशावरून मार्ग काढताना कोणती गोष्ट लक्षात ठेवावी?\",\"options\":[\"रंग\",\"आकार\",\"दिशा\",\"आकारमान\"],\"answer\":2,\"explain\":\"मार्ग काढताना दिशा महत्त्वाची असते.\"},{\"q\":\"शाळेत जाण्याचा मार्ग रेखाचित्रात कसा दाखवायचा?\",\"options\":[\"मजकूर लिहून\",\"पेन्सिलने रेषा काढून\",\"चित्र काढून\",\"संगीत वाजवून\"],\"answer\":1,\"explain\":\"रेखाचित्रात पेन्सिलने रेषा काढून दाखवतात.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16723,20,4,'Marathi','mr','आम्ही असेही बोलतो','[\"आम्ही असेही बोलतो या अध्यायात आपण शब्दांच्या विविध अर्थांबद्दल व त्यांच्या वापराबद्दल शिकतो.\",\"शब्दाचे अर्थ विविध प्रसंगात बदलू शकतात.\",\"उदाहरणार्थ, \'बोलणे\' या शब्दाचे अर्थ बोलणे, सांगणे, व्यक्त करणे असे असू शकतात.\",\"शब्दांचे विविध अर्थ ओळखण्यासाठी वाक्यांचा संदर्भ पाहणे महत्त्वाचे आहे.\",\"शब्दांच्या अर्थांमध्ये समानार्थी व विरुद्धार्थी शब्द ओळखणे उपयुक्त ठरते.\",\"समानार्थी शब्द म्हणजे एकसारखे अर्थ असणारे शब्द.\",\"विरुद्धार्थी शब्द म्हणजे वेगळे किंवा उलटे अर्थ असणारे शब्द.\",\"शब्दांचे अर्थ समजण्यासाठी उदाहरण वाक्ये वाचणे गरजेचे आहे.\",\"शब्दांचे अर्थ वाक्याच्या संदर्भावर अवलंबून असतात.\",\"शब्दांच्या अर्थांमध्ये बदल झाल्यास वाक्याचा अर्थही बदलतो.\",\"शब्दांच्या विविध अर्थांमुळे संवाद अधिक समृद्ध होतो.\",\"शब्दांच्या अर्थांची ओळख व वापर वाचन व लेखन कौशल्य वाढवतो.\",\"शब्दांचे अर्थ ओळखण्यासाठी शब्दकोश व संदर्भ ग्रंथ उपयुक्त असतात.\",\"शब्दांचे अर्थ वाक्याच्या भावनेवर परिणाम करतात.\",\"शब्दांच्या विविध अर्थांमुळे भाषा अधिक लवचिक व अभिव्यक्तीशील होते.\"]','[{\"q\":\"शब्दाचे विविध अर्थ ओळखण्यासाठी काय महत्त्वाचे आहे?\",\"options\":[\"वाक्याचा संदर्भ\",\"वाक्याची लांबी\",\"वाक्यातील अक्षरांची संख्या\",\"वाक्यातील शब्दांची संख्या\"],\"answer\":0,\"explain\":\"वाक्याचा संदर्भ शब्दाच्या अर्थावर प्रभाव टाकतो.\"},{\"q\":\"समानार्थी शब्द म्हणजे काय?\",\"options\":[\"वेगळे अर्थ असणारे शब्द\",\"एकसारखे अर्थ असणारे शब्द\",\"विरुद्ध अर्थ असणारे शब्द\",\"अर्थ नसणारे शब्द\"],\"answer\":1,\"explain\":\"समानार्थी शब्दांचे अर्थ एकसारखे असतात.\"},{\"q\":\"विरुद्धार्थी शब्दांचे उदाहरण काय?\",\"options\":[\"बोलणे - ऐकणे\",\"पाहणे - पाहणे\",\"वाचणे - लिहिणे\",\"सांगणे - बोलणे\"],\"answer\":0,\"explain\":\"बोलणे आणि ऐकणे हे विरुद्धार्थी शब्द आहेत.\"},{\"q\":\"शब्दांचे अर्थ समजण्यासाठी काय उपयुक्त?\",\"options\":[\"शब्दकोश\",\"कॅल्क्युलेटर\",\"रंगीत चित्रे\",\"संगीत\"],\"answer\":0,\"explain\":\"शब्दकोश शब्दांच्या अर्थांची माहिती देतो.\"},{\"q\":\"शब्दांच्या विविध अर्थांमुळे काय होते?\",\"options\":[\"भाषा अधिक लवचिक होते\",\"भाषा कठीण होते\",\"भाषा कमी होते\",\"भाषा बदलत नाही\"],\"answer\":0,\"explain\":\"विविध अर्थांमुळे भाषा अधिक लवचिक व अभिव्यक्तीशील होते.\"},{\"q\":\"शब्दांचे अर्थ ओळखण्यासाठी काय मदत करते?\",\"options\":[\"उदाहरण वाक्ये\",\"चित्रपट\",\"संगीत\",\"कविता\"],\"answer\":0,\"explain\":\"उदाहरण वाक्ये शब्दाचे अर्थ स्पष्ट करतात.\"},{\"q\":\"शब्दांचे अर्थ वाक्याच्या भावनेवर कसा परिणाम करतात?\",\"options\":[\"भावना बदलते\",\"भावना समान राहते\",\"भावना कमी होते\",\"भावना वाढते\"],\"answer\":0,\"explain\":\"शब्दाचे अर्थ वाक्याची भावना बदलू शकतात.\"},{\"q\":\"शब्दकोशाचा उपयोग काय?\",\"options\":[\"शब्दांचे अर्थ शोधणे\",\"गणिताचे प्रश्न सोडवणे\",\"संगीत वाजवणे\",\"चित्र काढणे\"],\"answer\":0,\"explain\":\"शब्दकोश शब्दांचे अर्थ शोधण्यासाठी वापरला जातो.\"},{\"q\":\"शब्दांचे अर्थ ओळखण्यासाठी काय महत्त्वाचे?\",\"options\":[\"वाक्याचा संदर्भ\",\"वाक्याची लांबी\",\"वाक्यातील अक्षरांची संख्या\",\"वाक्यातील शब्दांची संख्या\"],\"answer\":0,\"explain\":\"वाक्याचा संदर्भ शब्दाच्या अर्थावर प्रभाव टाकतो.\"},{\"q\":\"शब्दांचे विविध अर्थ ओळखणे का महत्त्वाचे?\",\"options\":[\"वाचन व लेखन कौशल्य वाढते\",\"वाचन व लेखन कौशल्य कमी होते\",\"फक्त बोलण्यात मदत होते\",\"फक्त लिहिण्यात मदत होते\"],\"answer\":0,\"explain\":\"विविध अर्थ ओळखल्याने वाचन व लेखन कौशल्य सुधारते.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16724,20,4,'Marathi','mr','थोर हुतात्मे','[\"सुखदेव आणि भगतसिंग हे तरुण क्रांतिकारी होते.\",\"त्यांनी ‘हिंदुस्थान सोशॅलिस्ट रिपब्लिकन असोसिएशन’ नावाची संघटना उभारली.\",\"या संघटनेचे उद्दिष्ट भारताला ब्रिटिश शोषणातून मुक्त करणे होते.\",\"सुखदेवाने लाहोरमध्ये ‘नौजवान भारत सभा’ स्थापन केली.\",\"या संघटनेचे कार्यक्रम: स्वातंत्र्यलढ्यासाठी तरुणांना प्रोत्साहन, तर्कसंगत वैज्ञानिक दृष्टी, जातीयतेविरुद्ध लढा आणि अस्पृश्यतेची प्रथा बंद करणे.\",\"भगतसिंगांनी लाहोरच्या तुरुंगात तीन क्रांतिवीरांना घोषणा दिली.\",\"१९२८ मध्ये लाहोरमध्ये ‘नौजवान भारत सभा’ विरोधात निदर्शने झाली.\",\"सुखदेव आणि भगतसिंग यांनी ‘नौजवान भारत सभा’ स्थापन करण्यास एकमेकांची मदत घेतली.\",\"राजगुरू हे ‘हुतात्मा’ होते आणि त्यांचा जन्मगाव ‘खेड’ चे नाव ‘राजगुरूनगर’ असे बदलले.\",\"राजगुरू यांनी बनारसच्या वास्तव्यात विविध कार्ये केली.\",\"सुखदेवाने लाहोरच्या तुरुंगात कैद्यांच्या अमानुष वागणुकीबद्दल उपोषण केले.\",\"सुखदेवाला लाहोर खटल्यात माफीचा साक्षीदार होण्यास सांगण्यात आले पण त्यांनी नाकारले.\",\"सुखदेव आणि भगतसिंग यांनी लाहोरच्या तुरुंगात कैद्यांना मदत करण्यासाठी विविध उपाय केले.\",\"सुखदेव आणि भगतसिंग यांनी ‘नौजवान भारत सभा’ च्या कार्यक्रमात ‘जातीयतेविरुद्ध लढा’ आणि ‘अस्पृश्यतेची प्रथा बंद करणे’ यांचा समावेश केला.\",\"सुखदेव आणि भगतसिंग यांनी लाहोरच्या तुरुंगात कैद्यांना मदत करण्यासाठी ‘सहकारी’ आणि ‘सहभाग’ यांचा वापर केला.\",\"सुखदेव आणि भगतसिंग यांनी ‘नौजवान भारत सभा’ च्या कार्यक्रमात ‘स्वातंत्र्यलढ्यासाठी तरुणांना प्रोत्साहन’ आणि ‘तर्कसंगत वैज्ञानिक दृष्टी’ यांचा समावेश केला.\",\"सुखदेव आणि भगतसिंग यांनी ‘नौजवान भारत सभा’ च्या कार्यक्रमात ‘जातीयतेविरुद्ध लढा’ आणि ‘अस्पृश्यतेची प्रथा बंद करणे’ यांचा समावेश केला.\",\"सुखदेव आणि भगतसिंग यांनी ‘नौजवान भारत सभा’ च्या कार्यक्रमात ‘स्वातंत्र्यलढ्यासाठी तरुणांना प्रोत्साहन’ आणि ‘तर्कसंगत वैज्ञानिक दृष्टी’ यांचा समावेश केला.\",\"सुखदेव आणि भगतसिंग यांनी ‘नौजवान भारत सभा’ च्या कार्यक्रमात ‘जातीयतेविरुद्ध लढा’ आणि ‘अस्पृश्यतेची प्रथा बंद करणे’ यांचा समावेश केला.\",\"सुखदेव आणि भगतसिंग यांनी ‘नौजवान भारत सभा’ च्या कार्यक्रमात ‘स्वातंत्र्यलढ्यासाठी तरुणांना प्रोत्साहन’ आणि ‘तर्कसंगत वैज्ञानिक दृष्टी’ यांचा समावेश केला.\",\"सुखदेव आणि भगतसिंग यांनी ‘नौजवान भारत सभा’ च्या कार्यक्रमात ‘जातीयतेविरुद्ध लढा’ आणि ‘अस्पृश्यतेची प्रथा बंद करणे’ यांचा समावेश केला.\",\"सुखदेव आणि भगतसिंग यांनी ‘नौजवान भारत सभा’ च्या कार्यक्रमात ‘स्वातंत्र्यलढ्यासाठी तरुणांना प्रोत्साहन’ आणि ‘तर्कसंगत वैज्ञानिक दृष्टी’ यांचा समावेश केला.\"]','[{\"q\":\"सुखदेव आणि भगतसिंग यांनी लाहोरच्या तुरुंगात कोणती घोषणा दिली?\",\"options\":[\"स्वातंत्र्याची घोषणा\",\"सामाजिक न्यायाची घोषणा\",\"राजकीय स्वातंत्र्याची घोषणा\",\"आर्थिक स्वातंत्र्याची घोषणा\"],\"answer\":2,\"explain\":\"त्यांनी राजकीय स्वातंत्र्याची घोषणा दिली.\"},{\"q\":\"१९२८ मध्ये लाहोरमध्ये कोणत्या विरोधात निदर्शने झाली?\",\"options\":[\"ब्रिटिश सरकारच्या धोरणाविरुद्ध\",\"सुखदेवच्या उपोषणाविरुद्ध\",\"भगतसिंगच्या शिक्षणाविरुद्ध\",\"सुखदेवच्या नावावर\"],\"answer\":0,\"explain\":\"लाहोरमध्ये ब्रिटिश सरकारच्या धोरणाविरुद्ध निदर्शने झाली.\"},{\"q\":\"भगतसिंगांनी कोणकोणत्या महाविद्यालयांत शिक्षण घेतले?\",\"options\":[\"कानपूर, चौराबाजार\",\"बंग, खेड\",\"चौराबाजार, बंग\",\"कानपूर, खेड\"],\"answer\":3,\"explain\":\"भगतसिंगांनी कानपूर आणि खेड या महाविद्यालयांत शिक्षण घेतले.\"},{\"q\":\"सुखदेवांनी ‘नौजवान भारत सभा’ स्थापन करण्यास कोणाची मदत घेतली?\",\"options\":[\"भगतसिंग\",\"सुखदेव स्वतः\",\"सुखदेव आणि भगतसिंग दोघेही\",\"सुखदेव आणि इतर विद्यार्थी\"],\"answer\":0,\"explain\":\"सुखदेवांनी भगतसिंगची मदत घेतली.\"},{\"q\":\"राजगुरू यांनी बनारसच्या वास्तव्यात काय केले?\",\"options\":[\"सामाजिक कार्य\",\"राजकीय कार्य\",\"साहित्यिक कार्य\",\"सर्व कार्ये\"],\"answer\":3,\"explain\":\"राजगुरू यांनी सर्व कार्ये केली.\"},{\"q\":\"सुखदेवाने लाहोरच्या तुरुंगात कैद्यांना मदत करण्यासाठी काय केले?\",\"options\":[\"उपोषण\",\"सहकारी\",\"सहभाग\",\"सर्व\"],\"answer\":3,\"explain\":\"सुखदेवाने सर्व उपाय केले.\"},{\"q\":\"सुखदेव आणि भगतसिंग यांनी ‘नौजवान भारत सभा’ च्या कार्यक्रमात काय समाविष्ट केले?\",\"options\":[\"स्वातंत्र्यलढ्यासाठी तरुणांना प्रोत्साहन\",\"जातीयतेविरुद्ध लढा\",\"अस्पृश्यतेची प्रथा बंद करणे\",\"वरील सर्व\"],\"answer\":3,\"explain\":\"सर्व तीन गोष्टी समाविष्ट केल्या.\"},{\"q\":\"सुखदेव आणि भगतसिंग यांनी लाहोरच्या तुरुंगात कैद्यांना मदत करण्यासाठी कोणते उपाय केले?\",\"options\":[\"सहकारी\",\"सहभाग\",\"दोन्ही\",\"काहीही नाही\"],\"answer\":2,\"explain\":\"दोन्ही उपाय केले.\"},{\"q\":\"राजगुरू यांच्या जन्मगावाचे नाव बदलून काय केले?\",\"options\":[\"खेड\",\"राजगुरूनगर\",\"खेडराजगुरू\",\"राजगुरू\"],\"answer\":1,\"explain\":\"खेडचे नाव राजगुरूनगर असे बदलले.\"},{\"q\":\"सुखदेव आणि भगतसिंग यांनी ‘नौजवान भारत सभा’ च्या कार्यक्रमात कोणते सामाजिक कार्य समाविष्ट केले?\",\"options\":[\"जातीयतेविरुद्ध लढा\",\"अस्पृश्यतेची प्रथा बंद करणे\",\"दोन्ही\",\"काहीही नाही\"],\"answer\":2,\"explain\":\"दोन्ही सामाजिक कार्ये समाविष्ट केली.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16725,20,4,'Marathi','mr','संतवाणी संत तुकाराम','[\"संत तुकाराम हे मराठीतील महान संत आणि कवी होते.\",\"त्यांना संतवाणी म्हणून ओळखले जाते.\",\"संत तुकाराम यांनी ‘संतवाणी’ या पुस्तकात आपले विचार आणि शिकवण लिहिली.\",\"त्यांची भाषा साधी, स्पष्ट आणि सर्वसामान्य लोकांना समजणारी होती.\",\"त्यांनी ‘संतवाणी’ मध्ये भक्ति, नैतिकता आणि समाज सुधारणा यावर भर दिला.\",\"संत तुकाराम यांची जन्म तारीख १६०३ मध्ये झाली.\",\"त्यांनी १६४० मध्ये ‘संतवाणी’ प्रकाशित केली.\",\"संत तुकाराम यांना ‘संतवाणी’ मध्ये ‘संतवाणी’ हे नाव दिले.\",\"संत तुकाराम यांनी ‘संतवाणी’ मध्ये ‘संतवाणी’ या शब्दाचा अर्थ ‘संताचे वाणी’ असा घेतला.\",\"संत तुकाराम यांनी ‘संतवाणी’ मध्ये ‘संतवाणी’ या शब्दाचा अर्थ ‘संताचे वाणी’ असा घेतला.\",\"संत तुकाराम यांनी ‘संतवाणी’ मध्ये ‘संतवाणी’ या शब्दाचा अर्थ ‘संताचे वाणी’ असा घेतला.\",\"संत तुकाराम यांनी ‘संतवाणी’ मध्ये ‘संतवाणी’ या शब्दाचा अर्थ ‘संताचे वाणी’ असा घेतला.\",\"संत तुकाराम यांनी ‘संतवाणी’ मध्ये ‘संतवाणी’ या शब्दाचा अर्थ ‘संताचे वाणी’ असा घेतला.\",\"संत तुकाराम यांनी ‘संतवाणी’ मध्ये ‘संतवाणी’ या शब्दाचा अर्थ ‘संताचे वाणी’ असा घेतला.\",\"संत तुकाराम यांनी ‘संतवाणी’ मध्ये ‘संतवाणी’ या शब्दाचा अर्थ ‘संताचे वाणी’ असा घेतला.\",\"संत तुकाराम यांनी ‘संतवाणी’ मध्ये ‘संतवाणी’ या शब्दाचा अर्थ ‘संताचे वाणी’ असा घेतला.\",\"संत तुकाराम यांनी ‘संतवाणी’ मध्ये ‘संतवाणी’ या शब्दाचा अर्थ ‘संताचे वाणी’ असा घेतला.\",\"संत तुकाराम यांनी ‘संतवाणी’ मध्ये ‘संतवाणी’ या शब्दाचा अर्थ ‘संताचे वाणी’ असा घेतला.\",\"संत तुकाराम यांनी ‘संतवाणी’ मध्ये ‘संतवाणी’ या शब्दाचा अर्थ ‘संताचे वाणी’ असा घेतला.\",\"संत तुकाराम यांनी ‘संतवाणी’ मध्ये ‘संतवाणी’ या शब्दाचा अर्थ ‘संताचे वाणी’ असा घेतला.\",\"संत तुकाराम यांनी ‘संतवाणी’ मध्ये ‘संतवाणी’ या शब्दाचा अर्थ ‘संताचे वाणी’ असा घेतला.\",\"संत तुकाराम यांनी ‘संतवाणी’ मध्ये ‘संतवाणी’ या शब्दाचा अर्थ ‘संताचे वाणी’ असा घेतला.\",\"संत तुकाराम यांनी ‘संतवाणी’ मध्ये ‘संतवाणी’ या शब्दाचा अर्थ ‘संताचे वाणी’ असा घेतला.\"]','[{\"q\":\"संत तुकाराम यांचा जन्म कोणत्या वर्षी झाला?\",\"options\":[\"1603\",\"1620\",\"1580\",\"1640\"],\"answer\":0,\"explain\":\"संत तुकाराम यांचा जन्म 1603 मध्ये झाला.\"},{\"q\":\"संत तुकाराम यांनी कोणते पुस्तक लिहिले?\",\"options\":[\"संतवाणी\",\"काव्यशाला\",\"भक्तवाणी\",\"संतकथा\"],\"answer\":0,\"explain\":\"संत तुकाराम यांनी ‘संतवाणी’ हे पुस्तक लिहिले.\"},{\"q\":\"संत तुकाराम यांनी ‘संतवाणी’ मध्ये कोणत्या विषयावर भर दिला?\",\"options\":[\"भक्ति\",\"नैतिकता\",\"समाज सुधारणा\",\"वरील सर्व\"],\"answer\":3,\"explain\":\"संत तुकाराम यांनी ‘संतवाणी’ मध्ये भक्ति, नैतिकता आणि समाज सुधारणा यावर भर दिला.\"},{\"q\":\"संत तुकाराम यांना कोणत्या नावाने ओळखले जाते?\",\"options\":[\"संतवाणी\",\"संतकवि\",\"भक्तसंत\",\"संतवाणी\"],\"answer\":0,\"explain\":\"संत तुकाराम यांना ‘संतवाणी’ म्हणून ओळखले जाते.\"},{\"q\":\"संत तुकाराम यांनी ‘संतवाणी’ मध्ये ‘संतवाणी’ या शब्दाचा अर्थ काय घेतला?\",\"options\":[\"संताचे वाणी\",\"संताचे शब्द\",\"संताचे गाणे\",\"संताचे जीवन\"],\"answer\":0,\"explain\":\"‘संतवाणी’ मध्ये ‘संतवाणी’ या शब्दाचा अर्थ ‘संताचे वाणी’ असा घेतला.\"},{\"q\":\"संत तुकाराम यांनी ‘संतवाणी’ मध्ये कोणत्या प्रकारची भाषा वापरली?\",\"options\":[\"साधी\",\"जटिल\",\"अभिजात\",\"शास्त्रीय\"],\"answer\":0,\"explain\":\"संत तुकाराम यांनी ‘संतवाणी’ मध्ये साधी भाषा वापरली.\"},{\"q\":\"संत तुकाराम यांनी ‘संतवाणी’ मध्ये कोणते मुख्य संदेश दिले?\",\"options\":[\"भक्ति आणि नैतिकता\",\"सामाजिक न्याय\",\"शिक्षण\",\"वरील सर्व\"],\"answer\":3,\"explain\":\"संत तुकाराम यांनी ‘संतवाणी’ मध्ये भक्ति, नैतिकता आणि सामाजिक न्याय यावर भर दिला.\"},{\"q\":\"संत तुकाराम यांची ‘संतवाणी’ कोणत्या वर्षी प्रकाशित झाली?\",\"options\":[\"1640\",\"1650\",\"1620\",\"1630\"],\"answer\":0,\"explain\":\"संत तुकाराम यांनी 1640 मध्ये ‘संतवाणी’ प्रकाशित केली.\"},{\"q\":\"संत तुकाराम यांना कोणत्या संज्ञेने ओळखले जाते?\",\"options\":[\"संतवाणी\",\"संतकवि\",\"भक्तसंत\",\"संतवाणी\"],\"answer\":0,\"explain\":\"संत तुकाराम यांना ‘संतवाणी’ म्हणून ओळखले जाते.\"},{\"q\":\"संत तुकाराम यांनी ‘संतवाणी’ मध्ये कोणत्या विषयावर चर्चा केली?\",\"options\":[\"भक्ति\",\"नैतिकता\",\"समाज सुधारणा\",\"वरील सर्व\"],\"answer\":3,\"explain\":\"संत तुकाराम यांनी ‘संतवाणी’ मध्ये भक्ति, नैतिकता आणि समाज सुधारणा यावर चर्चा केली.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16726,21,4,'Maths','en','Geometrical Figures','[\"Angles are formed when two lines meet.\",\"A right angle is exactly 90° and is seen at corners of a book, a window, a clock at 3 or 9 o’clock, and the blades of scissors when closed.\",\"An acute angle is less than 90° – for example the angle between the blades of scissors when they are almost closed.\",\"An obtuse angle is more than 90° – for example when the scissors blades are almost open.\",\"The angle made by an electric pole or a ladder with the ground can be right, acute or obtuse depending on the situation.\",\"A triangle has 3 vertices, 3 sides and 3 angles.\",\"A rectangle has 4 sides, 4 vertices, opposite sides equal and all angles right angles.\",\"A square has 4 equal sides, 4 equal angles (all right angles).\",\"A circle has a centre, a radius (line from centre to any point on the circle), a diameter (a radius that passes through the centre and ends on the circle) and any chord (a line joining two points on the circle).\",\"The centre of a circle can be found by folding a paper circle twice; the intersection of the two folds is the centre.\",\"A diameter is also a special type of chord that passes through the centre.\",\"The radius is half the length of the diameter.\",\"A chord that is not a diameter is called a normal chord.\",\"A circle can be drawn by using a compass or by tracing a circular object.\",\"The number of sides of a shape is the count of its straight edges.\",\"The number of corners (vertices) is the count of points where two sides meet.\",\"In a rectangle, opposite sides are equal in length.\",\"In a square, all four sides are equal.\",\"In a triangle, the sum of the three interior angles is 180°.\",\"Angles can be found in everyday objects like ladders, trees, and scissors.\",\"When you fold a paper circle twice, the two fold lines are diameters and they meet at the centre.\",\"The centre of a circle is the point from which all radii are equal.\",\"The radius is the distance from the centre to any point on the circle.\",\"A chord is any straight line segment whose endpoints lie on the circle.\",\"A diameter is a chord that passes through the centre.\"]','[{\"q\":\"Which angle is 90°?\",\"options\":[\"Acute\",\"Obtuse\",\"Right\",\"None\"],\"answer\":2,\"explain\":\"A right angle measures 90°.\"},{\"q\":\"The angle between the blades of scissors when they are almost closed is an?\",\"options\":[\"Acute\",\"Obtuse\",\"Right\",\"None\"],\"answer\":0,\"explain\":\"When almost closed the angle is less than 90°.\"},{\"q\":\"What is the name of the line that passes through the centre of a circle and ends on the circle?\",\"options\":[\"Chord\",\"Radius\",\"Diameter\",\"Arc\"],\"answer\":1,\"explain\":\"A radius is a line from centre to any point on the circle.\"},{\"q\":\"A rectangle has how many sides?\",\"options\":[\"2\",\"3\",\"4\",\"5\"],\"answer\":2,\"explain\":\"A rectangle has four sides.\"},{\"q\":\"Which of the following is NOT a type of angle?\",\"options\":[\"Acute\",\"Obtuse\",\"Right\",\"Parallel\"],\"answer\":3,\"explain\":\"Parallel is not an angle type.\"},{\"q\":\"The sum of the interior angles of a triangle is?\",\"options\":[\"90°\",\"180°\",\"270°\",\"360°\"],\"answer\":1,\"explain\":\"Three angles add up to 180°.\"},{\"q\":\"Which shape has all sides equal and all angles right?\",\"options\":[\"Triangle\",\"Rectangle\",\"Square\",\"Circle\"],\"answer\":2,\"explain\":\"A square has equal sides and right angles.\"},{\"q\":\"What is the intersection point of two diameters in a circle?\",\"options\":[\"Vertex\",\"Centre\",\"Chord\",\"Radius\"],\"answer\":1,\"explain\":\"The two diameters meet at the centre.\"},{\"q\":\"An angle that is more than 90° is called?\",\"options\":[\"Acute\",\"Obtuse\",\"Right\",\"None\"],\"answer\":1,\"explain\":\"Obtuse angles are greater than 90°.\"},{\"q\":\"The line joining two points on a circle that does not pass through the centre is called?\",\"options\":[\"Diameter\",\"Radius\",\"Chord\",\"Arc\"],\"answer\":2,\"explain\":\"Any such line is a chord.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16727,21,4,'Maths','en','Number Work','[\"- A number is a symbol that tells how many things are there.\",\"- Digits 0 to 9 are the building blocks of all numbers.\",\"- The place of a digit tells its value: thousands, hundreds, tens, units.\",\"- In a four‑digit number, the leftmost digit is in the thousands place.\",\"- 0 can be used in any place except the first (hundreds) of a three‑digit number.\",\"- To read a number, start from the leftmost digit and say its place value.\",\"- 1,000 is called a thousand, 10,000 a ten‑thousand, 100,000 a hundred‑thousand.\",\"- The word “and” is used before the last part of a number (e.g., one hundred and twenty‑five).\",\"- Expanded form writes a number as a sum of its place values (e.g., 5,324 = 5,000 + 300 + 20 + 4).\",\"- Even numbers leave no remainder when divided by 2; odd numbers leave a remainder of 1.\",\"- The smallest digit in a number can be used to make the units place in a new number.\",\"- Numbers can be rearranged to make new numbers; each digit can be used only once.\",\"- To compare two numbers, look at the leftmost different digit.\",\"- A number with more digits is always larger than a number with fewer digits.\",\"- In India, numbers on money and transport are written in English so everyone can read them.\"]','[{\"q\":\"Which digit is in the thousands place of 4,028?\",\"options\":[\"4\",\"0\",\"2\",\"8\"],\"answer\":0,\"explain\":\"The leftmost digit of a four‑digit number is the thousands place.\"},{\"q\":\"What is the expanded form of 5,324?\",\"options\":[\"5,000 + 300 + 20 + 4\",\"5,000 + 300 + 2 + 4\",\"5,000 + 30 + 20 + 4\",\"5,000 + 300 + 200 + 4\"],\"answer\":0,\"explain\":\"5,324 = 5 thousand + 3 hundred + 2 tens + 4 units.\"},{\"q\":\"Which of these numbers is odd?\",\"options\":[\"12\",\"23\",\"40\",\"54\"],\"answer\":1,\"explain\":\"23 ends in 3, an odd digit.\"},{\"q\":\"How many digits are in the number 78,999?\",\"options\":[\"4\",\"5\",\"6\",\"7\"],\"answer\":1,\"explain\":\"78,999 has five digits.\"},{\"q\":\"What is the next number after 1,999?\",\"options\":[\"1,998\",\"2,000\",\"1,999\",\"2,001\"],\"answer\":1,\"explain\":\"Adding 1 gives 2,000.\"},{\"q\":\"Which of these is a thousand?\",\"options\":[\"1,000\",\"10,000\",\"100,000\",\"1,000,000\"],\"answer\":0,\"explain\":\"1,000 is called a thousand.\"},{\"q\":\"Which number is the largest?\",\"options\":[\"9,999\",\"10,000\",\"10,001\",\"9,998\"],\"answer\":2,\"explain\":\"10,001 has more digits than 9,999.\"},{\"q\":\"What is the units digit of 4,876?\",\"options\":[\"4\",\"6\",\"7\",\"8\"],\"answer\":1,\"explain\":\"The rightmost digit is 6.\"},{\"q\":\"Write the number 62,037 in words.\",\"options\":[\"Sixty-two thousand thirty-seven\",\"Sixty-two thousand and thirty-seven\",\"Sixty-two thousand and thirty-seven units\",\"Sixty-two thousand and thirty-seven tens\"],\"answer\":0,\"explain\":\"Read from left to right: 62 thousand, 0 hundred, 3 tens, 7 units.\"},{\"q\":\"Which of these is an even number?\",\"options\":[\"35\",\"67\",\"32\",\"30\"],\"answer\":3,\"explain\":\"30 ends in 0, an even digit.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16728,21,4,'Maths','en','Addition','[\"Addition is adding numbers together to get a sum.\",\"When adding, start from the rightmost column – units, then tens, hundreds, thousands, etc.\",\"Carry over is used when a column adds up to 10 or more – write the remainder and carry the tens to the next column left.\",\"In vertical addition, write each number in its own line, aligning the same place values.\",\"In horizontal addition, write the numbers side by side and add each column from right to left.\",\"When adding more than two numbers, add them one pair at a time or add all columns together.\",\"The result of adding 3, 4, and 5 is 12 – 3+4=7, 7+5=12.\",\"If a column sums to 15, write 5 and carry 1 to the next column.\",\"Adding 1000 and 2000 gives 3000 – thousands add to thousands.\",\"When adding a single digit to a number, place it under the units column.\",\"The sum of 12 and 8 is 20 – 2 units, carry 1 to tens.\",\"When adding 5 and 7, you get 12 – write 2 and carry 1.\",\"Adding 500 and 300 gives 800 – hundreds add to hundreds.\",\"When adding 0 to any number, the number stays the same.\",\"In a 4‑digit addition, the leftmost column is the thousands place.\",\"Adding 999 + 1 gives 1000 – a new place value appears.\",\"When adding 3 numbers, you can add the first two, then add the third to the result.\",\"Adding 0 to a number does not change the number.\",\"When adding 10 and 20, the result is 30 – tens add to tens.\",\"Adding 100 and 200 gives 300 – hundreds add to hundreds.\",\"When adding 1000 and 2000, the result is 3000 – thousands add to thousands.\",\"Adding 123 and 456 gives 579 – units, tens, hundreds added separately.\"]','[{\"q\":\"What is the sum of 342 and 123?\",\"options\":[\"465\",\"4650\",\"4652\",\"4653\"],\"answer\":0,\"explain\":\"Add units 2+3=5, tens 4+2=6, hundreds 3+1=4 → 465.\"},{\"q\":\"When adding 170 and 200, which place value is added first?\",\"options\":[\"Units\",\"Tens\",\"Hundreds\",\"Thousands\"],\"answer\":0,\"explain\":\"Start with units: 0+0=0.\"},{\"q\":\"Which of the following is the correct vertical addition of 2301 + 4056?\",\"options\":[\"6357\",\"6358\",\"6359\",\"6360\"],\"answer\":0,\"explain\":\"Units 1+6=7, tens 0+5=5, hundreds 3+0=3, thousands 2+4=6 → 6357.\"},{\"q\":\"In horizontal addition, what is 7006 + 2193?\",\"options\":[\"9199\",\"9198\",\"9197\",\"9200\"],\"answer\":0,\"explain\":\"Add units 6+3=9, tens 0+9=9, hundreds 0+1=1, thousands 7+2=9 → 9199.\"},{\"q\":\"Match the equal numbers: 14,000 + 300 equals ___?\",\"options\":[\"14,300\",\"14,000\",\"14,300\",\"14,300\"],\"answer\":0,\"explain\":\"14,000 + 300 = 14,300.\"},{\"q\":\"What is the result of 5689 + 135?\",\"options\":[\"5824\",\"5825\",\"5826\",\"5827\"],\"answer\":0,\"explain\":\"Add units 9+5=14 carry 1, tens 8+3+1=12 carry 1, hundreds 6+1+1=8, thousands 5+0=5 → 5824.\"},{\"q\":\"Which is the correct sum of 7859 + 8546?\",\"options\":[\"16405\",\"16404\",\"16406\",\"16407\"],\"answer\":0,\"explain\":\"Add units 9+6=15 carry 1, tens 5+4+1=10 carry 1, hundreds 8+5+1=14 carry 1, thousands 7+8+1=16 → 16405.\"},{\"q\":\"In the addition 24558 + 37, where should the 3 (tens) be written?\",\"options\":[\"Units place\",\"Tens place\",\"Hundreds place\",\"Thousands place\"],\"answer\":1,\"explain\":\"37 has 3 tens, so write 3 under the tens column.\"},{\"q\":\"What is 27005 + 1238?\",\"options\":[\"28243\",\"28244\",\"28242\",\"28245\"],\"answer\":0,\"explain\":\"Add units 5+8=13 carry 1, tens 0+3+1=4, hundreds 0+2=2, thousands 7+1=8, ten‑thousands 2+0=2 → 28243.\"},{\"q\":\"Which of these is the correct result of 4000 + 1600 + 800 + 80 + 320 + 32?\",\"options\":[\"70232\",\"70232\",\"70232\",\"70232\"],\"answer\":0,\"explain\":\"Add all parts: 4000+1600=5600, +800=6400, +80=6480, +320=6800, +32=6832 → 6832.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16729,21,4,'Maths','en','Subtraction','[\"Subtraction is taking away one number from another.\",\"To subtract, line up the numbers by place value: units, tens, hundreds, thousands.\",\"Start from the rightmost column (units).\",\"If the top digit is smaller than the bottom, borrow 1 from the next left column.\",\"Borrowing means turning 1 of the next column into 10 of the current column.\",\"After borrowing, subtract the digits in each column.\",\"Write the result below each column.\",\"If a column becomes 0 after borrowing, it may be omitted in the final answer.\",\"Subtracting 0 from any number gives the number itself.\",\"When subtracting equal numbers, the answer is 0.\",\"Subtracting a smaller number from a larger one gives a positive difference.\",\"Subtracting a larger number from a smaller one gives a negative result (not used in this book).\",\"The difference is the amount by which the first number exceeds the second.\",\"Use mental subtraction for small numbers by counting backwards.\",\"Use mental subtraction for larger numbers by borrowing mentally.\",\"Check the answer by adding the difference to the smaller number to see if you get the larger number.\",\"Practice with word problems to apply subtraction in real life.\"]','[{\"q\":\"What do you do if the top digit in a column is smaller than the bottom digit?\",\"options\":[\"Add 10 to the top digit and borrow 1 from the next column\",\"Subtract 1 from the bottom digit\",\"Ignore the column\",\"Write 0 in the result\"],\"answer\":0,\"explain\":\"You borrow 1 from the next left column, turning it into 10 of the current column.\"},{\"q\":\"How many more neem trees must be planted to have the same number as teak trees if there are 452 teak trees and 321 neem trees?\",\"options\":[\"131\",\"1310\",\"321\",\"452\"],\"answer\":0,\"explain\":\"Subtract 321 from 452 to get 131.\"},{\"q\":\"If Ajay has 207 seeds and Vijay has 165 seeds, how many more seeds does Ajay have?\",\"options\":[\"42\",\"42.5\",\"42.0\",\"42.2\"],\"answer\":0,\"explain\":\"207 minus 165 equals 42.\"},{\"q\":\"Which of the following is a correct subtraction problem with answer 200?\",\"options\":[\"500 – 300\",\"400 – 200\",\"600 – 400\",\"300 – 100\"],\"answer\":1,\"explain\":\"400 minus 200 equals 200.\"},{\"q\":\"What is the difference between 9072 and 7548?\",\"options\":[\"1524\",\"1525\",\"1523\",\"1526\"],\"answer\":0,\"explain\":\"9072 minus 7548 equals 1524.\"},{\"q\":\"When borrowing from the thousands column, how many hundreds do you get?\",\"options\":[\"10\",\"9\",\"8\",\"7\"],\"answer\":0,\"explain\":\"1 thousand equals 10 hundreds.\"},{\"q\":\"If 5000 – 2000 = 3000, what is 5888 – 2888?\",\"options\":[\"3000\",\"3001\",\"3002\",\"3003\"],\"answer\":0,\"explain\":\"Subtracting 2888 from 5888 gives 3000.\"},{\"q\":\"Which of these is a correct subtraction word problem using 534 and 252?\",\"options\":[\"How many more apples are in 534 than in 252?\",\"How many fewer apples are in 534 than in 252?\",\"How many more apples are in 252 than in 534?\",\"How many fewer apples are in 252 than in 534?\"],\"answer\":0,\"explain\":\"534 minus 252 gives the number of apples more in 534.\"},{\"q\":\"What is the result of 5000 – 967?\",\"options\":[\"4033\",\"4034\",\"4032\",\"4035\"],\"answer\":0,\"explain\":\"Subtracting 967 from 5000 gives 4033.\"},{\"q\":\"If you subtract 28 from 53 by counting forward, how many numbers do you add?\",\"options\":[\"25\",\"24\",\"23\",\"26\"],\"answer\":0,\"explain\":\"Adding 2, 20, and 3 (total 25) to 28 gives 53.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16730,21,4,'Maths','en','Multiplication : Part 1','[\"Multiplication is repeated addition.\",\"A dozen means 12.\",\"Eight dozen = 8 × 12 = 96.\",\"To multiply two numbers, you can use the lattice method or the standard algorithm.\",\"When multiplying a whole hundred (like 300) by another number, multiply the hundreds digit and add two zeros to the product.\",\"Example: 300 × 4 = 3 × 4 = 12 → 1200 (add two zeros).\",\"When multiplying a number ending in 0 by another number, you can ignore the zero, multiply the remaining part, and then add a zero to the result.\",\"Example: 40 × 300 = (4 × 3) = 12 → 12000 (add three zeros).\",\"Multiplying a number by 10, 100, 1000 etc. just adds zeros to the right of the number.\",\"If you multiply a number by 1, the result is the number itself.\",\"Multiplying by 0 gives 0.\",\"When you have a number like 245, you can break it into 200 + 40 + 5 and multiply each part separately.\",\"Add the partial products to get the final answer.\",\"The product of 244 × 28 is 6832 seedlings planted.\",\"The product of 709 × 76 is 53884.\",\"Multiplying 819 × 12 gives 9828.\",\"Multiplying 545 × 38 gives 20710.\",\"Multiplying 953 × 38 gives 36174.\",\"Multiplying 610 × 45 gives 27450.\",\"Multiplying 407 × 55 gives 22385.\",\"Multiplying 781 × 90 gives 70290.\",\"If 31 students each give 175, the teacher gets 31 × 175 = 5425.\",\"If a van has 205 crates and each crate has 48 mangoes, total mangoes = 205 × 48 = 9840.\"]','[{\"q\":\"How many bananas are in eight dozen?\",\"options\":[\"96\",\"84\",\"108\",\"120\"],\"answer\":0,\"explain\":\"Eight dozen means 8 × 12.\"},{\"q\":\"What is 37 × 15?\",\"options\":[\"555\",\"525\",\"585\",\"615\"],\"answer\":0,\"explain\":\"Multiplying 37 by 15 gives 555.\"},{\"q\":\"What is 300 × 4?\",\"options\":[\"1200\",\"120\",\"3000\",\"4000\"],\"answer\":0,\"explain\":\"300 is 3 hundreds; 3 × 4 = 12 → 1200.\"},{\"q\":\"What is 40 × 300?\",\"options\":[\"12000\",\"1200\",\"3000\",\"40000\"],\"answer\":0,\"explain\":\"3 × 4 = 12, add three zeros → 12000.\"},{\"q\":\"What is 245 × 8?\",\"options\":[\"1960\",\"1840\",\"196\",\"2450\"],\"answer\":0,\"explain\":\"245 = 200+40+5; multiply each by 8 and add.\"},{\"q\":\"What is 124 × 3?\",\"options\":[\"372\",\"312\",\"424\",\"324\"],\"answer\":0,\"explain\":\"3 × 124 = 372.\"},{\"q\":\"What is the cost of 4 chairs if one chair costs 650?\",\"options\":[\"2600\",\"650\",\"1300\",\"5200\"],\"answer\":0,\"explain\":\"4 × 650 = 2600.\"},{\"q\":\"How many mangoes are in a van with 205 crates of 48 each?\",\"options\":[\"9840\",\"10000\",\"9500\",\"9000\"],\"answer\":0,\"explain\":\"205 × 48 = 9840.\"},{\"q\":\"If 31 students each give 175, how much does the teacher get?\",\"options\":[\"5425\",\"5250\",\"5750\",\"5000\"],\"answer\":0,\"explain\":\"31 × 175 = 5425.\"},{\"q\":\"What is 709 × 76?\",\"options\":[\"53884\",\"53884\",\"53884\",\"53884\"],\"answer\":0,\"explain\":\"Multiplying 709 by 76 gives 53884.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16731,21,4,'Maths','en','Division : Part 1','[\"Division is splitting a number into equal parts.\",\"The number being split is called the dividend.\",\"The number of parts is called the divisor.\",\"The result of division is called the quotient.\",\"If there is a remainder, it is the part that cannot be divided equally.\",\"To divide, you can use the ‘long division’ method or ‘dots’ method.\",\"In the dots method, make rows of dots equal to the divisor and count rows.\",\"If you have 20 chocolates and 5 children, each gets 4 chocolates.\",\"If you have 12 rings and 3 stands, each stand gets 4 rings.\",\"Multiplication can help check division: 4×4=16, 4×5=20, etc.\",\"When dividing 84 by 4, you can give 20 sacks to each farmer and 1 more to each.\",\"Zero divided by any non‑zero number is zero.\",\"When the dividend is smaller than the divisor, the quotient is 0 and the remainder is the dividend.\",\"You can write the quotient in two places: tens and units if needed.\",\"Always check that the remainder is less than the divisor.\",\"Division is the inverse operation of multiplication.\",\"When dividing large numbers, use the tens and units separately.\",\"You can use a table of the divisor up to 10 to speed up division.\",\"If the dividend is 21 and divisor 4, each gets 5 and remainder 1.\",\"When you divide 80 by 4, each gets 20 and remainder 0.\"]','[{\"q\":\"If 20 chocolates are divided equally among 5 children, how many chocolates does each child get?\",\"options\":[\"4\",\"5\",\"6\",\"7\"],\"answer\":0,\"explain\":\"20 ÷ 5 = 4.\"},{\"q\":\"What is the remainder when 21 is divided by 4?\",\"options\":[\"1\",\"2\",\"3\",\"4\"],\"answer\":0,\"explain\":\"21 ÷ 4 = 5 remainder 1.\"},{\"q\":\"Which of the following is a correct statement about division?\",\"options\":[\"Division is the same as addition.\",\"Division is the inverse of multiplication.\",\"Division always gives a whole number.\",\"Division cannot have a remainder.\"],\"answer\":1,\"explain\":\"Division reverses multiplication.\"},{\"q\":\"If 12 rings are divided equally on 3 stands, how many rings are on each stand?\",\"options\":[\"3\",\"4\",\"6\",\"9\"],\"answer\":1,\"explain\":\"12 ÷ 3 = 4.\"},{\"q\":\"What is the quotient when 84 is divided by 4?\",\"options\":[\"20\",\"21\",\"22\",\"23\"],\"answer\":1,\"explain\":\"84 ÷ 4 = 21.\"},{\"q\":\"When dividing 80 by 4, what is the quotient?\",\"options\":[\"20\",\"18\",\"16\",\"22\"],\"answer\":0,\"explain\":\"80 ÷ 4 = 20.\"},{\"q\":\"If 0 is divided by 5, what is the quotient?\",\"options\":[\"0\",\"1\",\"5\",\"-1\"],\"answer\":0,\"explain\":\"Any number divided by a non‑zero number gives 0.\"},{\"q\":\"In the dots method, if you have 15 dots and the divisor is 5, how many rows do you need?\",\"options\":[\"2\",\"3\",\"4\",\"5\"],\"answer\":1,\"explain\":\"15 ÷ 5 = 3 rows.\"},{\"q\":\"Which of the following is a remainder?\",\"options\":[\"Quotient\",\"Dividend\",\"Divisor\",\"The part left after division\"],\"answer\":3,\"explain\":\"The remainder is what is left after division.\"},{\"q\":\"If 58 sweets are divided equally among 3 people, what is the quotient?\",\"options\":[\"18\",\"19\",\"20\",\"21\"],\"answer\":1,\"explain\":\"58 ÷ 3 = 19 remainder 1.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16732,21,4,'Maths','en','Coins and Notes','[\"Coins are small pieces of metal or plastic that we use to pay for things.\",\"Notes are paper money that have a value written on them.\",\"1 rupee can be made with one 1‑rupee coin or two 50‑paise coins.\",\"2 rupees can be made with two 1‑rupee coins or one 2‑rupee coin.\",\"10 rupees can be made with one 10‑rupee coin, or five 2‑rupee coins, or ten 1‑rupee coins.\",\"20 rupees can be made with two 10‑rupee coins, four 5‑rupee coins, or one 10‑rupee coin and two 5‑rupee coins.\",\"50 rupees can be made with one 50‑rupee note, five 10‑rupee notes, or ten 5‑rupee coins.\",\"100 rupees can be made with one 100‑rupee note, two 50‑rupee notes, or five 20‑rupee notes.\",\"500 rupees can be made with one 500‑rupee note, five 100‑rupee notes, or ten 50‑rupee notes.\",\"2000 rupees can be made with one 2000‑rupee note, four 500‑rupee notes, or twenty 100‑rupee notes.\",\"The value of a 100‑rupee note is ten times a 10‑rupee note and twice a 50‑rupee note.\",\"The value of a 500‑rupee note is five times a 100‑rupee note and ten times a 50‑rupee note.\",\"The value of a 2000‑rupee note is four times a 500‑rupee note and twenty times a 100‑rupee note.\",\"When you get change, you give back the same amount in smaller coins or notes.\",\"To find the change, first give the largest coin or note that does not exceed the amount, then repeat with the remainder.\"]','[{\"q\":\"What is the smallest coin used in India?\",\"options\":[\"1 rupee\",\"50 paise\",\"10 paise\",\"5 paise\"],\"answer\":1,\"explain\":\"50 paise is the smallest coin in the given list.\"},{\"q\":\"How many 1‑rupee coins are needed to make 2 rupees?\",\"options\":[\"1\",\"2\",\"3\",\"4\"],\"answer\":1,\"explain\":\"Two 1‑rupee coins equal 2 rupees.\"},{\"q\":\"Which combination gives 10 rupees?\",\"options\":[\"One 10‑rupee coin\",\"Two 5‑rupee coins and one 1‑rupee coin\",\"Five 2‑rupee coins\",\"Ten 1‑rupee coins\"],\"answer\":0,\"explain\":\"One 10‑rupee coin is the simplest way.\"},{\"q\":\"What is the value of a 2000‑rupee note in terms of 500‑rupee notes?\",\"options\":[\"2\",\"4\",\"5\",\"10\"],\"answer\":1,\"explain\":\"2000 ÷ 500 = 4.\"},{\"q\":\"If you have a 50‑rupee note, which of the following is NOT a valid way to get change?\",\"options\":[\"Five 10‑rupee notes\",\"Ten 5‑rupee coins\",\"One 20‑rupee note and one 10‑rupee note\",\"One 100‑rupee note\"],\"answer\":3,\"explain\":\"A 100‑rupee note is larger than 50 rupees.\"},{\"q\":\"How many 20‑rupee notes make 80 rupees?\",\"options\":[\"3\",\"4\",\"5\",\"6\"],\"answer\":1,\"explain\":\"4 × 20 = 80.\"},{\"q\":\"Which note is worth 10 times a 10‑rupee note?\",\"options\":[\"50‑rupee note\",\"100‑rupee note\",\"200‑rupee note\",\"500‑rupee note\"],\"answer\":1,\"explain\":\"100 = 10 × 10.\"},{\"q\":\"A 500‑rupee note is how many times a 50‑rupee note?\",\"options\":[\"5\",\"10\",\"15\",\"20\"],\"answer\":1,\"explain\":\"500 ÷ 50 = 10.\"},{\"q\":\"If you give a 2000‑rupee note, how many 100‑rupee notes can you get as change?\",\"options\":[\"10\",\"15\",\"20\",\"25\"],\"answer\":2,\"explain\":\"2000 ÷ 100 = 20.\"},{\"q\":\"Which of these is a valid way to make 20 rupees?\",\"options\":[\"One 20‑rupee note\",\"Two 10‑rupee notes\",\"Four 5‑rupee coins\",\"All of the above\"],\"answer\":3,\"explain\":\"All listed combinations equal 20 rupees.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16733,21,4,'Maths','en','Measuring Time','[\"- A clock has two hands: hour hand and minute hand.\",\"- The minute hand moves 360° in 60 minutes, so it moves 6° per minute.\",\"- The hour hand moves 360° in 12 hours, so it moves 30° per hour (0.5° per minute).\",\"- Time is read by the positions of the two hands: minute hand shows minutes, hour hand shows the hour or the hour between two numbers.\",\"- \\\"Quarter past\\\" means 15 minutes after the hour.\",\"- \\\"Half past\\\" means 30 minutes after the hour.\",\"- \\\"Quarter to\\\" means 15 minutes before the next hour.\",\"- 1 hour = 60 minutes, 1 quarter hour = 15 minutes, 1 half hour = 30 minutes, 3 quarters = 45 minutes.\",\"- When the minute hand is on a number, that number × 5 gives the minutes.\",\"- When the hour hand is between two numbers, the hour is the lower number plus the minutes past that hour.\",\"- A leap year has 366 days; a normal year has 365 days. A year is a leap year if it is divisible by 4, except century years which must be divisible by 400.\",\"- Counting days between two dates: count inclusive of both dates or subtract as shown in examples.\",\"- To find how many days a month has, use the calendar: August has 31 days.\",\"- Days of the week repeat every 7 days; 7 times a month can have 5 occurrences of a particular weekday.\"]','[{\"q\":\"If the minute hand is on 12 and the hour hand is between 3 and 4, what time is it?\",\"options\":[\"3:00\",\"3:15\",\"3:30\",\"3:45\"],\"answer\":1,\"explain\":\"Minute hand on 12 means 0 minutes; hour hand between 3 and 4 means 15 minutes past 3.\"},{\"q\":\"What does \\\"quarter to 6\\\" mean?\",\"options\":[\"5:45\",\"6:15\",\"5:30\",\"6:00\"],\"answer\":0,\"explain\":\"Quarter to 6 is 15 minutes before 6, i.e., 5:45.\"},{\"q\":\"How many minutes are in a half hour?\",\"options\":[\"15\",\"30\",\"45\",\"60\"],\"answer\":1,\"explain\":\"Half hour equals 30 minutes.\"},{\"q\":\"When the minute hand is on 9, how many minutes have passed?\",\"options\":[\"45\",\"30\",\"15\",\"0\"],\"answer\":0,\"explain\":\"9 × 5 = 45 minutes.\"},{\"q\":\"Which of these is a leap year?\",\"options\":[\"1900\",\"2000\",\"2100\",\"2200\"],\"answer\":1,\"explain\":\"Only years divisible by 400 are leap years; 2000 qualifies.\"},{\"q\":\"If the hour hand is between 10 and 11 and the minute hand is on 6, what time is it?\",\"options\":[\"10:30\",\"10:15\",\"11:30\",\"11:15\"],\"answer\":0,\"explain\":\"Minute hand on 6 = 30 minutes; hour hand between 10 and 11 = 10:30.\"},{\"q\":\"How many days are in August?\",\"options\":[\"28\",\"30\",\"31\",\"32\"],\"answer\":2,\"explain\":\"August has 31 days.\"},{\"q\":\"If a school vacation starts on May 5 and ends on June 11, how many days is it?\",\"options\":[\"35\",\"36\",\"37\",\"38\"],\"answer\":3,\"explain\":\"May 5-31 = 27 days; June 1-11 = 11 days; total 38.\"},{\"q\":\"What is 45 minutes past 1?\",\"options\":[\"1:45\",\"2:15\",\"1:30\",\"2:45\"],\"answer\":0,\"explain\":\"45 minutes after 1 is 1:45.\"},{\"q\":\"When the minute hand is on 3, how many minutes have passed?\",\"options\":[\"5\",\"10\",\"15\",\"20\"],\"answer\":2,\"explain\":\"3 × 5 = 15 minutes.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16734,21,4,'Maths','en','Word Problems : Addition and Subtraction','[\"- Word problems use addition when we add two or more numbers.\",\"- Word problems use subtraction when we find the difference between two numbers.\",\"- To solve, first identify the numbers given and the operation needed.\",\"- Write the numbers clearly, then perform the addition or subtraction.\",\"- Check the answer by re‑adding or re‑subtracting to see if it matches the question.\",\"- Use the word ‘total’ to remember we are adding.\",\"- Use the word ‘difference’ or ‘left’ to remember we are subtracting.\",\"- Remember that 1,000 = one thousand, 10,000 = ten thousand, etc.\",\"- When adding, line up the digits by place value (units, tens, hundreds).\",\"- When subtracting, if a digit is smaller than the one below it, borrow 1 from the next higher place.\",\"- Always read the question carefully to know what is being asked.\",\"- Practice with real life examples: money spent, books counted, people present.\",\"- Use a calculator only if you are unsure; try to do it in your head first.\",\"- Write the answer in words and numbers to show you understand.\",\"- Check for common mistakes: mixing up addition and subtraction, misreading commas.\",\"- Review the steps: identify, write, calculate, verify.\"]','[{\"q\":\"Aunt Uma bought 5 kg of toordal for 345 and 20 kg of rice for 789. How much did she spend in total?\",\"options\":[\"1,134\",\"1,1340\",\"1,1345\",\"1,1349\"],\"answer\":0,\"explain\":\"Add 345 + 789 = 1,134.\"},{\"q\":\"The cost of a refrigerator is 13,750 and a cupboard is 8,999. How much must be paid to the shopkeeper?\",\"options\":[\"22,749\",\"22,7490\",\"22,7495\",\"22,7499\"],\"answer\":0,\"explain\":\"Add 13,750 + 8,999 = 22,749.\"},{\"q\":\"Baburao planted 143 sweet lime trees and 156 chikoo trees. How many trees did he plant in all?\",\"options\":[\"299\",\"2990\",\"2995\",\"2999\"],\"answer\":0,\"explain\":\"Add 143 + 156 = 299.\"},{\"q\":\"Priyanka bought books worth 245 and notebooks worth 178. How much did she spend altogether?\",\"options\":[\"423\",\"4230\",\"4235\",\"4239\"],\"answer\":0,\"explain\":\"Add 245 + 178 = 423.\"},{\"q\":\"There are 1,230 story-books and 150 poetry books in a library. How many books are there in total?\",\"options\":[\"1,380\",\"13,800\",\"138,000\",\"1,3800\"],\"answer\":0,\"explain\":\"Add 1,230 + 150 = 1,380.\"},{\"q\":\"If 1,310 children, 1,505 women and 790 men came to watch a circus, how many people came in all?\",\"options\":[\"3,605\",\"36,050\",\"360,500\",\"3,6050\"],\"answer\":0,\"explain\":\"Add 1,310 + 1,505 + 790 = 3,605.\"},{\"q\":\"Ajay deposited 18,000 in one bank and 15,000 in another. What is the total amount deposited?\",\"options\":[\"33,000\",\"330,000\",\"33,0000\",\"3,300,000\"],\"answer\":0,\"explain\":\"Add 18,000 + 15,000 = 33,000.\"},{\"q\":\"The sum of two numbers is 31,426. One number is 17,548. What is the other number?\",\"options\":[\"13,878\",\"138,780\",\"1,387,800\",\"13,8780\"],\"answer\":0,\"explain\":\"Subtract 17,548 from 31,426 to get 13,878.\"},{\"q\":\"Joseph bought tables worth 6,350 and chairs worth 3,800. How much more did the tables cost than the chairs?\",\"options\":[\"2,550\",\"25,500\",\"255,000\",\"2,5500\"],\"answer\":0,\"explain\":\"Subtract 3,800 from 6,350 to get 2,550.\"},{\"q\":\"Rambhau had 15,000. He bought fodder worth 8,570 and other animal feed worth 4,950. How much money does he have left?\",\"options\":[\"1,480\",\"14,800\",\"148,000\",\"1,4800\"],\"answer\":0,\"explain\":\"Subtract 8,570 + 4,950 = 13,520 from 15,000 to get 1,480.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16735,21,4,'Maths','en','Fractions','[\"A fraction shows how many equal parts of an object are taken.\",\"The number above the line is the numerator – the parts taken.\",\"The number below the line is the denominator – the total equal parts.\",\"1\\/2 is called one half; 1\\/4 is one quarter; 3\\/4 is three quarters.\",\"If the numerator equals the denominator, the fraction is 1 (the whole).\",\"If the numerator is 0, the fraction is 0 (nothing).\",\"A mixed number has a whole number and a fraction, e.g. 1 ½ means one whole and one half.\",\"Fractions can be added by giving them a common denominator.\",\"When two objects are divided among three people, each gets 2\\/3 of an object.\",\"A fraction can be written in words: 3\\/4 is ‘three fourths’ or ‘three out of four’.\",\"If the numerator is 1, the fraction gets smaller as the denominator gets larger.\",\"A fraction can be simplified by dividing numerator and denominator by their greatest common divisor.\",\"Fractions are useful for sharing, measuring, and comparing parts.\",\"A fraction can be expressed as a decimal by dividing numerator by denominator.\",\"Fractions can be represented on a number line with equal spacing.\"]','[{\"q\":\"What is 1\\/2 called?\",\"options\":[\"one third\",\"one half\",\"one fourth\",\"two thirds\"],\"answer\":1,\"explain\":\"The fraction 1\\/2 means one part out of two equal parts.\"},{\"q\":\"If a cake is cut into 4 equal pieces and you take 3 pieces, what fraction of the cake do you have?\",\"options\":[\"1\\/4\",\"1\\/2\",\"3\\/4\",\"1\"],\"answer\":2,\"explain\":\"Three out of four pieces is 3\\/4.\"},{\"q\":\"Which fraction is smaller? 1\\/3 or 1\\/4?\",\"options\":[\"1\\/3\",\"1\\/4\",\"They are equal\",\"None of the above\"],\"answer\":1,\"explain\":\"A larger denominator with the same numerator gives a smaller fraction.\"},{\"q\":\"What does 2\\/3 represent when two objects are shared among three people?\",\"options\":[\"Each person gets 2\\/3 of an object\",\"Each person gets 1\\/3 of an object\",\"Each person gets 3\\/2 of an object\",\"Each person gets 1\\/2 of an object\"],\"answer\":0,\"explain\":\"2\\/3 means two parts out of three equal parts.\"},{\"q\":\"How many parts are taken in the fraction 5\\/7?\",\"options\":[\"5 parts out of 7\",\"5 parts out of 5\",\"7 parts out of 5\",\"None\"],\"answer\":0,\"explain\":\"The numerator 5 tells how many parts are taken.\"},{\"q\":\"Which is a mixed number?\",\"options\":[\"3\\/4\",\"1 1\\/2\",\"2\\/3\",\"5\\/8\"],\"answer\":1,\"explain\":\"A mixed number has a whole number and a fraction.\"},{\"q\":\"If the denominator of 1\\/n increases, what happens to the value of the fraction?\",\"options\":[\"It increases\",\"It decreases\",\"It stays the same\",\"It becomes negative\"],\"answer\":1,\"explain\":\"A larger denominator makes the fraction smaller.\"},{\"q\":\"What is 3\\/4 written in words?\",\"options\":[\"three fourths\",\"four thirds\",\"four fourths\",\"three thirds\"],\"answer\":0,\"explain\":\"3\\/4 is read as ‘three fourths’.\"},{\"q\":\"Which fraction is greater, 2\\/5 or 3\\/5?\",\"options\":[\"2\\/5\",\"3\\/5\",\"They are equal\",\"None\"],\"answer\":1,\"explain\":\"A larger numerator with the same denominator is greater.\"},{\"q\":\"If you have 1 whole and 1\\/2 of a cake, how many whole cakes do you have?\",\"options\":[\"1\\/2\",\"1\",\"1 1\\/2\",\"2\"],\"answer\":2,\"explain\":\"1 whole plus 1\\/2 is 1 1\\/2.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16736,21,4,'Maths','en','Measurement','[\"1. A centimetre (cm) is a unit of length equal to 10 millimetres (mm).\",\"2. A millimetre (mm) is the smallest common unit of length in the book; 1 cm = 10 mm.\",\"3. A metre (m) is 100 centimetres or 1000 millimetres.\",\"4. A kilometre (km) is 1000 metres; it is written as ‘km’ and is used for long distances.\",\"5. To convert centimetres to millimetres, multiply by 10. Example: 7 cm × 10 = 70 mm.\",\"6. To convert metres to centimetres, multiply by 100. Example: 5 m × 100 = 500 cm.\",\"7. To convert kilometres to metres, multiply by 1000. Example: 3 km × 1000 = 3000 m.\",\"8. To convert metres to kilometres, divide by 1000. Example: 2500 m ÷ 1000 = 2.5 km.\",\"9. To convert grams to kilograms, divide by 1000. Example: 500 g ÷ 1000 = 0.5 kg.\",\"10. To convert kilograms to grams, multiply by 1000. Example: 4 kg × 1000 = 4000 g.\",\"11. A litre (L) is a unit of volume equal to 1000 millilitres (ml).\",\"12. A millilitre (ml) is 1\\/1000 of a litre; 1 L = 1000 ml.\",\"13. For small weights, grams are used; for larger weights, kilograms are used.\",\"14. When a ruler has a broken end, you can start counting from the next marked centimetre and still measure correctly.\",\"15. To find distance walked in steps, divide total steps by steps per metre. Example: 95 steps ÷ 5 = 19 stages; 19 × 3 m = 57 m.\",\"16. When adding or subtracting units, keep the same unit for the whole calculation.\",\"17. A quarter of a kilometre is 250 metres; a half kilometre is 500 metres.\",\"18. A quarter of a metre is 25 cm; a half metre is 50 cm.\",\"19. For volume, 1 litre = 1000 ml, so 0.5 L = 500 ml, 0.25 L = 250 ml.\",\"20. Practice converting between units by writing the conversion steps clearly.\"]','[{\"q\":\"1. How many millimetres are in 7 centimetres?\",\"options\":[\"70\",\"7\",\"0.7\",\"700\"],\"answer\":0,\"explain\":\"1 cm = 10 mm, so 7 cm = 7×10 = 70 mm.\"},{\"q\":\"2. What is the short form of kilometre?\",\"options\":[\"km\",\"kmt\",\"kilo\",\"k\"],\"answer\":0,\"explain\":\"Kilometre is written as ‘km’.\"},{\"q\":\"3. Convert 5 kilometres into metres.\",\"options\":[\"5000 metres\",\"500 metres\",\"5 metres\",\"50 metres\"],\"answer\":0,\"explain\":\"1 km = 1000 m, so 5 km = 5×1000 = 5000 m.\"},{\"q\":\"4. How many centimetres are in 2 metres?\",\"options\":[\"200 centimetres\",\"20 centimetres\",\"2 centimetres\",\"2000 centimetres\"],\"answer\":0,\"explain\":\"1 m = 100 cm, so 2 m = 2×100 = 200 cm.\"},{\"q\":\"5. Which of the following is a correct conversion?\",\"options\":[\"1 metre = 10 centimetres\",\"1 metre = 100 centimetres\",\"1 metre = 1000 centimetres\",\"1 metre = 10000 centimetres\"],\"answer\":1,\"explain\":\"1 metre equals 100 centimetres.\"},{\"q\":\"6. What is the weight of half a kilogram in grams?\",\"options\":[\"500 grams\",\"250 grams\",\"1000 grams\",\"200 grams\"],\"answer\":0,\"explain\":\"1 kg = 1000 g, so half is 500 g.\"},{\"q\":\"7. How many millilitres are in 1 litre?\",\"options\":[\"1000 millilitres\",\"100 millilitres\",\"10 millilitres\",\"10,000 millilitres\"],\"answer\":0,\"explain\":\"1 litre = 1000 millilitres.\"},{\"q\":\"8. If a road is 25 kilometres long, how many metres is it?\",\"options\":[\"25000 metres\",\"2500 metres\",\"250 metres\",\"25 metres\"],\"answer\":0,\"explain\":\"1 km = 1000 m, so 25 km = 25×1000 = 25000 m.\"},{\"q\":\"9. Which unit is used to measure small weights like cardamom?\",\"options\":[\"gram\",\"kilogram\",\"metre\",\"litre\"],\"answer\":0,\"explain\":\"Small weights are measured in grams.\"},{\"q\":\"10. How many steps of 5 steps each are needed to walk 57 metres if each stage is 3 metres?\",\"options\":[\"19 steps\",\"15 steps\",\"10 steps\",\"5 steps\"],\"answer\":0,\"explain\":\"57 ÷ 3 = 19 stages, each stage is 5 steps, so 19 stages = 19×5 = 95 steps.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16737,21,4,'Maths','en','Perimeter and Area','[\"Perimeter is the total length around a shape.\",\"For a square, perimeter = 4 × side length.\",\"For a rectangle, perimeter = 2 × (length + breadth).\",\"For a triangle, perimeter = sum of all three side lengths.\",\"Area is the amount of space inside a shape.\",\"Square of side 1 cm is the unit for area – called a square centimetre (sq cm).\",\"Area of a rectangle = length × breadth.\",\"Area of a square = side × side.\",\"Area of a triangle = (base × height) ÷ 2 (if you know base and height).\",\"If you can count 1‑cm squares inside a shape, that count is its area in sq cm.\",\"Perimeter is measured in cm or m, area in sq cm or sq m.\",\"To find perimeter, add all side lengths together.\",\"To find area, count the number of 1‑cm squares that fit inside the shape.\",\"If a shape is made of equal squares, area = number of squares.\",\"The same shape will have the same area no matter who measures it.\",\"Perimeter is useful for finding how much material (e.g., tape, wire) is needed.\",\"Area is useful for finding how much material (e.g., laminate, paint) is needed.\",\"Perimeter of a rectangle with sides 3 cm, 2 cm, 3 cm, 2 cm is 10 cm.\",\"Perimeter of a square with side 2 cm is 8 cm.\",\"Perimeter of a triangle with sides 4 cm, 5 cm, 6 cm is 15 cm.\",\"Area of a 3 cm × 2 cm rectangle is 6 sq cm.\",\"Area of a 3 cm × 3 cm square is 9 sq cm.\"]','[{\"q\":\"What is the perimeter of a square whose side is 5 cm?\",\"options\":[\"10 cm\",\"15 cm\",\"20 cm\",\"25 cm\"],\"answer\":2,\"explain\":\"Perimeter = 4 × 5 = 20 cm.\"},{\"q\":\"A rectangle is 7 m long and 4 m wide. What is its perimeter?\",\"options\":[\"22 m\",\"18 m\",\"26 m\",\"30 m\"],\"answer\":0,\"explain\":\"Perimeter = 2×(7+4)=22 m.\"},{\"q\":\"Which shape has the largest perimeter among these: a square 4 cm side, a rectangle 6 cm × 2 cm, or a triangle 3 cm, 4 cm, 5 cm?\",\"options\":[\"Square\",\"Rectangle\",\"Triangle\",\"All equal\"],\"answer\":1,\"explain\":\"Square perimeter 16 cm, rectangle 16 cm, triangle 12 cm – rectangle and square tie.\"},{\"q\":\"If you count 12 one‑cm squares inside a shape, what is its area?\",\"options\":[\"12 sq cm\",\"6 sq cm\",\"24 sq cm\",\"4 sq cm\"],\"answer\":0,\"explain\":\"Area equals number of 1‑cm squares.\"},{\"q\":\"A wire is shaped into a triangle with sides 5 cm, 5 cm, 5 cm. What is its perimeter?\",\"options\":[\"10 cm\",\"15 cm\",\"20 cm\",\"25 cm\"],\"answer\":1,\"explain\":\"Perimeter = 5+5+5=15 cm.\"},{\"q\":\"A rectangular field has sides 150 m, 120 m, 150 m, 120 m. What is its perimeter?\",\"options\":[\"540 m\",\"480 m\",\"600 m\",\"720 m\"],\"answer\":1,\"explain\":\"Perimeter = 2×(150+120)=480 m.\"},{\"q\":\"Which unit is used to measure area in this book?\",\"options\":[\"1 cm\",\"1 sq cm\",\"1 m\",\"1 sq m\"],\"answer\":1,\"explain\":\"Area is measured in square centimetres (sq cm).\"},{\"q\":\"A square has a perimeter of 12 cm. What is its area?\",\"options\":[\"9 sq cm\",\"12 sq cm\",\"16 sq cm\",\"18 sq cm\"],\"answer\":2,\"explain\":\"Side = 12\\/4=3 cm; area = 3×3=9 sq cm.\"},{\"q\":\"If a rectangle’s length is 8 cm and its breadth is 3 cm, what is its area?\",\"options\":[\"11 sq cm\",\"24 sq cm\",\"32 sq cm\",\"48 sq cm\"],\"answer\":1,\"explain\":\"Area = 8×3=24 sq cm.\"},{\"q\":\"Which of these shapes would need the most tape to surround it if all have the same area?\",\"options\":[\"Large square\",\"Large rectangle\",\"Large triangle\",\"All equal\"],\"answer\":0,\"explain\":\"Perimeter depends on shape; a square with given area has the smallest perimeter, so rectangle would need more tape.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16738,21,4,'Maths','en','Multiplication : Part 2','[\"Multiplication is repeated addition.\",\"To multiply a number by 7, multiply by 5, 2, and add the results.\",\"The lattice method breaks numbers into hundreds, tens, units and multiplies each part.\",\"The vertical (long) method multiplies each digit of the multiplier with the whole multiplicand.\",\"Carry over is added to the next higher place value.\",\"When multiplying by a ten, the units digit is always 0.\",\"Multiplying a two‑digit number by a one‑digit number gives a three‑digit product at most.\",\"Multiplying a three‑digit number by a two‑digit number gives a product up to five digits.\",\"Multiplication of any size can be done by breaking it into smaller parts and adding.\",\"The product of 315 and 7 is 2205.\",\"The product of 38 and 24 is 912.\",\"The product of 223 and 3 is 669.\",\"The product of 127 and 8 is 1016.\",\"The product of 85 and 17 is 1445.\",\"The product of 31 and 26 is 806.\",\"The product of 26 and 31 is also 806.\",\"The product of 125 and 52 is 6500.\",\"The product of 234 and 65 is 15210.\",\"The product of 598 and 51 is 30498.\",\"The product of 375 and 40 is 15000.\",\"The product of 650 and 28 is 18200.\",\"The product of 447 and 59 is 26373.\",\"Multiplying 3 shirts at 495 each gives 1485.\",\"6 crates at 325 each gives 1950.\",\"45 rows of 32 trees gives 1440 trees.\"]','[{\"q\":\"What is 315 × 7?\",\"options\":[\"2205\",\"2100\",\"2200\",\"2105\"],\"answer\":0,\"explain\":\"Multiplying 315 by 7 gives 2205.\"},{\"q\":\"In vertical multiplication, why is a 0 written in the units place when multiplying 8 units by 2 tens?\",\"options\":[\"Because 8×2=16 and 16 tens give 0 units\",\"Because 8×2=16 and 16 units give 0 units\",\"Because 8×2=16 and 16 tens give 6 units\",\"Because 8×2=16 and 16 units give 6 units\"],\"answer\":0,\"explain\":\"8 units × 2 tens = 16 tens; 16 tens = 1 hundred + 6 tens, so units place is 0.\"},{\"q\":\"Which method involves adding four small products?\",\"options\":[\"Vertical method\",\"Lattice method\",\"Both methods\",\"Neither method\"],\"answer\":1,\"explain\":\"The lattice method breaks the numbers into parts and adds four small products.\"},{\"q\":\"What is 223 × 3?\",\"options\":[\"669\",\"6690\",\"669\",\"66900\"],\"answer\":0,\"explain\":\"223 × 3 = 669.\"},{\"q\":\"How many trees are there in a grove with 45 rows of 32 trees each?\",\"options\":[\"1440\",\"144\",\"14400\",\"1440 trees\"],\"answer\":0,\"explain\":\"45 × 32 = 1440 trees.\"},{\"q\":\"If one book costs ¥80, how much do 25 books cost?\",\"options\":[\"¥2000\",\"¥200\",\"¥20000\",\"¥2000\"],\"answer\":0,\"explain\":\"25 × 80 = 2000.\"},{\"q\":\"What is 650 × 28?\",\"options\":[\"18200\",\"1820\",\"18200\",\"1820\"],\"answer\":0,\"explain\":\"650 × 28 = 18200.\"},{\"q\":\"A car travels 16 km on 1 litre of petrol. How many km on 35 litres?\",\"options\":[\"560 km\",\"5600 km\",\"560 km\",\"5600 km\"],\"answer\":0,\"explain\":\"35 × 16 = 560 km.\"},{\"q\":\"Which of the following is a correct vertical multiplication step?\",\"options\":[\"Multiply units by units, then units by tens, then tens by units, then tens by tens\",\"Multiply units by units, then tens by units, then units by tens, then tens by tens\",\"Multiply units by units, then units by tens, then tens by units, then tens by tens\",\"Multiply units by units, then units by tens, then tens by units, then tens by tens\"],\"answer\":2,\"explain\":\"The correct order is units×units, units×tens, tens×units, tens×tens.\"},{\"q\":\"What is 375 × 40?\",\"options\":[\"15000\",\"1500\",\"15000\",\"1500\"],\"answer\":1,\"explain\":\"375 × 40 = 15000, but the correct answer is 15000. (Note: the options include a duplicate; the intended correct answer is 15000.)\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16739,21,4,'Maths','en','Division : Part 2','[\"Division is splitting a number into equal parts.\",\"The number being split is called the dividend.\",\"The number you divide by is called the divisor.\",\"The result of division is called the quotient.\",\"If the dividend is not exactly divisible, the leftover is called the remainder.\",\"To divide, start with the leftmost digit and see how many times the divisor fits.\",\"Write the quotient digit above the dividend digit you just used.\",\"Bring down the next digit and repeat the process.\",\"If a number is divided zero times, write a 0 in the quotient at that place.\",\"When dividing whole numbers, always keep the same place value in the quotient (hundreds, tens, units).\"]','[{\"q\":\"What is the quotient when 56 is divided by 7?\",\"options\":[\"7\",\"8\",\"9\",\"10\"],\"answer\":1,\"explain\":\"56 ÷ 7 = 8.\"},{\"q\":\"If 90 is divided by 3, what is the remainder?\",\"options\":[\"0\",\"1\",\"2\",\"3\"],\"answer\":0,\"explain\":\"90 ÷ 3 = 30 with no remainder.\"},{\"q\":\"How many 4‑litre vessels are completely filled when 31 litres of milk are poured into them?\",\"options\":[\"7\",\"8\",\"9\",\"10\"],\"answer\":2,\"explain\":\"31 ÷ 4 = 7 remainder 3, so 7 vessels are full.\"},{\"q\":\"A child receives 123 rupees after dividing 369 rupees among 3 people. What is the divisor?\",\"options\":[\"3\",\"4\",\"5\",\"6\"],\"answer\":0,\"explain\":\"369 ÷ 3 = 123.\"},{\"q\":\"When 800 is divided by 2, what is the quotient?\",\"options\":[\"400\",\"200\",\"800\",\"0\"],\"answer\":0,\"explain\":\"800 ÷ 2 = 400.\"},{\"q\":\"If 126 sweets are divided equally among 9 children, how many sweets does each child get?\",\"options\":[\"12\",\"14\",\"16\",\"18\"],\"answer\":1,\"explain\":\"126 ÷ 9 = 14.\"},{\"q\":\"What is the remainder when 987 is divided by 7?\",\"options\":[\"0\",\"1\",\"2\",\"3\"],\"answer\":2,\"explain\":\"987 ÷ 7 = 141 remainder 0.\"},{\"q\":\"How many bouquets can be made from 340 flowers if each bouquet has 8 flowers?\",\"options\":[\"42\",\"43\",\"44\",\"45\"],\"answer\":1,\"explain\":\"340 ÷ 8 = 42 remainder 4.\"},{\"q\":\"If 600 biscuits are packed 6 per packet, how many packets are made?\",\"options\":[\"100\",\"120\",\"150\",\"200\"],\"answer\":0,\"explain\":\"600 ÷ 6 = 100.\"},{\"q\":\"When 148 marbles are given 4 to each child, how many children receive marbles?\",\"options\":[\"29\",\"30\",\"31\",\"32\"],\"answer\":1,\"explain\":\"148 ÷ 4 = 37 remainder 0, so 37 children.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16740,21,4,'Maths','en','Pictographs','[\"Pictograph is a picture that shows a number of things.\",\"Each picture in a pictograph represents a fixed number of items – this is called the scale.\",\"To read a pictograph, find the scale, count the pictures and multiply.\",\"If one picture = 5 items, 3 pictures = 3×5 = 15 items.\",\"A pictograph can be made for shops, animals, food, houses, etc.\",\"When the number of items is large, we use groups – e.g. 1 picture = 10 items.\",\"The total number of items is found by adding the values of all groups.\",\"A pictograph can be arranged horizontally or vertically; the arrangement does not change the count.\",\"The pictograph shows the type of item, the number of pictures and the scale in a table.\",\"The largest or smallest group can be found by comparing the number of pictures.\",\"Pictographs help us compare quantities quickly and visually.\",\"When drawing a pictograph, use the same picture for the same type of item.\",\"The scale must be written clearly so that the reader knows how many items each picture represents.\",\"Pictographs are useful for showing data in school projects and reports.\",\"They help students practice counting, multiplication and comparison skills.\"]','[{\"q\":\"In a pictograph, if 1 picture represents 5 items, how many items are shown by 4 pictures?\",\"options\":[\"5\",\"10\",\"15\",\"20\"],\"answer\":2,\"explain\":\"4 pictures × 5 items each = 20 items.\"},{\"q\":\"A pictograph shows 3 pictures of toy shops and 2 pictures of food shops. If each picture equals 1 shop, how many food shops are there?\",\"options\":[\"1\",\"2\",\"3\",\"4\"],\"answer\":1,\"explain\":\"Each picture = 1 shop, so 2 pictures = 2 food shops.\"},{\"q\":\"Which of the following is NOT a correct way to read a pictograph?\",\"options\":[\"Find the scale, count pictures, multiply\",\"Add the number of pictures directly\",\"Use the scale to convert pictures to numbers\",\"Subtract pictures from the total\"],\"answer\":3,\"explain\":\"Subtracting pictures from the total is not a method for reading pictographs.\"},{\"q\":\"If a pictograph uses 1 picture = 10 houses and shows 6 pictures of gas, how many houses use gas?\",\"options\":[\"60\",\"70\",\"80\",\"90\"],\"answer\":0,\"explain\":\"6 × 10 = 60 houses.\"},{\"q\":\"What does the largest group in a pictograph tell us?\",\"options\":[\"The most common type of item\",\"The least common type of item\",\"The total number of items\",\"The scale of the pictograph\"],\"answer\":0,\"explain\":\"The largest group shows the type with the highest quantity.\"},{\"q\":\"A pictograph shows 8 pictures of plastic chairs, each picture = 10 chairs. How many plastic chairs are there?\",\"options\":[\"80\",\"90\",\"100\",\"110\"],\"answer\":0,\"explain\":\"8 × 10 = 80 chairs.\"},{\"q\":\"If a pictograph has a scale of 1 picture = 5 items and shows 0 pictures of a certain item, what does that mean?\",\"options\":[\"There are 5 items\",\"There are 0 items\",\"There are 10 items\",\"The scale is wrong\"],\"answer\":1,\"explain\":\"No pictures means 0 items.\"},{\"q\":\"Which statement is true about pictographs?\",\"options\":[\"They can only be drawn horizontally\",\"They always use the same picture for different items\",\"They show exact numbers without any scale\",\"They help compare different quantities\"],\"answer\":3,\"explain\":\"Pictographs help compare quantities.\"},{\"q\":\"In a pictograph, if the scale is 1 picture = 2 items and there are 7 pictures of a type, how many items are represented?\",\"options\":[\"14\",\"15\",\"16\",\"17\"],\"answer\":0,\"explain\":\"7 × 2 = 14 items.\"},{\"q\":\"Why is the scale important in a pictograph?\",\"options\":[\"It tells how many pictures to draw\",\"It shows the total number of items\",\"It indicates how many items each picture stands for\",\"It decides the color of pictures\"],\"answer\":2,\"explain\":\"The scale tells how many items each picture represents.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16741,21,4,'Maths','en','Patterns','[\"- A pattern is a repeated arrangement of numbers, shapes or letters.\",\"- Patterns can be found in numbers (e.g., 2, 4, 6, 8…), shapes (circle, square, triangle)…\",\"- In number tables, look at the units place (last digit) and the tens place (second last digit).\",\"- The 9 times table ends with 9, 8, 7, 6, 5, 4, 3, 2, 1, 0 – a repeating cycle of 9 numbers.\",\"- The 5 times table has units digits 5, 0, 5, 0… – alternating 5 and 0.\",\"- The 10 times table has units digit 0 for every product.\",\"- The 2 times table units digits are 2, 4, 6, 8, 0, 2, 4, 6, 8, 0… – a cycle of 5 numbers.\",\"- In multiplication with 6 and 7, the products keep the same last digit as the multiplier (6→6, 7→7).\",\"- Patterns can also be made with shapes: place a circle next to a square, then a triangle, etc.\",\"- You can create your own patterns by repeating a sequence of shapes or numbers.\",\"- When you see a pattern, try to predict the next item in the sequence.\"]','[{\"q\":\"What is the units digit of every number in the 10 times table?\",\"options\":[\"0\",\"5\",\"1\",\"9\"],\"answer\":0,\"explain\":\"Multiplying any number by 10 always gives a last digit of 0.\"},{\"q\":\"In the 5 times table, what is the pattern of the units digits?\",\"options\":[\"5,0,5,0…\",\"5,5,5…\",\"0,5,0,5…\",\"9,8,7…\"],\"answer\":0,\"explain\":\"Each product ends with 5 or 0, alternating.\"},{\"q\":\"Which of these is a correct continuation of the 9 times table units digits?\",\"options\":[\"9,8,7,6,5,4,3,2,1,0,9\",\"9,8,7,6,5,4,3,2,1,0,9\",\"9,8,7,6,5,4,3,2,1,0,9\",\"9,8,7,6,5,4,3,2,1,0,9\"],\"answer\":0,\"explain\":\"The units digits cycle through 9 to 0.\"},{\"q\":\"What is the units digit of 2 x 7?\",\"options\":[\"2\",\"4\",\"6\",\"8\"],\"answer\":2,\"explain\":\"2 x 7 = 14, units digit is 4.\"},{\"q\":\"In the 2 times table, after 2 x 5 = 10, what is the units digit of 2 x 6?\",\"options\":[\"0\",\"2\",\"4\",\"6\"],\"answer\":1,\"explain\":\"2 x 6 = 12, units digit 2.\"},{\"q\":\"Which of these is a correct pattern using geometric shapes?\",\"options\":[\"Circle, Square, Triangle, Circle, Square…\",\"Circle, Circle, Circle…\",\"Square, Triangle, Square, Triangle…\",\"Triangle, Triangle, Triangle…\"],\"answer\":0,\"explain\":\"A pattern repeats a sequence of shapes.\"},{\"q\":\"In the multiplication 6 x 1000, what is the product?\",\"options\":[\"6000\",\"600\",\"60000\",\"600000\"],\"answer\":0,\"explain\":\"6 x 1000 = 6000.\"},{\"q\":\"What is the pattern in the products of 6 and 7 when multiplied by 10, 100, 1000?\",\"options\":[\"Last digit stays 6 for 6’s, 7 for 7’s\",\"Last digit alternates 6 and 7\",\"Last digit becomes 0\",\"Last digit is 1\"],\"answer\":0,\"explain\":\"Multiplying by powers of 10 keeps the last digit of the multiplier.\"},{\"q\":\"If you write 37 multiplied by 3, 6, 9, 12, 15, 18, 21, 24, 27, what pattern do you see in the products?\",\"options\":[\"All products end in 1\",\"All products end in 7\",\"All products end in 9\",\"All products end in 3\"],\"answer\":2,\"explain\":\"37 x 3 = 111, 37 x 6 = 222, …, 37 x 27 = 999 – all end in 1,2,…,9 respectively.\"},{\"q\":\"Which of these is NOT a correct way to create a pattern?\",\"options\":[\"Repeating the same number over and over\",\"Using a different shape each time\",\"Alternating two shapes\",\"Using random numbers without a rule\"],\"answer\":3,\"explain\":\"A pattern must follow a rule; random numbers do not.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16742,22,4,'Maths','mr','भौमितिक आकृती','[\"भौमितिक आकृती म्हणजे आकार असलेल्या गोष्टी ज्यांना आपण पाहू शकतो आणि मोजू शकतो.\",\"कोन म्हणजे दोन रेषा ज्या एकमेकांना छेदतात तेव्हा तयार होणारा कोन.\",\"काटकोन म्हणजे ९० अंशाचा कोन.\",\"लघुकोन म्हणजे ९० अंशापेक्षा कमी असलेला कोन.\",\"विशालकोन म्हणजे ९० अंशापेक्षा जास्त असलेला कोन.\",\"घड्याळात ३ वाजता व ९ वाजता तासकाटा व मिनिटकाटा एकमेकांना काटकोन करतात.\",\"कात्रीच्या दोन पात्यांमध्ये लघुकोन व विशालकोन तयार होतो.\",\"वर्तुळ म्हणजे सर्व बिंदूंचा संच ज्यांचे अंतर केंद्रापासून समान असते.\",\"वर्तुळाची जीवा म्हणजे वर्तुळातील दोन बिंदूंना जोडणारी सरळ रेषा.\",\"वर्तुळाचा व्यास म्हणजे वर्तुळाच्या केंद्रातून जाणारी जीवा जी सर्वात लांब असते.\",\"वर्तुळाची त्रिज्या म्हणजे केंद्रापासून वर्तुळावरील कोणत्याही बिंदूपर्यंतचे अंतर.\",\"वर्तुळाचे केंद्र म्हणजे सर्व रेषा ज्या वर्तुळाला दोन सम भागात विभागतात त्या छेदबिंदू.\",\"आयताला चार बाजू व चार शिरोबिंदू असतात.\",\"आयताचे सर्व कोन काटकोन असतात.\",\"चौरसाला चार बाजू व चार शिरोबिंदू असतात आणि सर्व बाजू समान लांबीच्या असतात.\",\"चौरसाचे सर्व कोन काटकोन असतात.\",\"त्रिकोणाला तीन बाजू व तीन शिरोबिंदू असतात.\",\"त्रिकोणाचे कोन एकत्र १८० अंश असतात.\",\"लघुकोन, काटकोन व विशालकोन हे कोनांचे तीन प्रमुख प्रकार आहेत.\",\"कोन ओळखण्यासाठी आपण कोन मापक वापरू शकतो.\",\"कोन मापकावर ० अंश ते १८० अंशपर्यंतचे मापन असते.\",\"कोन मापकावर १ अंश = १ डिग्री असते.\",\"कोन मापकावर ९० अंश = १\\/४ वर्तुळ असते.\",\"कोन मापकावर १८० अंश = अर्धवर्तुळ असते.\",\"कोन मापकावर ३६० अंश = पूर्ण वर्तुळ असते.\"]','[{\"q\":\"घड्याळात ३ वाजता व ९ वाजता तासकाटा व मिनिटकाटा कोणत्या प्रकारचा कोन तयार करतात?\",\"options\":[\"काटकोन\",\"लघुकोन\",\"विशालकोन\",\"कोणताही कोन नाही\"],\"answer\":0,\"explain\":\"३ वाजता व ९ वाजता तासकाटा व मिनिटकाटा एकमेकांना ९० अंशाचा काटकोन करतात.\"},{\"q\":\"कात्रीच्या दोन पात्यांमध्ये लघुकोन तयार होतो का?\",\"options\":[\"होय\",\"नाही\",\"कधी कधी\",\"कधीच नाही\"],\"answer\":0,\"explain\":\"कात्रीच्या पात्यांमध्ये लघुकोन तयार होतो.\"},{\"q\":\"वर्तुळाची जीवा म्हणजे काय?\",\"options\":[\"वर्तुळाची सर्वात लांब रेषा\",\"वर्तुळाच्या केंद्रातून जाणारी रेषा\",\"वर्तुळातील दोन बिंदूंना जोडणारी सरळ रेषा\",\"वर्तुळाची त्रिज्या\"],\"answer\":2,\"explain\":\"जीवा म्हणजे वर्तुळातील दोन बिंदूंना जोडणारी सरळ रेषा.\"},{\"q\":\"आयताचे सर्व कोन कोणते असतात?\",\"options\":[\"काटकोन\",\"लघुकोन\",\"विशालकोन\",\"दोन्ही लघुकोन व काटकोन\"],\"answer\":0,\"explain\":\"आयताचे सर्व कोन काटकोन असतात.\"},{\"q\":\"चौरसाला किती शिरोबिंदू असतात?\",\"options\":[\"एक\",\"दोन\",\"तीन\",\"चार\"],\"answer\":3,\"explain\":\"चौरसाला चार शिरोबिंदू असतात.\"},{\"q\":\"त्रिकोणाचे कोन एकत्र किती अंशाचे असतात?\",\"options\":[\"९०\",\"१२०\",\"१८०\",\"२४०\"],\"answer\":2,\"explain\":\"त्रिकोणाचे कोन एकत्र १८० अंशाचे असतात.\"},{\"q\":\"वर्तुळाचा व्यास वर्तुळाच्या केंद्रातून कोणत्या बिंदूपर्यंत जातो?\",\"options\":[\"केंद्र व वर्तुळावरील कोणताही बिंदू\",\"केंद्र व वर्तुळाच्या कडावरील बिंदू\",\"केंद्र व वर्तुळाच्या बाहेरील बिंदू\",\"केंद्र व वर्तुळाच्या आतला बिंदू\"],\"answer\":1,\"explain\":\"व्यास केंद्र व वर्तुळाच्या कडावरील बिंदू जोडतो.\"},{\"q\":\"काटकोनापेक्षा लहान कोनाला काय म्हणतात?\",\"options\":[\"विशालकोन\",\"लघुकोन\",\"काटकोन\",\"कोणताही कोन नाही\"],\"answer\":1,\"explain\":\"लघुकोन म्हणजे काटकोनापेक्षा लहान कोन.\"},{\"q\":\"काटकोनापेक्षा मोठा कोन काय म्हणतात?\",\"options\":[\"लघुकोन\",\"विशालकोन\",\"काटकोन\",\"कोणताही कोन नाही\"],\"answer\":1,\"explain\":\"विशालकोन म्हणजे काटकोनापेक्षा मोठा कोन.\"},{\"q\":\"वर्तुळाचे केंद्र काय म्हणतात?\",\"options\":[\"मध्यबिंदू\",\"त्रिज्या\",\"जीवा\",\"व्यास\"],\"answer\":0,\"explain\":\"वर्तुळाचे केंद्र \'म\' असे म्हणतात.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16743,22,4,'Maths','mr','संख्याज्ञान','[\"संख्या म्हणजे अंकांची एकत्रित रचना.\",\"एकक, दशक, शतक, हजार अशी स्थानं असतात.\",\"शतकस्थानी 0 घेता येत नाही.\",\"अंककार्ड वापरून तीन अंकी संख्या तयार करता येतात.\",\"संख्या अक्षरांत लिहिताना शतक, दशक, एकक यांची नावे वापरली जातात.\",\"अक्षरांत लिहिलेल्या संख्येचं विस्तारित रूप म्हणजे प्रत्येक स्थानाची किंमत दाखवणं.\",\"विस्तारित रूपातून संख्या लिहिताना शून्य स्थानांवर 0 लिहिले जाते.\",\"दोन-तीन अंकी संख्या वाचताना सर्वात मोठ्या स्थानापासून सुरुवात करतात.\",\"लगतची पुढची संख्या म्हणजे दिलेल्या संख्येत 1 वाढवणे.\",\"लगतची मागची संख्या म्हणजे दिलेल्या संख्येत 1 कमी करणे.\",\"सम संख्या म्हणजे 2 ने भागल्यावर बाकी 0 येणारी संख्या.\",\"विषम संख्या म्हणजे 2 ने भागल्यावर बाकी 1 येणारी संख्या.\",\"सम संख्येच्या एकक स्थानावर 0,2,4,6,8 येतात.\",\"विषम संख्येच्या एकक स्थानावर 1,3,5,7,9 येतात.\",\"चार अंकी संख्या तयार करताना हजार स्थानाचे अंक प्रथम लिहिले जातात.\",\"दहह, शत, दशक, एकक या स्थानांना शून्य लिहिता येते जर अंक नसेल.\",\"आंतरराष्ट्रीय अंक 0-9 हेच असतात आणि सर्वत्र वापरले जातात.\",\"संख्या वाचताना सर्वात मोठ्या स्थानापासून वाचतात आणि नंतर लहान स्थानाकडे जातात.\",\"संख्या लिहिताना शतक, दशक, एकक या स्थानांमध्ये योग्य अंक लिहिले जातात.\",\"संख्या वाचताना शतकस्थानी 0 घेता येत नाही याची काळजी घ्यावी.\"]','[{\"q\":\"संख्या ३२५ अक्षरांत कशी लिहायची?\",\"options\":[\"तीनशे पच्चीस\",\"तीनशे पंचवीस\",\"तीनशे पाचवीस\",\"तीनशे पाचवीस\"],\"answer\":0,\"explain\":\"३२५ = तीनशे पच्चीस\"},{\"q\":\"५४९ या संख्येतील शतकस्थानी कोणता अंक आहे?\",\"options\":[\"५\",\"४\",\"९\",\"०\"],\"answer\":0,\"explain\":\"शतकस्थानी ५ आहे\"},{\"q\":\"६६७ या संख्येतील दशकस्थानी किती?\",\"options\":[\"६\",\"७\",\"६\",\"०\"],\"answer\":0,\"explain\":\"दशकस्थानी ६ आहे\"},{\"q\":\"७८२ या संख्येतील एककस्थानी काय?\",\"options\":[\"२\",\"८\",\"७\",\"०\"],\"answer\":0,\"explain\":\"एककस्थानी २ आहे\"},{\"q\":\"८९०० या संख्येतील शतकस्थानी ० आहे का?\",\"options\":[\"हो\",\"नाही\",\"कदाचित\",\"संदिग्ध\"],\"answer\":1,\"explain\":\"शतकस्थानी ० नाही, कारण ८९०० मध्ये शतकस्थानी ९ आहे\"},{\"q\":\"४०२८ या संख्येतील दशकस्थानी कोणता अंक?\",\"options\":[\"२\",\"८\",\"४\",\"०\"],\"answer\":0,\"explain\":\"दशकस्थानी २ आहे\"},{\"q\":\"५३०९ या संख्येतील एककस्थानी काय?\",\"options\":[\"९\",\"०\",\"५\",\"३\"],\"answer\":0,\"explain\":\"एककस्थानी ९ आहे\"},{\"q\":\"४००० या संख्येतील हजारस्थानी कोणता अंक?\",\"options\":[\"४\",\"०\",\"०\",\"०\"],\"answer\":0,\"explain\":\"हजारस्थानी ४ आहे\"},{\"q\":\"१२७४५ या संख्येतील हजारस्थानी काय?\",\"options\":[\"१\",\"२\",\"७\",\"४\"],\"answer\":0,\"explain\":\"हजारस्थानी १ आहे\"},{\"q\":\"५३४२ या संख्येतील शतकस्थानी कोणता अंक?\",\"options\":[\"५\",\"३\",\"४\",\"२\"],\"answer\":0,\"explain\":\"शतकस्थानी ३ आहे\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16744,22,4,'Maths','mr','बेरीज','[\"बेरीज म्हणजे दोन किंवा अधिक संख्यांची एकत्रित बेरीज करणे.\",\"एकक, दशक, शतक, हजार, दशहजार अशा स्थानांवरून बेरीज करतात.\",\"उभ्या मांडणीत सर्वात उजवीकडील एकक स्थानावरून डावीकडे जातात.\",\"जर एखाद्या स्थानावर बेरीज 10 किंवा जास्त झाली तर पुढील स्थानावर 1 ‘हात’ (carry) जातो.\",\"उभ्या मांडणीत प्रत्येक स्थानावर फक्त एकच अंक लिहितात.\",\"आडव्या मांडणीत सर्व संख्या एकमेकांच्या वर लिहून एकाच वेळी बेरीज करतात.\",\"बेरीज करताना ‘हात’ (carry) लिहिणे महत्त्वाचे आहे.\",\"समान स्थानांवरील अंकांची बेरीज करून ‘हात’ पुढे नेणे हे नियम आहे.\",\"चार अंकी किंवा पाच अंकी संख्यांची बेरीज करताना हजार आणि दशहजार स्थानांवरही ‘हात’ येऊ शकतो.\",\"बेरीज करताना ‘हात’ न लिहिल्यास चुकीची बेरीज होऊ शकते.\",\"उभ्या मांडणीत ‘हात’ लिहिणे सोपे असते कारण स्थानानुसार ओळखता येते.\",\"आडव्या मांडणीत ‘हात’ लिहिण्यासाठी ‘+’ चिन्हाच्या खाली ‘हात’ लिहितात.\",\"बेरीज करताना ‘हात’ न लिहिल्यास पुढील स्थानावर चुकीचा अंक येतो.\",\"बेरीज करताना सर्व स्थानांची बेरीज एकत्रित करून अंतिम उत्तर मिळते.\",\"बेरीज ही प्राथमिक गणितातील सर्वात महत्त्वाची क्रिया आहे.\",\"बेरीज करताना ‘हात’ लिहिणे हे गणितातील ‘कॅरी’ (carry) म्हणतात.\",\"बेरीज करताना ‘हात’ लिहिणे हे ‘कॅरी ओव्हर’ (carry over) म्हणतात.\",\"बेरीज करताना ‘हात’ लिहिणे हे ‘कॅरी’ (carry) म्हणून ओळखले जाते.\",\"बेरीज करताना ‘हात’ लिहिणे हे ‘कॅरी’ (carry) म्हणून ओळखले जाते.\",\"बेरीज करताना ‘हात’ लिहिणे हे ‘कॅरी’ (carry) म्हणून ओळखले जाते.\",\"बेरीज करताना ‘हात’ लिहिणे हे ‘कॅरी’ (carry) म्हणून ओळखले जाते.\",\"बेरीज करताना ‘हात’ लिहिणे हे ‘कॅरी’ (carry) म्हणून ओळखले जाते.\",\"बेरीज करताना ‘हात’ लिहिणे हे ‘कॅरी’ (carry) म्हणून ओळखले जाते.\",\"बेरीज करताना ‘हात’ लिहिणे हे ‘कॅरी’ (carry) म्हणून ओळखले जाते.\",\"बेरीज करताना ‘हात’ लिहिणे हे ‘कॅरी’ (carry) म्हणून ओळखले जाते.\"]','[{\"q\":\"३४२ + १२३ किती होईल?\",\"options\":[\"४६५\",\"४६४\",\"४६३\",\"४६२\"],\"answer\":0,\"explain\":\"३४२ + १२३ = ४६५.\"},{\"q\":\"५६४२ + ४१७९ किती होईल?\",\"options\":[\"९८२१\",\"९८२०\",\"९८१९\",\"९८१८\"],\"answer\":0,\"explain\":\"५६४२ + ४१७९ = ९८२१.\"},{\"q\":\"२३०१ + ४०५६ किती होईल?\",\"options\":[\"६३७७\",\"६३७६\",\"६३७५\",\"६३७४\"],\"answer\":0,\"explain\":\"२३०१ + ४०५६ = ६३७७.\"},{\"q\":\"७७७७ + २००१ किती होईल?\",\"options\":[\"९७७८\",\"९७७७\",\"९७७६\",\"९७७५\"],\"answer\":0,\"explain\":\"७७७७ + २००१ = ९७७८.\"},{\"q\":\"३४५ + ३२४ किती होईल?\",\"options\":[\"६६९\",\"६६८\",\"६६७\",\"६६६\"],\"answer\":0,\"explain\":\"३४५ + ३२४ = ६६९.\"},{\"q\":\"४०१७ + २०८१ किती होईल?\",\"options\":[\"६०००\",\"६००१\",\"६००२\",\"६००३\"],\"answer\":0,\"explain\":\"४०१७ + २०८१ = ६०००.\"},{\"q\":\"८५००९ + ३६५८ किती होईल?\",\"options\":[\"८८६६७\",\"८८६६६\",\"८८६६५\",\"८८६६४\"],\"answer\":0,\"explain\":\"८५००९ + ३६५८ = ८८६६७.\"},{\"q\":\"११५७ + ३०० किती होईल?\",\"options\":[\"१४५७\",\"१४५६\",\"१४५५\",\"१४५४\"],\"answer\":0,\"explain\":\"११५७ + ३०० = १४५७.\"},{\"q\":\"२४५५८ + ३० किती होईल?\",\"options\":[\"२४५८८\",\"२४५८९\",\"२४५८७\",\"२४५८६\"],\"answer\":0,\"explain\":\"२४५५८ + ३० = २४५८८.\"},{\"q\":\"३७ + ४० किती होईल?\",\"options\":[\"७७\",\"७६\",\"७५\",\"७४\"],\"answer\":0,\"explain\":\"३७ + ४० = ७७.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16745,22,4,'Maths','mr','वजाबाकी','[\"वजाबाकी म्हणजे मोठ्या संख्येतून लहान संख्या वजा करून उरलेली रक्कम शोधणे.\",\"उभ्या मांडणीने वजाबाकी करताना एकक, दशक, शतक, हजार अशा घरांमध्ये संख्या लिहून एककांपासून सुरुवात करतो.\",\"जर वजावटीची संख्या जास्त असेल तर ‘कर्ज घेणे’ म्हणजे पुढच्या घरातून 1 घेऊन वजावटीचे स्थान कमी करतो.\",\"उदाहरणार्थ ४५२ - ३२१ = १३१, २०७ - १६५ = ४२.\",\"वजाबाकीची तीन पद्धती: उभी मांडणी, आडवी मांडणी आणि तोंडी पद्धत.\",\"बेरीज आणि वजाबाकी एकमेकांच्या उलट आहेत – बेरीज = वजाबाकी + वजावटीची संख्या.\",\"वजाबाकी करताना शून्यापेक्षा कमी संख्या आली तर पुढच्या घरातून 1 ‘कर्ज’ घेऊन वजावटीची संख्या वाढवतो.\",\"वजाबाकीचे उदाहरण: ५८६ - ४२५ = १६१.\",\"वजाबाकीची उत्तरं नेहमीच धन संख्या असतात (सकारात्मक).\",\"वजाबाकी करताना ‘कर्ज’ घेणे म्हणजे ‘borrow’ या शब्दाने ओळखले जाते.\",\"वजाबाकीचे सराव करण्यासाठी विविध आकाराच्या संख्यांचे प्रश्न सोडवणे उपयुक्त.\",\"वजाबाकीच्या प्रश्नांमध्ये ‘किती कमी’ किंवा ‘किती जास्त’ हे विचारले जाते.\",\"वजाबाकी करताना ‘एकक’, ‘दशक’, ‘शतक’, ‘हजार’ या घरांमध्ये ‘borrow’ घेणे आवश्यक असते.\",\"वजाबाकीच्या प्रश्नांमध्ये ‘उरले’ किंवा ‘शिल्लक’ या शब्दांचा वापर होतो.\",\"वजाबाकीचे उत्तर शोधण्यासाठी ‘वजावटीची संख्या’ आणि ‘वजावटीची संख्या’ यांची तुलना करणे महत्त्वाचे.\",\"वजाबाकीचे सराव करताना ‘उभ्या’ आणि ‘आडव्या’ मांडणी दोन्ही वापरून पाहणे चांगले.\",\"वजाबाकीच्या प्रश्नांमध्ये ‘कमी’ किंवा ‘जास्त’ या शब्दांनी उत्तर शोधणे सोपे होते.\",\"वजाबाकी करताना ‘borrow’ घेणे म्हणजे ‘कर्ज’ घेणे – हे लक्षात ठेवणे आवश्यक.\",\"वजाबाकीचे प्रश्न सोडवताना ‘कर्ज’ घेतल्यावर पुढच्या घरातील संख्या 1 ने कमी होते.\",\"वजाबाकीचे सराव करताना ‘कर्ज’ घेतल्यावर पुढच्या घरातील संख्या 1 ने वाढते.\",\"वजाबाकीच्या प्रश्नांमध्ये ‘उरले’ किंवा ‘शिल्लक’ या शब्दांनी उत्तर दिले जाते.\",\"वजाबाकीच्या प्रश्नांमध्ये ‘कमी’ किंवा ‘जास्त’ या शब्दांनी उत्तर दिले जाते.\",\"वजाबाकी करताना ‘borrow’ घेणे म्हणजे ‘कर्ज’ घेणे – हे लक्षात ठेवणे आवश्यक.\",\"वजाबाकीचे सराव करताना ‘उभ्या’ आणि ‘आडव्या’ मांडणी दोन्ही वापरून पाहणे चांगले.\",\"वजाबाकीचे सराव करताना ‘कर्ज’ घेतल्यावर पुढच्या घरातील संख्या 1 ने कमी होते.\"]','[{\"q\":\"४५२ - ३२१ किती होईल?\",\"options\":[\"११२\",\"१३१\",\"१२०\",\"१२००\"],\"answer\":1,\"explain\":\"३२१ पासून ४५२ पर्यंत १३१ वजा करतो.\"},{\"q\":\"२०७ - १६५ किती?\",\"options\":[\"४२\",\"४१\",\"४३\",\"४०\"],\"answer\":0,\"explain\":\"२०७ वजा १६५ = ४२.\"},{\"q\":\"५८६ - ४२५ किती?\",\"options\":[\"१६१\",\"१६०\",\"१५९\",\"१६२\"],\"answer\":0,\"explain\":\"५८६ वजा ४२५ = १६१.\"},{\"q\":\"७५४ - २८७ किती?\",\"options\":[\"४६७\",\"४६६\",\"४६८\",\"४६५\"],\"answer\":0,\"explain\":\"७५४ वजा २८७ = ४६७.\"},{\"q\":\"३७२ - २५० किती?\",\"options\":[\"१२२\",\"१२१\",\"१२०\",\"१२३\"],\"answer\":0,\"explain\":\"३७२ वजा २५० = १२२.\"},{\"q\":\"९१५ - ४२७ किती?\",\"options\":[\"४८८\",\"४८७\",\"४८९\",\"४८६\"],\"answer\":0,\"explain\":\"९१५ वजा ४२७ = ४८८.\"},{\"q\":\"९१५ - ७०० किती?\",\"options\":[\"२१५\",\"२१४\",\"२१६\",\"२१७\"],\"answer\":0,\"explain\":\"९१५ वजा ७०० = २१५.\"},{\"q\":\"५३४ - २५२ किती?\",\"options\":[\"२८२\",\"२८१\",\"२८३\",\"२८४\"],\"answer\":0,\"explain\":\"५३४ वजा २५२ = २८२.\"},{\"q\":\"४०० - १०० किती?\",\"options\":[\"३००\",\"३१०\",\"२९०\",\"३२०\"],\"answer\":0,\"explain\":\"४०० वजा १०० = ३००.\"},{\"q\":\"५८८८ - २८८८ किती?\",\"options\":[\"३०००\",\"३१००\",\"३२००\",\"३३००\"],\"answer\":0,\"explain\":\"५८८८ वजा २८८८ = ३०००.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16746,22,4,'Maths','mr','गुणाकार : भाग १','[\"गुणाकार म्हणजे दोन किंवा अधिक संख्यांचा एकत्रित गुणाकार करणे.\",\"एक डझन म्हणजे १२.\",\"आठ डझन म्हणजे ८×१२ = ९६.\",\"गुणाकारासाठी ‘पद्‌धती’ किंवा ‘गुणाकार चौकट’ वापरता येते.\",\"शतक संख्या (१००) ला एखाद्या संख्येने गुणताना फक्त शतकातील अंकाला गुणून नंतर शून्ये लिहायची.\",\"उदा. ४×१०० = ४००, ६×१०० = ६००.\",\"शतकाच्या पलीकडील संख्या १०० पेक्षा कमी असतील तर त्यांना ‘शतक’ म्हणत नाहीत.\",\"गुणाकार करताना मोठ्या संख्येच्या एकक स्थानापासून सुरू करणे सोपे असते.\",\"उदाहरण: ३७×१५ = ५५५ (३७×१० + ३७×५).\",\"गुणाकाराचे परिणाम ‘उत्पादन’ म्हणतात.\",\"गुणाकाराचे नियम: गुणाकाराची क्रमबदल (a×b = b×a) आणि गुणाकाराची वितरण (a×(b+c)=a×b + a×c).\",\"गुणाकाराचे उत्तर शून्याने सुरू होत असेल तर शून्ये काढून टाकता येतात.\",\"गुणाकार करताना ‘शतक’ पद्धतीने शून्ये लिहिल्यास गणना सोपी होते.\",\"गुणाकाराचे सराव प्रश्न वाचून समजून घेणे महत्त्वाचे.\",\"गुणाकाराचे प्रश्न सोडवताना उत्तर तपासण्यासाठी उलट गुणाकार (भागाकार) वापरता येतो.\",\"गुणाकाराचे प्रश्न विविध विषयांमध्ये येतात: केळी, मुलं, पुस्तके, रोपे इत्यादी.\",\"गुणाकाराचे सराव प्रश्न सोडवताना ‘कॅल्क्युलेटर’ किंवा ‘हिशोबपत्र’ वापरू शकतो.\"]','[{\"q\":\"८ डझन केळी किती केळी होतील?\",\"options\":[\"८०\",\"९६\",\"१००\",\"१२०\"],\"answer\":1,\"explain\":\"१ डझन = १२, ८×१२ = ९६.\"},{\"q\":\"३७×१५ चे उत्तर काय?\",\"options\":[\"५५५\",\"५४५\",\"५२५\",\"४८०\"],\"answer\":0,\"explain\":\"३७×१०=३७०, ३७×५=१८५, एकत्र ५५५.\"},{\"q\":\"४० विद्यार्थ्यांनी प्रत्येकी ३०० रुपये दिले तर एकूण किती रुपये?\",\"options\":[\"१२,०००\",\"१२,००००\",\"१०,०००\",\"८,०००\"],\"answer\":0,\"explain\":\"३००×४० = १२,०००.\"},{\"q\":\"२४५ रुपये असलेल्या ८ पुस्तकांचा एकूण खर्च किती?\",\"options\":[\"१९६०\",\"१९६००\",\"२४५०\",\"२४५००\"],\"answer\":0,\"explain\":\"२४५×८ = १९६०.\"},{\"q\":\"७०९×७६ चे उत्तर काय?\",\"options\":[\"५३८८४\",\"५३८८४०\",\"५३८८४००\",\"५३८८४०००\"],\"answer\":0,\"explain\":\"७०९×७६ = ५३८८४.\"},{\"q\":\"८१९×१२ चे उत्तर काय?\",\"options\":[\"९८२८\",\"९८२८०\",\"९८२८००\",\"९८२८०००\"],\"answer\":0,\"explain\":\"८१९×१०=८१९०, ८१९×२=१६३८, एकत्र ९८२८.\"},{\"q\":\"५४५×३८ चे उत्तर काय?\",\"options\":[\"२०६१०\",\"२०६१००\",\"२०६१०००\",\"२०६१००००\"],\"answer\":0,\"explain\":\"५४५×३०=१६३५०, ५४५×८=४३६०, एकत्र २०६१०.\"},{\"q\":\"९५३×३८ चे उत्तर काय?\",\"options\":[\"३६१४४\",\"३६१४४०\",\"३६१४४००\",\"३६१४४०००\"],\"answer\":0,\"explain\":\"९५३×३०=२८६००, ९५३×८=७६४४, एकत्र ३६१४४.\"},{\"q\":\"६१०×४५ चे उत्तर काय?\",\"options\":[\"२७४५०\",\"२७४५००\",\"२७४५०००\",\"२७४५००००\"],\"answer\":0,\"explain\":\"६१०×४०=२४४००, ६१०×५=३०५०, एकत्र २७४५०.\"},{\"q\":\"४०७×५५ चे उत्तर काय?\",\"options\":[\"२२,३५५\",\"२२,३५५०\",\"२२,३५५००\",\"२२,३५५०००\"],\"answer\":0,\"explain\":\"४०७×५०=२०३५०, ४०७×५=२०३५, एकत्र २२,३५५.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16747,22,4,'Maths','mr','भागाकार : भाग १','[\"भागाकार म्हणजे एखादी संख्या (भाज्य) दुसर्‍या संख्येने (भाजक) भागून मिळणारा निकाल\",\"भाजकाला ‘भाग’ म्हणतात, भाज्याला ‘भागाकार’ म्हणतात\",\"भागाकाराचे तीन भाग असतात – भाज्य, भाजक, भागाकार (आणि बाकी)\",\"भागाकार करताना ‘रेघेच्या वर’ भागाकार लिहितात आणि ‘रेघेच्या खाली’ बाकी लिहितात\",\"भागाकार करताना भाजकाची जास्तीत जास्त पट भाज्येतून वजा करतात\",\"उरलेली बाकी भाजकापेक्षा लहान असते\",\"भागाकार करताना ‘दशक’ आणि ‘एकक’ वेगळे करून सोडवतात\",\"उदाहरण: 84 ÷ 4 = 21 (दशक 8 वजा 4 = 4, एकक 4 वजा 4 = 0)\",\"भागाकार 0 असल्यास भागाकार 0 येतो (उदा. 0 ÷ 3 = 0)\",\"भागाकार करताना ‘समान वाटणी’ म्हणजे सर्वांना समान संख्या मिळणे\",\"भागाकाराचे नियम: भाजक 1 असल्यास भागाकार = भाज्य, भाजक भाज्यापेक्षा मोठा असल्यास भागाकार 0\",\"भागाकार करताना ‘पायरी पायरी’ पद्धत वापरतात – प्रथम दशके, नंतर एकके\",\"भागाकार करताना ‘उरलेली संख्या’ म्हणजे ‘बाकी’\",\"भागाकारात ‘रेघेच्या वर’ भागाकार, ‘रेघेच्या खाली’ बाकी लिहिणे आवश्यक\",\"भागाकार करताना ‘समान वाटणी’ आणि ‘उरलेली संख्या’ यांचा फरक ओळखणे महत्त्वाचे\",\"भागाकार करताना ‘दशक’ आणि ‘एकक’ वेगळे केल्याने मोठ्या संख्येचे भागाकार सोपे होते\",\"भागाकार करताना ‘उरलेली संख्या’ भाजकापेक्षा लहान असते\",\"भागाकार करताना ‘भागाकार’ आणि ‘बाकी’ यांचा संबंध: भाज्य = (भागाकार × भाजक) + बाकी\",\"भागाकार करताना ‘भागाकार’ आणि ‘बाकी’ दोन्ही लिहून पूर्ण उत्तर मिळते\",\"भागाकाराची ‘समीकरण’ अशी असते: भाज्य ÷ भाजक = भागाकार शेष बाकी\",\"भागाकार करताना ‘समान वाटणी’ आणि ‘उरलेली संख्या’ यांचा वापर करून प्रश्न सोडवतात\",\"भागाकार करताना ‘दशक’ आणि ‘एकक’ वेगळे केल्याने ‘उरलेली संख्या’ स्पष्ट होते\",\"भागाकार करताना ‘उरलेली संख्या’ 0 असल्यास ‘भागाकार’ पूर्ण असतो\",\"भागाकार करताना ‘उरलेली संख्या’ 0 नसल्यास ‘भागाकार’ पूर्ण नाही\",\"भागाकार करताना ‘उरलेली संख्या’ 0 असल्यास ‘भागाकार’ आणि ‘बाकी’ दोन्ही लिहावे\"]','[{\"q\":\"20 चॉकलेटे 5 मुलांना समान वाटल्यास प्रत्येकाला किती चॉकलेटे मिळतील?\",\"options\":[\"4\",\"3\",\"5\",\"2\"],\"answer\":0,\"explain\":\"20 ÷ 5 = 4\"},{\"q\":\"12 रिंगा 3 स्टँडवर समान वाटल्यास प्रत्येक स्टँडवर किती रिंगा?\",\"options\":[\"4\",\"3\",\"2\",\"1\"],\"answer\":0,\"explain\":\"12 ÷ 3 = 4\"},{\"q\":\"84 पोती 4 शेतकऱ्यांना समान वाटल्यास प्रत्येकाला किती पोती?\",\"options\":[\"21\",\"20\",\"22\",\"19\"],\"answer\":0,\"explain\":\"84 ÷ 4 = 21\"},{\"q\":\"36 टिकल्या 4 ओळींमध्ये समान वाटल्यास प्रत्येक ओळीत किती टिकल्या?\",\"options\":[\"9\",\"8\",\"6\",\"5\"],\"answer\":0,\"explain\":\"36 ÷ 4 = 9\"},{\"q\":\"36 टिकल्या 6 ओळींमध्ये समान वाटल्यास प्रत्येक ओळीत किती टिकल्या?\",\"options\":[\"6\",\"5\",\"4\",\"3\"],\"answer\":0,\"explain\":\"36 ÷ 6 = 6\"},{\"q\":\"58 गोळ्या 3 जणांना समान वाटल्यास प्रत्येकाला किती गोळ्या?\",\"options\":[\"19\",\"20\",\"18\",\"17\"],\"answer\":0,\"explain\":\"58 ÷ 3 = 19 शेष 1\"},{\"q\":\"21 लाडू 4 बश्या मध्ये समान वाटल्यास प्रत्येक बशीत किती लाडू?\",\"options\":[\"5\",\"4\",\"3\",\"2\"],\"answer\":0,\"explain\":\"21 ÷ 4 = 5 शेष 1\"},{\"q\":\"0 गोळ्या 3 जणांना समान वाटल्यास प्रत्येकाला किती गोळ्या?\",\"options\":[\"0\",\"1\",\"2\",\"3\"],\"answer\":0,\"explain\":\"0 ÷ 3 = 0\"},{\"q\":\"80 वस्तू 4 जणांना समान वाटल्यास प्रत्येकाला किती वस्तू?\",\"options\":[\"20\",\"15\",\"25\",\"10\"],\"answer\":0,\"explain\":\"80 ÷ 4 = 20\"},{\"q\":\"10 पेरू 3 जणांना समान वाटल्यास प्रत्येकाला किती पेरू?\",\"options\":[\"3\",\"4\",\"2\",\"1\"],\"answer\":0,\"explain\":\"10 ÷ 3 = 3 शेष 1\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16748,22,4,'Maths','mr','नाणी व नोटा','[\"नाणी व नोटा म्हणजे पैसे मोजण्याचे विविध प्रकारचे नाणे व नोटा.\",\"रुपयाची मोड म्हणजे एखाद्या रकमेचे लहान नाणी व नोटा वापरून तोडणे.\",\"उदाहरणार्थ ५ रुपयांची मोड २ नाणी ५० पैशांची २ नाणी किंवा १ रुपयाचे १ नाणे व ५० पैशांची २ नाणी अशी होऊ शकते.\",\"१० रुपयांची मोड १ नोट किंवा ५ नाणी २ रुपये व १ नाणे अशी होऊ शकते.\",\"२० रुपयांची मोड ४ नाणी ५ रुपयांची किंवा २ नाणी १० रुपयांची किंवा १ नाणे १० रुपये व २ नाणी ५ रुपये अशी होऊ शकते.\",\"बंदे करणे म्हणजे लहान मूल्याची नाणी किंवा नोटा देऊन त्याच रकमेची जास्त मूल्याची नाणी किंवा नोटा घेणे.\",\"नाण्यांचे मूल्य १० पट, ५ पट, २ पट इत्यादी गुणकांमध्ये असते. उदाहरणार्थ १०० रुपयांच्या नोटेचे मूल्य १०० रुपयांच्या नोटेच्या १० पट असते.\",\"नोटांच्या मूल्यांची तुलना करताना गुणकांचा वापर करावा.\",\"सुटे पैसे म्हणजे दिलेल्या रकमेचे बदल म्हणून दिलेले पैसे.\",\"नाणी व नोटा मोजताना एकक, दहावे, शंभरव्या इत्यादींची ओळख असणे आवश्यक आहे.\",\"मोड करताना विविध संयोजनांचा वापर करून एकच रक्कम मिळवता येते.\",\"सुटे पैसे मोजताना सर्वात मोठी नोट प्रथम वापरून नंतर लहान नोटा व नाणी वापरली जातात.\",\"नाण्यांचे मूल्य ५० पैशांची १ नाणी, १०० पैशांची १ नाणी इत्यादी असते.\",\"रुपयाच्या नोटांचे मूल्य १०० रुपयांची १ नोट, ५० रुपयांची १ नोट, २० रुपयांची १ नोट, १० रुपयांची १ नोट, ५ रुपयांची १ नोट अशी असते.\",\"नाणी व नोटा मोजताना एकूण रक्कम, नोटांची संख्या आणि नाण्यांची संख्या यांची गणना करावी.\",\"मोड करताना विविध पद्धतींची कल्पना करून लवचिकता वाढवावी.\",\"सुटे पैसे देताना ग्राहकाला योग्य रक्कम परत द्यावी.\",\"नाणी व नोटा मोजताना अचूकता व काळजी आवश्यक आहे.\",\"सुटे पैसे मोजताना सर्वात मोठी नोट प्रथम वापरणे सोपे व जलद असते.\",\"मोड करताना विविध संयोजनांची कल्पना करून गणितीय विचार वाढवता येतो.\",\"नाणी व नोटा मोजणे हे दैनंदिन जीवनातील महत्त्वाचे कौशल्य आहे.\",\"नाणी व नोटा मोजताना गणितीय तर्कशक्ती व तर्कशुद्धता वापरावी.\"]','[{\"q\":\"एका नाण्याचे मूल्य ५० पैशांचे आहे. २ रुपयांची मोड करण्यासाठी किती ५० पैशांची नाणी लागतील?\",\"options\":[\"2\",\"4\",\"6\",\"8\"],\"answer\":1,\"explain\":\"२ रुपयांमध्ये ४०० पैशे असतात. ४०० ÷ ५० = ८ नाणी.\"},{\"q\":\"१०० रुपयांच्या नोटेचे मूल्य ५० रुपयांच्या नोटेच्या दुप्पट आहे. तर २०० रुपयांच्या नोटेचे मूल्य किती पट असेल?\",\"options\":[\"2 पट\",\"4 पट\",\"5 पट\",\"10 पट\"],\"answer\":2,\"explain\":\"२०० रुपये = ४ × ५० रुपये, त्यामुळे ४ पट.\"},{\"q\":\"५०० रुपयांच्या नोटेचे मूल्य १०० रुपयांच्या नोटेच्या 5 पट आहे. ५०० रुपयांच्या ४ नोटांची एकूण किंमत किती?\",\"options\":[\"२००० रुपये\",\"२५०० रुपये\",\"३००० रुपये\",\"३५०० रुपये\"],\"answer\":0,\"explain\":\"४ × ५०० = २००० रुपये.\"},{\"q\":\"२० रुपयांचे सुटे १० रुपयांच्या २ नोटा किंवा ५ रुपयांच्या ४ नाणी अशा पद्धतीने दिले जाऊ शकतात. आणखी एक पद्धत कोणती?\",\"options\":[\"२ रुपयांच्या १० नाणी\",\"१० रुपयांच्या १ नोट व १० रुपयांच्या १ नोट\",\"५ रुपयांच्या २ नाणी व १० रुपयांच्या १ नाणी\",\"१० रुपयांच्या १ नोट व १० रुपयांच्या १ नाणी\"],\"answer\":2,\"explain\":\"५ रुपये × २ + १० रुपये × १ = २० रुपये.\"},{\"q\":\"अजयकडे ९ नोटा आहेत ज्यांची एकूण किंमत ५०० रुपये आहे. जर सर्व नोटा ५० रुपयांच्या असतील तर तो किती नोटा घेईल?\",\"options\":[\"9\",\"10\",\"8\",\"7\"],\"answer\":0,\"explain\":\"९ × ५० = ४५० रुपये, त्यामुळे ५० रुपयांच्या ९ नोटा ४५० रुपये होतात, ५० रुपये कमी.\"},{\"q\":\"स्वातीकडे १०० रुपयांच्या, ५० रुपयांच्या आणि २० रुपयांच्या नोटा आहेत. एकूण ५०० रुपये आहेत. जर १०० रुपयांच्या २ नोटा असतील तर ५० रुपयांच्या किती नोटा असतील?\",\"options\":[\"5\",\"4\",\"3\",\"2\"],\"answer\":1,\"explain\":\"२ × १०० = २०० रुपये, उरले ३०० रुपये. ३०० ÷ ५० = ६, परंतु २० रुपयांच्या नोटा देखील आहेत. योग्य संयोजन ४ × ५० = २००, २ × १०० = २००, एकूण ४००. त्यामुळे ५० रुपयांच्या ४ नोटा.\"},{\"q\":\"१०० रुपयांच्या नोटेचे मूल्य १० रुपयांच्या नोटेच्या १० पट आहे. १०० रुपयांच्या ५ नोटांची एकूण किंमत किती?\",\"options\":[\"५०० रुपये\",\"५५० रुपये\",\"६०० रुपये\",\"७०० रुपये\"],\"answer\":0,\"explain\":\"५ × १०० = ५०० रुपये.\"},{\"q\":\"२००० रुपयांच्या नोटेचे मूल्य ५०० रुपयांच्या नोटेच्या किती पट आहे?\",\"options\":[\"4 पट\",\"5 पट\",\"6 पट\",\"7 पट\"],\"answer\":1,\"explain\":\"२००० ÷ ५०० = 4, त्यामुळे ४ पट.\"},{\"q\":\"२००० रुपयांच्या नोटेचे मूल्य १०० रुपयांच्या नोटेच्या किती पट आहे?\",\"options\":[\"10 पट\",\"20 पट\",\"25 पट\",\"30 पट\"],\"answer\":1,\"explain\":\"२००० ÷ १०० = 20, त्यामुळे २० पट.\"},{\"q\":\"१ रुपयाची मोड करण्यासाठी ५० पैशांची किती नाणी लागतील?\",\"options\":[\"1\",\"2\",\"3\",\"4\"],\"answer\":3,\"explain\":\"१ रुपयात १०० पैशे असतात. १०० ÷ ५० = २ नाणी.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16749,22,4,'Maths','mr','वेळ मोजूया','[\"वेळ म्हणजे तास आणि मिनिटे\",\"१ तास = ६० मिनिटे\",\"अर्धा तास = ३० मिनिटे\",\"पाव तास = १५ मिनिटे\",\"पाऊण तास = ४५ मिनिटे\",\"घड्याळात १२ नंतर पुन्हा १ पासून वेळ मोजायला सुरुवात होते\",\"तासकाटा आणि मिनिटकाटा यांचा वापर करून वेळ वाचतात\",\"१ वाजून ३० मिनिटे = १.५ तास किंवा ‘दीड वाजला’\",\"१ वाजून १५ मिनिटे = ‘सव्वा एक’\",\"१ वाजून ४५ मिनिटे = ‘पाऊण एक’\",\"२ वाजून ३० मिनिटे = ‘साडे दोन’\",\"३ वाजून ३० मिनिटे = ‘साडे तीन’\",\"४ वाजून ३० मिनिटे = ‘साडे चार’\",\"५ वाजून ३० मिनिटे = ‘साडे पाच’\",\"६ वाजून ३० मिनिटे = ‘साडे सहा’\",\"७ वाजून ३० मिनिटे = ‘साडे सात’\",\"८ वाजून ३० मिनिटे = ‘साडे आठ’\",\"९ वाजून ३० मिनिटे = ‘साडे नऊ’\",\"१० वाजून ३० मिनिटे = ‘साडे दहा’\",\"११ वाजून ३० मिनिटे = ‘साडे अकरा’\",\"१२ वाजून ३० मिनिटे = ‘साडे बार’\",\"सव्वा म्हणजे ‘पावण’ + तास\",\"साडे म्हणजे ‘पावण’ + तास + ३० मिनिटे\",\"सव्वा आणि साडे हे वेळ वाचताना वापरले जाणारे शब्द आहेत\",\"लीप वर्ष म्हणजे फेब्रुवारीत २९ दिवस असणारे वर्ष\"]','[{\"q\":\"१ तासात किती मिनिटे असतात?\",\"options\":[\"३०\",\"४५\",\"६०\",\"७५\"],\"answer\":2,\"explain\":\"१ तास = ६० मिनिटे.\"},{\"q\":\"१ वाजून ३० मिनिटे कसे वाचतात?\",\"options\":[\"साडे एक\",\"सव्वा एक\",\"दीड वाजला\",\"पाऊण एक\"],\"answer\":2,\"explain\":\"१ वाजून ३० मिनिटे = ‘दीड वाजला’.\"},{\"q\":\"२ वाजून १५ मिनिटे कसे वाचतात?\",\"options\":[\"सव्वा दोन\",\"साडे दोन\",\"सव्वा एक\",\"साडे एक\"],\"answer\":0,\"explain\":\"२ वाजून १५ मिनिटे = ‘सव्वा दोन’.\"},{\"q\":\"३ वाजून ४५ मिनिटे कसे वाचतात?\",\"options\":[\"साडे तीन\",\"सव्वा तीन\",\"साडे दोन\",\"सव्वा दोन\"],\"answer\":0,\"explain\":\"३ वाजून ४५ मिनिटे = ‘साडे तीन’.\"},{\"q\":\"लीप वर्षात फेब्रुवारी महिन्यात किती दिवस असतात?\",\"options\":[\"२८\",\"२९\",\"३०\",\"३१\"],\"answer\":1,\"explain\":\"लीप वर्षात फेब्रुवारीत २९ दिवस असतात.\"},{\"q\":\"१५ ऑगस्ट कोणत्या दिवशी साजरा होतो?\",\"options\":[\"स्वातंत्र्यदिन\",\"वसंतोत्सव\",\"मकर संक्रांती\",\"दिवाळी\"],\"answer\":0,\"explain\":\"१५ ऑगस्ट रोजी स्वातंत्र्यदिन साजरा होतो.\"},{\"q\":\"१ वाजून ४५ मिनिटे कसे वाचतात?\",\"options\":[\"पाऊण एक\",\"सव्वा एक\",\"साडे एक\",\"दीड वाजला\"],\"answer\":0,\"explain\":\"१ वाजून ४५ मिनिटे = ‘पाऊण एक’.\"},{\"q\":\"१ वाजून १५ मिनिटे कसे वाचतात?\",\"options\":[\"सव्वा एक\",\"साडे एक\",\"सव्वा दोन\",\"साडे दोन\"],\"answer\":0,\"explain\":\"१ वाजून १५ मिनिटे = ‘सव्वा एक’.\"},{\"q\":\"१२ वाजून ३० मिनिटे कसे वाचतात?\",\"options\":[\"साडे बार\",\"सव्वा बार\",\"साडे दहा\",\"सव्वा दहा\"],\"answer\":0,\"explain\":\"१२ वाजून ३० मिनिटे = ‘साडे बार’.\"},{\"q\":\"सव्वा आणि साडे यातील फरक काय?\",\"options\":[\"सव्वा = १५ मिनिटे, साडे = ४५ मिनिटे\",\"सव्वा = ३० मिनिटे, साडे = ४५ मिनिटे\",\"सव्वा = १५ मिनिटे, साडे = ३० मिनिटे\",\"सव्वा = ४५ मिनिटे, साडे = १५ मिनिटे\"],\"answer\":0,\"explain\":\"सव्वा = १५ मिनिटे, साडे = ४५ मिनिटे.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16750,22,4,'Maths','mr','शाब्दिक उदाहरणे : बेरीज व वजाबाकी','[\"बेरीज म्हणजे दोन किंवा अधिक संख्यांना एकत्र करून एकूण मिळवणे.\",\"वजाबाकी म्हणजे एक संख्या दुसऱ्या संख्येतून वजा करून फरक शोधणे.\",\"बेरीज करताना समान स्थानाचे अंक एकत्र करतात, जर 10 किंवा अधिक झाले तर पुढच्या स्थानावर 1 जोडतात.\",\"वजाबाकी करताना कमी अंक मोठ्या अंकातून वजा करतात, जर कमी अंक मोठा असेल तर पुढच्या स्थानावरून 1 उधार घेतात.\",\"बेरीज व वजाबाकी दोन्हीमध्ये दशांश स्थान (दशांश बिंदू) लक्षात ठेवणे आवश्यक.\",\"सोप्या बेरीजसाठी 0 जोडणे किंवा वजाबाकी करताना 0 वजा करणे हे नियम आहेत.\",\"बेरीज व वजाबाकीची गणना करताना आकड्यांची क्रमवारता महत्त्वाची असते.\",\"बेरीज व वजाबाकीचे उदाहरणे दैनंदिन जीवनात जसे खरेदी, पैसे, लोकसंख्या इत्यादींमध्ये वापरतात.\",\"बेरीज व वजाबाकी करताना कॅल्क्युलेटर न वापरता कागदावर पायरी पायरीने लिहून सोडवता येते.\",\"समान स्थानाचे अंक एकत्र करून बेरीज करताना \'कॅरी\' (उधार) घेणे लक्षात ठेवावे.\",\"वजाबाकी करताना \'बोरो\' (उधार) घेणे लक्षात ठेवावे.\",\"बेरीज व वजाबाकीचे परिणाम एकच संख्या असते ज्याला \'परिणाम\' म्हणतात.\",\"बेरीज व वजाबाकीची गणना करताना आकड्यांमध्ये अल्पविराम (,) वापरल्याने वाचन सोपे होते.\",\"बेरीज व वजाबाकीच्या समस्यांमध्ये दिलेल्या आकड्यांना \'माहिती\' म्हणतात.\",\"समस्येतील प्रश्नाला \'विचारलेले\' असे म्हणतात आणि त्याचे उत्तर \'उपाय\' असते.\"]','[{\"q\":\"उमाकाकूंनी ५ किलोग्रॅम तूरडाळ ३४५ रुपये आणि २० किलोग्रॅम तांदूळ ७८९ रुपये खरेदी केले. एकूण किती रुपये दिले?\",\"options\":[\"१,१३४ रुपये\",\"१,४३४ रुपये\",\"१,५३४ रुपये\",\"१,६३४ रुपये\"],\"answer\":0,\"explain\":\"३४५ + ७८९ = १,१३४ रुपये.\"},{\"q\":\"एका रेफ्रिजरेटरची किंमत ₹१३,७५० आणि एका कपाटाची किंमत ₹८,९९९ आहे. दोन्ही वस्तू खरेदी केल्यास एकूण किती रुपये द्यावे?\",\"options\":[\"२२,७४९ रुपये\",\"२२,७४९ रुपये\",\"२२,७४९ रुपये\",\"२२,७४९ रुपये\"],\"answer\":0,\"explain\":\"१३,७५० + ८,९९९ = २२,७४९ रुपये.\"},{\"q\":\"बाबूरावांनी मोसंबीची १४३ झाडे आणि चिकूची १५६ झाडे लावली. एकूण किती झाडे लावली?\",\"options\":[\"२९९ झाडे\",\"२९९ झाडे\",\"२९९ झाडे\",\"२९९ झाडे\"],\"answer\":0,\"explain\":\"१४३ + १५६ = २९९ झाडे.\"},{\"q\":\"सर्कस पाहण्यासाठी १,३१० मुले, १,५०५ स्त्रिया आणि ७९० पुरुष आले. एकूण किती लोक आले?\",\"options\":[\"४,००५\",\"४,००५\",\"४,००५\",\"४,००५\"],\"answer\":0,\"explain\":\"१,३१० + १,५०५ + ७९० = ४,००५ लोक.\"},{\"q\":\"अजयने १८,००० रुपये आणि १५,००० रुपये ठेवले. एकूण किती रुपये ठेवले?\",\"options\":[\"३३,००० रुपये\",\"३३,००० रुपये\",\"३३,००० रुपये\",\"३३,००० रुपये\"],\"answer\":0,\"explain\":\"१८,००० + १५,००० = ३३,००० रुपये.\"},{\"q\":\"एका ग्रंथालयात १,२३० गोष्टींची पुस्तके आणि १५० कवितांची पुस्तके आहेत. एकूण किती पुस्तके आहेत?\",\"options\":[\"१,३८०\",\"१,३८०\",\"१,३८०\",\"१,३८०\"],\"answer\":0,\"explain\":\"१,२३० + १५० = १,३८० पुस्तके.\"},{\"q\":\"एका जंगलात एकूण ४२,३०६ झाडे आहेत. सागवानाची २३,४७९ आणि सुबाभळीची १६,६७५ झाडे आहेत. इतर झाडे किती?\",\"options\":[\"२,१५२\",\"२,१५२\",\"२,१५२\",\"२,१५२\"],\"answer\":0,\"explain\":\"४२,३०६ - (२३,४७९ + १६,६७५) = २,१५२ इतर झाडे.\"},{\"q\":\"एका कंपनीत पुरुषांची संख्या १,४५० आणि स्त्रियांची संख्या १,२७० आहे. एकूण किती लोक काम करतात?\",\"options\":[\"२,७२०\",\"२,७२०\",\"२,७२०\",\"२,७२०\"],\"answer\":0,\"explain\":\"१,४५० + १,२७० = २,७२० लोक.\"},{\"q\":\"एका मोटरसायकलची किंमत ₹४७,५८० आणि दुसऱ्या मोटरसायकलची किंमत ₹५०,२४० आहे. कोणत्या कंपनीची मोटरसायकल जास्त महाग आहे आणि किती रुपये जास्त?\",\"options\":[\"ब कंपनी ₹२,६०० जास्त\",\"ब कंपनी ₹२,६०० जास्त\",\"ब कंपनी ₹२,६०० जास्त\",\"ब कंपनी ₹२,६०० जास्त\"],\"answer\":0,\"explain\":\"५०,२४० - ४७,५८० = २,६०० रुपये जास्त.\"},{\"q\":\"एका रोपवाटिकेत ३२,१४० रोपे तयार झाली. त्यांपैकी १२,७८९ आंब्याची रोपे आणि १०,४२३ सागवानाची रोपे आहेत. इतर प्रकारची रोपे किती?\",\"options\":[\"९,०८८\",\"९,०८८\",\"९,०८८\",\"९,०८८\"],\"answer\":0,\"explain\":\"३२,१४० - (१२,७८९ + १०,४२३) = ९,०८८ रोपे.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16751,22,4,'Maths','mr','अपूर्णांक','[\"अपूर्णांक म्हणजे एखाद्या वस्तूला समान भागात विभागून घेतलेल्या भागाचे वर्णन करणारा संख्या.\",\"अपूर्णांकात दोन भाग असतात – वरची संख्या अंश (भागांची संख्या) आणि खालची संख्या छेद (समान भागांची एकूण संख्या).\",\"उदाहरण: १\\/२ म्हणजे एक अंश आणि दोन छेद – म्हणजे एक भाग दोन समान भागांपैकी एक.\",\"१\\/४ म्हणजे एक अंश आणि चार छेद – एक भाग चार समान भागांपैकी एक.\",\"१\\/३ म्हणजे एक अंश आणि तीन छेद – एक भाग तीन समान भागांपैकी एक.\",\"१\\/५, २\\/५, ३\\/५, ४\\/५ हे सर्व ५ समान भागांपैकी घेतलेल्या भागांचे अपूर्णांक आहेत.\",\"१\\/२, ३\\/४, २\\/३ हे सर्व अपूर्णांक आहेत ज्यात अंश आणि छेद दोन्ही १ पेक्षा जास्त असू शकतात.\",\"अपूर्णांक वाचताना आपण म्हणतो “अंश छेद” किंवा “अंश छेद” असे. उदाहरण: २\\/५ वाचतो “दोन अंश पाच छेद”.\",\"अपूर्णांकाचे गुणाकार किंवा भागाकार करताना अंश आणि छेद यांची गणना करावी लागते.\",\"अपूर्णांकाचे तुलनात्मक मूल्य पाहण्यासाठी अंश\\/छेद या गुणोत्तराची तुलना करावी लागते. छेद समान असतील तर अंश मोठा असेल तर अपूर्णांक मोठा.\",\"अपूर्णांकाचे कमी करणे म्हणजे अंश व छेद दोघांनाही त्यांच्या सर्वात मोठ्या समान विभाजकाने भागणे.\",\"अपूर्णांकाचे भिन्न रूपे: १\\/२ = २\\/४ = ३\\/६ इत्यादी. सर्व रूपे समान मूल्य दर्शवतात.\",\"अपूर्णांकाचे मिश्र संख्या: १ पूर्ण आणि १\\/२ म्हणजे १ १\\/२. हे “एक पूर्ण आणि अर्धा” असे वाचतात.\",\"अपूर्णांकाचे अपूर्णांक (improper fraction) म्हणजे अंश छेदापेक्षा मोठा किंवा समान असतो. उदाहरण: ३\\/२, ५\\/४.\",\"अपूर्णांकाचे पूर्णांकयुक्त अपूर्णांक (mixed number) म्हणजे पूर्णांक आणि अपूर्णांक यांचा एकत्रित भाग. उदाहरण: १ १\\/२, २ ३\\/४.\",\"अपूर्णांकाचे वाचन करताना ‘अंश’ आणि ‘छेद’ हे शब्द स्पष्टपणे वापरावेत.\",\"अपूर्णांकाचे मूल्य वाढवण्यासाठी अंश वाढवावा किंवा छेद कमी करावा.\",\"अपूर्णांकाचे मूल्य कमी करण्यासाठी अंश कमी करावा किंवा छेद वाढवावा.\",\"अपूर्णांकाचे तुलना करताना समान छेद असणे सोपे असते. जर छेद वेगळे असतील तर समान छेद बनवून तुलना करावी.\",\"अपूर्णांकाचे वाचन करताना ‘एक अंश दोन छेद’ किंवा ‘एक छेद दोन’ असे दोन्ही प्रकारे वाचता येते.\",\"अपूर्णांकाचे वाचन करताना ‘एक पूर्ण आणि अर्धा’ किंवा ‘एक पूर्ण आणि १\\/२’ असे वाचता येते.\",\"अपूर्णांकाचे वाचन करताना ‘पावण’ म्हणजे ‘१\\/२’ आणि ‘पावण’ म्हणजे ‘१\\/४’ यासारखे शब्द वापरले जातात.\",\"अपूर्णांकाचे वाचन करताना ‘सव्वा’ म्हणजे ‘१ १\\/४’ आणि ‘साडेतीन’ म्हणजे ‘३ १\\/२’ असे वाचतात.\",\"अपूर्णांकाचे वाचन करताना ‘पावणेदोन’ म्हणजे ‘१\\/२’ व ‘पावणेतीन’ म्हणजे ‘१\\/३’ असे वाचतात.\",\"अपूर्णांकाचे वाचन करताना ‘साडेचार’ म्हणजे ‘४ १\\/२’ असे वाचतात.\"]','[{\"q\":\"१\\/२ अपूर्णांकाचे वाचन कसे करतात?\",\"options\":[\"एक अंश दोन छेद\",\"एक अंश दोन\",\"एक अंश दोन छेद दोन\",\"एक अंश दोन छेद दोन\"],\"answer\":0,\"explain\":\"१\\/२ मध्ये अंश १ आणि छेद २ आहे.\"},{\"q\":\"१\\/४ अपूर्णांकाचे वाचन कसे करतात?\",\"options\":[\"एक अंश चार\",\"एक अंश चार छेद\",\"एक अंश चार छेद\",\"एक अंश चार छेद\"],\"answer\":2,\"explain\":\"१\\/४ मध्ये अंश १ आणि छेद ४ आहे.\"},{\"q\":\"३\\/४ अपूर्णांकाचे मूल्य काय आहे?\",\"options\":[\"०.५\",\"०.७५\",\"१\",\"१.२५\"],\"answer\":1,\"explain\":\"३\\/४ = ०.७५.\"},{\"q\":\"१\\/३ अपूर्णांकाचे वाचन कसे करतात?\",\"options\":[\"एक अंश तीन\",\"एक अंश तीन छेद\",\"एक अंश तीन छेद\",\"एक अंश तीन छेद\"],\"answer\":2,\"explain\":\"१\\/३ मध्ये अंश १ आणि छेद ३ आहे.\"},{\"q\":\"१ पूर्ण आणि १\\/२ अपूर्णांकाचे मिश्र संख्या काय आहे?\",\"options\":[\"१ १\\/२\",\"१\\/२ १\",\"१ १\\/४\",\"१\\/४ १\"],\"answer\":0,\"explain\":\"१ पूर्ण आणि १\\/२ = १ १\\/२.\"},{\"q\":\"२\\/५ अपूर्णांकाचे वाचन कसे करतात?\",\"options\":[\"दोन अंश पाच छेद\",\"दोन अंश पाच\",\"दोन अंश पाच छेद\",\"दोन अंश पाच छेद\"],\"answer\":0,\"explain\":\"२\\/५ मध्ये अंश २ आणि छेद ५ आहे.\"},{\"q\":\"१\\/२ आणि १\\/४ यापैकी कोणता अपूर्णांक मोठा आहे?\",\"options\":[\"१\\/२\",\"१\\/४\",\"दोन्ही समान\",\"कोणताही नाही\"],\"answer\":0,\"explain\":\"१\\/२ > १\\/४.\"},{\"q\":\"१\\/३ आणि २\\/३ यापैकी कोणता अपूर्णांक लहान आहे?\",\"options\":[\"१\\/३\",\"२\\/३\",\"दोन्ही समान\",\"कोणताही नाही\"],\"answer\":0,\"explain\":\"१\\/३ < २\\/३.\"},{\"q\":\"१\\/५ आणि २\\/५ यापैकी कोणता अपूर्णांक मोठा आहे?\",\"options\":[\"१\\/५\",\"२\\/५\",\"दोन्ही समान\",\"कोणताही नाही\"],\"answer\":1,\"explain\":\"२\\/५ > १\\/५.\"},{\"q\":\"१\\/४ आणि १\\/२ यापैकी कोणता अपूर्णांक लहान आहे?\",\"options\":[\"१\\/४\",\"१\\/२\",\"दोन्ही समान\",\"कोणताही नाही\"],\"answer\":0,\"explain\":\"१\\/४ < १\\/२.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16752,22,4,'Maths','mr','मापन','[\"सेंटीमीटर (सेमी) = 10 मिलिमीटर (मिमी)\",\"1 सेमी = 10 मिमी\",\"मिलिमीटरला थोडक्यात “मिमी” असे लिहितात\",\"सेंटीमीटरला थोडक्यात “सेमी” असे लिहितात\",\"1 मीटर = 100 सेंटीमीटर\",\"1 मीटर = 1000 मिलिमीटर\",\"1 किलोमीटर = 1000 मीटर\",\"1 किलोमीटर = 100000 मिलिमीटर\",\"1 किलोग्रॅम = 1000 ग्रॅम\",\"1 लीटर = 1000 मिलिलीटर\",\"मापनाचे एकक वाढविल्यास संख्या लहान होते\",\"मापनाचे एकक कमी केल्यास संख्या मोठी होते\",\"मापन करताना पट्टीच्या पहिल्या खूणेला टोकाशी जुळवतात\",\"मापन करताना वस्तूची लांबी पट्टीच्या दोन टोकांमधील संख्या असते\",\"मापन करताना पायऱ्यांनी चालून अंतर मोजता येते\",\"मापन करताना पावलं 5 पावलांची 1 टप्पा = 3 मीटर असे धरले जाऊ शकते\",\"मापन करताना लांबीचे रूपांतर करताना गुणाकार किंवा भागाकार वापरतात\",\"मापन करताना एककांचे रूपांतर करताना “>” चिन्हाने “अधिक” दर्शवतात\",\"मापन करताना एककांचे रूपांतर करताना “<” चिन्हाने “कमी” दर्शवतात\",\"मापन करताना एककांचे रूपांतर करताना “=” चिन्हाने “बराबर” दर्शवतात\"]','[{\"q\":\"1 सेमीमध्ये किती मिलिमीटर असतात?\",\"options\":[\"10\",\"5\",\"20\",\"15\"],\"answer\":0,\"explain\":\"1 सेमी = 10 मिमी.\"},{\"q\":\"1 मीटरमध्ये किती सेंटीमीटर असतात?\",\"options\":[\"100\",\"10\",\"1000\",\"50\"],\"answer\":0,\"explain\":\"1 मी = 100 सेमी.\"},{\"q\":\"1 किलोमीटरमध्ये किती मीटर असतात?\",\"options\":[\"1000\",\"100\",\"10000\",\"500\"],\"answer\":0,\"explain\":\"1 किमी = 1000 मी.\"},{\"q\":\"1 किलोग्रॅममध्ये किती ग्रॅम असतात?\",\"options\":[\"1000\",\"100\",\"10\",\"500\"],\"answer\":0,\"explain\":\"1 किग्रॅ = 1000 ग्रॅम.\"},{\"q\":\"1 लीटरमध्ये किती मिलिलीटर असतात?\",\"options\":[\"1000\",\"100\",\"10\",\"500\"],\"answer\":0,\"explain\":\"1 ली = 1000 मिली.\"},{\"q\":\"7 सेमी किती मिलिमीटर असतात?\",\"options\":[\"70\",\"7\",\"700\",\"0.7\"],\"answer\":0,\"explain\":\"7 सेमी = 7×10 = 70 मिमी.\"},{\"q\":\"5 मीटर किती सेंटीमीटर असतात?\",\"options\":[\"500\",\"50\",\"5000\",\"5\"],\"answer\":0,\"explain\":\"5 मी = 5×100 = 500 सेमी.\"},{\"q\":\"2 किलोमीटर किती मीटर असतात?\",\"options\":[\"2000\",\"200\",\"20\",\"20000\"],\"answer\":0,\"explain\":\"2 किमी = 2×1000 = 2000 मी.\"},{\"q\":\"3 किलोग्रॅम किती ग्रॅम असतात?\",\"options\":[\"3000\",\"300\",\"30\",\"30000\"],\"answer\":0,\"explain\":\"3 किग्रॅ = 3×1000 = 3000 ग्रॅम.\"},{\"q\":\"1.5 किलोग्रॅम किती ग्रॅम असतात?\",\"options\":[\"1500\",\"150\",\"15\",\"5000\"],\"answer\":0,\"explain\":\"1.5 किग्रॅ = 1500 ग्रॅम.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16753,22,4,'Maths','mr','परिमिती व क्षेत्रफळ','[\"परिमिती म्हणजे आकृतीच्या बाहेरील रेषेची एकूण लांबी.\",\"चौरसाची परिमिती = 4 × बाजूची लांबी.\",\"आयताची परिमिती = 2 × (लांबी + रुंदी).\",\"त्रिकोणाची परिमिती = बाजूंची बेरीज.\",\"परिमिती मोजण्यासाठी आकृतीच्या सर्व बाजूंची लांबी एकत्र करावी.\",\"क्षेत्रफळ म्हणजे आकृतीच्या आतल्या जागेचे मापन.\",\"चौरसाचे क्षेत्रफळ = बाजू × बाजू.\",\"आयताचे क्षेत्रफळ = लांबी × रुंदी.\",\"त्रिकोणाचे क्षेत्रफळ = (आधार × उंची)\\/2 (साधे सूत्र).\",\"क्षेत्रफळ मोजण्यासाठी 1 सेमी बाजूचे चौरस मोजून एकूण संख्या काढता येते.\",\"परिमिती आणि क्षेत्रफळ दोन्ही एकाच आकृतीसाठी वेगवेगळे असतात.\",\"आयताकृती शेताला कुंपण लावायचे असल्यास परिमिती काढून ताराची लांबी ठरवता येते.\",\"त्रिकोणाच्या बाजूंची लांबी दिली असेल तर परिमिती = a+b+c.\",\"चौरसाची परिमिती 2 सेमी बाजू असल्यास 8 सेमी.\",\"आयताची परिमिती 3 सेमी आणि 2 सेमी बाजू असल्यास 10 सेमी.\",\"परिमितीची गणना करताना सर्व बाजूंची बेरीज करणे आवश्यक.\",\"क्षेत्रफळाची गणना करताना आकृतीचे माप एकक (चौरस सेमी) वापरले जाते.\",\"परिमिती आणि क्षेत्रफळ दोन्ही मोजताना आकृतीचे सर्व बाजू किंवा चौरस मोजणे महत्त्वाचे.\",\"परिमितीची लांबी मोजण्यासाठी रेषा किंवा तार सरळ करून मोजली जाते.\",\"आकृतीच्या परिमितीची गणना करताना तिरपी बाजूही समाविष्ट कराव्या लागतात.\",\"परिमिती आणि क्षेत्रफळ हे दोन्ही गणितात मूलभूत संकल्पना आहेत.\",\"परिमितीची गणना करण्यासाठी आकृतीच्या प्रत्येक बाजूची लांबी माहित असणे आवश्यक.\",\"क्षेत्रफळ मोजण्यासाठी आकृतीला लहान चौरसांमध्ये विभागून मोजणे सोपे असते.\"]','[{\"q\":\"चौरसाची परिमिती कशी मोजायची?\",\"options\":[\"4 × बाजू\",\"2 × (लांबी + रुंदी)\",\"बाजू + उंची\",\"बाजू × बाजू\"],\"answer\":0,\"explain\":\"चौरसाच्या चारही बाजूंची लांबी समान असते, त्यामुळे 4 ने गुणिले जाते.\"},{\"q\":\"आयताची परिमिती काढण्यासाठी काय करावे?\",\"options\":[\"बाजूंची बेरीज\",\"2 × (लांबी + रुंदी)\",\"बाजू × बाजू\",\"बाजू + उंची\"],\"answer\":1,\"explain\":\"आयताला दोन लांबी आणि दोन रुंदी असतात.\"},{\"q\":\"त्रिकोणाची परिमिती कशी मोजायची?\",\"options\":[\"बाजूंची बेरीज\",\"2 × (लांबी + रुंदी)\",\"बाजू × बाजू\",\"बाजू + उंची\"],\"answer\":0,\"explain\":\"त्रिकोणाला तीन बाजू असतात, त्यांची बेरीज परिमिती.\"},{\"q\":\"3 सेमी बाजू असलेल्या चौरसाचे क्षेत्रफळ किती?\",\"options\":[\"9 चौरस सेमी\",\"6 चौरस सेमी\",\"12 चौरस सेमी\",\"3 चौरस सेमी\"],\"answer\":0,\"explain\":\"क्षेत्रफळ = बाजू × बाजू = 3×3.\"},{\"q\":\"2 सेमी बाजू असलेल्या चौरसाची परिमिती किती?\",\"options\":[\"4 सेमी\",\"6 सेमी\",\"8 सेमी\",\"10 सेमी\"],\"answer\":2,\"explain\":\"4 × 2 = 8 सेमी.\"},{\"q\":\"आयताची लांबी 5 मी आणि रुंदी 3 मी असेल तर परिमिती किती?\",\"options\":[\"16 मी\",\"14 मी\",\"10 मी\",\"8 मी\"],\"answer\":1,\"explain\":\"2 × (5+3)=16 मी.\"},{\"q\":\"त्रिकोणाच्या बाजू 4 सेमी, 5 सेमी, 6 सेमी असतील तर परिमिती किती?\",\"options\":[\"15 सेमी\",\"14 सेमी\",\"13 सेमी\",\"12 सेमी\"],\"answer\":0,\"explain\":\"4+5+6=15 सेमी.\"},{\"q\":\"आयताकृती शेताच्या बाजू 15 मी, 12 मी, 15 मी, 12 मी असतील तर परिमिती किती?\",\"options\":[\"54 मी\",\"48 मी\",\"60 मी\",\"42 मी\"],\"answer\":0,\"explain\":\"2×(15+12)=54 मी.\"},{\"q\":\"1 सेमी बाजू असलेल्या चौरसाचे क्षेत्रफळ काय?\",\"options\":[\"1 चौरस सेमी\",\"2 चौरस सेमी\",\"0.5 चौरस सेमी\",\"10 चौरस सेमी\"],\"answer\":0,\"explain\":\"1×1=1.\"},{\"q\":\"आयताचे क्षेत्रफळ 3 मी × 2 मी असेल तर किती चौरस मीटर?\",\"options\":[\"6\",\"5\",\"4\",\"3\"],\"answer\":0,\"explain\":\"3×2=6 चौरस मीटर.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16754,22,4,'Maths','mr','गुणाकार : भाग २','[\"गुणाकार म्हणजे दोन किंवा अधिक संख्यांचा एकत्रित गुणाकार करणे.\",\"उभ्या मांडणीत (स्टॅक) गुणाकार करताना प्रत्येक अंकाला वेगळे गुणून बेरीज करतो.\",\"चौकट पद्धतीत (कॅरॅक्टर) गुणाकार करताना मोठे गुणाकार करून बेरीज करतो.\",\"गुणाकारात एकक, दहाचा, शतक, हजार अशा स्थानांची ओळख आवश्यक असते.\",\"एकक स्थानावर गुणाकार झाल्यावर जर 10 पेक्षा जास्त असेल तर पुढच्या स्थानावर 1 (कॅरी) जातो.\",\"दहाच्या स्थानावर गुणाकार झाल्यास 100 पेक्षा जास्त झाल्यास शतकावर कॅरी होते.\",\"गुणाकार करताना मोठ्या संख्येची लांबी लक्षात घेऊन पद्धत निवडता येते.\",\"उभ्या मांडणीत दोन अंकांची संख्या × दोन अंकांची संख्या = चार अंकांची संख्या होऊ शकते.\",\"चौकट पद्धतीत 3×4 गुणाकारासाठी 3×4=12, 3×0=0, 1×4=4, 1×0=0 अशी लहान गुणाकारांची बेरीज करतो.\",\"गुणाकाराचे परिणाम शून्याने संपल्यास एकक स्थानावर 0 लिहितो.\",\"गुणाकार करताना कॅरी (हातचे) लक्षात ठेवणे महत्त्वाचे आहे.\",\"गुणाकाराचे उत्तर लांब असल्यास स्थानानुसार अंक लिहितो.\",\"गुणाकाराचे नियम सर्व अंकांसाठी सारखेच असतात, फक्त स्थान बदलते.\",\"गुणाकाराचे सराव करताना विविध पद्धती वापरून पाहणे उपयुक्त असते.\",\"गुणाकाराचे प्रश्न सोडवताना प्रथम लहान गुणाकार करून नंतर बेरीज करणे सोपे असते.\",\"गुणाकाराचे उत्तर तपासण्यासाठी गुणाकार आणि भागाकार दोन्ही वापरू शकतो.\"]','[{\"q\":\"३१५ × ७ किती होईल?\",\"options\":[\"२२०५\",\"२२००\",\"२१००\",\"२१५५\"],\"answer\":0,\"explain\":\"३१५ ला ७ ने गुणल्यास २२०५ येते.\"},{\"q\":\"३८ × ४ = ?\",\"options\":[\"१५२\",\"१५०\",\"१४८\",\"१६०\"],\"answer\":0,\"explain\":\"३८ ला ४ ने गुणल्यास १५२ येते.\"},{\"q\":\"२३४ × ६५ किती?\",\"options\":[\"१५००\",\"१५०००\",\"१५००००\",\"१५०००००\"],\"answer\":0,\"explain\":\"२३४ ला ६५ ने गुणल्यास १५००० येते.\"},{\"q\":\"५९८ × ५१ = ?\",\"options\":[\"३००००\",\"३०००००\",\"३००००००\",\"३०००००००\"],\"answer\":0,\"explain\":\"५९८ ला ५१ ने गुणल्यास ३०००० येते.\"},{\"q\":\"१२५ × ५२ = ?\",\"options\":[\"६५००\",\"६५०००\",\"६५००००\",\"६५०००००\"],\"answer\":0,\"explain\":\"१२५ ला ५२ ने गुणल्यास ६५०० येते.\"},{\"q\":\"३७५ × ४० = ?\",\"options\":[\"१५०००\",\"१५००००\",\"१५०००००\",\"१५००००००\"],\"answer\":0,\"explain\":\"३७५ ला ४० ने गुणल्यास १५००० येते.\"},{\"q\":\"६५० × २८ = ?\",\"options\":[\"१८२००\",\"१८२०००\",\"१८२००००\",\"१८२०००००\"],\"answer\":0,\"explain\":\"६५० ला २८ ने गुणल्यास १८२०० येते.\"},{\"q\":\"४४७ × ५९ = ?\",\"options\":[\"२६४००\",\"२६४०००\",\"२६४००००\",\"२६४०००००\"],\"answer\":0,\"explain\":\"४४७ ला ५९ ने गुणल्यास २६४०० येते.\"},{\"q\":\"३८ × ४ = १५२. या गुणाकारात 0 का आले?\",\"options\":[\"कारण ८ × ४ = ३२, २ दहाच्या स्थानावर जाते\",\"कारण ३ × ४ = १२, २ दहाच्या स्थानावर जाते\",\"कारण ३ × ४ = १२, १ शतकावर जाते\",\"कारण ८ × ४ = ३२, १ शतकावर जाते\"],\"answer\":0,\"explain\":\"८ × ४ = ३२, २ दहाच्या स्थानावर जाते.\"},{\"q\":\"१ हेक्‍टर बागेत ३६५ झाडे लावता येतात. ८ हेक्‍टरमध्ये किती झाडे?\",\"options\":[\"२९२०\",\"२९२००\",\"२९२०००\",\"२९२००००\"],\"answer\":0,\"explain\":\"३६५ × ८ = २९२०.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16755,22,4,'Maths','mr','भागाकार : भाग २','[\"भागाकार म्हणजे एखाद्या वस्तूला समान भागांत विभागणे\",\"भागाकाराचे चिन्ह ÷ किंवा \\/\",\"भागाकारात ‘भाग’ म्हणजे ‘विभाजक’ आणि ‘भागाकार’ म्हणजे ‘भागाकार’\",\"भागाकाराचे उत्तर ‘भागाकार’ म्हणतात\",\"भागाकार करताना शून्याने भागणे शक्य नाही\",\"भागाकार करताना ‘शून्य भाग’ लिहिताना योग्य स्थानावर 0 लिहावे\",\"भागाकारात ‘शेष’ म्हणजे उरलेली रक्कम\",\"भागाकाराचे नियम: प्रथम शतकस्थानी, नंतर दशकस्थानी, शेवटी एककस्थानी भाग करणे\",\"भागाकाराचे ‘भाग’ आणि ‘भागाकार’ दोन्ही समान असतील तर ‘समान वाटप’ म्हणतात\",\"भागाकाराचे उदाहरण: १००÷४=२५\",\"भागाकाराचे ‘भाग’ आणि ‘भागाकार’ दोन्ही पूर्णांक असतील तर ‘पूर्ण भागाकार’ म्हणतात\",\"भागाकारात ‘भाग’ आणि ‘भागाकार’ दोन्ही पूर्णांक नसतील तर ‘शेष’ राहतो\",\"भागाकार करताना ‘शून्य’ भागाकारात लिहिताना ‘शून्य’ स्थानावर 0 लिहावे\",\"भागाकारात ‘शेष’ 0 असेल तर ‘भागाकार’ पूर्ण आहे\",\"भागाकाराचे ‘भाग’ आणि ‘भागाकार’ दोन्ही समान असतील तर ‘भागाकार’ 1 असतो\",\"भागाकाराचे ‘भाग’ आणि ‘भागाकार’ दोन्ही समान असतील तर ‘भागाकार’ 1 असतो\",\"भागाकाराचे ‘भाग’ आणि ‘भागाकार’ दोन्ही समान असतील तर ‘भागाकार’ 1 असतो\",\"भागाकाराचे ‘भाग’ आणि ‘भागाकार’ दोन्ही समान असतील तर ‘भागाकार’ 1 असतो\",\"भागाकाराचे ‘भाग’ आणि ‘भागाकार’ दोन्ही समान असतील तर ‘भागाकार’ 1 असतो\",\"भागाकाराचे ‘भाग’ आणि ‘भागाकार’ दोन्ही समान असतील तर ‘भागाकार’ 1 असतो\",\"भागाकाराचे ‘भाग’ आणि ‘भागाकार’ दोन्ही समान असतील तर ‘भागाकार’ 1 असतो\",\"भागाकाराचे ‘भाग’ आणि ‘भागाकार’ दोन्ही समान असतील तर ‘भागाकार’ 1 असतो\",\"भागाकाराचे ‘भाग’ आणि ‘भागाकार’ दोन्ही समान असतील तर ‘भागाकार’ 1 असतो\",\"भागाकाराचे ‘भाग’ आणि ‘भागाकार’ दोन्ही समान असतील तर ‘भागाकार’ 1 असतो\"]','[{\"q\":\"१००÷४ किती होईल?\",\"options\":[\"25\",\"20\",\"30\",\"15\"],\"answer\":0,\"explain\":\"१०० ला ४ ने भागल्यास २५ येते.\"},{\"q\":\"८०÷८ किती होईल?\",\"options\":[\"10\",\"8\",\"9\",\"7\"],\"answer\":0,\"explain\":\"८० ला ८ ने भागल्यास १० येते.\"},{\"q\":\"६०÷७ मध्ये शेष किती?\",\"options\":[\"३\",\"४\",\"५\",\"६\"],\"answer\":0,\"explain\":\"६० ला ७ ने भागल्यास ८ शेष ४ येतो.\"},{\"q\":\"३१÷४ मध्ये भागाकार किती?\",\"options\":[\"७\",\"८\",\"९\",\"६\"],\"answer\":1,\"explain\":\"३१ ला ४ ने भागल्यास ७ शेष ३ येतो.\"},{\"q\":\"४९÷७ किती?\",\"options\":[\"७\",\"६\",\"५\",\"८\"],\"answer\":0,\"explain\":\"४९ ला ७ ने भागल्यास ७ येते.\"},{\"q\":\"८७÷९ किती?\",\"options\":[\"९\",\"८\",\"७\",\"६\"],\"answer\":1,\"explain\":\"८७ ला ९ ने भागल्यास ९ शेष ६ येतो.\"},{\"q\":\"३६९÷३ किती?\",\"options\":[\"१०३\",\"१०४\",\"१०२\",\"१०५\"],\"answer\":0,\"explain\":\"३६९ ला ३ ने भागल्यास १०३ येते.\"},{\"q\":\"४६५÷५ किती?\",\"options\":[\"९३\",\"९४\",\"९२\",\"९५\"],\"answer\":0,\"explain\":\"४६५ ला ५ ने भागल्यास ९३ येते.\"},{\"q\":\"८००÷२ किती?\",\"options\":[\"४००\",\"३९९\",\"४०१\",\"४०२\"],\"answer\":0,\"explain\":\"८०० ला २ ने भागल्यास ४०० येते.\"},{\"q\":\"१२६÷९ किती?\",\"options\":[\"१४\",\"१३\",\"१५\",\"१६\"],\"answer\":1,\"explain\":\"१२६ ला ९ ने भागल्यास १४ शेष ० येतो.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16756,22,4,'Maths','mr','चित्रालेख','[\"चित्रालेख म्हणजे एखाद्या गोष्टीची माहिती चित्रांच्या मदतीने दाखवणे.\",\"चित्र म्हणजे एकच गोष्ट दर्शवणारे चिन्ह.\",\"चित्रांची संख्या = त्या गोष्टीची संख्या ÷ प्रमाण (उदा. 10 झाडांसाठी 1 चित्र).\",\"प्रमाण म्हणजे चित्रांची संख्या आणि वास्तविक वस्तूंची संख्या यातील गुणोत्तर.\",\"चित्रांचा वापर तक्ते बनवण्यासाठी होतो, ज्यामुळे माहिती सोप्या पद्धतीने समजते.\",\"चित्रे उभ्या किंवा आडव्या ओळींमध्ये काढली जाऊ शकतात.\",\"चित्रांचा वापर करून आपण एकूण संख्या मोजू शकतो.\",\"चित्रांचा वापर करून आपण तुलना करू शकतो (उदा. किती कुटुंबांनी मदत दिली).\",\"चित्रांच्या मदतीने आपण विविध प्रकारच्या वस्तूंची संख्या ओळखू शकतो (खुर्च्या, इंधन, पीक).\",\"चित्रांच्या मदतीने आपण सर्वाधिक आणि सर्वात कमी असलेल्या गोष्टी ओळखू शकतो.\",\"चित्रांचे प्रमाण 1:10, 1:20 इत्यादी असू शकते.\",\"चित्रांचा वापर करताना आकडे स्पष्टपणे लिहावे.\",\"चित्रे काढताना समान आकार आणि अंतर राखावे.\",\"चित्रांच्या तक्त्यातील माहिती वाचताना प्रथम प्रमाण वाचावे.\",\"चित्रांच्या मदतीने आपण एकूण संख्या शोधू शकतो (उदा. 15 चित्रे = 150 वस्तू).\"]','[{\"q\":\"चित्रालेख म्हणजे काय?\",\"options\":[\"चित्रांच्या मदतीने माहिती दाखवणे\",\"फक्त शब्दांनी माहिती देणे\",\"संगणकावरून माहिती दाखवणे\",\"कागदावर लिहिणे\"],\"answer\":0,\"explain\":\"चित्रालेख म्हणजे चित्रांच्या मदतीने माहिती दाखवणे.\"},{\"q\":\"चित्रांच्या तक्त्यातील प्रमाण 1:10 म्हणजे काय?\",\"options\":[\"10 चित्रे = 1 वस्तू\",\"1 चित्र = 10 वस्तू\",\"10 चित्रे = 10 वस्तू\",\"1 चित्र = 1 वस्तू\"],\"answer\":1,\"explain\":\"प्रमाण 1:10 म्हणजे 1 चित्र = 10 वस्तू.\"},{\"q\":\"खुर्च्यांच्या तक्त्यात 15 चित्रे काढली आहेत. एकूण किती खुर्च्या आहेत?\",\"options\":[\"150\",\"15\",\"10\",\"1500\"],\"answer\":0,\"explain\":\"15 चित्रे × 10 खुर्च्या = 150 खुर्च्या.\"},{\"q\":\"गुलाबाच्या झाडांची संख्या 40 आहे आणि प्रमाण 1:10 आहे. किती चित्रे काढली जातील?\",\"options\":[\"4\",\"40\",\"10\",\"400\"],\"answer\":0,\"explain\":\"40 ÷ 10 = 4 चित्रे.\"},{\"q\":\"किती कुटुंबांनी मदत म्हणून औषधे दिली?\",\"options\":[\"20\",\"4\",\"10\",\"0\"],\"answer\":0,\"explain\":\"प्रमाण 1:20 असल्याने 4 कुटुंबे = 80 औषधे.\"},{\"q\":\"इंधन वापरणाऱ्या घरांची सर्वाधिक संख्या कोणत्या इंधनाची आहे?\",\"options\":[\"गॅस\",\"केरोसीन\",\"लाकूड\",\"गॅस आणि केरोसीन दोन्ही\"],\"answer\":0,\"explain\":\"तक्त्यानुसार गॅस वापरणारी घरे सर्वाधिक आहेत.\"},{\"q\":\"ज्वारी पिकवणाऱ्या शेतकऱ्यांची संख्या किती?\",\"options\":[\"9\",\"22\",\"30\",\"0\"],\"answer\":0,\"explain\":\"तक्त्यानुसार ज्वारी पिकवणारे 9 शेतकरी.\"},{\"q\":\"गणवेश नसलेल्या दिवशी पिवळ्या रंगाचे कपडे घातलेल्या मुलांची संख्या किती?\",\"options\":[\"5\",\"6\",\"10\",\"0\"],\"answer\":1,\"explain\":\"प्रमाण 6 म्हणजे 5 मुले, त्यामुळे पिवळ्या रंगाचे 5 मुले.\"},{\"q\":\"सर्वाधिक मदत करणारी कुटुंबे कोणत्या स्वरूपात आहेत?\",\"options\":[\"औषधे\",\"खाद्यपदार्थ\",\"शेती\",\"कपडे\"],\"answer\":1,\"explain\":\"तक्त्यानुसार खाद्यपदार्थ सर्वाधिक मदत करणारी कुटुंबे.\"},{\"q\":\"गॅस वापरणारी घरे किती आहेत?\",\"options\":[\"20\",\"10\",\"5\",\"0\"],\"answer\":0,\"explain\":\"प्रमाण 1:10 असल्याने 2 चित्रे = 20 घरे.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16757,22,4,'Maths','mr','आकृतिबंध','[\"आकृतिबंध म्हणजे विविध भौमितिक आकार एकत्र करून बनवलेली रचना.\",\"भौमितिक आकारांमध्ये वर्तुळ, चौकोन, त्रिकोण, आयत, त्रिकोणीय पट्टी व इतर साधे आकार असतात.\",\"आकृतिबंध बनवताना आकारांची मांडणी एकमेकांवर ठेवल्यास नवीन आकृतिबंध तयार होतो.\",\"आकृतिबंधात पुनरावृत्ती होणारा नमुना म्हणजे आकृतिबंधाचा मुख्य भाग.\",\"आकृतिबंध ओळखण्यासाठी आकारांची संख्या, दिशा व अंतर लक्षात घ्या.\",\"आकृतिबंधात समान आकारांची जोडणी केल्यास सममिती निर्माण होते.\",\"आकृतिबंध तयार करताना आकारांची उंची व रुंदी समान ठेवणे सोपे असते.\",\"आकृतिबंधात विविध आकारांची मिश्रण केल्याने रंगीत नक्षी तयार होते.\",\"आकृतिबंधाच्या पॅटर्नमध्ये एकक स्थान व दशक स्थानावर अंकांची पुनरावृत्ती दिसते.\",\"आकृतिबंध ओळखण्यासाठी पॅटर्नमध्ये अंकांची क्रमवार वाढ किंवा घट पहा.\",\"आकृतिबंधात १, २, ३, ४, ५ अशा क्रमाने अंकांची वाढ होऊ शकते.\",\"आकृतिबंधात ०, ५, ०, ५ अशा पुनरावृत्तीचे नमुने दिसू शकतात.\",\"आकृतिबंधात आकृतिबंधाचे नाव व आकार ओळखणे महत्त्वाचे आहे.\",\"आकृतिबंध तयार करताना हाताने रेखाटणे किंवा कागदावर काढणे उपयुक्त असते.\",\"आकृतिबंधाच्या अभ्यासाने गणित व भूगोल या दोन्ही विषयांमध्ये मदत होते.\",\"आकृतिबंधात आकारांची जोडणी करताना सममिती व संतुलन राखणे आवश्यक आहे.\",\"आकृतिबंधात विविध रंगांचा वापर केल्यास दृश्य आकर्षक होते.\",\"आकृतिबंधाच्या अभ्यासात पॅटर्न ओळखण्याची क्षमता वाढते.\",\"आकृतिबंधाचे उदाहरणे: पिरॅमिड, ग्रीड, पॅटर्न व नक्षी.\",\"आकृतिबंध तयार करताना आकारांची लांबी व रुंदी समान ठेवणे सोपे असते.\",\"आकृतिबंधात विविध आकृतिबंधांचे संयोजन केल्यास नवीन पॅटर्न तयार होतो.\",\"आकृतिबंधाच्या अभ्यासात गणितीय गुणाकार व भागाकाराचे पॅटर्न ओळखणे महत्त्वाचे आहे.\"]','[{\"q\":\"आकृतिबंधात कोणते भौमितिक आकार वापरले जातात?\",\"options\":[\"वर्तुळ, चौकोन, त्रिकोण\",\"वृक्ष, पान, फुल\",\"पुस्तक, पेन, कागद\",\"संगणक, फोन, टॅबलेट\"],\"answer\":0,\"explain\":\"आकृतिबंधात साधे भौमितिक आकार वापरले जातात.\"},{\"q\":\"आकृतिबंधात पुनरावृत्ती होणारा नमुना काय म्हणतात?\",\"options\":[\"आकृतिबंध\",\"पॅटर्न\",\"रंग\",\"आकार\"],\"answer\":1,\"explain\":\"पुनरावृत्ती होणारा नमुना पॅटर्न म्हणतात.\"},{\"q\":\"१, २, ३, ४, ५ या क्रमाने आकृतिबंधात काय होते?\",\"options\":[\"वाढ\",\"घट\",\"काहीच नाही\",\"समान\"],\"answer\":0,\"explain\":\"अंकांची क्रमवार वाढ होते.\"},{\"q\":\"आकृतिबंधात सममिती कशी राखली जाते?\",\"options\":[\"आकारांची लांबी व रुंदी समान ठेवून\",\"विविध रंग वापरून\",\"आकृतिबंध लहान करून\",\"आकृतिबंध मोठा करून\"],\"answer\":0,\"explain\":\"सममिती राखण्यासाठी आकारांची लांबी व रुंदी समान ठेवली जाते.\"},{\"q\":\"आकृतिबंधात कोणत्या प्रकारचे पॅटर्न दिसतात?\",\"options\":[\"एकक स्थानाचे पॅटर्न\",\"दशक स्थानाचे पॅटर्न\",\"दोन्ही\",\"काहीही नाही\"],\"answer\":2,\"explain\":\"दोन्ही पॅटर्न दिसतात.\"},{\"q\":\"आकृतिबंध तयार करताना काय करणे सोपे असते?\",\"options\":[\"आकारांची उंची व रुंदी समान ठेवणे\",\"आकारांची संख्या वाढवणे\",\"आकारांची दिशा बदलणे\",\"आकारांची संख्या कमी करणे\"],\"answer\":0,\"explain\":\"उंची व रुंदी समान ठेवणे सोपे असते.\"},{\"q\":\"आकृतिबंधात विविध रंगांचा वापर केल्यास काय होते?\",\"options\":[\"दृश्य आकर्षक होते\",\"आकृतिबंध लहान होतो\",\"आकृतिबंध मोठा होतो\",\"आकृतिबंध बदलत नाही\"],\"answer\":0,\"explain\":\"रंग वापरल्याने दृश्य आकर्षक होते.\"},{\"q\":\"आकृतिबंधात कोणत्या गणितीय क्रिया ओळखता येतात?\",\"options\":[\"गुणाकार व भागाकार\",\"प्लस व मायनस\",\"फक्त गुणाकार\",\"फक्त भागाकार\"],\"answer\":0,\"explain\":\"गुणाकार व भागाकाराचे पॅटर्न ओळखता येतात.\"},{\"q\":\"आकृतिबंधात आकृतिबंधाचे नाव कसे ओळखायचे?\",\"options\":[\"आकार व आकृतिबंध पाहून\",\"रंग पाहून\",\"आकारांची संख्या पाहून\",\"काहीही नाही\"],\"answer\":0,\"explain\":\"आकार व आकृतिबंध पाहून नाव ओळखता येते.\"},{\"q\":\"आकृतिबंध तयार करताना कोणती पद्धत वापरली जाते?\",\"options\":[\"मुक्तहस्त रेखाटन\",\"कम्प्यूटर सॉफ्टवेअर\",\"दोन्ही\",\"काहीही नाही\"],\"answer\":0,\"explain\":\"मुक्तहस्त रेखाटन वापरले जाते.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16758,23,5,'EVS Part 1','en','Our Earth and Our Solar System','[\"The Sun is a star and the only star that we can see with the naked eye.\",\"The Earth is a planet that revolves around the Sun and receives light and heat from it.\",\"The Moon is the Earth’s only natural satellite and it revolves around the Earth.\",\"Planets are heavenly bodies that do not twinkle because they have their own light or reflect the Sun’s light.\",\"Stars are bright points in the sky that twinkle because they are far away and have their own light.\",\"The Solar System contains the Sun, eight planets, dwarf planets, asteroids, and comets.\",\"The eight planets from the Sun are Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, and Neptune.\",\"The order of the planets from the Sun is: Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, Neptune.\",\"Dwarf planets such as Pluto, Ceres, Eris, Haumea, and Makemake are also part of the Solar System.\",\"Satellites are natural or man‑made objects that revolve around a planet; the Moon is the Earth’s satellite.\",\"Asteroids are small rocky bodies that mainly lie between Mars and Jupiter.\",\"The force that keeps planets, satellites, and other bodies in orbit is gravity.\",\"Gravity is the attraction between any two masses; the Sun’s gravity keeps the planets in orbit.\",\"The Moon’s phases change because only part of its illuminated side is visible from Earth.\",\"Space is the empty region beyond the planets and stars where rockets and satellites travel.\",\"Rockets use powerful engines to overcome Earth’s gravity and reach space.\"]','[{\"q\":\"Which planet is closest to the Sun?\",\"options\":[\"Mercury\",\"Venus\",\"Earth\",\"Mars\"],\"answer\":0,\"explain\":\"Mercury is the nearest planet to the Sun.\"},{\"q\":\"What is the name of the Earth\'s only natural satellite?\",\"options\":[\"Mars\",\"Jupiter\",\"Saturn\",\"Moon\"],\"answer\":3,\"explain\":\"The Moon is Earth\'s only natural satellite.\"},{\"q\":\"Which of the following is a dwarf planet in our solar system?\",\"options\":[\"Ceres\",\"Pluto\",\"Vesta\",\"Eros\"],\"answer\":1,\"explain\":\"Pluto is classified as a dwarf planet.\"},{\"q\":\"Which planet is known as the \'Red Planet\'?\",\"options\":[\"Venus\",\"Mars\",\"Jupiter\",\"Saturn\"],\"answer\":1,\"explain\":\"Mars is called the Red Planet because of its reddish appearance.\"},{\"q\":\"What is the main source of light for the planets?\",\"options\":[\"The Sun\",\"The Moon\",\"Stars\",\"Artificial satellites\"],\"answer\":0,\"explain\":\"Planets receive light from the Sun.\"},{\"q\":\"Which planet has the most moons?\",\"options\":[\"Earth\",\"Mars\",\"Jupiter\",\"Venus\"],\"answer\":2,\"explain\":\"Jupiter has the most moons of all planets.\"},{\"q\":\"What is the term for the path a planet follows around the Sun?\",\"options\":[\"Orbit\",\"Revolution\",\"Rotation\",\"Trajectory\"],\"answer\":0,\"explain\":\"The path around the Sun is called an orbit.\"},{\"q\":\"Which of these objects are found between Mars and Jupiter?\",\"options\":[\"Comets\",\"Asteroids\",\"Satellites\",\"Dwarf planets\"],\"answer\":1,\"explain\":\"A belt of asteroids lies between Mars and Jupiter.\"},{\"q\":\"What is the main purpose of a rocket in space travel?\",\"options\":[\"To carry people only\",\"To carry cargo only\",\"To carry both people and cargo\",\"To carry only satellites\"],\"answer\":2,\"explain\":\"Rockets are used to carry both people and cargo into space.\"},{\"q\":\"Which force keeps the Moon in orbit around the Earth?\",\"options\":[\"Magnetic force\",\"Gravitational force\",\"Electric force\",\"Nuclear force\"],\"answer\":1,\"explain\":\"Gravity keeps the Moon in orbit around Earth.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16759,23,5,'EVS Part 1','en','Motions of the Earth','[\"Earth rotates around its own axis once every 24 hours – this is called rotation.\",\"The line about which Earth turns is the axis of rotation, passing through the North and South Poles.\",\"The equator is the imaginary circle that divides Earth into northern and southern hemispheres.\",\"Daytime occurs when a part of Earth faces the Sun; nighttime when it faces away.\",\"A full rotation of Earth gives one day, which is divided into 24 hours.\",\"Earth also revolves around the Sun once every 365 days and 6 hours – this is one year.\",\"Because Earth’s axis is tilted, the length of day and night changes with seasons.\",\"The Sun rises in the east and sets in the west because Earth rotates from west to east.\",\"The Moon revolves around Earth once every 28–30 days, producing its phases.\",\"The Moon’s phases are called the waxing (Shukla Paksha) and waning (Krishna Paksha) periods.\",\"A lunar month is the time from one new moon to the next, about 29–30 days.\",\"The month is divided into 15 days of waxing and 15 days of waning, called tithis.\",\"Leap year adds an extra day (29 Feb) every four years to keep the calendar in sync with Earth’s orbit.\",\"The equator is the widest part of Earth, equidistant from the poles.\",\"The North Pole is the point where the axis points north; the South Pole points south.\",\"The Earth’s axis is inclined at about 23.5°, causing seasons.\",\"Sunrise and sunset occur when the Sun crosses the horizon at a particular location.\",\"The Sun rises in the east because Earth’s rotation is anti‑clockwise when viewed from the North Pole.\",\"The Moon is visible only when illuminated by the Sun’s light.\",\"During a full moon, the entire near side of the Moon faces Earth.\",\"During a new moon, the near side is dark and not visible from Earth.\",\"The length of day is longer than night in the Northern Hemisphere between 22 March and 23 September.\",\"In the Southern Hemisphere, the opposite is true during the same period.\",\"The Earth’s rotation and revolution together create day, night, and seasons.\"]','[{\"q\":\"What is the term for Earth turning around its own axis?\",\"options\":[\"Revolution\",\"Rotation\",\"Precession\",\"Precession\"],\"answer\":1,\"explain\":\"Rotation is the motion of Earth around its axis.\"},{\"q\":\"Which line divides Earth into northern and southern hemispheres?\",\"options\":[\"Meridian\",\"Equator\",\"Prime Meridian\",\"Great Circle\"],\"answer\":1,\"explain\":\"The equator is the imaginary circle dividing the hemispheres.\"},{\"q\":\"How many hours are in one day?\",\"options\":[\"12\",\"24\",\"36\",\"48\"],\"answer\":1,\"explain\":\"A day is divided into 24 hours.\"},{\"q\":\"What is the period of Earth’s revolution around the Sun?\",\"options\":[\"24 hours\",\"365 days\",\"30 days\",\"12 months\"],\"answer\":1,\"explain\":\"One year is about 365 days and 6 hours.\"},{\"q\":\"What is the name of the Moon’s phases when the illuminated part increases?\",\"options\":[\"Waning\",\"Waxing\",\"Full\",\"New\"],\"answer\":1,\"explain\":\"Waxing phases occur when the illuminated part grows.\"},{\"q\":\"Which city is in the Northern Hemisphere?\",\"options\":[\"Mumbai\",\"Nagpur\",\"Bhopal\",\"Kolkata\"],\"answer\":3,\"explain\":\"Kolkata is in the Northern Hemisphere.\"},{\"q\":\"What is a leap year?\",\"options\":[\"A year with 365 days\",\"A year with 366 days\",\"A year with 364 days\",\"A year with 367 days\"],\"answer\":1,\"explain\":\"Leap year has 366 days, adding 29 Feb.\"},{\"q\":\"Which part of Earth faces the Sun during daytime?\",\"options\":[\"The side facing away\",\"The side facing the Sun\",\"The side facing the Moon\",\"The side facing the North Pole\"],\"answer\":1,\"explain\":\"Daytime occurs when Earth faces the Sun.\"},{\"q\":\"What is the term for Earth’s motion around the Sun?\",\"options\":[\"Rotation\",\"Revolution\",\"Precession\",\"Precession\"],\"answer\":1,\"explain\":\"Revolution is the motion around the Sun.\"},{\"q\":\"How many tithis are there in a lunar month?\",\"options\":[\"10\",\"15\",\"20\",\"25\"],\"answer\":1,\"explain\":\"A lunar month has 15 waxing and 15 waning tithis.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16760,23,5,'EVS Part 1','en','The Earth and its Living World','[\"The Earth has four main spheres: lithosphere (land), hydrosphere (water), atmosphere (air) and biosphere (living things).\",\"The lithosphere is the hard outer shell made of rock and soil. It is where we build houses and where tree roots grow.\",\"The hydrosphere includes all water on Earth – oceans, rivers, lakes, groundwater and ice.\",\"The atmosphere is the air that surrounds Earth. It is made mainly of nitrogen, oxygen, water vapour and carbon dioxide.\",\"The atmosphere has five layers: troposphere, stratosphere, mesosphere, ionosphere and exosphere. The troposphere is the lowest layer where weather happens.\",\"The troposphere extends up to about 13 km. Above it the air gets cooler. The stratosphere starts at about 13 km and contains the ozone layer.\",\"The ozone layer absorbs harmful ultraviolet rays from the sun. This protects living things.\",\"The water cycle is a continuous loop: evaporation, condensation, clouds, precipitation (rain, snow) and runoff. It keeps water moving on Earth.\",\"Evaporation happens when the sun heats water and it turns into vapour. It rises into the troposphere.\",\"Condensation is when vapour cools and turns back into liquid droplets, forming clouds. When droplets become heavy they fall as rain or snow.\"]','[{\"q\":\"Which sphere of the Earth is the outermost layer that surrounds the planet?\",\"options\":[\"Lithosphere\",\"Hydrosphere\",\"Atmosphere\",\"Biosphere\"],\"answer\":2,\"explain\":\"The atmosphere is the outermost gaseous envelope around Earth.\"},{\"q\":\"What is the layer of the atmosphere where most weather occurs?\",\"options\":[\"Stratosphere\",\"Mesosphere\",\"Troposphere\",\"Exosphere\"],\"answer\":2,\"explain\":\"Weather phenomena like clouds and rain happen in the troposphere.\"},{\"q\":\"Which gas in the stratosphere protects life from harmful rays?\",\"options\":[\"Oxygen\",\"Nitrogen\",\"Ozone\",\"Carbon dioxide\"],\"answer\":2,\"explain\":\"Ozone absorbs ultraviolet rays from the Sun.\"},{\"q\":\"What is the main source of water for rivers?\",\"options\":[\"Groundwater\",\"Rainfall\",\"Icebergs\",\"Deserts\"],\"answer\":1,\"explain\":\"Rainfall and melting ice feed rivers.\"},{\"q\":\"Which of the following is NOT a landform?\",\"options\":[\"Mountain\",\"Plain\",\"River\",\"Plateau\"],\"answer\":2,\"explain\":\"River is a water body, not a landform.\"},{\"q\":\"What is the term for water that has fallen from clouds and lands on the ground?\",\"options\":[\"Condensation\",\"Precipitation\",\"Evaporation\",\"Transpiration\"],\"answer\":1,\"explain\":\"Precipitation includes rain, snow, etc.\"},{\"q\":\"Which sphere contains the Earth\'s crust?\",\"options\":[\"Atmosphere\",\"Hydrosphere\",\"Lithosphere\",\"Biosphere\"],\"answer\":2,\"explain\":\"The lithosphere is the Earth\'s crust and upper mantle.\"},{\"q\":\"What is the main component of the Earth\'s atmosphere?\",\"options\":[\"Oxygen\",\"Nitrogen\",\"Carbon dioxide\",\"Water vapour\"],\"answer\":1,\"explain\":\"Nitrogen makes up about 78% of the atmosphere.\"},{\"q\":\"Which process turns water vapor into liquid droplets in clouds?\",\"options\":[\"Evaporation\",\"Condensation\",\"Precipitation\",\"Transpiration\"],\"answer\":1,\"explain\":\"Condensation forms cloud droplets.\"},{\"q\":\"Which of these is a type of freshwater body?\",\"options\":[\"Ocean\",\"Sea\",\"Lake\",\"Seaweed\"],\"answer\":2,\"explain\":\"A lake is a freshwater body; oceans and seas are saltwater.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16761,23,5,'EVS Part 1','en','Environmental Balance','[\"- Biodiversity is the variety of living things in a particular area.\",\"- Living things depend on each other and on non‑living factors like sunlight, air, water, and soil.\",\"- A food chain shows who eats whom; each link is a species or group.\",\"- A food web is a network of many food chains connected together.\",\"- Plants are the base of most food chains because they make food using sunlight, water, and CO₂.\",\"- Decomposition by micro‑organisms turns dead matter into nutrients for soil.\",\"- The water cycle keeps water moving through evaporation, condensation and precipitation.\",\"- The carbon cycle involves plants taking in CO₂ and releasing O₂, while animals breathe O₂ and exhale CO₂.\",\"- Balance in the environment means that food, water, and nutrients are available for all living things.\",\"- If one link in a food chain disappears, the whole chain can be affected.\",\"- Scientists observe living things in different conditions (day\\/night, seasons) to study biodiversity.\",\"- Observations may include noting shape, colour, sound, and habitat of organisms.\",\"- A food chain can be broken if one link is removed; it then becomes a food web if many chains interconnect.\",\"- Maintaining biodiversity helps keep ecosystems stable and productive.\",\"- Human activities like using insecticides can harm beneficial insects and disrupt balance.\",\"- Plants need nutrients from soil, which are replenished by decomposition and fertilisation.\",\"- Oxygen produced by plants is essential for animal respiration.\",\"- Micro‑organisms in soil help recycle nutrients and support plant growth.\",\"- The environment is a system where living and non‑living factors interact and give and take.\",\"- Conservation of habitats protects many species and keeps ecosystems functioning.\",\"- Simple actions like planting trees, reducing waste, and protecting water bodies help maintain balance.\"]','[{\"q\":\"What is the base of most food chains?\",\"options\":[\"Animals\",\"Plants\",\"Micro‑organisms\",\"Water\"],\"answer\":1,\"explain\":\"Plants produce food through photosynthesis, providing energy for other organisms.\"},{\"q\":\"Which cycle involves plants taking in CO₂ and releasing O₂?\",\"options\":[\"Water cycle\",\"Nitrogen cycle\",\"Carbon cycle\",\"Oxygen cycle\"],\"answer\":2,\"explain\":\"The carbon cycle describes this exchange.\"},{\"q\":\"If a predator disappears from a food chain, what may happen?\",\"options\":[\"The chain becomes shorter\",\"The chain becomes longer\",\"The chain is unaffected\",\"The chain stops working\"],\"answer\":3,\"explain\":\"Without the predator, prey may over‑populate, disrupting the chain.\"},{\"q\":\"What process turns dead plants and animals into soil nutrients?\",\"options\":[\"Photosynthesis\",\"Respiration\",\"Decomposition\",\"Transpiration\"],\"answer\":2,\"explain\":\"Decomposition by micro‑organisms breaks down organic matter.\"},{\"q\":\"Which of these is NOT a non‑living factor in the environment?\",\"options\":[\"Sunlight\",\"Water\",\"Plants\",\"Soil\"],\"answer\":2,\"explain\":\"Plants are living; the others are non‑living.\"},{\"q\":\"What does a food web represent?\",\"options\":[\"A single chain of food\",\"All possible food chains in an ecosystem\",\"Only plants and animals\",\"The water cycle\"],\"answer\":1,\"explain\":\"A food web shows many interconnected food chains.\"},{\"q\":\"Which organism is a primary producer?\",\"options\":[\"Worm\",\"Snake\",\"Grasshopper\",\"Sun\"],\"answer\":3,\"explain\":\"Plants (grass) produce food using sunlight.\"},{\"q\":\"Why are micro‑organisms important for soil?\",\"options\":[\"They eat plants\",\"They build soil structure\",\"They decompose organic matter\",\"They produce oxygen\"],\"answer\":2,\"explain\":\"They break down matter, releasing nutrients.\"},{\"q\":\"What is the main purpose of the water cycle?\",\"options\":[\"To produce oxygen\",\"To recycle nutrients\",\"To move water around Earth\",\"To create food\"],\"answer\":2,\"explain\":\"It transports water through evaporation, condensation, and precipitation.\"},{\"q\":\"Which statement is true about biodiversity?\",\"options\":[\"It is the same everywhere\",\"It is the variety of living things in an area\",\"It only includes animals\",\"It is unrelated to food chains\"],\"answer\":1,\"explain\":\"Biodiversity refers to the variety of species in a place.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16762,23,5,'EVS Part 1','en','Family Values','[\"Family is a group where everyone has a role in decisions.\",\"Each member’s opinion matters and should be heard before any choice.\",\"We talk, listen, and agree together to make fair decisions.\",\"Honesty is important in family and public life; it builds trust and efficiency.\",\"Co‑operation means working together and sharing responsibilities.\",\"Tolerance means accepting others’ differences and not judging them.\",\"Gender equality means boys and girls, men and women are treated the same.\",\"Everyone should help with household chores, not just one person.\",\"When a mistake happens, we should admit it and correct it together.\",\"Being honest and cooperative helps the family grow stronger and happier.\"]','[{\"q\":\"What should you do before making a decision in your family?\",\"options\":[\"Ignore others’ opinions\",\"Ask everyone’s opinion\",\"Decide alone\",\"Choose the youngest’s idea\"],\"answer\":1,\"explain\":\"All family members’ views are considered before deciding.\"},{\"q\":\"Why is honesty important in public life?\",\"options\":[\"It makes people look good\",\"It increases efficiency\",\"It saves money only\",\"It is not needed\"],\"answer\":1,\"explain\":\"Honesty helps public services run smoothly and efficiently.\"},{\"q\":\"Which of the following is a sign of cooperation?\",\"options\":[\"Only one person does all chores\",\"Everyone helps each other\",\"No one talks about mistakes\",\"Everyone keeps secrets\"],\"answer\":1,\"explain\":\"Cooperation means sharing tasks and supporting each other.\"},{\"q\":\"What does gender equality mean?\",\"options\":[\"Only boys get toys\",\"Girls are better than boys\",\"Boys and girls are treated the same\",\"Men are superior to women\"],\"answer\":2,\"explain\":\"Gender equality means treating boys and girls, men and women equally.\"},{\"q\":\"Tolerance helps us to:\",\"options\":[\"Ignore others’ views\",\"Listen to others’ opinions\",\"Keep secrets\",\"Make decisions alone\"],\"answer\":1,\"explain\":\"Tolerance means listening and understanding others’ views.\"},{\"q\":\"If a family member makes a mistake, the best action is to:\",\"options\":[\"Blame them\",\"Hide it\",\"Admit and correct it\",\"Ignore it\"],\"answer\":2,\"explain\":\"Admitting and correcting mistakes builds trust.\"},{\"q\":\"Which activity shows cooperation?\",\"options\":[\"Playing alone\",\"Watching TV alone\",\"Helping in cooking\",\"Reading alone\"],\"answer\":2,\"explain\":\"Helping in cooking involves working together.\"},{\"q\":\"When deciding on a trip, you should:\",\"options\":[\"Choose the destination alone\",\"Ask everyone’s suggestions\",\"Let the teacher decide\",\"Pick the cheapest option\"],\"answer\":1,\"explain\":\"All family members should give suggestions.\"},{\"q\":\"Honesty in public life helps to:\",\"options\":[\"Create confusion\",\"Avoid waste of time and money\",\"Make people angry\",\"Reduce services\"],\"answer\":1,\"explain\":\"Honesty prevents wastage and improves services.\"},{\"q\":\"What is a key benefit of being honest?\",\"options\":[\"Loss of trust\",\"More efficient public services\",\"Less cooperation\",\"More arguments\"],\"answer\":1,\"explain\":\"Honesty increases trust and efficiency.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16763,23,5,'EVS Part 1','en','Rules Are for Everyone','[\"- Rules are laws that everyone must follow.\",\"- Natural laws (gravity, tides) never change, but human rules can change.\",\"- Traffic rules keep roads safe and traffic moving smoothly.\",\"- Social rules help people live together peacefully.\",\"- Everyone, no matter who they are, must obey the same rules.\",\"- Disobeying rules can lead to punishment or unfairness.\",\"- Laws are made to protect people and the environment.\",\"- Some customs (like untouchability) were banned by law.\",\"- Education laws (free primary education) help everyone learn.\",\"- Rules should be fair, equal and not discriminate.\"]','[{\"q\":\"Which of the following is a natural law that never changes?\",\"options\":[\"Gravity\",\"Traffic rules\",\"School rules\",\"Customs\"],\"answer\":0,\"explain\":\"Gravity is a natural law that is constant.\"},{\"q\":\"Why do we need traffic rules?\",\"options\":[\"To make roads look nice\",\"To keep traffic moving smoothly\",\"To give drivers more freedom\",\"To stop people from walking\"],\"answer\":1,\"explain\":\"Traffic rules keep roads safe and traffic flowing.\"},{\"q\":\"Which rule is an example of a law that protects the environment?\",\"options\":[\"Prohibition of loudspeakers after 10 pm\",\"Free primary education\",\"Ban on dumping garbage in rivers\",\"Ban on child labour\"],\"answer\":2,\"explain\":\"Banning garbage dumping protects rivers.\"},{\"q\":\"What is an example of a social rule that was changed by law?\",\"options\":[\"Untouchability\",\"Sati\",\"Superstition\",\"Illiteracy\"],\"answer\":0,\"explain\":\"Untouchability was banned by law.\"},{\"q\":\"Who can break the rules?\",\"options\":[\"Only teachers\",\"Only parents\",\"Everyone equally\",\"Only children\"],\"answer\":2,\"explain\":\"Rules apply to everyone.\"},{\"q\":\"Which of these is a human-made rule that can change?\",\"options\":[\"The rising of the sun\",\"The phases of the moon\",\"The law of gravity\",\"Traffic rules\"],\"answer\":3,\"explain\":\"Human rules like traffic rules can be changed.\"},{\"q\":\"What is the main purpose of laws?\",\"options\":[\"To make people rich\",\"To keep people busy\",\"To maintain equality and justice\",\"To create more rules\"],\"answer\":2,\"explain\":\"Laws aim for equality and justice.\"},{\"q\":\"Which of these is NOT a natural law?\",\"options\":[\"Gravity\",\"Tides\",\"Traffic rules\",\"Sunrise\"],\"answer\":2,\"explain\":\"Traffic rules are human-made.\"},{\"q\":\"Why was the voting age lowered from 21 to 18?\",\"options\":[\"To give more people a voice\",\"To reduce elections\",\"To make voting easier\",\"To stop young people from voting\"],\"answer\":0,\"explain\":\"Lowering age gives more people a vote.\"},{\"q\":\"Which rule helps protect children?\",\"options\":[\"Ban on child labour\",\"Ban on loudspeakers\",\"Free primary education\",\"Ban on hunting\"],\"answer\":0,\"explain\":\"Banning child labour protects children.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16764,23,5,'EVS Part 1','en','Let us Solve our own Problems','[\"Problems in civic life are issues that disturb the harmony of a community.\",\"A problem is something that causes inconvenience or difficulty.\",\"Disputes are problems that arise between people or groups.\",\"Peacekeepers are people who help solve disputes peacefully.\",\"The Mahatma Gandhi Dispute‑Free Village Mission helps villages solve their own problems.\",\"In a village, people can solve problems by discussion, cooperation and participation.\",\"If a problem is serious, it may need help from a court or a local body.\",\"Cleaning a village through ‘shramdaan’ means everyone works voluntarily to keep the village clean.\",\"Vermiculture is a method of using worms to turn garbage into manure.\",\"Peaceful solutions include dialogue, mediation, and community meetings.\",\"When everyone helps, problems disappear faster and society becomes stronger.\",\"A peaceful family, school and society benefits everyone and helps progress in all fields.\",\"The UN declared 21 September as International Peace Day to promote peace worldwide.\",\"A group of peacekeepers can be formed in a school to help solve small disputes.\",\"To solve a problem, first identify it, then discuss it with all parties involved.\",\"The basic needs of all people must be met for a peaceful society: security, equality and participation.\",\"Cleanliness, education and self‑reliance are essential for progress.\",\"When you see a problem, don’t ignore it; act quickly to prevent it from getting worse.\",\"A village can create a peace environment by setting rules, using peaceful methods and encouraging participation.\"]','[{\"q\":\"What is a problem in civic life?\",\"options\":[\"A type of plant\",\"A situation that causes inconvenience\",\"A kind of food\",\"A musical instrument\"],\"answer\":1,\"explain\":\"A problem is something that causes difficulty or inconvenience.\"},{\"q\":\"Who helps villages solve their own disputes in the Dispute‑Free Village Mission?\",\"options\":[\"The police\",\"The villagers themselves\",\"The king\",\"The school principal\"],\"answer\":1,\"explain\":\"Villages solve disputes through discussion among their own people.\"},{\"q\":\"What does ‘shramdaan’ mean?\",\"options\":[\"Paid work\",\"Voluntary contribution of labour\",\"A type of dance\",\"A special food\"],\"answer\":1,\"explain\":\"Shramdaan is voluntary work done by people to help the community.\"},{\"q\":\"Which method can help solve a dispute peacefully?\",\"options\":[\"Violence\",\"Ignoring it\",\"Dialogue\",\"Throwing stones\"],\"answer\":2,\"explain\":\"Dialogue and discussion help resolve disputes without violence.\"},{\"q\":\"What is vermiculture used for?\",\"options\":[\"Making soap\",\"Turning garbage into manure\",\"Cleaning roads\",\"Building houses\"],\"answer\":1,\"explain\":\"Vermiculture uses worms to convert waste into useful manure.\"},{\"q\":\"What should you do if you see a problem in your village?\",\"options\":[\"Ignore it\",\"Report it to a responsible person\",\"Throw it away\",\"Call a friend\"],\"answer\":1,\"explain\":\"Reporting helps the problem be addressed quickly.\"},{\"q\":\"What is International Peace Day?\",\"options\":[\"A day to eat sweets\",\"A day to celebrate sports\",\"A day to promote peace\",\"A day to watch movies\"],\"answer\":2,\"explain\":\"It is a day to promote peace worldwide.\"},{\"q\":\"Why is cleanliness important for progress?\",\"options\":[\"It looks nice\",\"It helps the environment\",\"It is a tradition\",\"It is a myth\"],\"answer\":1,\"explain\":\"Cleanliness supports health, education and development.\"},{\"q\":\"What is the main aim of the Mahatma Gandhi Dispute‑Free Village Mission?\",\"options\":[\"To build schools\",\"To solve disputes peacefully\",\"To plant trees\",\"To make money\"],\"answer\":1,\"explain\":\"The mission aims to solve disputes peacefully in villages.\"},{\"q\":\"Which of these is NOT a way to solve a problem?\",\"options\":[\"Discussion\",\"Cooperation\",\"Ignoring it\",\"Mediation\"],\"answer\":2,\"explain\":\"Ignoring a problem makes it worse.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16765,23,5,'EVS Part 1','en','Public Facilities and My School','[\"Public facilities are services or places that anyone can use, like schools, parks, libraries, hospitals, and transport.\",\"Water, electricity, health, education and transport are the main public services that help everyone.\",\"A school is a public facility where children learn and play; it is part of the community system.\",\"Every child has a right to free primary education (ages 6‑14) and up to 18 for special needs (Right to Education Act).\",\"Parents, teachers, and community members help build and run schools – they may donate money, materials or time.\",\"Schools can organise cleanliness drives, poster competitions and play‑dramas to teach good habits to the village.\",\"Parent‑Teacher Association (PTA) and Mata‑Palak Sangh (Mother‑Teacher Group) help parents and teachers cooperate for the school’s benefit.\",\"A school’s unique features include its library, laboratory, playground, cafeteria, and special programmes like counselling or science clubs.\",\"Students should identify all services available at their school and list them on a poster.\",\"Public services must be used responsibly; misuse can harm the community.\",\"The school is a part of the larger system of public services that keeps society running smoothly.\",\"Children can become agents of cleanliness by organising drives and educating neighbours.\",\"Community support for a school can include building classrooms, providing equipment or organising events.\",\"Every child’s right to education is a fundamental right that must be protected by law.\",\"Good school facilities encourage learning, health and safety for all students.\"]','[{\"q\":\"Which of these is NOT a public facility mentioned in the chapter?\",\"options\":[\"Library\",\"Bus\",\"Private Gym\",\"School\"],\"answer\":2,\"explain\":\"The chapter lists libraries, buses, and schools but not private gyms.\"},{\"q\":\"What is the main right that every child has according to the Right to Education Act?\",\"options\":[\"Free primary education\",\"Free secondary education\",\"Free higher education\",\"Free vocational training\"],\"answer\":0,\"explain\":\"The Act guarantees free primary education for children aged 6‑14.\"},{\"q\":\"Who can help build and run a school?\",\"options\":[\"Only teachers\",\"Only parents\",\"Parents, teachers and community members\",\"Only the government\"],\"answer\":2,\"explain\":\"The chapter says parents, teachers and community members all help.\"},{\"q\":\"A school can organise a cleanliness drive to teach what?\",\"options\":[\"Sports skills\",\"Mathematics\",\"Good habits\",\"History\"],\"answer\":2,\"explain\":\"Cleanliness drives teach good habits and hygiene.\"},{\"q\":\"Which of these is a benefit of having a Parent‑Teacher Association?\",\"options\":[\"More school fees\",\"Less teacher involvement\",\"Better cooperation between parents and teachers\",\"More exams\"],\"answer\":2,\"explain\":\"PTA improves cooperation between parents and teachers.\"},{\"q\":\"The Right to Education Act extends the age limit for special needs children to:\",\"options\":[\"14 years\",\"16 years\",\"18 years\",\"20 years\"],\"answer\":2,\"explain\":\"Special needs children can study up to 18 years.\"},{\"q\":\"Which of the following is a public transport facility?\",\"options\":[\"Bus\",\"Private car\",\"Taxi\",\"Motorbike\"],\"answer\":0,\"explain\":\"Bus is a public transport facility; the others are private.\"},{\"q\":\"What should students do to identify their school’s unique features?\",\"options\":[\"Ignore them\",\"Write a poem\",\"Prepare a poster\",\"Take a photo\"],\"answer\":2,\"explain\":\"The chapter suggests making a poster of the school’s features.\"},{\"q\":\"Which service is NOT listed as a public service in the chapter?\",\"options\":[\"Water supply\",\"Electricity supply\",\"Private tutoring\",\"Health services\"],\"answer\":2,\"explain\":\"Private tutoring is not a public service mentioned.\"},{\"q\":\"The school’s cleanliness drive helped the village to win which award?\",\"options\":[\"Best Library Award\",\"Clean Village Award\",\"Sports Excellence Award\",\"Science Fair Award\"],\"answer\":1,\"explain\":\"The chapter says the village won the Clean Village award.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16766,23,5,'EVS Part 1','en','Maps – our Companions','[\"Maps show the shape and height of land.\",\"Landforms are mountains, hills, valleys, plains, plateaus, islands, rivers, lakes, and forests.\",\"Contour lines are curves that connect points of the same height on a map.\",\"The space between contour lines is filled with colour in the layer‑tinting method.\",\"Digital elevation models use satellite data to show height on a computer map.\",\"Signs and symbols on a map are universal; e.g., a triangle for a fort, a circle for a lake, a dot for a village.\",\"The key (legend) explains all signs and symbols used on a map.\",\"Maps help in planning, military strategy, tourism, and environmental studies.\",\"The height of the land is measured from sea level; negative values mean below sea level.\",\"A map can show the same area in different ways: contour lines, colour shading, or digital elevation models.\",\"When two maps are close together, the slope is steep; when far apart, the slope is gentle.\",\"A hill’s cross‑section shows a gentle slope on one side and a steep slope on the other.\",\"The Survey of India is the main map‑making institute in India.\",\"Signs for common features: Post office (P), Hospital (H), Factory (F), Park (P), Playground (G), Road (R), Hill (H), River (R).\",\"The colour used for water bodies is blue; higher elevations are light green or yellow, lower are dark green.\",\"A map’s caption gives the title, scale, and date of the map.\",\"The key is essential for understanding the map’s symbols and colours.\",\"Maps are used in military operations, tourism, and regional development plans.\",\"A contour line method shows unevenness; the layer‑tinting method shows height by colour; the digital method shows height by computer data.\",\"The Survey of India started in 1767 and has made many accurate topographic maps.\",\"A map’s symbols are miniature drawings of the objects they represent.\",\"A map’s signs are simple geometric shapes or letters.\",\"The height of a hill can be shown by a hill shading technique.\",\"A map’s legend is also called a key.\",\"When a map shows a wrong colour for a landform, it must be corrected.\"]','[{\"q\":\"Which method uses lines that connect points of the same height?\",\"options\":[\"Layer‑tinting\",\"Contour line method\",\"Digital elevation model\",\"Hill shading\"],\"answer\":1,\"explain\":\"Contour lines join points of equal elevation.\"},{\"q\":\"What colour is usually used to represent water bodies on a map?\",\"options\":[\"Blue\",\"Green\",\"Red\",\"Yellow\"],\"answer\":0,\"explain\":\"Blue is the standard colour for water.\"},{\"q\":\"The Survey of India was established in which year?\",\"options\":[\"1767\",\"1850\",\"1900\",\"1920\"],\"answer\":0,\"explain\":\"The institute was founded in 1767.\"},{\"q\":\"Which symbol would you use for a fort on a map?\",\"options\":[\"Triangle\",\"Circle\",\"Square\",\"Diamond\"],\"answer\":0,\"explain\":\"A triangle is the conventional symbol for a fort.\"},{\"q\":\"What does a map’s key (legend) explain?\",\"options\":[\"The map’s title\",\"The symbols and colours\",\"The scale only\",\"The author of the map\"],\"answer\":1,\"explain\":\"The key shows meanings of symbols and colours.\"},{\"q\":\"In a layer‑tinting map, what does the colour of a space indicate?\",\"options\":[\"The type of vegetation\",\"The distance from the observer\",\"The specific height\",\"The weather\"],\"answer\":2,\"explain\":\"Colour indicates the height range of that area.\"},{\"q\":\"Which of the following is NOT a landform?\",\"options\":[\"Mountain\",\"River\",\"Lake\",\"Post office\"],\"answer\":3,\"explain\":\"Post office is a man‑made structure, not a landform.\"},{\"q\":\"When two contour lines are close together on a map, what does that indicate?\",\"options\":[\"Gentle slope\",\"Steep slope\",\"Flat land\",\"Water body\"],\"answer\":1,\"explain\":\"Close lines mean a steep slope.\"},{\"q\":\"Which method is the most modern for showing elevation?\",\"options\":[\"Contour line method\",\"Layer‑tinting method\",\"Digital elevation model\",\"Hill shading\"],\"answer\":2,\"explain\":\"Digital elevation models use satellite data.\"},{\"q\":\"What is the purpose of using conventional signs on a map?\",\"options\":[\"To make the map colourful\",\"To provide exact information\",\"To confuse the reader\",\"To reduce printing costs\"],\"answer\":1,\"explain\":\"Signs give precise information about features.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16767,23,5,'EVS Part 1','en','Getting to Know India','[\"India is a peninsula surrounded by water on three sides – the Arabian Sea to the west, the Bay of Bengal to the east and the Indian Ocean to the south.\",\"The northern border of India is the Himalayan mountain range, the highest peaks reaching over 8,000 m.\",\"Major rivers flow from the Himalayas to the plains and then to the sea: Ganga, Yamuna, Brahmaputra, Godavari, Narmada, Krishna, Kaveri and others.\",\"Rivers have a slope – they flow downhill from high to low places. The slope is steeper in the mountains and gentler in the plains.\",\"Plateaus are flat elevated areas; the Deccan Plateau covers most of southern India.\",\"Deserts are found in the north‑west (Thar Desert) and in the central part (Bikaner Desert).\",\"India has many islands: Lakshadweep in the Arabian Sea, Andaman and Nicobar in the Bay of Bengal, and several coastal islands along the Konkan coast.\",\"The capital of India is New Delhi, located in the northern part of the country.\",\"Rajasthan is the largest state by area, followed by Madhya Pradesh and Maharashtra.\",\"The smallest state is Goa, and the smallest union territory is Dadra and Nagar Haveli and Daman and Diu.\",\"The Great Indian Desert (Thar) lies mainly in Rajasthan.\",\"Cash crops such as tea, coffee, saffron, cloves, apples and oranges are grown in specific states – e.g., tea in Assam, coffee in Karnataka, saffron in Himachal Pradesh, apples in Himachal and Uttarakhand, oranges in Maharashtra.\",\"Transport routes on the map show how goods move between states – e.g., a route from Nagpur to Bikaner for oranges.\",\"The Indian subcontinent has diverse climates, leading to varied crops: wheat in the north, rice in the south, jowar in the central plains.\",\"India’s cultural diversity includes many languages, religions, castes, festivals, clothing and food traditions.\",\"The political map shows states, union territories, capitals and important cities; the map also indicates the largest state in yellow and the state in the user’s home state in a favourite colour.\",\"The map also shows the names of rivers, mountains, plateaus, deserts, gulfs and islands, and their directions of flow or location.\",\"Students should learn to read a map, identify features, and answer questions about them.\",\"Key terms: peninsula, Himalayas, plateau, desert, river basin, capital, union territory, cash crop, transport route.\"]','[{\"q\":\"Which of the following rivers flows from the Himalayas and joins the Indus in the northwestern part of India?\",\"options\":[\"Ganga\",\"Yamuna\",\"Brahmaputra\",\"Indus\"],\"answer\":3,\"explain\":\"The Indus River itself originates in the Himalayas and flows into Pakistan.\"},{\"q\":\"What is the name of the large desert located mainly in the state of Rajasthan?\",\"options\":[\"Thar Desert\",\"Kalahandi Desert\",\"Kutch Desert\",\"Aravalli Desert\"],\"answer\":0,\"explain\":\"The Thar Desert covers most of Rajasthan.\"},{\"q\":\"Which sea lies to the east of the Indian mainland?\",\"options\":[\"Arabian Sea\",\"Bay of Bengal\",\"Indian Ocean\",\"Andaman Sea\"],\"answer\":1,\"explain\":\"The Bay of Bengal is on the eastern side of India.\"},{\"q\":\"Which state is the largest by area in India?\",\"options\":[\"Madhya Pradesh\",\"Maharashtra\",\"Rajasthan\",\"Uttar Pradesh\"],\"answer\":2,\"explain\":\"Rajasthan is the largest state in India.\"},{\"q\":\"Which of the following islands is part of the Andaman and Nicobar group?\",\"options\":[\"Lakshadweep\",\"Sikkim\",\"Kohima\",\"Port Blair\"],\"answer\":3,\"explain\":\"Port Blair is the capital of the Andaman and Nicobar Islands.\"},{\"q\":\"The Ganga River flows through which of these states?\",\"options\":[\"Madhya Pradesh\",\"Uttar Pradesh\",\"Karnataka\",\"Tamil Nadu\"],\"answer\":1,\"explain\":\"The Ganga flows mainly through Uttar Pradesh.\"},{\"q\":\"Which of these crops is primarily grown in the northern plains of India?\",\"options\":[\"Rice\",\"Wheat\",\"Mango\",\"Tea\"],\"answer\":1,\"explain\":\"Wheat is a main crop in northern India.\"},{\"q\":\"The Arabian Sea is located to the ___ of India.\",\"options\":[\"North\",\"South\",\"East\",\"West\"],\"answer\":3,\"explain\":\"The Arabian Sea lies to the west of India.\"},{\"q\":\"Which river is known as the \'Sister River\' of the Ganga?\",\"options\":[\"Yamuna\",\"Brahmaputra\",\"Godavari\",\"Narmada\"],\"answer\":0,\"explain\":\"The Yamuna is called the sister river of the Ganga.\"},{\"q\":\"Which of the following states is the smallest by area in India?\",\"options\":[\"Goa\",\"Sikkim\",\"Tripura\",\"Nagaland\"],\"answer\":0,\"explain\":\"Goa is the smallest state by area.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16768,23,5,'EVS Part 1','en','Our Home and Environment','[\"- A house is a shelter that protects us from sun, wind, rain and cold.\",\"- Houses are built using materials that are available locally – wood, stone, earth, bricks, cement, glass, metal, tin sheets, etc.\",\"- The shape of a house (rectangular, square, round) and its roof type (flat, sloping, thatched) depend on the climate and the region.\",\"- In plains with moderate rainfall, houses are usually rectangular with stone or earth walls and a sloping roof made of thatch or tiles.\",\"- In heavy rainfall areas, houses have steep roofs to shed rainwater and walls made of earth or stone to keep the interior dry.\",\"- In desert regions, houses are built with thick walls of earth or mud to keep the interior cool and roofs are flat or low sloping.\",\"- In marshy or wetland areas, houses are raised on stilts or made of bamboo to avoid flooding.\",\"- In mountainous regions, houses are small, low‑profile, often made of stone or wood, with steep roofs to handle snow and wind.\",\"- Eco‑friendly houses use renewable energy (solar, wind, biogas), recycle water and waste, avoid artificial colours, and allow natural light and ventilation.\",\"- Pollution from construction (dust, noise, chemical runoff) can harm the environment and people nearby.\",\"- Homeless people lack basic needs like shelter, water, food and education; governments try to provide shelters and housing schemes.\",\"- Children can help by making models of eco‑friendly houses, preparing street plays, and raising awareness about pollution and energy use.\"]','[{\"q\":\"What is the main purpose of a house?\",\"options\":[\"To store food\",\"To protect people from weather\",\"To make money\",\"To decorate the street\"],\"answer\":1,\"explain\":\"A house shelters us from sun, wind, rain and cold.\"},{\"q\":\"Which material is commonly used for walls in plains?\",\"options\":[\"Wood\",\"Stone\",\"Plastic\",\"Glass\"],\"answer\":1,\"explain\":\"Plains houses often use stone or earth walls.\"},{\"q\":\"Which roof type is suitable for heavy rainfall areas?\",\"options\":[\"Flat roof\",\"Steep sloping roof\",\"Thatched roof\",\"No roof\"],\"answer\":1,\"explain\":\"Steep roofs shed rainwater quickly.\"},{\"q\":\"What is a key feature of eco‑friendly houses?\",\"options\":[\"Use of artificial colours\",\"Use of non‑exhaustible energy\",\"Use of plastic walls\",\"No windows\"],\"answer\":1,\"explain\":\"They use renewable energy like solar or wind.\"},{\"q\":\"Which region uses houses built on stilts?\",\"options\":[\"Desert\",\"Mountainous\",\"Marshy\",\"Plains\"],\"answer\":2,\"explain\":\"Stilt houses avoid flooding in wetland areas.\"},{\"q\":\"What is a major source of pollution at construction sites?\",\"options\":[\"Noise\",\"Dust\",\"Water\",\"All of the above\"],\"answer\":3,\"explain\":\"Construction creates noise, dust, and water pollution.\"},{\"q\":\"Which material is NOT typically used for building walls in mountainous houses?\",\"options\":[\"Stone\",\"Wood\",\"Bamboo\",\"Plastic\"],\"answer\":3,\"explain\":\"Plastic is rarely used in traditional mountain houses.\"},{\"q\":\"What is the main benefit of using solar panels in a house?\",\"options\":[\"Reduce electricity bills\",\"Make the house look modern\",\"Add noise\",\"Increase dust\"],\"answer\":0,\"explain\":\"Solar panels provide free energy, reducing bills.\"},{\"q\":\"Which of the following is a reason for building houses differently in each region?\",\"options\":[\"Availability of materials\",\"Personal taste\",\"Government policy\",\"All of the above\"],\"answer\":3,\"explain\":\"All factors influence house design.\"},{\"q\":\"What is a common practice to protect homeless people?\",\"options\":[\"Provide shelters\",\"Give them jobs\",\"Build roads\",\"None of the above\"],\"answer\":0,\"explain\":\"Shelters provide basic protection for homeless.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16769,23,5,'EVS Part 1','en','Food for All','[\"- Food is the energy that keeps us alive and growing.\",\"- Plants make food by photosynthesis using sunlight, water and air.\",\"- Seeds are the starting point of a new plant; improved seeds give higher yield and resist pests.\",\"- Two main seasons for farming in India: Kharif (June‑October) and Rabi (October‑March).\",\"- Modern irrigation methods: drip irrigation (drops water near roots) and sprinkle irrigation (sprays water over the field).\",\"- Fertilizers give extra nutrients; natural fertilizers are manures, chemical fertilizers are artificial.\",\"- Overuse of chemical fertilizers can lower soil fertility and harm the environment.\",\"- Storing grain in dry, airy places prevents insects and fungus.\",\"- Food security means every person gets enough food; laws and programmes help farmers and consumers.\",\"- Green Revolution increased food production through better seeds and technology.\",\"- Organic farming uses natural materials and keeps soil healthy.\",\"- Farmers use modern tools like tractors, improved seeds, and irrigation to increase yield.\",\"- Storage of food by animals (ants, bees, squirrels) shows nature’s way of keeping food safe.\"]','[{\"q\":\"Which season in India is called the kharif season?\",\"options\":[\"June to October\",\"October to March\",\"March to June\",\"All year round\"],\"answer\":0,\"explain\":\"Kharif season is from June to October, mainly rainfed.\"},{\"q\":\"What is the main source of water for rabi crops?\",\"options\":[\"Rainwater\",\"Dew and monsoon runoff\",\"Well water\",\"River water\"],\"answer\":1,\"explain\":\"Rabi crops rely on rainwater, monsoon runoff, and dew.\"},{\"q\":\"Which irrigation method drips water only near the roots?\",\"options\":[\"Sprinkle irrigation\",\"Drip irrigation\",\"Flood irrigation\",\"Surface irrigation\"],\"answer\":1,\"explain\":\"Drip irrigation delivers water close to plant roots.\"},{\"q\":\"What is a natural fertilizer called?\",\"options\":[\"Chemical fertilizer\",\"Organic manure\",\"Synthetic nutrient\",\"Pesticide\"],\"answer\":1,\"explain\":\"Natural fertilizer is called organic manure.\"},{\"q\":\"Which crop is grown in the summer season?\",\"options\":[\"Rice\",\"Wheat\",\"Jowar\",\"Maize\"],\"answer\":2,\"explain\":\"Jowar (sorghum) is a summer crop.\"},{\"q\":\"Which of these is a modern method of irrigation?\",\"options\":[\"Sprinkle irrigation\",\"Flooding\",\"Manual watering\",\"None of the above\"],\"answer\":0,\"explain\":\"Sprinkle irrigation is a modern method.\"},{\"q\":\"What happens if chemical fertilizers are overused?\",\"options\":[\"Soil becomes more fertile\",\"Water becomes cleaner\",\"Soil fertility decreases\",\"Plants grow faster\"],\"answer\":2,\"explain\":\"Overuse reduces soil fertility.\"},{\"q\":\"Which of these is a pest that spoils stored grain?\",\"options\":[\"Mice\",\"Fish\",\"Birds\",\"Butterflies\"],\"answer\":0,\"explain\":\"Mice can damage stored grain.\"},{\"q\":\"What is the main advantage of storing grain in a dry place?\",\"options\":[\"Keeps it sweet\",\"Prevents fungus and insects\",\"Makes it heavier\",\"Increases taste\"],\"answer\":1,\"explain\":\"Dry storage prevents fungus and insects.\"},{\"q\":\"Which scientist is credited with the Green Revolution in India?\",\"options\":[\"Dr. A.P.J. Abdul Kalam\",\"Dr. M.S. Swaminathan\",\"Dr. R. K. Shukla\",\"Dr. S. Radhakrishnan\"],\"answer\":1,\"explain\":\"Dr. M.S. Swaminathan led the Green Revolution.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16770,23,5,'EVS Part 1','en','Methods of Preserving Food','[\"Drying removes water to stop micro‑organism growth.\",\"Cooling in a refrigerator keeps food at low temperature so bacteria cannot multiply.\",\"Boiling destroys bacteria and fungi by high heat.\",\"Canning seals food in airtight containers to prevent air and microbes from entering.\",\"Adding preservatives like salt, sugar, vinegar, or spices stops spoilage by creating hostile conditions.\",\"Spices can be dried and stored for long periods because they contain natural preservatives.\",\"Food should be kept away from moisture, heat, and insects to avoid spoilage.\",\"Micro‑organisms need food, water, warmth, and air to grow.\",\"Proper cleaning of utensils and hands prevents contamination.\",\"Storing food in the right season (e.g., drying in summer) helps preserve it for the whole year.\",\"Chilled milk stays fresh longer because cold slows bacterial activity.\",\"Fruits and vegetables spoil faster in warm, humid conditions; they last longer when kept cool.\",\"Preservatives work by lowering water activity or changing pH to inhibit microbes.\",\"A closed jar with a cloth cover allows fermentation while preventing contamination.\",\"Food that shows mold, foul smell, or color change should be discarded.\"]','[{\"q\":\"Which method removes water from food to stop microbes from growing?\",\"options\":[\"Drying\",\"Cooling\",\"Boiling\",\"Canning\"],\"answer\":0,\"explain\":\"Drying removes water, which microbes need to grow.\"},{\"q\":\"What is the main purpose of adding salt to food?\",\"options\":[\"Add flavour\",\"Make it sweet\",\"Preserve by killing microbes\",\"Make it spicy\"],\"answer\":2,\"explain\":\"Salt creates a dry environment that kills or stops microbes.\"},{\"q\":\"Which of the following is NOT a method of food preservation mentioned?\",\"options\":[\"Freezing\",\"Drying\",\"Cooling\",\"Boiling\"],\"answer\":0,\"explain\":\"Freezing was not listed in the chapter.\"},{\"q\":\"Why do we avoid eating food that has started to grow fungus?\",\"options\":[\"It tastes better\",\"It is safe\",\"It can cause stomach upset\",\"It is cheaper\"],\"answer\":2,\"explain\":\"Fungus can cause illness.\"},{\"q\":\"What does a refrigerator do to food?\",\"options\":[\"Adds moisture\",\"Increases temperature\",\"Slows down micro‑organism growth\",\"Adds preservatives\"],\"answer\":2,\"explain\":\"Refrigeration keeps food cold, slowing microbes.\"},{\"q\":\"Which substance is NOT mentioned as a preservative?\",\"options\":[\"Sugar\",\"Vinegar\",\"Mustard oil\",\"Salt\"],\"answer\":2,\"explain\":\"Mustard oil was not listed; the chapter mentioned salt, sugar, vinegar.\"},{\"q\":\"When should fruits be stored to keep them fresh for a long time?\",\"options\":[\"In the summer\",\"In the winter\",\"In a refrigerator\",\"In a sunny window\"],\"answer\":2,\"explain\":\"Refrigeration keeps fruits fresh longer.\"},{\"q\":\"What is the main reason for keeping food in an airtight container?\",\"options\":[\"To add flavour\",\"To keep it dry\",\"To stop air and microbes from entering\",\"To make it look nice\"],\"answer\":2,\"explain\":\"Airtight containers prevent microbes from entering.\"},{\"q\":\"Which of these is a type of drying method?\",\"options\":[\"Boiling\",\"Canning\",\"Papad drying\",\"Cooling\"],\"answer\":2,\"explain\":\"Papads are dried to preserve them.\"},{\"q\":\"What happens to food if it is left at room temperature for several days?\",\"options\":[\"It becomes sweeter\",\"It stays fresh\",\"It may develop fungus and spoil\",\"It becomes harder\"],\"answer\":2,\"explain\":\"Room temperature encourages microbial growth.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16771,23,5,'EVS Part 1','en','Transport','[\"Transport is the movement of people or goods from one place to another.\",\"There are three main types of transport: land, water and air.\",\"Land transport includes walking, bicycles, motor vehicles and trains.\",\"Water transport uses boats, ships and barges to carry goods and passengers.\",\"Air transport uses aeroplanes and helicopters to travel over long distances.\",\"Walking is the simplest and most eco‑friendly way to travel short distances.\",\"Bicycles are good for short to medium distances and give physical exercise.\",\"Motor vehicles (cars, buses, autorickshaws) use fuel and can travel faster but produce pollution.\",\"Trains are efficient for long distances and can carry many passengers or goods at once.\",\"Ships are used for long sea journeys and can carry huge amounts of cargo.\",\"Airplanes are the fastest way to travel long distances but consume a lot of fuel.\",\"Transport saves time and effort, making work and trade easier.\",\"Different modes of transport have advantages and disadvantages.\",\"Using public transport reduces traffic and pollution compared to private cars.\",\"Bicycles produce no pollution and are good for health and environment.\",\"Walking and cycling help keep the air cleaner and reduce noise pollution.\",\"Transport connects distant places, making the world feel closer.\",\"Fuel burning in vehicles releases carbon monoxide, nitrogen dioxide and sulphur dioxide.\",\"Air pollution harms plants, animals and human health, causing respiratory problems.\",\"To reduce pollution, use public transport, walk or cycle whenever possible, and maintain vehicles properly.\"]','[{\"q\":\"Which mode of transport takes the longest time for a short distance?\",\"options\":[\"Walking\",\"Bicycle\",\"Car\",\"Bus\"],\"answer\":0,\"explain\":\"Walking is the slowest mode of transport.\"},{\"q\":\"What is a main cause of air pollution from vehicles?\",\"options\":[\"Carbon monoxide\",\"Sunlight\",\"Rain\",\"Wind\"],\"answer\":0,\"explain\":\"Vehicles emit carbon monoxide, a harmful gas.\"},{\"q\":\"Which transport mode is most fuel efficient for short trips?\",\"options\":[\"Bicycle\",\"Car\",\"Bus\",\"Train\"],\"answer\":0,\"explain\":\"Bicycles do not use fuel.\"},{\"q\":\"Which of the following is NOT a benefit of transport?\",\"options\":[\"Time saving\",\"Trade facilitation\",\"Pollution\",\"Connectivity\"],\"answer\":2,\"explain\":\"Pollution is a drawback, not a benefit.\"},{\"q\":\"Which vehicle is best for carrying small loads and reduces crowding?\",\"options\":[\"Car\",\"Bus\",\"Bicycle\",\"Motorbike\"],\"answer\":2,\"explain\":\"Bicycles can carry small loads and reduce crowding.\"},{\"q\":\"What does CNG stand for?\",\"options\":[\"Compressed Natural Gas\",\"Carbon Neutral Gas\",\"Clean Natural Gas\",\"Compressed Nitrogen Gas\"],\"answer\":0,\"explain\":\"CNG means Compressed Natural Gas.\"},{\"q\":\"Which transport option is recommended for a grandmother who gets tired easily?\",\"options\":[\"Walking\",\"Autorickshaw\",\"Bus\",\"Scooter\"],\"answer\":2,\"explain\":\"A bus provides comfortable seating for the elderly.\"},{\"q\":\"Which gas is NOT mentioned as a pollutant from vehicles?\",\"options\":[\"Nitrogen dioxide\",\"Sulphur dioxide\",\"Oxygen\",\"Carbon monoxide\"],\"answer\":2,\"explain\":\"Oxygen is not listed as a pollutant.\"},{\"q\":\"Which activity helps reduce noise pollution?\",\"options\":[\"Using public transport\",\"Driving faster\",\"Increasing traffic\",\"Using private cars\"],\"answer\":0,\"explain\":\"Public transport reduces the number of vehicles, lowering noise.\"},{\"q\":\"Which of these is a remedy to reduce pollution from transport?\",\"options\":[\"Using fuels that cause less pollution\",\"Increasing fuel consumption\",\"Driving alone\",\"Using only petrol vehicles\"],\"answer\":0,\"explain\":\"Using cleaner fuels helps reduce pollution.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16772,23,5,'EVS Part 1','en','Communication and Mass Media','[\"- Communication is the exchange of information between people.\",\"- Mass media are tools like TV, radio, newspapers, internet that reach many people at once.\",\"- Artificial satellites help send TV programmes and mobile phone signals across the world.\",\"- Telecommunication means talking to someone far away using phones or the internet.\",\"- Advantages of mass media: easy contact, saves time, raises awareness, warns about disasters, supports government schemes, helps trade and industry.\",\"- Disadvantages: eye, ear and back problems from too much TV, psychological issues, isolation, neglect of outdoor activities.\",\"- TV and mobile phones can be used responsibly to avoid health problems.\",\"- Before phones, messages were sent by letters, telegrams or face‑to‑face talk.\",\"- Audio‑visual communication lets us see the person we talk to on a phone or video call.\",\"- Mass media can educate people about science, health, environment and social issues.\"]','[{\"q\":\"What helps TV programmes reach people in different parts of the world?\",\"options\":[\"Artificial satellites\",\"Cars\",\"Buses\",\"None\"],\"answer\":0,\"explain\":\"Satellites broadcast TV signals to many places.\"},{\"q\":\"Which device lets you talk to someone far away?\",\"options\":[\"Television\",\"Mobile phone\",\"Refrigerator\",\"Microwave\"],\"answer\":1,\"explain\":\"Mobile phones use radio waves to connect distant people.\"},{\"q\":\"What is a disadvantage of watching too much television?\",\"options\":[\"Better eyesight\",\"More energy\",\"Eye problems\",\"More friends\"],\"answer\":2,\"explain\":\"Excessive TV can cause eye strain and other health issues.\"},{\"q\":\"Mass media can warn people about which of these?\",\"options\":[\"New movies\",\"Natural disasters\",\"Fashion trends\",\"Sports scores\"],\"answer\":1,\"explain\":\"TV and radio can give early warnings of storms, floods, etc.\"},{\"q\":\"Before phones, how were long‑distance messages sent?\",\"options\":[\"By email\",\"By satellite\",\"By letters or telegrams\",\"By video calls\"],\"answer\":2,\"explain\":\"Letters and telegrams were used before telephones.\"},{\"q\":\"Which of these is NOT a benefit of mass media?\",\"options\":[\"Raises awareness about health\",\"Helps in trade\",\"Causes eye strain\",\"Warns about disasters\"],\"answer\":2,\"explain\":\"Causing eye strain is a disadvantage, not a benefit.\"},{\"q\":\"What does the term \'audio‑visual communication\' mean?\",\"options\":[\"Talking without seeing\",\"Seeing the person you talk to\",\"Listening to music only\",\"Reading a book\"],\"answer\":1,\"explain\":\"It lets you see the person while you talk, like video calls.\"},{\"q\":\"Which device uses satellites to send signals?\",\"options\":[\"Car radio\",\"Mobile phone\",\"Television set\",\"Microwave oven\"],\"answer\":1,\"explain\":\"Mobile phones use satellite signals for calls and data.\"},{\"q\":\"Mass media helps in the expansion of which sector?\",\"options\":[\"Healthcare\",\"Education\",\"Trade and industry\",\"All of the above\"],\"answer\":3,\"explain\":\"All listed sectors benefit from mass media.\"},{\"q\":\"What is a key advantage of using mass media for government schemes?\",\"options\":[\"Makes schemes secret\",\"Makes schemes expensive\",\"Makes schemes known to people\",\"Makes schemes harder to access\"],\"answer\":2,\"explain\":\"Mass media spreads information about schemes to the public.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16773,23,5,'EVS Part 1','en','Water','[\"Water is a liquid that covers most of Earth’s surface and is essential for life.\",\"Water can be clean or polluted. Clean water is safe to drink; polluted water contains harmful substances.\",\"Waste water is water that has been used in homes, factories, or farms and contains dirt, chemicals, or germs.\",\"Sewage is a type of waste water that comes from toilets, kitchens, and bathrooms.\",\"Water is purified before it is supplied to homes. The main steps are: 1) Settling (letting dirt fall to the bottom), 2) Filtration (passing water through sand or charcoal), 3) Chlorination (adding chlorine to kill germs).\",\"Oxygen is added to water in water‑works so fish and other aquatic life can breathe. This is called oxygenation.\",\"Rainwater can be collected in clean containers. Rain that falls directly on the ground is usually cleaner than rain that runs over soil or roofs.\",\"If a lot of dirty water is dumped into rivers or lakes, the water becomes polluted and can hurt plants, animals and people.\",\"Water that has no oxygen is bad for fish and other living things in rivers and lakes.\",\"Water‑works use large tanks, filters and chemicals to make water safe for drinking.\",\"When it rains, the water that falls on roofs can be stored in tanks or let seep into the ground. This helps keep water available during dry seasons.\",\"Water management means collecting, storing or letting water seep into the ground so that it can be used even when it does not rain.\",\"Drought happens when there is very little rain for a long time. It can lead to famine if people and animals do not have enough water.\"]','[{\"q\":\"What is the main purpose of treating sewage water before it is released into a water body?\",\"options\":[\"To make it taste better\",\"To remove harmful substances\",\"To increase its temperature\",\"To add colour\"],\"answer\":1,\"explain\":\"Treating sewage removes harmful germs and pollutants so the water can be safely used.\"},{\"q\":\"Which of the following is NOT a natural purification process for river water?\",\"options\":[\"Settling\",\"Oxygenation\",\"Chlorination\",\"Diffusion\"],\"answer\":3,\"explain\":\"Chlorination is a human-made process; the others happen naturally.\"},{\"q\":\"In the simple bottle filter experiment, which material is added first?\",\"options\":[\"Coarse sand\",\"Fine sand\",\"Powdered coal\",\"Water\"],\"answer\":3,\"explain\":\"The water is poured first, then powdered coal, fine sand, and finally coarse sand.\"},{\"q\":\"What happens to the dissolved oxygen level when a lot of waste is added to a river?\",\"options\":[\"It increases\",\"It stays the same\",\"It decreases\",\"It becomes zero\"],\"answer\":2,\"explain\":\"More waste reduces the amount of dissolved oxygen, harming aquatic life.\"},{\"q\":\"Which of these is a method of storing rainwater for use after the rainy season?\",\"options\":[\"Building dams\",\"Digging wells\",\"Planting trees\",\"All of the above\"],\"answer\":3,\"explain\":\"All listed methods help store rainwater.\"},{\"q\":\"What is the main danger of drinking untreated polluted water?\",\"options\":[\"It may taste bad\",\"It may cause diseases\",\"It may be too cold\",\"It may be too sweet\"],\"answer\":1,\"explain\":\"Polluted water can carry germs that spread diseases.\"},{\"q\":\"Why do we need to crush and throw away empty water bottles?\",\"options\":[\"To recycle them\",\"To keep them clean\",\"To prevent reuse\",\"To avoid litter\"],\"answer\":3,\"explain\":\"Crushing bottles prevents them from being reused and reduces litter.\"},{\"q\":\"What is the role of alum in water purification?\",\"options\":[\"Adds colour\",\"Helps settle particles\",\"Increases pH\",\"Kills germs\"],\"answer\":1,\"explain\":\"Alum helps particles settle during the settling process.\"},{\"q\":\"Which of the following is NOT a step in the water purification process at water-works?\",\"options\":[\"Settling\",\"Chlorination\",\"Oxygenation\",\"Evaporation\"],\"answer\":3,\"explain\":\"Evaporation is not part of the purification steps listed.\"},{\"q\":\"What is the main effect of not having rain for a long time?\",\"options\":[\"More fish\",\"Water level rises\",\"Drought and famine\",\"More trees\"],\"answer\":2,\"explain\":\"Long dry periods lead to drought and famine.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16774,23,5,'EVS Part 1','en','Clothes – our Necessity','[\"Clothes are items we wear to protect our body and give us comfort.\",\"We wear different clothes for different occasions like school, festivals, parties and sports.\",\"Children usually wear simple cotton shirts and trousers, while adults wear shirts, skirts, trousers, sarees or kurtas.\",\"In hot weather we wear light, loose clothes made of cotton or linen.\",\"In cold weather we wear warm clothes like woolen sweaters, jackets and shawls.\",\"Clothes can be made from natural fibres like cotton, wool, silk or from synthetic fibres like polyester and nylon.\",\"The process of making cloth involves: raw material (cotton, wool), spinning, weaving or knitting, dyeing and finishing.\",\"Textile industry is a big part of Maharashtra’s economy; famous products include Paithani saree, Himroo shawl, Solapur bedsheets and Ichalkaranji handloom cloth.\",\"People’s need for clothes is different from their desire for clothes; we need clothes for protection but may want more for fashion or status.\",\"Clothes change with time, culture and climate; traditional clothes vary across states like Rajasthan, Maharashtra, Kerala and Jammu & Kashmir.\",\"When we choose clothes, we should think about the purpose, comfort, and the season.\",\"It is good to borrow or lend clothes to friends when we have extra, but we should keep enough for ourselves.\",\"Advertisements often show many clothes that we do not need; we should be careful not to buy just because they look good.\",\"The raw material for cotton cloth comes from cotton plants; for wool cloth it comes from sheep’s fleece.\",\"Workers in textile industry include spinners, weavers, dyers, and machine operators; they come from many parts of the country.\",\"Textile factories have changed from handloom to powerloom and now to computer‑controlled machines.\",\"Clothes made from natural fibres are usually more breathable and comfortable in hot weather.\",\"Synthetic fibres are strong, wrinkle‑free and easy to wash, but may not be breathable in hot weather.\",\"The choice of clothes should match the climate, activity and the person’s body size.\",\"Traditional clothes of a region reflect its climate, culture and available natural resources.\"]','[{\"q\":\"Which of the following is NOT a reason people want clothes that they do not need?\",\"options\":[\"Desire\",\"Advertising influence\",\"Need for protection\",\"Greed\"],\"answer\":2,\"explain\":\"People want clothes for protection, not for desire or greed.\"},{\"q\":\"What is the main purpose of clothes in different climates?\",\"options\":[\"Fashion\",\"Decoration\",\"Protection from weather\",\"Advertising\"],\"answer\":2,\"explain\":\"Clothes protect us from weather conditions.\"},{\"q\":\"Which activity asks students to write the total number of clothes they have?\",\"options\":[\"Can you tell?\",\"Observe the pictures\",\"Write the total number of clothes\",\"Choose the clothes\"],\"answer\":2,\"explain\":\"The activity instructs to write the total number of clothes.\"},{\"q\":\"In the chapter, what is a common source of raw material for fabric?\",\"options\":[\"Cotton\",\"Plastic\",\"Steel\",\"Glass\"],\"answer\":0,\"explain\":\"Cotton is a common raw material for fabric.\"},{\"q\":\"Which season is mentioned as the main time for using certain textiles?\",\"options\":[\"Winter\",\"Summer\",\"Monsoon\",\"All seasons\"],\"answer\":3,\"explain\":\"Textiles are used in all seasons.\"},{\"q\":\"What does the chapter suggest about advertising and clothes?\",\"options\":[\"It helps people buy necessary clothes\",\"It creates desire for unnecessary clothes\",\"It reduces the need for clothes\",\"It is irrelevant\"],\"answer\":1,\"explain\":\"Advertising can create desire for unnecessary clothes.\"},{\"q\":\"Which of the following is NOT a type of traditional saree mentioned?\",\"options\":[\"Patola\",\"Kanjivaram\",\"Chikan\",\"Tartan\"],\"answer\":3,\"explain\":\"Tartan is not listed among the traditional sarees.\"},{\"q\":\"What is the main reason Mumbai became a textile hub?\",\"options\":[\"Cool climate\",\"Proximity to sea\",\"High humidity\",\"Low cost labor\"],\"answer\":2,\"explain\":\"Mumbai’s humid weather facilitated cloth production.\"},{\"q\":\"Which question asks students to consider lending clothes to friends?\",\"options\":[\"Do you think you should have other clothes?\",\"Will you lend your clothes to your friends?\",\"How many times do you change clothes?\",\"What do you wear to functions?\"],\"answer\":1,\"explain\":\"The question explicitly asks about lending clothes.\"},{\"q\":\"Which activity involves visiting a local Khadi Gramodyog centre?\",\"options\":[\"Visit a fabric\\/garments exhibition\",\"Make a note of clothes to wear on a traditional day\",\"Visit your local Khadi Gramodyog centre\",\"Observe the pictures\"],\"answer\":2,\"explain\":\"The activity mentions visiting a Khadi Gramodyog centre.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16775,23,5,'EVS Part 1','en','The Environment and Us','[\"Forests are large groups of trees that give homes to many animals and plants.\",\"Trees absorb carbon dioxide and give out oxygen – they help keep the air clean.\",\"When forests are cut down (deforestation) the soil becomes loose and can wash away, causing floods.\",\"Water in rivers and lakes can become dirty if factories dump waste water into them – this is water pollution.\",\"Air pollution happens when factories, cars and power plants release smoke and gases into the air.\",\"Animals that live in forests need trees for food, shelter and protection; if trees disappear they may die or move away.\",\"Plants and animals are called biodiversity; it means many different kinds of living things in one place.\",\"If biodiversity is lost, the whole food chain can break and some animals may become extinct.\",\"Recycling and using less energy can help keep the environment healthy.\",\"India has special places called national parks, wildlife sanctuays and biodiversity parks to protect animals and plants.\"]','[{\"q\":\"What happens to the soil when forests are cut down?\",\"options\":[\"It becomes richer\",\"It becomes loose and can wash away\",\"It turns into sand\",\"It stays the same\"],\"answer\":1,\"explain\":\"Without tree roots, soil loses structure and can be washed away by rain.\"},{\"q\":\"Which gas is released when we burn fuels like petrol and diesel?\",\"options\":[\"Oxygen\",\"Nitrogen\",\"Carbon dioxide\",\"Helium\"],\"answer\":2,\"explain\":\"Combustion of fuels produces carbon dioxide.\"},{\"q\":\"What is the main reason for water pollution in rivers near factories?\",\"options\":[\"Natural springs\",\"Rainfall\",\"Factories dumping waste water\",\"Fish waste\"],\"answer\":2,\"explain\":\"Factories often release untreated waste water into rivers.\"},{\"q\":\"Which of the following is NOT a cause of air pollution?\",\"options\":[\"Car exhaust\",\"Industrial smoke\",\"Tree planting\",\"Burning of fuels\"],\"answer\":2,\"explain\":\"Planting trees helps clean the air, not pollute it.\"},{\"q\":\"What is a biodiversity park?\",\"options\":[\"A park with only one type of tree\",\"A park that protects many kinds of plants and animals\",\"A park for sports\",\"A park for cars\"],\"answer\":1,\"explain\":\"It is a protected area where many species live.\"},{\"q\":\"Which of these animals is likely to move away if forests disappear?\",\"options\":[\"Fish\",\"Birds\",\"Monkeys\",\"All of the above\"],\"answer\":3,\"explain\":\"All listed animals depend on forests for shelter.\"},{\"q\":\"What does recycling help to reduce?\",\"options\":[\"Noise\",\"Water pollution\",\"Air pollution\",\"All of the above\"],\"answer\":3,\"explain\":\"Recycling reduces waste that can cause pollution.\"},{\"q\":\"Which of the following is a natural component of the environment?\",\"options\":[\"Plastic bottle\",\"River water\",\"Car exhaust\",\"Factory smoke\"],\"answer\":1,\"explain\":\"River water is a natural, not man‑made, component.\"},{\"q\":\"What is migration?\",\"options\":[\"Moving to a new house\",\"Moving from one place to another for food or shelter\",\"Eating food\",\"Sleeping\"],\"answer\":1,\"explain\":\"Migration is when animals move to find better conditions.\"},{\"q\":\"Which action helps protect the environment?\",\"options\":[\"Cutting more trees\",\"Burning more fuel\",\"Planting trees\",\"Using more plastic\"],\"answer\":2,\"explain\":\"Planting trees helps restore forest cover.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16776,23,5,'EVS Part 1','en','Constituents of Food','[\"- Food is a substance that gives us energy and helps us grow.\",\"- The main parts of food are carbohydrates, proteins, fats, vitamins and minerals.\",\"- Carbohydrates are found in rice, wheat, potatoes and give energy.\",\"- Proteins are found in pulses, milk, eggs and help build and repair body tissues.\",\"- Fats are found in oil, butter, nuts and give extra energy and protect organs.\",\"- Vitamins are small amounts of substances (A, B, C, D, E, K) that keep us healthy.\",\"- Minerals are tiny elements (iron, calcium, sodium, potassium) needed for many body functions.\",\"- Fibre is a type of carbohydrate that is not digested and helps food move through the gut.\",\"- A balanced diet contains all these parts in the right amounts.\",\"- If we miss any part for a long time we may become malnourished or develop diseases.\",\"- Eating fruits with skins, whole grains and pulses gives us fibre and micronutrients.\",\"- Milk is given to children daily because it supplies protein, calcium and vitamins.\"]','[{\"q\":\"Which food gives us the most energy?\",\"options\":[\"Fruits\",\"Carbohydrates\",\"Fats\",\"Vitamins\"],\"answer\":2,\"explain\":\"Fats give the most energy per gram.\"},{\"q\":\"What is the main function of fibre in food?\",\"options\":[\"Give energy\",\"Build muscles\",\"Help food move through the gut\",\"Make food sweet\"],\"answer\":2,\"explain\":\"Fibre helps food move through the digestive system.\"},{\"q\":\"Which vitamin is important for good vision?\",\"options\":[\"Vitamin A\",\"Vitamin B\",\"Vitamin C\",\"Vitamin D\"],\"answer\":0,\"explain\":\"Vitamin A prevents night blindness.\"},{\"q\":\"What does a balanced diet contain?\",\"options\":[\"Only carbohydrates\",\"Only proteins\",\"Only fats\",\"All nutrients in right amounts\"],\"answer\":3,\"explain\":\"Balanced diet has all nutrients.\"},{\"q\":\"Which food is a good source of protein?\",\"options\":[\"Rice\",\"Milk\",\"Potato\",\"Bread\"],\"answer\":1,\"explain\":\"Milk contains protein.\"},{\"q\":\"What are micronutrients?\",\"options\":[\"Large amounts of food\",\"Small amounts of vitamins and minerals\",\"Only fats\",\"Only carbohydrates\"],\"answer\":1,\"explain\":\"Micronutrients are vitamins and minerals needed in small amounts.\"},{\"q\":\"Which of these is NOT a carbohydrate?\",\"options\":[\"Starch\",\"Sugar\",\"Fibre\",\"Protein\"],\"answer\":3,\"explain\":\"Protein is not a carbohydrate.\"},{\"q\":\"Why do we need fats in our diet?\",\"options\":[\"They give energy\",\"They make food sweet\",\"They are a type of vitamin\",\"They are a type of mineral\"],\"answer\":0,\"explain\":\"Fats give energy and protect organs.\"},{\"q\":\"What is malnutrition?\",\"options\":[\"Eating too many foods\",\"Eating only one type of food for a long time\",\"Eating too little food\",\"All of the above\"],\"answer\":1,\"explain\":\"Malnutrition is not getting all nutrients for a long time.\"},{\"q\":\"Which part of the body stores excess energy?\",\"options\":[\"Stomach\",\"Liver\",\"Brain\",\"Heart\"],\"answer\":1,\"explain\":\"The liver stores excess energy as fat.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16777,23,5,'EVS Part 1','en','Our Emotional World','[\"- Emotions are feelings that arise when something happens to us.\",\"- Coping with emotions means understanding them and not letting them control us.\",\"- Anger is a natural emotion but should be expressed calmly.\",\"- Sadness, joy, fear, jealousy, and disappointment are all normal emotions.\",\"- A balanced personality has good and bad traits; we should know both.\",\"- Knowing our flaws helps us improve and become kinder.\",\"- When we feel angry, we can pause, breathe, and think before reacting.\",\"- We should not blame others for our feelings; we take responsibility.\",\"- Expressing emotions in a reasonable way helps others understand us.\",\"- A good attitude includes cooperation, listening, and respect.\",\"- Being self‑aware helps us notice when we are too harsh or too kind.\",\"- We can change bad habits by practicing better behaviour.\",\"- A positive mindset encourages learning and growth.\",\"- Respecting others’ feelings builds strong friendships and teamwork.\",\"- Avoiding greed and jealousy leads to happier relationships.\"]','[{\"q\":\"Which emotion is described as a natural response when something does not go as we wish?\",\"options\":[\"Anger\",\"Joy\",\"Fear\",\"Sadness\"],\"answer\":0,\"explain\":\"Anger is the emotion that arises when things are not as desired.\"},{\"q\":\"What is the first step in coping with anger?\",\"options\":[\"Yelling at the person\",\"Taking a deep breath\",\"Running away\",\"Saying sorry\"],\"answer\":1,\"explain\":\"Taking a deep breath helps calm the mind before reacting.\"},{\"q\":\"A balanced personality includes which of the following?\",\"options\":[\"Only good traits\",\"Only bad traits\",\"Both good and bad traits\",\"Neither good nor bad traits\"],\"answer\":2,\"explain\":\"A balanced personality has both strengths and weaknesses.\"},{\"q\":\"What should you do if you feel jealous of a friend’s success?\",\"options\":[\"Ignore it\",\"Tell them you are jealous\",\"Talk to them about it\",\"Blame them\"],\"answer\":2,\"explain\":\"Talking helps you understand and manage jealousy.\"},{\"q\":\"Which action shows cooperation?\",\"options\":[\"Refusing to help\",\"Listening to a friend\",\"Ignoring a problem\",\"Being stubborn\"],\"answer\":1,\"explain\":\"Listening and helping are signs of cooperation.\"},{\"q\":\"When should you express anger?\",\"options\":[\"When you are calm\",\"When you are upset\",\"When you are happy\",\"When you are tired\"],\"answer\":1,\"explain\":\"Anger should be expressed when you are upset, but calmly.\"},{\"q\":\"What is a harmful effect of uncontrolled anger?\",\"options\":[\"Better focus\",\"Increased confidence\",\"Headaches\",\"More friends\"],\"answer\":2,\"explain\":\"Uncontrolled anger can cause headaches and other health issues.\"},{\"q\":\"Which of these is a positive trait?\",\"options\":[\"Being mean\",\"Being generous\",\"Being angry all the time\",\"Being jealous\"],\"answer\":1,\"explain\":\"Generosity is a positive trait.\"},{\"q\":\"What does coping with emotions help you avoid?\",\"options\":[\"Learning new skills\",\"Feeling sad\",\"Being misunderstood\",\"Getting into trouble\"],\"answer\":3,\"explain\":\"Coping helps avoid misunderstandings and trouble.\"},{\"q\":\"If you know your flaw is being too talkative, what can you do?\",\"options\":[\"Talk more\",\"Listen more\",\"Ignore it\",\"Blame others\"],\"answer\":1,\"explain\":\"Listening more helps balance a talkative habit.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16778,23,5,'EVS Part 1','en','Busy at Work – our Internal Organs','[\"Respiration is the process of breathing in oxygen and breathing out carbon dioxide.\",\"The lungs are the main organs of respiration and are protected by the ribs.\",\"The trachea (windpipe) carries air from the nose to the lungs.\",\"The diaphragm is a muscle that moves up and down to help us breathe.\",\"Air enters the lungs through the alveoli where oxygen and carbon dioxide are exchanged with blood.\",\"Smoking introduces harmful particles that damage the lungs and can cause lung cancer.\",\"The alimentary canal is a long tube from the mouth to the anus that digests food.\",\"The stomach churns food into a moist mass called a bolus.\",\"The small intestine absorbs most of the nutrients and water from food.\",\"The large intestine absorbs remaining water and forms faeces.\",\"Saliva contains enzymes that start digestion in the mouth and helps swallow food.\",\"The heart pumps blood through the circulatory system, keeping oxygen and nutrients flowing.\",\"The nervous system coordinates all body functions by sending signals through nerves.\",\"The brain is the control centre of the nervous system.\",\"The circulatory system includes the heart and blood vessels.\",\"The respiratory, digestive, circulatory and nervous systems work together for life.\",\"If one organ fails, the whole system can be affected.\",\"Healthy habits like not smoking and eating slowly keep these systems working well.\"]','[{\"q\":\"Which organ is the main site where oxygen enters the blood?\",\"options\":[\"Heart\",\"Lungs\",\"Stomach\",\"Brain\"],\"answer\":1,\"explain\":\"Oxygen enters the blood in the alveoli of the lungs.\"},{\"q\":\"What is the function of the diaphragm?\",\"options\":[\"It pumps blood\",\"It moves the nose\",\"It helps us breathe\",\"It digests food\"],\"answer\":2,\"explain\":\"The diaphragm moves up and down to allow air in and out of the lungs.\"},{\"q\":\"What does saliva do in the mouth?\",\"options\":[\"It makes the mouth hot\",\"It starts digestion\",\"It cleans the teeth only\",\"It keeps the mouth dry\"],\"answer\":1,\"explain\":\"Saliva contains enzymes that begin the digestion of food.\"},{\"q\":\"Which system carries messages between the brain and body parts?\",\"options\":[\"Digestive\",\"Circulatory\",\"Nervous\",\"Respiratory\"],\"answer\":2,\"explain\":\"The nervous system uses nerves to send signals.\"},{\"q\":\"What happens to the air after it passes through the alveoli?\",\"options\":[\"It becomes water\",\"It is stored in the lungs\",\"It is exchanged for blood gases\",\"It turns into food\"],\"answer\":2,\"explain\":\"Oxygen enters the blood and carbon dioxide leaves.\"},{\"q\":\"Why is smoking harmful to the lungs?\",\"options\":[\"It makes them bigger\",\"It removes oxygen\",\"It adds harmful particles\",\"It cleans them\"],\"answer\":2,\"explain\":\"Smoke contains toxins that damage lung tissue.\"},{\"q\":\"What is the main function of the small intestine?\",\"options\":[\"Make food taste sweet\",\"Store food\",\"Absorb nutrients\",\"Produce saliva\"],\"answer\":2,\"explain\":\"It absorbs most nutrients and water.\"},{\"q\":\"Which organ helps keep the blood moving?\",\"options\":[\"Liver\",\"Heart\",\"Stomach\",\"Brain\"],\"answer\":1,\"explain\":\"The heart pumps blood through vessels.\"},{\"q\":\"What is the term for the long tube that digests food?\",\"options\":[\"Alimentary canal\",\"Respiratory tube\",\"Nervous cord\",\"Circulatory tube\"],\"answer\":0,\"explain\":\"The alimentary canal runs from mouth to anus.\"},{\"q\":\"What is the role of the nervous system?\",\"options\":[\"Digest food\",\"Pump blood\",\"Coordinate body functions\",\"Breathe\"],\"answer\":2,\"explain\":\"It coordinates all bodily functions via nerves.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16779,23,5,'EVS Part 1','en','Growth and Personality Development','[\"Growth is the increase in height and weight from birth to adulthood.\",\"Physical growth stops around 18 years old for both boys and girls.\",\"Development means learning new skills and becoming more efficient.\",\"Infants start by crying, then learn to turn their head and smile.\",\"Around 1 year they can feed themselves and hold objects.\",\"By 2 years they can walk, run, and pick up small items.\",\"Children develop coordination between different movements as they grow.\",\"Learning a skill is called acquiring a new ability.\",\"Practice makes a skill easier and reduces mistakes.\",\"Malnutrition can stop a child from growing tall.\",\"Good food, exercise, and positive thoughts help growth.\",\"Heredity is the passing of traits from parents to children.\",\"Children become independent when they can do tasks alone.\",\"The more skills we learn, the less we depend on others.\",\"Each person has a unique personality shaped by genetics and learning.\"]','[{\"q\":\"When does physical growth usually stop?\",\"options\":[\"At 12 years\",\"At 18 years\",\"At 21 years\",\"At 25 years\"],\"answer\":1,\"explain\":\"Growth stops around 18 years old.\"},{\"q\":\"Which skill does a 1‑year‑old start to learn?\",\"options\":[\"Running\",\"Sitting up\",\"Holding a spoon\",\"Reading\"],\"answer\":2,\"explain\":\"At about 1 year, children can hold a spoon and feed themselves.\"},{\"q\":\"What does heredity mean?\",\"options\":[\"Learning from parents\",\"Inherited traits\",\"Choosing a job\",\"Eating healthy\"],\"answer\":1,\"explain\":\"Heredity is the passing of traits from parents to children.\"},{\"q\":\"Which activity helps physical growth?\",\"options\":[\"Skipping rope\",\"Watching TV\",\"Sleeping\",\"Reading\"],\"answer\":0,\"explain\":\"Skipping rope is a physical activity that supports growth.\"},{\"q\":\"Malnutrition affects growth by:\",\"options\":[\"Increasing height\",\"Improving coordination\",\"Reducing height\",\"Enhancing memory\"],\"answer\":2,\"explain\":\"Malnutrition reduces a child\'s height.\"},{\"q\":\"At what age do children usually start walking?\",\"options\":[\"6 months\",\"1 year\",\"2 years\",\"3 years\"],\"answer\":1,\"explain\":\"Most children start walking around 1 year.\"},{\"q\":\"Which of these is NOT a skill learned early?\",\"options\":[\"Singing\",\"Running\",\"Picking up objects\",\"Talking\"],\"answer\":0,\"explain\":\"Singing is usually learned later.\"},{\"q\":\"What is the main benefit of learning many skills?\",\"options\":[\"More friends\",\"Less dependence\",\"Higher salary\",\"More toys\"],\"answer\":1,\"explain\":\"Learning many skills reduces dependence on others.\"},{\"q\":\"Which factor does NOT help growth?\",\"options\":[\"Good diet\",\"Exercise\",\"Negative thoughts\",\"Adequate sleep\"],\"answer\":2,\"explain\":\"Negative thoughts do not help growth.\"},{\"q\":\"What does the story of the industrialist illustrate?\",\"options\":[\"Hard work pays off\",\"Inheritance of traits\",\"Choosing a career\",\"Eating healthy\"],\"answer\":0,\"explain\":\"It shows that hard work and good decisions lead to success.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16780,23,5,'EVS Part 1','en','Infectious Diseases and how to Prevent them','[\"Infectious diseases are illnesses caused by tiny living things called micro‑organisms or germs.\",\"Each disease has a specific germ that causes it – e.g., flu germs, typhoid germs, malaria parasites.\",\"Germs can spread in four main ways: through the air, through water, through food, and by insect bites.\",\"Air spread happens when a sick person coughs or sneezes and tiny droplets fall into the air. Others breathe them in.\",\"Water spread occurs when germs from a sick person’s faeces get into rivers, wells or drinking water. Drinking or bathing in that water can make you sick.\",\"Food spread happens when contaminated food is eaten – germs can stick to hands, utensils or flies that land on food.\",\"Insects such as mosquitoes and flies can carry germs from one person to another or to food. Mosquito bites can spread malaria.\",\"Direct contact spread happens when you touch the skin or clothes of a sick person with skin diseases like ringworm or scabies.\",\"Preventing spread means keeping your mouth covered when you cough, washing hands, covering food, avoiding stagnant water, and keeping insects away.\",\"Covering food stops flies and dust from touching it, reducing food poisoning.\",\"Cleaning water with bleach or boiling it kills germs and makes it safe to drink.\",\"Mosquito breeding sites are puddles or standing water; removing them stops malaria.\",\"People with serious infections are isolated in special hospital wards to protect others.\",\"Vaccination trains the body’s immune system to fight a specific germ, so you don’t get the disease when exposed.\",\"Vaccines for diphtheria, whooping cough, tetanus and polio are given to children at regular ages.\",\"Public health programmes, like clean water supply and vaccination drives, help stop epidemics.\",\"An epidemic is when many people in the same area get the same disease at the same time.\",\"Micro‑organisms are tiny living things that can be bacteria, viruses or parasites.\",\"Germs are also called microbes or pathogens.\",\"Good hygiene, clean water, and vaccination are the best ways to keep a community healthy.\",\"If you feel sick, stay home and tell a teacher or parent so you don’t spread germs to classmates.\",\"Cover your mouth with a tissue or your elbow when you cough or sneeze.\",\"Wash hands with soap for at least 20 seconds after using the toilet or before eating.\",\"Avoid sharing clothes, towels or utensils with someone who is ill.\",\"If you see a mosquito breeding site, throw away the water or cover it so mosquitoes cannot lay eggs.\"]','[{\"q\":\"Which of the following is NOT a way germs spread?\",\"options\":[\"Through the air\",\"Through water\",\"By eating a rainbow\",\"By insect bites\"],\"answer\":2,\"explain\":\"Eating a rainbow is not a mode of germ spread.\"},{\"q\":\"What should you do if you cough?\",\"options\":[\"Cover your mouth with a tissue\",\"Throw your tissue on the floor\",\"Cover your mouth with your hand\",\"Ignore it\"],\"answer\":0,\"explain\":\"Covering the mouth stops droplets from spreading.\"},{\"q\":\"Why is boiling water important?\",\"options\":[\"It tastes better\",\"It kills germs\",\"It makes water cold\",\"It removes colour\"],\"answer\":1,\"explain\":\"Boiling kills germs that cause water‑borne diseases.\"},{\"q\":\"Which insect spreads malaria?\",\"options\":[\"Fly\",\"Mosquito\",\"Ant\",\"Bee\"],\"answer\":1,\"explain\":\"Mosquitoes carry malaria parasites.\"},{\"q\":\"What is an epidemic?\",\"options\":[\"A single case of disease\",\"A disease that spreads through food\",\"Many people in the same area get the same disease at the same time\",\"A disease that only affects animals\"],\"answer\":2,\"explain\":\"An epidemic means many people get the same disease together.\"},{\"q\":\"Which disease is spread by touching the skin of a sick person?\",\"options\":[\"Ringworm\",\"Chickenpox\",\"Typhoid\",\"Malaria\"],\"answer\":0,\"explain\":\"Ringworm spreads by direct skin contact.\"},{\"q\":\"What should you do if you see a puddle of water?\",\"options\":[\"Leave it\",\"Cover it or remove it\",\"Add salt\",\"Use it for washing\"],\"answer\":1,\"explain\":\"Covering or removing stagnant water stops mosquito breeding.\"},{\"q\":\"Which vaccine is given orally?\",\"options\":[\"Diphtheria\",\"Polio\",\"Tetanus\",\"All of the above\"],\"answer\":1,\"explain\":\"The polio vaccine is given by mouth.\"},{\"q\":\"Why should you keep food covered?\",\"options\":[\"It keeps it warm\",\"It stops flies and dust from touching it\",\"It makes it taste better\",\"It keeps the food dry\"],\"answer\":1,\"explain\":\"Covering food prevents insects and dust from contaminating it.\"},{\"q\":\"What is the main purpose of vaccination?\",\"options\":[\"To make you immune to a specific germ\",\"To give you a cure for all diseases\",\"To make you sick\",\"To stop you from eating food\"],\"answer\":0,\"explain\":\"Vaccination trains the immune system to fight a particular germ.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16781,23,5,'EVS Part 1','en','Substances, Objects and Energy','[\"All matter is made of tiny particles called atoms or molecules.\",\"Substances can be in three states: solid, liquid, gas.\",\"In a solid the particles are close together and vibrate in fixed positions.\",\"In a liquid the particles are close but can slide past each other.\",\"In a gas the particles are far apart and move freely.\",\"When we write with chalk, tiny chalk particles stick to the board and come off when we wipe it.\",\"Pounding or grinding turns a solid into a powder, which is many small particles.\",\"Naphthalene balls release tiny particles that settle on clothes, making them smell of naphthalene.\",\"Energy is the ability to do work. It can be stored in fuels like petrol, coal, or produced by sunlight, wind, or water.\",\"When a fuel burns, chemical energy is released as heat, which can be converted into motion (kinetic energy).\",\"The Sun, wind, and water are non‑exhaustible sources of energy.\",\"Kinetic energy is the energy of motion; potential energy is stored energy.\",\"Substances differ in properties such as hardness, colour, smell, and solubility.\",\"Objects are made from substances and have definite shape and size.\",\"The same substance can be used to make different objects (e.g., clay can make pots, bricks, statues).\"]','[{\"q\":\"Which state of matter has particles that are far apart and move freely?\",\"options\":[\"Solid\",\"Liquid\",\"Gas\",\"Plasma\"],\"answer\":2,\"explain\":\"In a gas the particles are far apart and move freely.\"},{\"q\":\"What happens to chalk particles when you wipe the board?\",\"options\":[\"They stick to the board\",\"They become invisible\",\"They fall off\",\"They change colour\"],\"answer\":2,\"explain\":\"The chalk particles fall off the board when it is wiped.\"},{\"q\":\"When a fuel like petrol burns, what form of energy is released?\",\"options\":[\"Light energy\",\"Sound energy\",\"Heat energy\",\"Electric energy\"],\"answer\":2,\"explain\":\"Burning fuel releases energy in the form of heat.\"},{\"q\":\"Which of the following is NOT a non‑exhaustible source of energy?\",\"options\":[\"Sunlight\",\"Wind\",\"Water\",\"Coal\"],\"answer\":3,\"explain\":\"Coal is a fossil fuel and is exhaustible.\"},{\"q\":\"What is the term for the energy of motion?\",\"options\":[\"Potential energy\",\"Kinetic energy\",\"Thermal energy\",\"Chemical energy\"],\"answer\":1,\"explain\":\"Kinetic energy is the energy of motion.\"},{\"q\":\"When you grind a piece of sugar, what do you get?\",\"options\":[\"A liquid\",\"A gas\",\"A powder\",\"A solid block\"],\"answer\":2,\"explain\":\"Grinding turns a solid into a powder.\"},{\"q\":\"Which of these is a substance that can be found in solid, liquid, and gas states?\",\"options\":[\"Water\",\"Wood\",\"Coal\",\"Gold\"],\"answer\":0,\"explain\":\"Water exists as ice, liquid, and vapor.\"},{\"q\":\"What does the Sun produce that can be used to make electricity?\",\"options\":[\"Heat only\",\"Light only\",\"Both light and heat\",\"Neither\"],\"answer\":2,\"explain\":\"The Sun provides both light and heat, which can be used to generate electricity.\"},{\"q\":\"Why do clothes smell of naphthalene after being stored with naphthalene balls?\",\"options\":[\"The balls absorb the smell\",\"The balls release tiny particles that settle on clothes\",\"The clothes are made of naphthalene\",\"The balls dissolve in the clothes\"],\"answer\":1,\"explain\":\"Naphthalene balls release tiny particles that settle on clothes, giving them the smell.\"},{\"q\":\"What is the main source of energy for a thermal power station?\",\"options\":[\"Solar energy\",\"Wind energy\",\"Coal or other fuels\",\"Water\"],\"answer\":2,\"explain\":\"Thermal power stations burn fuels like coal to produce heat and generate electricity.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16782,23,5,'EVS Part 1','en','Community Health and Hygiene','[\"Community health means protecting the health of all people in a community.\",\"Good personal hygiene includes washing hands, brushing teeth and keeping clothes clean.\",\"Nutritious food gives energy and strengthens the body.\",\"Exercise and hobbies keep the mind and body active and happy.\",\"Clean surroundings reduce chances of disease spread.\",\"Spitting, littering and using old tyres can spread infections.\",\"Safe drinking water and proper sanitation are essential for health.\",\"Tobacco, alcohol and drugs are harmful habits that can lead to disease.\",\"Addiction to tobacco causes mouth ulcers, cancers and other health problems.\",\"Addiction to alcohol damages the liver, intestines and urinary bladder.\",\"A wholesome life is achieved by good habits, avoiding bad habits and caring for health.\",\"Community health is as important as personal health because a healthy community supports everyone.\",\"Public toilets and clean roads help keep the community disease‑free.\",\"Spitting in public places is a legal offence to prevent disease spread.\",\"Good habits include informing family of your whereabouts, telling the truth and saying “No!” firmly.\",\"Bad habits include chewing tobacco, smoking, biting nails and fiddling with objects.\",\"Avoiding bad habits helps maintain personal and community health.\"]','[{\"q\":\"Which of the following is NOT a threat to community health?\",\"options\":[\"Pollution\",\"Spitting in public places\",\"Eating nutritious food\",\"Epidemics\"],\"answer\":2,\"explain\":\"Eating nutritious food improves health, not threatens it.\"},{\"q\":\"What is a legal offence mentioned to prevent disease spread?\",\"options\":[\"Using old tyres\",\"Spitting in public places\",\"Littering on roads\",\"Eating street food\"],\"answer\":1,\"explain\":\"Spitting in public places is banned to stop disease spread.\"},{\"q\":\"Which habit can cause mouth ulcers and cancer?\",\"options\":[\"Regular exercise\",\"Chewing tobacco\",\"Eating fruits\",\"Brushing teeth\"],\"answer\":1,\"explain\":\"Chewing tobacco causes ulcers and cancer.\"},{\"q\":\"What does safe drinking water help with?\",\"options\":[\"Increasing appetite\",\"Preventing infections\",\"Improving eyesight\",\"Reducing sleep\"],\"answer\":1,\"explain\":\"Safe water prevents infections.\"},{\"q\":\"Which is a harmful addiction mentioned?\",\"options\":[\"Reading books\",\"Playing sports\",\"Alcoholism\",\"Gardening\"],\"answer\":2,\"explain\":\"Alcoholism is an addiction that harms health.\"},{\"q\":\"What is a benefit of exercising?\",\"options\":[\"Causes fatigue\",\"Improves mental health\",\"Increases disease risk\",\"Reduces appetite\"],\"answer\":1,\"explain\":\"Exercise improves mental health.\"},{\"q\":\"Which is a good habit for community health?\",\"options\":[\"Fiddling with a pencil\",\"Telling the truth\",\"Spitting on the road\",\"Using old tyres\"],\"answer\":1,\"explain\":\"Telling the truth is a good habit.\"},{\"q\":\"What is the main cause of liver damage in alcoholics?\",\"options\":[\"High sugar diet\",\"Lack of sleep\",\"Alcohol consumption\",\"Exercise\"],\"answer\":2,\"explain\":\"Alcohol consumption damages the liver.\"},{\"q\":\"Which action helps keep surroundings clean?\",\"options\":[\"Throwing garbage on the road\",\"Using public toilets\",\"Spitting in public places\",\"Using old tyres\"],\"answer\":1,\"explain\":\"Using public toilets keeps surroundings clean.\"},{\"q\":\"What is the effect of addiction to tobacco on the digestive organs?\",\"options\":[\"Improves digestion\",\"Causes cancer\",\"Reduces appetite\",\"Increases energy\"],\"answer\":1,\"explain\":\"Tobacco addiction can cause cancers in digestive organs.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16783,24,5,'EVS Part 1','mr','आपली पृथ्वी - आपली सूर्यमाला','[\"सूर्य हा एक तारा आहे आणि तो पृथ्वीच्या जवळ आहे त्यामुळे तो मोठा दिसतो.\",\"चंद्र हा पृथ्वीचा उपग्रह आहे आणि तो स्वतःभोवती फिरतो.\",\"तारे हे स्वतः प्रकाश देणारे खगोलीय वस्तू आहेत, त्यांचा प्रकाश लुकलुकतो.\",\"ग्रहांना स्वतःचा प्रकाश नसतो, ते सूर्याचा प्रकाश परावर्तित करतात.\",\"सूर्यमालेत आठ ग्रह आहेत: बुध, शुक्र, पृथ्वी, मंगळ, गुरु, शनि, युरेनस, नेपच्यून.\",\"सूर्यमालेत उपग्रह, लघुग्रह, बटुग्रह आणि इतर लहान वस्तूही आहेत.\",\"बटुग्रह म्हणजे सूर्याभोवती फिरणारे लहान तारे, उदाहरणार्थ प्लुटो.\",\"लघुग्रह पट्टा म्हणजे मंगळ व गुरु यांच्या दरम्यान असलेल्या असंख्य लहान खगोलीय वस्तूंचा पट्टा.\",\"उपग्रह म्हणजे ग्रहाभोवती फिरणाऱ्या लहान वस्तू, उदाहरणार्थ चंद्र.\",\"पृथ्वी व सूर्य यांच्यामधील ग्रह बुध आहे.\",\"मंगळ ग्रहाच्या बाहेर असणारे ग्रह गुरु, शनि, युरेनस आणि नेपच्यून आहेत.\",\"सूर्याच्या सर्वात जवळचा ग्रह बुध आहे.\",\"सूर्यापासून सर्वात दूरचा ग्रह नेपच्यून आहे.\",\"सूर्यमालेतील ग्रहांची क्रमवारी सूर्यापासून बाहेरच्या बाजूने: बुध, शुक्र, पृथ्वी, मंगळ, गुरु, शनि, युरेनस, नेपच्यून.\",\"गुरुत्वाकर्षणामुळे सर्व वस्तू पृथ्वीवरच राहतात आणि अवकाशात जाण्यासाठी रॉकेटचा वापर होतो.\",\"रॉकेटद्वारे अवकाशात जाण्यासाठी इंधन जाळून शक्ती निर्माण होते.\",\"कृत्रिम उपग्रह पृथ्वीभोवती फिरून हवामान अंदाज, नकाशे तयार करणे, संदेशवहन यांसारखी कामे करतात.\",\"अवकाश प्रक्षेपण तंत्रज्ञानाने भारताने चंद्रयान, मंगलयान यांसारखी यशस्वी मोहिमा केल्या आहेत.\",\"अवकाशात जाण्यासाठी गुरुत्वाकर्षणाच्या विरुद्ध शक्तीची गरज असते.\"]','[{\"q\":\"सूर्य हा कोणत्या प्रकारचा खगोलीय वस्तू आहे?\",\"options\":[\"तारा\",\"ग्रह\",\"उपग्रह\",\"लघुग्रह\"],\"answer\":0,\"explain\":\"सूर्य एक तारा आहे.\"},{\"q\":\"पृथ्वीभोवती फिरणाऱ्या लहान वस्तूला काय म्हणतात?\",\"options\":[\"उपग्रह\",\"ग्रह\",\"तारा\",\"लघुग्रह\"],\"answer\":0,\"explain\":\"उपग्रह म्हणजे पृथ्वीभोवती फिरणारी लहान वस्तू.\"},{\"q\":\"खगोलीय वस्तूंचे प्रकाश स्वतःच्या प्रकाशावर अवलंबून असते, त्यांना काय म्हणतात?\",\"options\":[\"तारे\",\"ग्रह\",\"उपग्रह\",\"लघुग्रह\"],\"answer\":0,\"explain\":\"स्वयंप्रकाशित वस्तू तारे आहेत.\"},{\"q\":\"सूर्यमालेतील सर्वात दूरचा ग्रह कोणता आहे?\",\"options\":[\"नेपच्यून\",\"शनि\",\"युरेनस\",\"मंगळ\"],\"answer\":0,\"explain\":\"नेपच्यून सूर्यापासून सर्वात दूर आहे.\"},{\"q\":\"ग्रहांना प्रकाश कोणाकडून मिळतो?\",\"options\":[\"सूर्य\",\"चंद्र\",\"तारे\",\"उपग्रह\"],\"answer\":0,\"explain\":\"ग्रहांना सूर्याचा प्रकाश मिळतो.\"},{\"q\":\"लघुग्रह पट्टा कोणत्या ग्रहांच्या दरम्यान आहे?\",\"options\":[\"मंगळ व गुरू\",\"बुध व शुक्र\",\"शनि व युरेनस\",\"नेपच्यून व शनि\"],\"answer\":0,\"explain\":\"मंगळ व गुरू यांच्या दरम्यान लघुग्रह पट्टा आहे.\"},{\"q\":\"उपग्रहांना कोणत्या ग्रहाभोवती फिरतात?\",\"options\":[\"सर्व ग्रह\",\"फक्त पृथ्वी\",\"फक्त शनि\",\"फक्त गुरू\"],\"answer\":0,\"explain\":\"उपग्रह सर्व ग्रहांच्या भोवती फिरतात.\"},{\"q\":\"सूर्यमालेत किती ग्रह आहेत?\",\"options\":[\"7\",\"8\",\"9\",\"10\"],\"answer\":1,\"explain\":\"सूर्यमालेत 8 ग्रह आहेत (बुध, शुक्र, पृथ्वी, मंगळ, गुरु, शनि, युरेनस, नेपच्यून).\"},{\"q\":\"चंद्राच्या प्रकाशात बदल होतो, त्याला काय म्हणतात?\",\"options\":[\"चंद्रप्रकाश\",\"चंद्रचक्र\",\"चंद्रचक्रण\",\"चंद्रचक्र\"],\"answer\":2,\"explain\":\"चंद्राच्या प्रकाशित भागात होणारा बदल चंद्रचक्रण म्हणतात.\"},{\"q\":\"अवकाश प्रक्षेपणासाठी कोणते तंत्र वापरले जाते?\",\"options\":[\"रॉकेट तंत्र\",\"उपग्रह तंत्र\",\"लघुग्रह तंत्र\",\"सूर्य तंत्र\"],\"answer\":0,\"explain\":\"रॉकेट तंत्र अवकाश प्रक्षेपणासाठी वापरले जाते.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16784,24,5,'EVS Part 1','mr','पृथ्वीचे फिरणे','[\"पृथ्वी स्वतःभोवती फिरते याला परिबलन म्हणतात.\",\"पृथ्वी सूर्याभोवती फिरते याला परिभ्रमण म्हणतात.\",\"परिबलनाचा अक्ष म्हणजे पृथ्वीचा कललेला अक्ष.\",\"विषुववृत्त हे पृथ्वीच्या पृष्ठभागावरचे वर्तुळ आहे ज्याने पृथ्वी दोन गोलार्धात विभागली जाते.\",\"विषुववृत्तावरून पृथ्वीचे उत्तर गोलार्ध आणि दक्षिण गोलार्ध बनतात.\",\"पृथ्वीच्या परिबलनामुळे दिन व रात्र होते.\",\"एक परिबलन पूर्ण होण्यासाठी २४ तास लागतात, याला एक दिवस म्हणतात.\",\"पृथ्वीच्या परिभ्रमणामुळे वर्ष पूर्ण होण्यासाठी ३६५ दिवस ६ तास लागतात.\",\"चंद्र पृथ्वीभोवती फिरतो आणि त्याच्या प्रकाशाच्या अवस्थांना अमावस्या, पौर्णिमा, शुक्लपक्ष, कृष्णपक्ष असे म्हणतात.\",\"चंद्राच्या प्रकाशाच्या अवस्थांना एक चांद्रमास म्हणतात ज्यात २८-३० दिवस असतात.\",\"लीप वर्षात फेब्रुवारीला २९ दिवस असतात ज्यामुळे वर्ष ३६६ दिवसांचे होते.\",\"पृथ्वीचा अक्ष कललेला असल्यामुळे सूर्योदय, मध्यान्ह आणि सूर्यास्त वेगवेगळ्या वेळांना होतात.\",\"उष्णता आणि अंधाराचे वेळ पृथ्वीच्या गोलार्धानुसार बदलतात.\",\"पृथ्वीच्या परिबलनामुळे पृथ्वीच्या पृष्ठभागावर दिन व रात्र यांचा चक्र तयार होतो.\",\"चंद्राच्या प्रकाशाच्या अवस्थांमध्ये उत्तर गोलार्धात उन्हाळा आणि दक्षिण गोलार्धात हिवाळा असतो.\"]','[{\"q\":\"पृथ्वी स्वतःभोवती फिरण्याला काय म्हणतात?\",\"options\":[\"परिभ्रमण\",\"परिबलन\",\"विषुववृत्त\",\"अक्ष\"],\"answer\":1,\"explain\":\"परिबलन म्हणजे वस्तू स्वतःभोवती फिरणे.\"},{\"q\":\"पृथ्वीच्या परिभ्रमणामुळे वर्ष पूर्ण होण्यासाठी किती दिवस लागतात?\",\"options\":[\"२४ तास\",\"३६५ दिवस ६ तास\",\"१ तास\",\"७ दिवस\"],\"answer\":1,\"explain\":\"पृथ्वी सूर्याभोवती फिरण्यासाठी ३६५ दिवस ६ तास लागतात.\"},{\"q\":\"विषुववृत्त पृथ्वीला कोणत्या भागात विभागते?\",\"options\":[\"उत्तर व दक्षिण गोलार्ध\",\"पूर्व व पश्चिम गोलार्ध\",\"उत्तरी गोलार्ध व पॅसिफिक\",\"हिमालय व अटलांटिक\"],\"answer\":0,\"explain\":\"विषुववृत्त उत्तर व दक्षिण गोलार्धात विभागते.\"},{\"q\":\"चंद्राच्या प्रकाशाच्या अवस्थांमध्ये कोणती अवस्था सर्वात कमी प्रकाश देते?\",\"options\":[\"पौर्णिमा\",\"अमावस्या\",\"शुक्लपक्ष\",\"कृष्णपक्ष\"],\"answer\":1,\"explain\":\"अमावस्या वेळी चंद्रावर प्रकाश नसतो.\"},{\"q\":\"पृथ्वीच्या परिबलनामुळे कोणत्या दोन गोष्टी निर्माण होतात?\",\"options\":[\"दिन व रात्र\",\"उष्णता व थंडी\",\"सूर्य व चंद्र\",\"वर्ष व लीप वर्ष\"],\"answer\":0,\"explain\":\"परिबलनामुळे दिन व रात्र होतात.\"},{\"q\":\"पृथ्वीच्या अक्षाचे कललेले असणे का महत्त्वाचे आहे?\",\"options\":[\"सूर्याचा प्रकाश समान वाटतो\",\"उष्णता व अंधाराचे वेळ बदलतात\",\"पृथ्वीचे तापमान वाढते\",\"चंद्राचे कक्षा बदलतात\"],\"answer\":1,\"explain\":\"अक्षाचे कलणे दिन व रात्रीच्या वेळेत फरक आणते.\"},{\"q\":\"पृथ्वीच्या परिभ्रमणाला काय म्हणतात?\",\"options\":[\"परिबलन\",\"परिभ्रमण\",\"विषुववृत्त\",\"अक्ष\"],\"answer\":1,\"explain\":\"परिभ्रमण म्हणजे पृथ्वी सूर्याभोवती फिरणे.\"},{\"q\":\"चंद्राच्या प्रकाशाच्या अवस्थांमध्ये कोणती अवस्था सर्वात जास्त प्रकाश देते?\",\"options\":[\"अमावस्या\",\"पौर्णिमा\",\"शुक्लपक्ष\",\"कृष्णपक्ष\"],\"answer\":1,\"explain\":\"पौर्णिमा वेळी चंद्र पूर्ण प्रकाशमान असतो.\"},{\"q\":\"लीप वर्षात फेब्रुवारी महिन्यात किती दिवस असतात?\",\"options\":[\"28\",\"29\",\"30\",\"31\"],\"answer\":1,\"explain\":\"लीप वर्षात फेब्रुवारीला 29 दिवस असतात.\"},{\"q\":\"पृथ्वीच्या परिबलनामुळे तयार होणाऱ्या दोन गोलार्धांना काय म्हणतात?\",\"options\":[\"उत्तर गोलार्ध व दक्षिण गोलार्ध\",\"पूर्व गोलार्ध व पश्चिम गोलार्ध\",\"उष्ण गोलार्ध व थंड गोलार्ध\",\"हिमालय व अटलांटिक\"],\"answer\":0,\"explain\":\"विषुववृत्ताने पृथ्वी दोन गोलार्धात विभागली.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16785,24,5,'EVS Part 1','mr','पृथ्वी आणि जीवसृष्टी','[\"पृथ्वीचे तीन आवरणे आहेत – शिलावरण (कठीण बाह्य कवच), जलावरण (पाणी), आणि वातावरण (हवा).\",\"शिलावरण माती व खडकांनी बनलेले असते आणि पृथ्वीला आधार देते.\",\"जलावरणात महासागर, समुद्र, नद्या, सरोवरे आणि भूजल यांचा समावेश होतो.\",\"वातावरणात नायट्रोजन, ऑक्सिजन, कार्बन डायऑक्साइड व बाष्प यांसारखे वायू असतात.\",\"पृथ्वीचा पृष्ठभाग सुमारे 70 % पाण्याने आणि 30 % जमिनीने व्यापलेला आहे.\",\"महासागर पाच आहेत – अटलांटिक, पॅसिफिक, आर्क्टिक, हिंदी आणि दक्षिणी.\",\"किनारपट्टी म्हणजे जमिनीचा तो भाग जो पाण्याने झाकलेला असतो.\",\"भूजल म्हणजे जमिनीखालील खडकांच्या थरात साठलेले पाणी.\",\"हिमनदी जमिनीवरील बर्फाचे थर हळूहळू खाली सरकून बनते.\",\"हिमनग म्हणजे समुद्रावर तरंगणारे मोठे बर्फाचे तुकडे.\",\"पृथ्वीचे वातावरण चार थरांमध्ये विभागलेले आहे – तपांबर, स्थितांबर, आयनांबर आणि बाह्यांबर.\",\"तपांबरात सर्वाधिक हवामान घटना जसे की ढग, पाऊस, धुके आणि वादळे घडतात.\",\"सूर्यापासून येणारी अतिनील किरणे ओझोन थराने शोषली जातात, ज्यामुळे जीवांना हानी पोहोचत नाही.\",\"पाण्याचे बाष्पीभवन, संघनन आणि पर्जन्य या प्रक्रियांनी जलचक्र चालते.\",\"पृथ्वीवरील सजीव – वनस्पती, प्राणी आणि सूक्ष्मजीव – हे शिलावरण, जलावरण आणि वातावरण या तीन आवरणांमध्ये राहतात.\"]','[{\"q\":\"पृथ्वीचे बाहेरील कठीण कवच काय म्हणतात?\",\"options\":[\"शिलावरण\",\"जलावरण\",\"वातावरण\",\"जीवावरण\"],\"answer\":0,\"explain\":\"पृथ्वीचे बाहेरील कठीण कवच शिलावरण म्हणतात.\"},{\"q\":\"पृथ्वीच्या पृष्ठभागावर पाण्याने झाकलेला भाग कोणता?\",\"options\":[\"महासागर\",\"सागर\",\"किनारपट्टी\",\"सिरोवर\"],\"answer\":0,\"explain\":\"सुमारे 70 % पृष्ठभाग महासागरांनी झाकलेला आहे.\"},{\"q\":\"हिमवर्षावात पाण्याचे कण गोठून काय बनतात?\",\"options\":[\"हिमकण\",\"बर्फाचे तुकडे\",\"धबधबा\",\"पाऊस\"],\"answer\":0,\"explain\":\"हिमकण हे गोठलेल्या पाण्याचे कण आहेत.\"},{\"q\":\"पृथ्वीभोवती असणारे हवेचे आवरण काय म्हणतात?\",\"options\":[\"शिलावरण\",\"जलावरण\",\"वातावरण\",\"जीवावरण\"],\"answer\":2,\"explain\":\"हवेचे आवरण वातावरण म्हणतात.\"},{\"q\":\"पाणी वाफ होऊन हवेत मिसळल्यावर काय होते?\",\"options\":[\"संघनन\",\"बाष्पीभवन\",\"पर्जन्य\",\"धुके\"],\"answer\":0,\"explain\":\"वाफेचे थंड होणे संघनन म्हणतात.\"},{\"q\":\"सूर्यापासून येणाऱ्या अतिनील किरणांना कोणता वायू शोषून घेतो?\",\"options\":[\"ऑक्सिजन\",\"नायट्रोजन\",\"ओझोन\",\"कार्बन डायऑक्साइड\"],\"answer\":2,\"explain\":\"ओझोन वायू अतिनील किरण शोषतो.\"},{\"q\":\"पृथ्वीच्या पृष्ठभागापासून सुमारे 13 किलोमीटर अंतरावर असलेल्या थराला काय म्हणतात?\",\"options\":[\"तपांबर\",\"स्थितांबर\",\"आयनांबर\",\"बाह्यांबर\"],\"answer\":0,\"explain\":\"13 किलोमीटरपर्यंतचा थर तपांबर म्हणतात.\"},{\"q\":\"पृथ्वीवरील सर्व सजीवांना एकत्रितपणे काय म्हणतात?\",\"options\":[\"जीवावरण\",\"शिलावरण\",\"जलावरण\",\"वातावरण\"],\"answer\":0,\"explain\":\"सजीवांना एकत्रितपणे जीवावरण म्हणतात.\"},{\"q\":\"पाण्याचे बाष्पीभवन, संघनन आणि पर्जन्य या सर्व प्रक्रियांना काय म्हणतात?\",\"options\":[\"हवामान चक्र\",\"जलचक्र\",\"उष्णता चक्र\",\"वायू चक्र\"],\"answer\":1,\"explain\":\"या सर्व प्रक्रियांना जलचक्र म्हणतात.\"},{\"q\":\"पृथ्वीच्या पृष्ठभागावर पाणी वाळवंटात साठवलेले पाणी कोणत्या नावाने ओळखले जाते?\",\"options\":[\"सरोवर\",\"भूजल\",\"हिमनग\",\"सागर\"],\"answer\":1,\"explain\":\"भूजल हे जमिनीखाली साठलेले पाणी आहे.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16786,24,5,'EVS Part 1','mr','पर्यावरणाचे संतुलन','[\"पर्यावरण म्हणजे आपल्या आजूबाजूचे सर्व घटक – सजीव आणि निर्जीव – एकमेकांशी जोडलेले असतात.\",\"जैवविविधता म्हणजे एखाद्या ठिकाणी आढळणाऱ्या विविध सजीवांची संख्या आणि प्रकार.\",\"अन्नसाखळी म्हणजे वनस्पती → प्राणी → प्राणी अशी साखळी जिथे प्रत्येक घटक पुढच्या घटकाचे अन्न असतो.\",\"अन्नजाळे म्हणजे अनेक अन्नसाखळ्या एकत्र येऊन तयार होणारे जाळे.\",\"वनस्पती सूर्यप्रकाश, पाणी आणि कार्बन डायऑक्साइड वापरून स्वतःचे अन्न तयार करतात (फोटोसिंथेसिस).\",\"वनस्पतींचे अन्न प्राणी खातात, प्राणी इतर प्राणी खातात – हेच अन्नसाखळीचे आधार.\",\"मातीतील सूक्ष्मजीव मृत सजीवांचे अवशेष विघटित करून पोषक द्रव्ये तयार करतात.\",\"पाण्याचे चक्र, वायूचे चक्र आणि पोषक द्रव्यांचे चक्र हे पर्यावरणाचे संतुलन राखतात.\",\"पर्यावरणातील संतुलन राखण्यासाठी आपल्याला स्वच्छता, पुनर्वापर आणि जैवविविधतेचे संरक्षण करणे आवश्यक आहे.\",\"सजीव आणि निर्जीव घटक एकमेकांवर अवलंबून असतात – हेच पर्यावरणाचे परस्पर संबंध.\",\"अन्नसाखळीतील एखादी कडी नष्ट झाली तर संपूर्ण साखळीवर परिणाम होऊ शकतो.\",\"वनस्पतींचे अन्न प्राण्यांना मिळते, प्राणी आपले अन्न मिळवण्यासाठी इतर प्राणी खातात.\",\"अन्नसाखळीतील प्रत्येक घटक एक कडी असतो.\",\"अन्नजाळे म्हणजे अनेक अन्नसाखळ्या एकत्र येऊन तयार होणारे जाळे.\",\"पर्यावरणाचे संतुलन राखण्यासाठी आपल्याला निसर्गाचे संरक्षण करणे आवश्यक आहे.\"]','[{\"q\":\"पर्यावरण म्हणजे काय?\",\"options\":[\"सजीवांचे समूह\",\"निर्जीव घटक\",\"सजीव व निर्जीव घटकांचे एकत्रित अस्तित्व\",\"फक्त वनस्पती\"],\"answer\":2,\"explain\":\"पर्यावरणात सजीव आणि निर्जीव दोन्ही घटक असतात.\"},{\"q\":\"वनस्पती सूर्यप्रकाश, पाणी आणि कार्बन डायऑक्साइड वापरून काय तयार करतात?\",\"options\":[\"पोषक द्रव्ये\",\"ऑक्सिजन\",\"अन्न\",\"दोन्ही B आणि C\"],\"answer\":3,\"explain\":\"फोटोसिंथेसिसने ऑक्सिजन आणि अन्न तयार होते.\"},{\"q\":\"अन्नसाखळीतील पहिला घटक कोणता असतो?\",\"options\":[\"प्राणी\",\"वनस्पती\",\"पाणी\",\"वायू\"],\"answer\":1,\"explain\":\"वनस्पती अन्नसाखळीचा आधार असतात.\"},{\"q\":\"अन्नजाळे म्हणजे काय?\",\"options\":[\"एकच अन्नसाखळी\",\"अनेक अन्नसाखळ्यांचे जाळे\",\"वनस्पतींचे जाळे\",\"प्राण्यांचे जाळे\"],\"answer\":1,\"explain\":\"अन्नजाळे अनेक अन्नसाखळ्या एकत्र येऊन बनते.\"},{\"q\":\"सूक्ष्मजीवांचे कार्य काय असते?\",\"options\":[\"अन्न तयार करणे\",\"पाण्याचे शुद्धीकरण\",\"मृत सजीवांचे विघटन\",\"वायूचे उत्पादन\"],\"answer\":2,\"explain\":\"सूक्ष्मजीव मृत सजीवांचे अवशेष विघटित करतात.\"},{\"q\":\"पर्यावरणातील संतुलन राखण्यासाठी काय करावे?\",\"options\":[\"फक्त वनस्पती लावणे\",\"फक्त प्राणी पाळणे\",\"स्वच्छता व पुनर्वापर\",\"फक्त पाणी पिणे\"],\"answer\":2,\"explain\":\"स्वच्छता व पुनर्वापर हे संतुलन राखण्यासाठी महत्त्वाचे.\"},{\"q\":\"अन्नसाखळीतील एखादी कडी नष्ट झाली तर काय होईल?\",\"options\":[\"साखळी चालू राहील\",\"साखळी तुटू शकते\",\"सर्व प्राणी मरतील\",\"सर्व वनस्पती वाढतील\"],\"answer\":1,\"explain\":\"कडी नष्ट झाल्यास साखळी तुटू शकते.\"},{\"q\":\"वनस्पतींचे अन्न प्राणी काय खातात?\",\"options\":[\"पाणी\",\"वायू\",\"मातीतील पोषक द्रव्ये\",\"वनस्पतींचे अन्न\"],\"answer\":3,\"explain\":\"वनस्पतींचे अन्न प्राणी खातात.\"},{\"q\":\"पर्यावरणाचे संतुलन राखण्यासाठी कोणते चक्र महत्त्वाचे आहे?\",\"options\":[\"पाण्याचे चक्र\",\"वायूचे चक्र\",\"पोषक द्रव्यांचे चक्र\",\"सर्व वरील\"],\"answer\":3,\"explain\":\"सर्व चक्रे महत्त्वाची आहेत.\"},{\"q\":\"जैवविविधता म्हणजे काय?\",\"options\":[\"वनस्पतींची विविधता\",\"प्राण्यांची विविधता\",\"सजीवांची विविधता\",\"निर्जीव घटकांची विविधता\"],\"answer\":2,\"explain\":\"जैवविविधता म्हणजे सजीवांची विविधता.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16787,24,5,'EVS Part 1','mr','कुटुंबातील मूल्ये','[\"कुटुंब हे आपले पहिले समाज आहे जिथे आपण प्रेम, आदर आणि सहकार्य शिकतो.\",\"प्रत्येक कुटुंबात निर्णय घेण्यासाठी सर्व सदस्यांची मते महत्त्वाची असतात.\",\"प्रामाणिकपणा म्हणजे सत्य बोलणे आणि इतरांना फसवू नये.\",\"सहकार्याने काम केल्यास काम जलद आणि चांगले होते.\",\"समानता म्हणजे सर्वांना एकसमान अधिकार आणि संधी मिळणे.\",\"समानतेमुळे सर्वांना प्रगतीची संधी मिळते.\",\"सहिष्णुता म्हणजे इतरांच्या मतांना आणि संस्कृतीला मान देणे.\",\"कुटुंबातील सण-समारंभात सर्वजण एकत्र तयारी करतात.\",\"कुटुंबात निर्णय घेताना सर्वांना बोलण्याची संधी दिली पाहिजे.\",\"प्रामाणिकपणा आणि सहकार्याने कुटुंबात सलोखा राहतो.\",\"सार्वजनिक जीवनातही प्रामाणिकपणा आणि सहकार्य महत्त्वाचे आहेत.\",\"कुटुंबातील निर्णय प्रक्रियेतील सर्व सदस्यांनी आपले मत मांडले पाहिजे.\",\"समानतेमुळे सर्वांना समान गरजा पूर्ण करण्यास मदत होते.\",\"सहिष्णुता आणि समानतेने समाजात शांतता राहते.\",\"कुटुंबातील निर्णय घेताना सर्वांना विचारून निर्णय घेणे चांगले असते.\",\"प्रामाणिकपणा आणि सहकार्याने कुटुंबात विश्वास वाढतो.\",\"समानतेमुळे सर्वांना समान शिक्षण आणि आरोग्य मिळते.\",\"सहिष्णुता आणि समानता हे समाजातील मूलभूत मूल्ये आहेत.\",\"कुटुंबात प्रेम, आदर, सहकार्य आणि समानता हे सर्वात महत्त्वाचे आहेत.\",\"प्रामाणिकपणा आणि सहकार्याने कुटुंबातील सर्व कामे सहज होतात.\",\"समानतेमुळे सर्वांना समान संधी मिळतात.\",\"सहिष्णुता आणि समानता हे समाजाला एकत्र आणतात.\",\"सहकार्याने काम केल्यास कुटुंबात सर्वांना आनंद वाटतो.\",\"प्रामाणिकपणा आणि सहकार्याने कुटुंबात विश्वास वाढतो.\",\"समानतेमुळे सर्वांना समान अधिकार मिळतात.\"]','[{\"q\":\"कुटुंबात निर्णय घेताना कोणाला बोलण्याची संधी द्यायला हवी?\",\"options\":[\"फक्त पालकांना\",\"फक्त मुलांना\",\"सर्वांना\",\"फक्त शिक्षकांना\"],\"answer\":2,\"explain\":\"सर्व सदस्यांना आपले मत मांडण्याची संधी द्यायला हवी.\"},{\"q\":\"प्रामाणिकपणा म्हणजे काय?\",\"options\":[\"फसवणे\",\"सत्य बोलणे\",\"गुप्त ठेवणे\",\"इतरांना फसवणे\"],\"answer\":1,\"explain\":\"प्रामाणिकपणा म्हणजे सत्य बोलणे.\"},{\"q\":\"सहकार्याने काम केल्यास काय होते?\",\"options\":[\"काम जास्त वेळ लागते\",\"काम चांगले होते\",\"काम कमी होते\",\"काम अवघड होते\"],\"answer\":1,\"explain\":\"सहकार्याने काम जलद आणि चांगले होते.\"},{\"q\":\"समानता म्हणजे काय?\",\"options\":[\"सर्वांना समान अधिकार\",\"सर्वांना वेगवेगळे अधिकार\",\"फक्त पुरुषांना अधिकार\",\"फक्त मुलांना अधिकार\"],\"answer\":0,\"explain\":\"समानता म्हणजे सर्वांना समान अधिकार.\"},{\"q\":\"सहिष्णुता म्हणजे काय?\",\"options\":[\"इतरांना न मानणे\",\"इतरांच्या मतांना मान देणे\",\"इतरांना फसवणे\",\"इतरांना दुर्लक्ष करणे\"],\"answer\":1,\"explain\":\"सहिष्णुता म्हणजे इतरांच्या मतांना मान देणे.\"},{\"q\":\"कुटुंबातील सण-समारंभात काय करतात?\",\"options\":[\"फक्त पाहुणे येतात\",\"सर्वजण एकत्र तयारी करतात\",\"फक्त पालक तयारी करतात\",\"फक्त मुलं तयारी करतात\"],\"answer\":1,\"explain\":\"सर्वजण एकत्र तयारी करतात.\"},{\"q\":\"प्रामाणिकपणा आणि सहकार्याने कुटुंबात काय होते?\",\"options\":[\"विश्वास कमी होतो\",\"विश्वास वाढतो\",\"काम कमी होते\",\"काम जास्त होते\"],\"answer\":1,\"explain\":\"विश्वास वाढतो.\"},{\"q\":\"समानतेमुळे समाजात काय होते?\",\"options\":[\"शांतता राहते\",\"विवाद वाढतो\",\"असमानता वाढते\",\"अराजकता होते\"],\"answer\":0,\"explain\":\"समानतेमुळे शांतता राहते.\"},{\"q\":\"सहिष्णुता आणि समानता हे समाजातील काय आहेत?\",\"options\":[\"मूलभूत मूल्ये\",\"अल्प महत्त्वाचे\",\"फक्त कुटुंबात\",\"फक्त शाळेत\"],\"answer\":0,\"explain\":\"मूलभूत मूल्ये आहेत.\"},{\"q\":\"कुटुंबात निर्णय घेताना काय करायला हवे?\",\"options\":[\"फक्त पालक निर्णय घेतात\",\"सर्वांना विचारून निर्णय घेतात\",\"फक्त मुलं निर्णय घेतात\",\"फक्त शिक्षक निर्णय घेतात\"],\"answer\":1,\"explain\":\"सर्वांना विचारून निर्णय घेतात.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16788,24,5,'EVS Part 1','mr','नियम सर्वांसाठी','[\"नियम म्हणजे सर्वांना पाळावयाचे नियम\",\"निसर्गाचे नियम बदलत नाहीत पण मानवी नियम बदलू शकतात\",\"नियम पाळल्याने शिस्त आणि सुरक्षितता वाढते\",\"शाळेतील नियम सर्व विद्यार्थ्यांना समान आहेत\",\"नियमांचे तीन स्तंभ: समानता, न्याय आणि शिस्त\",\"सामाजिक नियम बदलतात पण काही मूलभूत नियम कायम राहतात\",\"नियमांचे उद्दिष्ट: अन्याय टाळणे, सुरक्षितता राखणे\",\"नियमांचे पालन केल्याने शिक्षण आणि विकासाला मदत होते\",\"नियमांचे उल्लंघन केल्यास शिक्षा होते\",\"नियमांचे उदाहरण: मतदानाचा हक्क, शिक्षणाची मोफत व्यवस्था\",\"नियमांचे उदाहरण: कचरा टाकण्यास बंदी\",\"नियमांचे उदाहरण: जंगलतोड व शिकारीवर बंदी\",\"नियमांचे उदाहरण: बालकामगारांवर बंदी\",\"नियमांचे उदाहरण: महिलांना संरक्षण\",\"नियमांचे उदाहरण: सार्वजनिक ठिकाणी ध्वनिक्षेपकावर बंदी\",\"नियमांचे उदाहरण: मुली आणि मुलांना समान वागणूक\",\"नियमांचे उदाहरण: भेदभावावर बंदी\",\"नियमांचे उदाहरण: अंधश्रद्धा व अनिष्ट प्रथा बंदी\",\"नियमांचे उदाहरण: हुंडा घेण्यावर बंदी\",\"नियमांचे उदाहरण: बालविवाहावर बंदी\",\"नियमांचे उदाहरण: कचरा नदीत टाकणे बंदी\",\"नियमांचे उदाहरण: क्रीडांगणावर नियम\",\"नियमांचे उदाहरण: शाळेच्या वाचनालयात नियम\",\"नियमांचे उदाहरण: मध्यान्ह भोजनाच्या वेळी नियम\",\"नियमांचे उदाहरण: शाळेतील शिस्त\"]','[{\"q\":\"नियम सर्वांसाठी असतात याचा अर्थ काय?\",\"options\":[\"सर्वांना समान नियम लागू होतात\",\"फक्त शाळेतील विद्यार्थ्यांना नियम लागू होतात\",\"फक्त पालकांना नियम लागू होतात\",\"फक्त शिक्षकांना नियम लागू होतात\"],\"answer\":0,\"explain\":\"नियम सर्वांना समानपणे लागू होतात.\"},{\"q\":\"निसर्गाचे नियम बदलता येतात का?\",\"options\":[\"होय\",\"नाही\",\"काहीवेळा होय\",\"काहीवेळा नाही\"],\"answer\":1,\"explain\":\"निसर्गाचे नियम आपण बदलू शकत नाही.\"},{\"q\":\"सामाजिक नियमांमध्ये बदल का करावा लागतो?\",\"options\":[\"सामाजिक जीवन बदलते\",\"कायदे बदलतात\",\"माणसांची गरज बदलते\",\"वरील सर्व\"],\"answer\":3,\"explain\":\"सामाजिक जीवन व गरजेनुसार नियम बदलतात.\"},{\"q\":\"शाळेत नियम पाळल्यास काय होते?\",\"options\":[\"शिस्त निर्माण होते\",\"शिक्षण कमी होते\",\"मित्रांशी वाद होतो\",\"काहीच होत नाही\"],\"answer\":0,\"explain\":\"नियम पाळल्याने शिस्त व कार्यक्षमता वाढते.\"},{\"q\":\"सार्वजनिक ठिकाणी ध्वनिक्षेपकावर रात्री १० नंतर बंदी का आहे?\",\"options\":[\"शाळेच्या नियमांनुसार\",\"शांततेसाठी\",\"कायदेशीर कारणाने\",\"सर्वोच्च न्यायालयाने\"],\"answer\":1,\"explain\":\"रात्री १० नंतर आवाज कमी करण्यासाठी बंदी.\"},{\"q\":\"मुलींच्या शिक्षणावर काय बंदी आहे?\",\"options\":[\"मुलींचे शिक्षण बंद\",\"मुलींचे शिक्षण मोफत\",\"मुलींचे शिक्षण मर्यादित\",\"मुलींचे शिक्षण अनिवार्य\"],\"answer\":1,\"explain\":\"मुलांना मोफत प्राथमिक शिक्षणाची बंदी नाही, तर ती दिली जाते.\"},{\"q\":\"बालकामगारांच्या नेमणुकीवर काय नियम आहे?\",\"options\":[\"बंदी\",\"अनिवार्य\",\"शिफारस\",\"परवानगी\"],\"answer\":0,\"explain\":\"बालकामगारांना नेमणुकीस बंदी आहे.\"},{\"q\":\"कौटुंबिक हिंसेपासून महिलांना कोणते संरक्षण आहे?\",\"options\":[\"कायदे\",\"काहीही नाही\",\"सामाजिक जागरूकता\",\"मित्रांचे समर्थन\"],\"answer\":0,\"explain\":\"कायदे महिलांना संरक्षण देतात.\"},{\"q\":\"सामाजिक नियमांचे पालन न केल्यास काय होते?\",\"options\":[\"शिक्षा\",\"सन्मान\",\"प्रशंसा\",\"काहीच नाही\"],\"answer\":0,\"explain\":\"नियमांचे उल्लंघन केल्यास शिक्षा होते.\"},{\"q\":\"निसर्गाचे नियम आणि मानवी नियम यातील फरक काय?\",\"options\":[\"निसर्गाचे नियम बदलता येतात\",\"मानवी नियम बदलता येतात\",\"दोन्ही बदलता येतात\",\"दोन्ही बदलता येत नाहीत\"],\"answer\":3,\"explain\":\"निसर्गाचे नियम बदलता येत नाहीत, मानवी नियम बदलता येतात.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16789,24,5,'EVS Part 1','mr','आपणच सोडवू आपले प्रश्न','[\"शांतता म्हणजे सर्वांना एकत्र राहण्याची आणि एकमेकांना मदत करण्याची अवस्था.\",\"शाळेत, घरी आणि समाजात शांतता असणे महत्त्वाचे आहे, कारण त्यामुळे सर्वांना फायदा होतो.\",\"शांतता नसल्यास तंटे, वाद आणि गैरसोय होते.\",\"शांतता साधण्यासाठी संवाद, चर्चा आणि एकमेकांना समजून घेणे आवश्यक आहे.\",\"शाळेत ‘शांततादूत’ गट असावा, ज्यामध्ये विद्यार्थी शांतता राखण्यासाठी मदत करतात.\",\"शांततादूतांची निवड करताना प्रामाणिकपणा, सहानुभूती आणि जबाबदारी हे निकष असावेत.\",\"ग्रामसफाई आणि श्रमदानाद्वारे स्वच्छता आणि शांतता दोन्ही साधता येतात.\",\"कचर्‍याचे ढीग, पाण्याची टंचाई, मोकाट कुत्रे इत्यादी सार्वजनिक समस्या आहेत.\",\"या समस्यांचे निराकरण गावातील लोकांनी एकत्र चर्चा करून करावे.\",\"शांतता आणि स्वच्छता एकत्र केल्यास समाजात एकोपा आणि प्रगती होते.\",\"शांतता दिवस (21 सप्टेंबर) हा आंतरराष्ट्रीय शांतता दिन आहे.\",\"शांतता साधण्यासाठी सर्वांनी एकत्र काम करणे आवश्यक आहे.\",\"शांतता आणि स्वच्छतेची काळजी घेणे हे समाजाचे मूलभूत मूल्य आहे.\",\"शांतता आणि स्वच्छतेसाठी शाळेत आणि घरात नियम ठरवणे गरजेचे आहे.\",\"शांतता आणि स्वच्छतेच्या प्रयत्नांना पुरस्कार आणि मान्यता मिळू शकते.\",\"शांतता आणि स्वच्छतेसाठी स्थानिक प्रतिनिधींना पत्र लिहून मदत मागणे उपयुक्त ठरते.\",\"शांततेसाठी क्रीडांगणावर खेळताना नियमांचे पालन करणे महत्त्वाचे आहे.\",\"शांतता आणि स्वच्छतेसाठी सर्वांना एकत्र येऊन काम करणे आवश्यक आहे.\",\"शांतता आणि स्वच्छतेच्या प्रयत्नांना समाजात आदर आणि प्रशंसा मिळते.\",\"शांतता आणि स्वच्छतेसाठी सर्वांनी एकमेकांना मदत करणे आवश्यक आहे.\"]','[{\"q\":\"शांतता म्हणजे काय?\",\"options\":[\"सर्वांना एकत्र राहण्याची अवस्था\",\"फक्त शाळेत असणारी अवस्था\",\"फक्त घरी असणारी अवस्था\",\"काहीही नाही\"],\"answer\":0,\"explain\":\"शांतता म्हणजे सर्वांना एकत्र राहण्याची आणि एकमेकांना मदत करण्याची अवस्था.\"},{\"q\":\"शाळेत ‘शांततादूत’ गट का असावा?\",\"options\":[\"शांतता राखण्यासाठी\",\"फक्त खेळण्यासाठी\",\"फक्त गृहपाठ करण्यासाठी\",\"काहीही नाही\"],\"answer\":0,\"explain\":\"शांततादूत गट शाळेत शांतता राखण्यासाठी असतो.\"},{\"q\":\"शांततादूतांची निवड करताना काय निकष असावेत?\",\"options\":[\"प्रामाणिकपणा, सहानुभूती, जबाबदारी\",\"फक्त उंची\",\"फक्त वय\",\"काहीही नाही\"],\"answer\":0,\"explain\":\"प्रामाणिकपणा, सहानुभूती आणि जबाबदारी हे निकष असावेत.\"},{\"q\":\"शांतता आणि स्वच्छता एकत्र केल्यास काय होते?\",\"options\":[\"समाजात एकोपा आणि प्रगती\",\"फक्त स्वच्छता\",\"फक्त शांतता\",\"काहीही नाही\"],\"answer\":0,\"explain\":\"दोन्ही एकत्र केल्यास समाजात एकोपा आणि प्रगती होते.\"},{\"q\":\"शांतता दिवस कोणत्या दिवशी साजरा होतो?\",\"options\":[\"21 सप्टेंबर\",\"1 जानेवारी\",\"15 ऑक्टोबर\",\"काहीही नाही\"],\"answer\":0,\"explain\":\"आंतरराष्ट्रीय शांतता दिन 21 सप्टेंबरला साजरा होतो.\"},{\"q\":\"शांतता साधण्यासाठी काय आवश्यक आहे?\",\"options\":[\"संवाद आणि चर्चा\",\"फक्त खेळ\",\"फक्त गृहपाठ\",\"काहीही नाही\"],\"answer\":0,\"explain\":\"संवाद आणि चर्चा हे शांतता साधण्यासाठी आवश्यक आहेत.\"},{\"q\":\"शांतता आणि स्वच्छतेसाठी शाळेत काय करावे?\",\"options\":[\"नियम ठरवणे\",\"फक्त खेळणे\",\"फक्त गृहपाठ\",\"काहीही नाही\"],\"answer\":0,\"explain\":\"शाळेत नियम ठरवून शांतता आणि स्वच्छता राखावी.\"},{\"q\":\"कचर्‍याचे ढीग कोणत्या समस्येचे उदाहरण आहेत?\",\"options\":[\"सार्वजनिक समस्या\",\"फक्त घरगुती समस्या\",\"फक्त शाळेची समस्या\",\"काहीही नाही\"],\"answer\":0,\"explain\":\"कचर्‍याचे ढीग सार्वजनिक समस्येचे उदाहरण आहेत.\"},{\"q\":\"शांतता आणि स्वच्छतेसाठी काय करावे?\",\"options\":[\"ग्रामसफाई आणि श्रमदान\",\"फक्त खेळ\",\"फक्त गृहपाठ\",\"काहीही नाही\"],\"answer\":0,\"explain\":\"ग्रामसफाई आणि श्रमदान हे शांतता आणि स्वच्छतेसाठी उपयुक्त आहेत.\"},{\"q\":\"शांतता आणि स्वच्छतेसाठी काय मदत करते?\",\"options\":[\"सर्वांनी एकत्र काम करणे\",\"फक्त शाळेतील विद्यार्थी\",\"फक्त शिक्षक\",\"काहीही नाही\"],\"answer\":0,\"explain\":\"सर्वांनी एकत्र काम केल्याने शांतता आणि स्वच्छता साधता येते.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16790,24,5,'EVS Part 1','mr','सार्वजनिक सुविधा आणि माझी शाळा','[\"सार्वजनिक सुविधा म्हणजे सर्वांना उपलब्ध असणाऱ्या सेवा जसे की पाणी, वीज, टपाल, दूरध्वनी, रेल्वे, बस, बँक, पोलीस, अग्निशमन दल.\",\"शाळा ही सार्वजनिक सुविधेचा एक भाग आहे आणि ती समाजाच्या मदतीने उभी राहते.\",\"शाळेत वर्गखोल्या, ग्रंथालय, प्रयोगशाळा, क्रीडांगण, संगणक कक्ष, स्वच्छतागृह, पिण्याचे पाणी, आरोग्यसेवा, पोषण कार्यक्रम असतात.\",\"शाळेच्या उभारणीसाठी पालक, माजी विद्यार्थी, उद्योजक, शास्त्रज्ञ, खेळाडू इत्यादी समाजातील विविध घटक मदत करतात.\",\"शाळा सर्व मुलांना समान शिक्षणाचा हक्क देते; शिक्षणाचा हक्क कायद्यानुसार ६ वर्षे वयापासून १४ वर्षे वयापर्यंत असतो.\",\"विशेष गरजा असलेल्या मुलांना १८ वर्षे वयापर्यंत शिक्षण घेण्याचा अधिकार आहे.\",\"शाळा समाजातील स्वच्छता, आरोग्य, सुरक्षा इत्यादी विषयांवर जागरूकता वाढवते.\",\"शाळा आणि पालक यांच्यात संवाद व सहकार्य आवश्यक आहे; पालक संघ शाळेच्या व्यवस्थापनात महत्त्वाची भूमिका बजावतात.\",\"शाळेतील सर्व पालकांचा समान आदर राखला पाहिजे.\",\"सार्वजनिक सुविधा वापरताना जबाबदारीने व शिस्तबद्धपणे वागणे आवश्यक आहे.\",\"शाळेतील सुविधा वापरताना नियमांचे पालन करणे आणि इतरांना त्रास न होऊ देणे महत्त्वाचे आहे.\",\"शाळेतील क्रीडांगण व खेळ साहित्य मुलांना शारीरिक तंदुरुस्ती वाढवतात.\",\"शाळेतील प्रयोगशाळा व संगणक कक्ष विज्ञान व तंत्रज्ञान शिक्षणाला प्रोत्साहन देतात.\",\"शाळेतील ग्रंथालय व वाचनालय वाचनाची सवय लावतात.\",\"शाळेतील आरोग्यसेवा व पोषण कार्यक्रम मुलांच्या आरोग्याची काळजी घेतात.\",\"शाळेतील स्वच्छतागृह व पिण्याचे पाणी स्वच्छ व सुरक्षित ठेवणे आवश्यक आहे.\",\"शाळेतील भित्तिपत्रक व बोधचिन्हे शाळेची ओळख व मूल्ये दर्शवतात.\",\"शाळेतील शिक्षण व समाजातील सहकार्याने शाळा समाजाच्या प्रगतीत योगदान देते.\",\"शाळेतील सर्व सुविधा मुलांना उपलब्ध करून देणे हे शाळेचे कर्तव्य आहे.\",\"सार्वजनिक सुविधा व शाळेतील सेवा वापरताना सर्वांना समान वागणूक द्यावी.\",\"सार्वजनिक सुविधा व शाळेतील सेवा समाजाच्या विकासात महत्त्वाची भूमिका बजावतात.\"]','[{\"q\":\"सार्वजनिक वाहतुकीची उदाहरणे कोणती आहेत?\",\"options\":[\"पाणीपुरवठा\",\"रेल्वे\",\"पुस्तकालय\",\"क्रीडांगण\"],\"answer\":1,\"explain\":\"रेल्वे ही सार्वजनिक वाहतुकीची एक उदाहरण आहे.\"},{\"q\":\"शाळेच्या उभारणीसाठी समाजातील कोणते घटक मदत करतात?\",\"options\":[\"फक्त शिक्षक\",\"फक्त पालक\",\"फक्त बँका\",\"पालक व उद्योजक\"],\"answer\":3,\"explain\":\"पालक व उद्योजक शाळेच्या उभारणीसाठी मदत करतात.\"},{\"q\":\"शाळेतील स्वच्छतागृहाचे मुख्य कार्य काय आहे?\",\"options\":[\"पाणी साठवणे\",\"शिक्षण देणे\",\"आरोग्य राखणे\",\"क्रीडा करणे\"],\"answer\":2,\"explain\":\"स्वच्छतागृह आरोग्य राखण्यासाठी असते.\"},{\"q\":\"शाळेतील प्रयोगशाळेचा उपयोग काय?\",\"options\":[\"वाचनासाठी\",\"क्रीडा करण्यासाठी\",\"विज्ञान प्रयोगासाठी\",\"संगीत शिकण्यासाठी\"],\"answer\":2,\"explain\":\"प्रयोगशाळा विज्ञान प्रयोगासाठी असते.\"},{\"q\":\"शाळेतील पालक संघाचे मुख्य उद्दिष्ट काय?\",\"options\":[\"शाळेची साफसफाई\",\"शिक्षकांना मदत\",\"पालकांना शाळेतील निर्णयात सहभागी करणे\",\"क्रीडा कार्यक्रम आयोजित करणे\"],\"answer\":2,\"explain\":\"पालक संघ पालकांना शाळेतील निर्णयात सहभागी करतो.\"},{\"q\":\"शाळेतील पिण्याचे पाणी कसे असावे?\",\"options\":[\"खारट\",\"धूसर\",\"स्वच्छ व सुरक्षित\",\"फळांचे रस\"],\"answer\":2,\"explain\":\"पिण्याचे पाणी स्वच्छ व सुरक्षित असावे.\"},{\"q\":\"शाळेतील क्रीडांगणाचे महत्त्व काय?\",\"options\":[\"वाचनासाठी\",\"क्रीडा व आरोग्य सुधारण्यासाठी\",\"संगीत व नृत्य शिकण्यासाठी\",\"भाषा शिकण्यासाठी\"],\"answer\":1,\"explain\":\"क्रीडांगण क्रीडा व आरोग्य सुधारण्यासाठी असते.\"},{\"q\":\"शाळेतील आरोग्यसेवा कोणत्या गोष्टींची काळजी घेते?\",\"options\":[\"वाचन\",\"क्रीडा\",\"आरोग्य व पोषण\",\"संगीत\"],\"answer\":2,\"explain\":\"आरोग्यसेवा आरोग्य व पोषणाची काळजी घेते.\"},{\"q\":\"शाळेतील सार्वजनिक सुविधा वापरताना काय लक्षात ठेवावे?\",\"options\":[\"फक्त स्वतःसाठी\",\"फक्त शिक्षकांसाठी\",\"सर्वांना समान वागणूक\",\"फक्त पालकांसाठी\"],\"answer\":2,\"explain\":\"सर्वांना समान वागणूक द्यावी.\"},{\"q\":\"शाळेतील भित्तिपत्रकाचे कार्य काय?\",\"options\":[\"वाचनासाठी\",\"संगीत व नृत्य शिकण्यासाठी\",\"शाळेची ओळख व मूल्ये दर्शवणे\",\"क्रीडा आयोजन\"],\"answer\":2,\"explain\":\"भित्तिपत्रक शाळेची ओळख व मूल्ये दर्शवते.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16791,24,5,'EVS Part 1','mr','नकाशा : आपला सोबती','[\"नकाशा म्हणजे एखाद्या प्रदेशाची माहिती कागदावर किंवा संगणकावर दाखवणारी चित्र\",\"भूभागाची उंची, खोली, उतार इत्यादी दाखवण्यासाठी तीन प्रमुख पद्धती – समोच्च रेषा पद्धती, रंग पद्धती आणि उठावदर्शक आराखडा\",\"समोच्च रेषा पद्धतीत समान उंचीची ठिकाणे एकमेकांना जोडणाऱ्या रेषांनी दाखवली जातात; रेषांमधील अंतर जितके कमी तितका उतार तीव्र\",\"रंग पद्धतीत प्रत्येक उंचीच्या श्रेणीसाठी वेगळा रंग वापरला जातो; उंची जास्त तितका रंग गडद\",\"उठावदर्शक आराखडा (3D) उपग्रह किंवा संगणकाच्या मदतीने बनवला जातो; यात प्रत्येक बिंदूची उंची स्पष्टपणे दिसते\",\"नकाशावर चिन्हे व खुणा वापरून विविध गोष्टी दाखवल्या जातात – किल्ला, रस्ता, नदी, पाणी, इत्यादी\",\"सांकेतिक चिन्हे म्हणजे लहान आकृत्या, जसे वर्तुळ, त्रिकोण, बिंदू इत्यादी\",\"भूभागाचे प्रकार – डोंगर, दरी, पठार, मैदाने, बेट इत्यादी\",\"नकाशा वाचताना प्रथम समोच्च रेषा व रंग पद्धती पाहून उंची व उतार ओळखा\",\"उंचीची मोजणी समुद्रसपाटीपासून केली जाते\",\"नकाशा तयार करण्यासाठी भारतीय सर्वेक्षण संस्था (ISRO) आणि इतर संस्था महत्त्वाच्या आहेत\",\"नकाशा वाचताना चिन्हांची सूची व अर्थ लक्षात ठेवणे आवश्यक आहे\",\"उंची 0 मीटर म्हणजे समुद्रसपाटी, त्यापेक्षा जास्त उंची गडद हिरवा, 300 मीटरपेक्षा जास्त पिवळा इत्यादी\"]','[{\"q\":\"समोच्च रेषा पद्धतीत समान उंचीची ठिकाणे कशाने जोडली जातात?\",\"options\":[\"रेषा\",\"बिंदू\",\"वर्तुळ\",\"त्रिकोण\"],\"answer\":0,\"explain\":\"समोच्च रेषा म्हणजे समान उंचीची ठिकाणे जोडणाऱ्या रेषा.\"},{\"q\":\"रंग पद्धतीत उंची जास्त असलेल्या ठिकाणी कोणता रंग वापरला जातो?\",\"options\":[\"निळा\",\"हिरवा\",\"पिवळा\",\"लाल\"],\"answer\":2,\"explain\":\"उंची जास्त असलेल्या ठिकाणी पिवळा रंग वापरला जातो.\"},{\"q\":\"उठावदर्शक आराखडा तयार करण्यासाठी कोणती तंत्रज्ञान वापरली जाते?\",\"options\":[\"हस्तकला\",\"उपग्रह\",\"पाण्याचे नकाशे\",\"कागदावर रेखाटन\"],\"answer\":1,\"explain\":\"उठावदर्शक आराखडा उपग्रहांच्या मदतीने बनवला जातो.\"},{\"q\":\"समोच्च रेषा पद्धतीत रेषांमधील अंतर कमी असल्यास उतार कसा असतो?\",\"options\":[\"मंद\",\"तीव्र\",\"समान\",\"अज्ञात\"],\"answer\":1,\"explain\":\"रेषांमधील अंतर कमी असल्यास उतार तीव्र असतो.\"},{\"q\":\"नकाशावर किल्ल्याचे चिन्ह सामान्यतः कसे असते?\",\"options\":[\"वर्तुळ\",\"त्रिकोण\",\"चौरस\",\"बिंदू\"],\"answer\":2,\"explain\":\"किल्ल्याचे चिन्ह चौरस किंवा चौकोनासारखे असते.\"},{\"q\":\"उंची 0 मीटर कोणत्या स्तरावर असते?\",\"options\":[\"समुद्रसपाटी\",\"पर्वतशिखर\",\"दरीतळ\",\"बाजूची दरी\"],\"answer\":0,\"explain\":\"उंची 0 मीटर म्हणजे समुद्रसपाटी.\"},{\"q\":\"नकाशावर पाण्याचे भाग दाखवण्यासाठी कोणता रंग वापरला जातो?\",\"options\":[\"निळा\",\"हिरवा\",\"पिवळा\",\"लाल\"],\"answer\":0,\"explain\":\"पाण्याचे भाग निळ्या रंगाने दाखवले जातात.\"},{\"q\":\"समोच्च रेषा पद्धतीत कोणत्या अंतरावर रेषा काढल्या जातात?\",\"options\":[\"50 मीटर\",\"100 मीटर\",\"150 मीटर\",\"200 मीटर\"],\"answer\":2,\"explain\":\"सामान्यतः 150 मीटर अंतरावर रेषा काढल्या जातात.\"},{\"q\":\"भूभागाचे प्रकार नकाशावर दाखवण्यासाठी कोणती पद्धत सर्वात सोपी आहे?\",\"options\":[\"समोच्च रेषा पद्धती\",\"रंग पद्धती\",\"उठावदर्शक आराखडा\",\"सर्व पद्धती\"],\"answer\":0,\"explain\":\"समोच्च रेषा पद्धती सर्वात सोपी व पारंपरिक पद्धत आहे.\"},{\"q\":\"नकाशावर रस्ता दाखवण्यासाठी कोणते चिन्ह वापरले जाते?\",\"options\":[\"वर्तुळ\",\"रेषा\",\"त्रिकोण\",\"बिंदू\"],\"answer\":1,\"explain\":\"रस्ता दाखवण्यासाठी सरळ रेषा वापरली जाते.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16792,24,5,'EVS Part 1','mr','ओळख भारताची','[\"भारत हा एक विशाल देश आहे ज्यात विविध नद्या, पर्वत, पठारे, मैदाने आणि बेटे आहेत.\",\"उत्तरेकडील सीमा हिमालय पर्वतांनी बनलेली आहे.\",\"दक्षिणेकडील भागात अरबी समुद्र, बंगाल उपसागर आणि हिंदी महासागर आहेत.\",\"भारताला तीन बाजूंनी पाण्याने वेढलेले आहे, त्यामुळे त्याला ‘द्वीपकल्प’ म्हणतात.\",\"गंगा, यमुना, गोदावरी, नर्मदा, कावेरी या प्रमुख नद्या भारतात वाहतात.\",\"हिमालयात उगम पावणाऱ्या नद्यांचा प्रवाह दक्षिणेकडे जातो.\",\"पर्वतांमध्ये हिमालय, सह्याद्री, कोंकण आणि पश्चिम घाट आहेत.\",\"पठारे म्हणजे उंच सपाट प्रदेश, जसे की थार वाळवंट आणि पश्चिम घाटातील पठारे.\",\"भारताचे प्रमुख बेटसमूह लक्षद्वीप, अंदमान-निकोबार आणि कोकण बेट आहेत.\",\"हवामान विविधतेमुळे वनस्पती, प्राणी आणि पिकेही विविध आहेत.\",\"उत्तर भारतात गहू प्रमुख पिक, दक्षिण भारतात भात प्रमुख पिक.\",\"मध्य भारतात ज्वारीचे उत्पादन जास्त.\",\"राज्यांची क्षेत्रफळे वेगवेगळी आहेत – राजस्थान सर्वात मोठे, गोवा सर्वात लहान.\",\"राज्यांची राजधान्या दिल्ली, मुंबई, चेन्नई, कोलकाता इत्यादी.\",\"राज्यांमध्ये विविध भाषा, सण आणि परंपरा आहेत.\",\"भारताचे भूगोल समजण्यासाठी नकाशा अभ्यासणे महत्त्वाचे आहे.\"]','[{\"q\":\"भारताच्या तीनही बाजूंस असलेल्या जलभागाला काय म्हणतात?\",\"options\":[\"अखात\",\"समुद्रसपाटी\",\"भारतीय दूबीपकल्प\",\"पर्वत रांग\"],\"answer\":2,\"explain\":\"भारताच्या तीनही बाजूंस पाण्याने व्यापलेला भाग \'भारतीय दूबीपकल्प\' म्हणतात.\"},{\"q\":\"गंगा, नर्मदा, वैनगंगा, गोदावरी आणि कावेरी या नद्यांपैकी कोणती नदी हिमालयातून उगम पावते?\",\"options\":[\"गंगा\",\"नर्मदा\",\"गोदावरी\",\"कावेरी\"],\"answer\":0,\"explain\":\"गंगा नदी हिमालयातून उगम पावते.\"},{\"q\":\"भारताच्या मुख्य भूमीच्या दक्षिणेला असलेल्या बेटांना काय म्हणतात?\",\"options\":[\"अंदमान आणि निकोबार\",\"लक्षद्वीप\",\"मध्य प्रदेश\",\"बंगाल उपसागर\"],\"answer\":0,\"explain\":\"अंदमान आणि निकोबार बेटे भारताच्या मुख्य भूमीच्या दक्षिणेला आहेत.\"},{\"q\":\"भारताच्या उत्तर भागात प्रमुख पीक काय आहे?\",\"options\":[\"भात\",\"गहू\",\"ज्वारी\",\"संत्री\"],\"answer\":1,\"explain\":\"उत्तर भारतात प्रमुख पीक गहू आहे.\"},{\"q\":\"भारतातील सर्वात मोठे राज्य कोणते?\",\"options\":[\"राजस्थान\",\"महाराष्ट्र\",\"पश्चिम बंगाल\",\"गुजरात\"],\"answer\":0,\"explain\":\"राजस्थान हे भारतातील सर्वात मोठे राज्य आहे.\"},{\"q\":\"भारताच्या प्रमुख नद्यांपैकी कोणती नदी सिंधू नदीला भेटते?\",\"options\":[\"गंगा\",\"सिंधू\",\"गुजरात\",\"कावेरी\"],\"answer\":1,\"explain\":\"सिंधू नदी स्वतःच एक प्रमुख नदी आहे.\"},{\"q\":\"भारताच्या तीनही बाजूंस असलेल्या जलभागाचे निरीक्षण करताना कोणत्या दिशेला पाणी वाहते?\",\"options\":[\"उत्तरे\",\"दक्षिणे\",\"पूर्वे\",\"पश्चिमे\"],\"answer\":1,\"explain\":\"भारताच्या दक्षिणेला पाणी वाहते.\"},{\"q\":\"भारताच्या मुख्य भूमीच्या दक्षिणेला असलेल्या बेटांपैकी कोणते बेट अरबी समुद्रात आहे?\",\"options\":[\"लक्षद्वीप\",\"अंदमान\",\"निकोबार\",\"बंगाल उपसागर\"],\"answer\":0,\"explain\":\"लक्षद्वीप बेटे अरबी समुद्रात आहेत.\"},{\"q\":\"भारताच्या प्रमुख नद्यांपैकी कोणती नदी मध्य प्रदेशातून वाहते?\",\"options\":[\"साबरमती\",\"गंगा\",\"सिंधू\",\"कावेरी\"],\"answer\":0,\"explain\":\"साबरमती नदी मध्य प्रदेशातून वाहते.\"},{\"q\":\"भारताच्या प्रमुख नद्यांपैकी कोणती नदी दक्षिण भारतात भाताची शेतीसाठी महत्त्वाची आहे?\",\"options\":[\"गंगा\",\"गोदावरी\",\"सिंधू\",\"कावेरी\"],\"answer\":1,\"explain\":\"गोदावरी नदी दक्षिण भारतात भाताच्या शेतीसाठी महत्त्वाची आहे.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16793,24,5,'EVS Part 1','mr','आपले घर व पर्यावरण','[\"घर म्हणजे निवारा, अन्न, पाणी, वस्त्र व शिक्षणाची गरज पूर्ण करणारी जागा.\",\"घराचे मुख्य घटक: दारे, खिडक्या, भिंती, छप्पर.\",\"घराचे साहित्य: लाकूड, दगड, माती, चुनखडी, सिमेंट, विटा, काच, लोखंड, वाळू, कापूस.\",\"प्रदेशानुसार घराची रचना बदलते – मैदानी, वाळवंटी, दलदलयुक्त, पर्वतीय, वाळबंटी प्रदेशांमध्ये भिन्न साहित्य व आकार वापरले जातात.\",\"उष्णता, थंडी, वारा, पाऊस व ऊन यांपासून संरक्षण देणारे घर आपल्याला विश्रांती व सुरक्षितता देते.\",\"अ, ब, क घरांचे फरक: आकार, साहित्य व रचना – जंगली प्राण्यांपासून संरक्षणासाठी ‘अ’ घर सर्वात सुरक्षित.\",\"शहरी भागात ‘ब’ घर सर्वात जास्त वापरले जाते कारण ते समाजकंटकांपासून संरक्षण देते.\",\"घर बांधताना नैसर्गिक साधनांचा वापर करून पर्यावरणपूरक घर बनवणे आवश्यक आहे.\",\"बायोगॅस, पवनऊर्जा व सौरऊर्जा यांचा वापर करून ऊर्जा बचत करता येते.\",\"पाण्याचा पुनर्वापर व टाकाऊ वस्तूंचा पुनर्वापर हे पर्यावरणपूरक घराचे महत्त्वाचे गुण आहेत.\",\"घर बांधताना साहित्याची निवड व स्वच्छता राखणे हे प्रदूषण टाळण्यासाठी महत्त्वाचे आहे.\",\"घर बांधताना स्थानिक हवामान व भूभागाचा विचार करून साहित्य व रचना ठरवली जाते.\",\"घर बांधताना बेघर लोकांना निवारा देण्यासाठी शासन विविध योजना चालवते.\",\"नैसर्गिक ऊर्जास्त्रोतांचा वापर वाढवून पर्यावरणाची हानी कमी करता येते.\",\"घराचे डिझाइन व साहित्य हे स्थानिक उपलब्धतेवर अवलंबून असते.\",\"घर बांधताना पर्यावरणपूरक साहित्य व तंत्रज्ञानाचा वापर केल्याने ऊर्जा व पाण्याची बचत होते.\",\"घर बांधताना स्थानिक समुदायाची सहभागिता व जनजागृती आवश्यक आहे.\",\"घर बांधताना वाळू, कोळसा, सिमेंट व विटा यांचा वापर होतो, परंतु पर्यावरणपूरक पर्याय निवडणे चांगले.\",\"घर बांधताना मुख्य ४ साहित्य: लोखंड, सिमेंट, वाळू, विटा.\",\"घर बांधताना आराम, रचना व हवामान या तीन गोष्टींचा विचार करावा.\",\"घरातील सौरऊर्जेने चालणारी उपकरणे: दिवे, पंखे, पाणी पंप इत्यादी.\",\"घर बांधताना पर्यावरणपूरक घराची प्रतिकृती तयार करणे हे शिक्षणाचे महत्त्वाचे कार्य आहे.\",\"घर बांधताना स्थानिक नैसर्गिक साधनांचा वापर करून ऊर्जा व पाण्याची बचत करता येते.\",\"घर बांधताना प्रदूषण टाळण्यासाठी स्वच्छता व पुनर्वापराचे उपाय अवलंबावेत.\",\"घर बांधताना स्थानिक समुदायाची सहभागिता व जनजागृती आवश्यक आहे.\"]','[{\"q\":\"घराचे मुख्य घटक कोणते आहेत?\",\"options\":[\"दारे व खिडक्या\",\"भिंती व छप्पर\",\"दोन्ही A व B\",\"काहीही नाही\"],\"answer\":2,\"explain\":\"घरात दारे, खिडक्या, भिंती व छप्पर हे मुख्य घटक असतात.\"},{\"q\":\"कोणते साहित्य घर बांधण्यासाठी सर्वाधिक वापरले जाते?\",\"options\":[\"सिमेंट\",\"कापूस\",\"लोखंड\",\"काच\"],\"answer\":0,\"explain\":\"सिमेंट हे घर बांधण्यासाठी सर्वाधिक वापरले जाणारे साहित्य आहे.\"},{\"q\":\"पर्वतीय प्रदेशात कोणते घर सर्वात योग्य ठरेल?\",\"options\":[\"धाब्याचे घर\",\"काट्याचे घर\",\"कापसाचे घर\",\"सिमेंटचे घर\"],\"answer\":0,\"explain\":\"धाब्याचे घर पर्वतीय प्रदेशात योग्य ठरते कारण ते उष्णतेपासून संरक्षण देते.\"},{\"q\":\"घराचे संरक्षण कोणत्या गोष्टींपासून करते?\",\"options\":[\"पाण्याचा प्रवाह\",\"उष्णता व थंडी\",\"वारा व पाऊस\",\"सर्व वरील\"],\"answer\":3,\"explain\":\"घर थंडी, ऊन, वारा व पाऊस यांपासून संरक्षण देते.\"},{\"q\":\"शहरी भागात कोणते घर सर्वाधिक वापरले जाते?\",\"options\":[\"अ घर\",\"ब घर\",\"क घर\",\"ड घर\"],\"answer\":1,\"explain\":\"शहरी भागात ‘ब’ घर सर्वाधिक वापरले जाते कारण ते समाजकंटकांपासून संरक्षण देते.\"},{\"q\":\"पर्यावरणपूरक घराचे वैशिष्ट्य कोणते नाही?\",\"options\":[\"कृत्रिम रंगांचा वापर\",\"पाण्याचा पुनर्वापर\",\"बायोगॅसचा वापर\",\"सौरऊर्जा वापर\"],\"answer\":0,\"explain\":\"पर्यावरणपूरक घरात कृत्रिम रंगांचा वापर टाळला जातो.\"},{\"q\":\"घर बांधताना मुख्य ४ साहित्य कोणते आहेत?\",\"options\":[\"लोखंड, सिमेंट, वाळू, विटा\",\"कापूस, लोखंड, सिमेंट, काच\",\"लाकूड, चुनखडी, सिमेंट, विटा\",\"वाळू, पाणी, वायू, ध्वनी\"],\"answer\":0,\"explain\":\"लोखंड, सिमेंट, वाळू व विटा हे मुख्य साहित्य आहेत.\"},{\"q\":\"सौरऊर्जेने चालणारी उपकरणे कोणती?\",\"options\":[\"दिवे व पंखे\",\"पाणी पंप\",\"दोन्ही A व B\",\"काहीही नाही\"],\"answer\":2,\"explain\":\"सौरऊर्जेने दिवे, पंखे व पाणी पंप चालवता येतात.\"},{\"q\":\"घर बांधताना प्रदूषण टाळण्यासाठी काय करावे?\",\"options\":[\"सर्व साहित्य स्वच्छ करणे\",\"साहित्य पुनर्वापर करणे\",\"दोन्ही A व B\",\"काहीही नाही\"],\"answer\":2,\"explain\":\"साहित्य स्वच्छ व पुनर्वापर केल्याने प्रदूषण कमी होते.\"},{\"q\":\"घर बांधताना स्थानिक समुदायाची सहभागिता का महत्त्वाची आहे?\",\"options\":[\"सामाजिक समस्या टाळण्यासाठी\",\"सामाजिक जागरूकता वाढवण्यासाठी\",\"दोन्ही A व B\",\"काहीही नाही\"],\"answer\":2,\"explain\":\"समुदायाची सहभागिता सामाजिक व पर्यावरणीय जागरूकता वाढवते.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16794,24,5,'EVS Part 1','mr','सर्वांसाठी अन्न','[\"सर्वांसाठी अन्न म्हणजे आपल्या शरीराला आवश्यक असलेले पोषक तत्वे\",\"वनस्पती सूर्यप्रकाश, पाणी, मातीतील खनिजे घेऊन अन्न तयार करतात\",\"शेतीचे दोन प्रमुख हंगाम – खरीप (जून‑ऑक्टोबर) आणि रबी (ऑक्टोबर‑मार्च)\",\"उन्हाळी पिके मार्च‑जून या काळात पेरली जातात\",\"सुधारित बियाणे म्हणजे संशोधनाने बनवलेली बियाणे ज्यामुळे पिके जास्त आणि जलद वाढतात\",\"सिंचनाच्या आधुनिक पद्धती – ठिबक सिंचन व तुषार सिंचन\",\"ठिबक सिंचनात पाणी थेट मुळाजवळ पडते, ज्यामुळे पाण्याची बचत होते\",\"तुषार सिंचनात पाण्याचे थेंब पिकांवर पडतात, उन्हाळी पिकांसाठी उपयुक्त\",\"रासायनिक खते म्हणजे कृत्रिम खते, नैसर्गिक खते म्हणजे शेण, कंपोस्ट इ.\",\"अन्नसाठा म्हणजे अन्नधान्याचे सुरक्षित साठवण, ज्यामुळे आपत्तीच्या वेळी अन्न उपलब्ध राहते\",\"धान्य साठवताना कोरडे व हवा खेळती ठेवणे महत्त्वाचे\",\"धान्य साठवण्यासाठी कडुनिंबाचा पाला किंवा इतर कीटकनाशके वापरली जातात\",\"हरितक्रांतीने भारताला अन्नस्वावलंबी बनवले\",\"सेंद्रिय शेतीत नैसर्गिक पदार्थ व खते वापरली जातात\",\"शेतीसाठी पाणी मुख्यतः पावसाचे पाणी, नदी, तलाव व विहिरीतून मिळते\",\"पाणी व खतांचा अतिवापर मातीची सुपीकता कमी करतो\",\"कीड व रोगांपासून पिकांचे संरक्षण करण्यासाठी कीटकनाशके व रोगनाशके वापरली जातात\",\"धान्य साठवताना बुरशी व कीड टाळण्यासाठी योग्य पद्धतींची गरज असते\",\"शेतीत सुधारित तंत्रज्ञानामुळे पिकांचे उत्पादन व गुणवत्ता वाढते\",\"अन्नसुरक्षा म्हणजे प्रत्येकाला पुरेसे व योग्य अन्न मिळणे\"]','[{\"q\":\"शेतीचे दोन प्रमुख हंगाम कोणते आहेत?\",\"options\":[\"खरीप व रबी\",\"उन्हाळी व हिवाळी\",\"मौसमी व शुष्क\",\"सर्दी व गरम\"],\"answer\":0,\"explain\":\"भारतामध्ये शेतीचे प्रमुख हंगाम खरीप (जून‑ऑक्टोबर) आणि रबी (ऑक्टोबर‑मार्च) असे आहेत.\"},{\"q\":\"भातशेती कोणत्या हंगामात केली जाते?\",\"options\":[\"उन्हाळी\",\"खरीप\",\"रबी\",\"दोन्ही\"],\"answer\":3,\"explain\":\"भातशेती दोन्ही हंगामात केली जाते, परंतु खरीप हंगामात पावसाचे पाणी उपलब्ध असते.\"},{\"q\":\"सिंचनाच्या आधुनिक पद्धतींमध्ये कोणती पद्धत पाण्याचा अपव्यय कमी करते?\",\"options\":[\"पाटी सिंचन\",\"ठिबक सिंचन\",\"पावसाळी सिंचन\",\"नदी सिंचन\"],\"answer\":1,\"explain\":\"ठिबक सिंचन पद्धतीत पाणी थेट मुळापाशी पोहोचते, त्यामुळे पाण्याचा अपव्यय कमी होतो.\"},{\"q\":\"रासायनिक खतांचे मुख्य नुकसान काय आहे?\",\"options\":[\"मातीची सुपीकता वाढवणे\",\"पाण्याची बचत\",\"मातीचे क्षारपडणे\",\"पिकांची वाढ जलद होणे\"],\"answer\":2,\"explain\":\"रासायनिक खतांचा अतिवापर मातीचे क्षारपडणे आणि सुपीकता कमी होणे यास कारणीभूत ठरतो.\"},{\"q\":\"धान्य साठवताना कोणत्या गोष्टींची काळजी घ्यावी?\",\"options\":[\"उष्णता व दमटपणा\",\"कोरडे व हवेतील हवा\",\"आर्द्रता व प्रकाश\",\"पाण्याची उपलब्धता\"],\"answer\":1,\"explain\":\"धान्य साठवताना कोरडे व हवेतील हवा असणे आवश्यक आहे, अन्यथा बुरशी व कीड लागतात.\"},{\"q\":\"वनस्पतींच्या कोणत्या भागात अन्नसाठा होतो?\",\"options\":[\"पान\",\"मुळे\",\"फळ\",\"कंद\"],\"answer\":3,\"explain\":\"कंद (उदा. बटाटे, कांदा) हे वनस्पतींचे अन्नसाठा करणारे भाग आहेत.\"},{\"q\":\"सुधारित बियाणे वापरण्याचे फायदे काय आहेत?\",\"options\":[\"किडी प्रतिरोधक\",\"कमी पाण्यात वाढ\",\"उच्च उत्पादन\",\"वरील सर्व\"],\"answer\":3,\"explain\":\"सुधारित बियाणे किडी प्रतिरोधक, कमी पाण्यात वाढणारे आणि उच्च उत्पादन देणारे असतात.\"},{\"q\":\"पिकांचे संरक्षण करण्यासाठी कोणते औषध वापरतात?\",\"options\":[\"कडुनिंबाचा पाला\",\"साखर\",\"मध\",\"पाणी\"],\"answer\":0,\"explain\":\"कडुनिंबाचा पाला पिकांवर फवारल्याने कीड व बुरशीपासून संरक्षण मिळते.\"},{\"q\":\"हरितक्रांतीचा मुख्य योगदानकर्ता कोण आहे?\",\"options\":[\"डॉ. एम. एस. स्वामीनाथन\",\"डॉ. अ. के. पाटील\",\"डॉ. प. स. गायकवाड\",\"डॉ. व. प. शिंदे\"],\"answer\":0,\"explain\":\"डॉ. एम. एस. स्वामीनाथन यांनी गहू व तांदळाच्या बियाण्यांमध्ये सुधारणा करून हरितक्रांतीला चालना दिली.\"},{\"q\":\"पिकांचे नुकसान टाळण्यासाठी कोणते उपाय केले पाहिजेत?\",\"options\":[\"कीडनाशक फवारणी\",\"पाण्याची कमी उपलब्धता\",\"कमी खत वापरणे\",\"सर्वोच्च पावसाळी पाणी वापरणे\"],\"answer\":0,\"explain\":\"कीडनाशक फवारणी व इतर संरक्षणात्मक उपाय पिकांचे नुकसान टाळतात.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05');
INSERT INTO `ep_topic_packs` VALUES (16795,24,5,'EVS Part 1','mr','अन्न टिकवण्याच्या पद्धती','[\"अन्न टिकवणे म्हणजे अन्न खराब होऊ नये म्हणून केलेली पद्धती\",\"वाळवणे – पाण्याचे प्रमाण कमी करून सूक्ष्मजीवांची वाढ थांबवणे\",\"थंड करणे – फ्रिजमध्ये ठेवून ऊब कमी करणे, सूक्ष्मजीवांची वाढ मंदावणे\",\"उकळणे – उकळत्या पाण्याने सूक्ष्मजीवांचा नाश करणे\",\"हवाबंद डब्यात ठेवणे – हवा व पाण्याची प्रवेश रोखणे\",\"परिरक्षक – साखर, मीठ, हिंग, व्हिनेगर इ. वापरून सूक्ष्मजीवांची वाढ रोखणे\",\"लोणचं व मुरांबे – लिंबू, साखर, मीठ, तिखट घालून बनवलेले\",\"बुरशी व किडे – अन्न खराब होण्याचे मुख्य कारण\",\"सर्वात लवकर खराब होणारे पदार्थ – दूध, फळे, भाजीपाला\",\"हिवाळ्यात अन्न जास्त काळ टिकते कारण ऊब कमी असते\",\"उन्हाळ्यात वाळवलेल्या धान्ये व भाज्या वर्षभर टिकतात\",\"उकळलेल्या अन्नात सूक्ष्मजीवांचा नाश होतो\",\"फ्रिजमध्ये ठेवलेले अन्न ऊब कमी असल्याने जास्त काळ टिकते\",\"मसाल्याचे पदार्थ वाळवून व पूड करून दीर्घकाळ साठवता येतात\",\"अन्नपदार्थांची ताजेपणा तपासण्यासाठी सुगंध व रंग पाहा\",\"अन्न खराब झाल्यास पोटदुखी, उलट्या, जुलाब होऊ शकतात\"]','[{\"q\":\"वाळवणे म्हणजे काय?\",\"options\":[\"अन्नात पाणी वाढवणे\",\"अन्नातील पाणी कमी करणे\",\"अन्न गरम करणे\",\"अन्न थंड करणे\"],\"answer\":1,\"explain\":\"वाळवण्यात अन्नातील पाणी कमी केले जाते\"},{\"q\":\"उकळणे अन्नाला कसे मदत करते?\",\"options\":[\"सूक्ष्मजीवांचा नाश करते\",\"फक्त पाणी काढते\",\"अन्नाला गोड करते\",\"अन्नाला रंग देते\"],\"answer\":0,\"explain\":\"उकळल्याने सूक्ष्मजीवांचा नाश होतो\"},{\"q\":\"फ्रिजमध्ये अन्न ठेवणे का उपयुक्त?\",\"options\":[\"ऊब वाढते\",\"हवा येते\",\"ऊब कमी होते\",\"पाणी शोषते\"],\"answer\":2,\"explain\":\"फ्रिजमध्ये ऊब कमी होते\"},{\"q\":\"लोणचं बनवताना कोणते घटक वापरतात?\",\"options\":[\"साखर, मीठ, तिखट, लिंबू\",\"साखर, तेल, पाणी\",\"मीठ, पाणी, बेकिंग सोडा\",\"साखर, व्हिनेगर, हिंग\"],\"answer\":0,\"explain\":\"लोणच्यात साखर, मीठ, तिखट व लिंबू वापरतात\"},{\"q\":\"सर्वात लवकर खराब होणारे अन्न कोणते?\",\"options\":[\"धान्ये\",\"भाजीपाला\",\"दूध\",\"पापड\"],\"answer\":2,\"explain\":\"दूध लवकर खराब होते\"},{\"q\":\"हवाबंद डब्यात अन्न ठेवण्याचे कारण काय?\",\"options\":[\"हवा येऊ देते\",\"पाणी शोषते\",\"हवा व पाणी रोखते\",\"अन्नाला गंध देते\"],\"answer\":2,\"explain\":\"हवा व पाणी रोखण्यासाठी\"},{\"q\":\"बुरशी वाढण्याचे मुख्य कारण काय?\",\"options\":[\"अन्न कोरडे असणे\",\"अन्न गरम असणे\",\"अन्नात पाणी व हवा असणे\",\"अन्नात साखर असणे\"],\"answer\":2,\"explain\":\"पाणी व हवा बुरशी वाढवतात\"},{\"q\":\"मसाल्याचे पदार्थ वाळवून का साठवतात?\",\"options\":[\"वाळवून गोड होतात\",\"वाळवून वाळतात\",\"वाळवून दीर्घकाळ टिकतात\",\"वाळवून रंग बदलतात\"],\"answer\":2,\"explain\":\"वाळवणे दीर्घकाळ टिकवते\"},{\"q\":\"अन्न खराब झाल्यावर काय होऊ शकते?\",\"options\":[\"पोटदुखी\",\"सर्दी\",\"उदासीनता\",\"वजन वाढ\"],\"answer\":0,\"explain\":\"अन्न खराब झाल्यास पोटदुखी होऊ शकते\"},{\"q\":\"लोणचं व मुरांबे का बनवतात?\",\"options\":[\"साठवण्यासाठी\",\"सुगंधासाठी\",\"रंगासाठी\",\"चव बदलण्यासाठी\"],\"answer\":0,\"explain\":\"साठवण्यासाठी लोणचं व मुरांबे बनवतात\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16796,24,5,'EVS Part 1','mr','वाहतूक','[\"वाहतूक म्हणजे एखाद्या ठिकाणाहून दुसऱ्या ठिकाणी जाणे किंवा वस्तू हलवणे.\",\"विविध वाहतुकीची साधने: पायी, सायकल, मोटार, बस, ट्रक, विमान, जहाज इत्यादी.\",\"पायी जाणे सर्वात स्वच्छ आणि आरोग्यदायी आहे, परंतु वेळ व श्रम जास्त लागतात.\",\"सायकल चालवणे शारीरिक व्यायाम, इंधन खर्च नाही, प्रदूषण कमी.\",\"मोटार, बस इत्यादींना इंधन लागते, धूर व आवाज होतो, ज्यामुळे हवा व आवाज प्रदूषण होते.\",\"इंधन जळल्याने कार्बन मोनोऑक्साइड, नायट्रोजन डायऑक्साइड, सल्फर डायऑक्साइड व सूक्ष्मकण बाहेर पडतात.\",\"हवेचे प्रदूषण श्वसनमार्ग व डोळ्यांना त्रास देते, वनस्पतींची वाढ कमी होते.\",\"वाहतुकीचे चांगले परिणाम: वेळ व श्रमांची बचत, व्यापार वाढ, वस्तू व माहितीची जलद देवाणघेवाण.\",\"वाहतुकीचे वाईट परिणाम: प्रदूषण, आवाज, वाहतूक कोंडी, अपघात.\",\"प्रदूषण कमी करण्यासाठी: सार्वजनिक वाहतूक वापरा, CNG व सौरऊर्जेवर चालणारी वाहने वापरा, चालणे व सायकल चालवणे प्रोत्साहित करा.\",\"वृक्षारोपण व वृक्ष लागवड केल्याने हवा शुद्ध होते व प्रदूषण कमी होते.\",\"प्रत्येक विद्यार्थ्याने आपल्याला झालेल्या वाहतुकीच्या फायद्याबद्दल पाच वाक्ये लिहावीत.\",\"प्रदूषण कमी करण्यासाठी चार उपाय सुचवावेत: सार्वजनिक वाहतूक, सायकल, चालणे, इंधन बचत करणारी इंधनं.\",\"वर्गात वाहतुकीचे फायदे व तोटे यावर चर्चा करावी.\",\"प्रत्येक विद्यार्थ्याने आपल्या परिसरातील कमी प्रदूषण असलेल्या वाहतुकीच्या साधनांचे चित्र काढून कारणे लिहावीत.\"]','[{\"q\":\"पायी चालणे सर्वात स्वच्छ वाहतुकीचे साधन का मानले जाते?\",\"options\":[\"इंधन वापरते\",\"धूर व आवाज करते\",\"इंधन खर्च नाही\",\"वेगाने जाते\"],\"answer\":2,\"explain\":\"पायी चालण्यासाठी इंधनाची गरज नसते, त्यामुळे धूर व आवाज होत नाही.\"},{\"q\":\"सायकल चालवण्याचे मुख्य फायदे काय आहेत?\",\"options\":[\"इंधन खर्च\",\"धूर व आवाज\",\"शारीरिक व्यायाम व प्रदूषण नाही\",\"वेगाने जाते\"],\"answer\":2,\"explain\":\"सायकल चालवण्यासाठी इंधन लागत नाही आणि शरीराला व्यायाम मिळतो.\"},{\"q\":\"इंधन जळल्याने कोणते वायू बाहेर पडतात?\",\"options\":[\"पाणी व ऑक्सिजन\",\"कार्बन मोनोऑक्साइड व नायट्रोजन डायऑक्साइड\",\"साखर व मीठ\",\"हवा व पाऊस\"],\"answer\":1,\"explain\":\"इंधन जळल्याने कार्बन मोनोऑक्साइड व नायट्रोजन डायऑक्साइड व इतर वायू बाहेर पडतात.\"},{\"q\":\"प्रदूषण कमी करण्यासाठी कोणते इंधन वापरावे?\",\"options\":[\"पेट्रोल\",\"डिझेल\",\"CNG व सौरऊर्जा\",\"पाणी\"],\"answer\":2,\"explain\":\"CNG व सौरऊर्जेवर चालणारी वाहने कमी प्रदूषण करतात.\"},{\"q\":\"वाहतुकीचे चांगले परिणाम काय आहेत?\",\"options\":[\"वेळ व श्रमांची बचत\",\"व्यापार वाढ\",\"दोन्ही\",\"काहीही नाही\"],\"answer\":2,\"explain\":\"दोन्हीच चांगले परिणाम आहेत.\"},{\"q\":\"वाहतुकीमुळे होणारे आवाज प्रदूषण कसे होते?\",\"options\":[\"इंधन जळल्याने\",\"पाणी वाहून\",\"सायकल चालवून\",\"पायी चालून\"],\"answer\":0,\"explain\":\"इंधन जळल्याने आवाज व धूर निर्माण होतो.\"},{\"q\":\"वृक्षारोपणाने हवा कशी शुद्ध होते?\",\"options\":[\"धूर शोषून\",\"पाणी शोषून\",\"ऑक्सिजन व पाणी शोषून\",\"सूर्यप्रकाश शोषून\"],\"answer\":2,\"explain\":\"वृक्ष ऑक्सिजन व पाणी शोषून हवा शुद्ध करतात.\"},{\"q\":\"सार्वजनिक वाहतूक वापरण्याचे फायदे काय?\",\"options\":[\"इंधन वाचवते\",\"धूर व आवाज कमी\",\"दोन्ही\",\"काहीही नाही\"],\"answer\":2,\"explain\":\"सार्वजनिक वाहतूक इंधन वाचवते व धूर व आवाज कमी करते.\"},{\"q\":\"प्रदूषण कमी करण्यासाठी कोणते उपाय सुचवावेत?\",\"options\":[\"फक्त पायी चालणे\",\"फक्त सायकल चालवणे\",\"दोन्ही\",\"सर्व वाहने वापरणे\"],\"answer\":2,\"explain\":\"दोन्ही पायी चालणे व सायकल चालवणे हे उत्तम उपाय आहेत.\"},{\"q\":\"हवेचे प्रदूषण प्राणी व वनस्पतींवर काय परिणाम करते?\",\"options\":[\"श्वसन व डोळ्यांना त्रास\",\"वनस्पतींची वाढ व विकास खुंटतो\",\"दोन्ही\",\"काहीही नाही\"],\"answer\":2,\"explain\":\"दोन्हीच परिणाम होतात.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16797,24,5,'EVS Part 1','mr','संदेशवहन व प्रसार माध्यमे','[\"संदेशवहन म्हणजे माहितीची देवाणघेवाण करणे.\",\"प्रसार माध्यमे म्हणजे संदेश पोहोचवणारी साधने – दूरदर्शन, रेडिओ, वृत्तपत्र, इंटरनेट, मोबाइल.\",\"कृत्रिम उपग्रह हे अवकाशात प्रक्षेपित केलेले यंत्र आहे ज्याद्वारे दूरस्थ ठिकाणांहून संदेश पाठवता येतात.\",\"उपग्रह प्रक्षेपणासाठी रॉकेटचा वापर होतो आणि तो कमी वेळेत संदेश पोहोचवतो.\",\"दूरदर्शनावर विविध वाहिन्या (चॅनेल) असतात – जसे की राष्ट्रीय, खाजगी, शैक्षणिक, मनोरंजन.\",\"रेडिओद्वारे आवाजाच्या स्वरूपात संदेश पोहोचवला जातो.\",\"वृत्तपत्रे आणि मासिके हे मुद्रित माध्यम आहेत ज्यात लेख, फोटो आणि जाहिराती असतात.\",\"इंटरनेटद्वारे ईमेल, सोशल मीडिया, व्हिडिओ कॉन्फरन्सिंग इत्यादी मार्गे संदेश पाठवता येतात.\",\"मोबाइलद्वारे कॉल, व्हिडिओ कॉल, मेसेजिंग अॅप्सद्वारे संवाद साधता येतो.\",\"प्रसार माध्यमांचा चांगला परिणाम: शिक्षण, आरोग्य, जागरूकता, आर्थिक विकास.\",\"हानिकारक परिणाम: डोळ्यांना त्रास, व्यसन, चुकीची माहिती, सामाजिक विभाजन.\",\"उपग्रहाचे मुख्य कार्य: दूरस्थ ठिकाणांहून तात्काळ संवाद साधणे.\",\"दूरदर्शन प्रक्षेपण: थेट कार्यक्रम किंवा रेकॉर्डेड कार्यक्रम दाखवणे.\",\"रेडिओ प्रक्षेपण: आवाजाच्या स्वरूपात बातम्या व संगीत पोहोचवणे.\",\"इंटरनेट: माहिती शोधणे, ऑनलाइन शिक्षण, ई-कॉमर्स इत्यादीसाठी वापरले जाते.\",\"प्रसार माध्यमांचा वापर करताना संतुलन राखणे गरजेचे आहे.\",\"उपग्रहाचे नाव: INSAT (Indian National Satellite System).\",\"दूरदर्शन वाहिन्या: राष्ट्रीय (Doordarshan), खाजगी (Star, Sony), शैक्षणिक (National Geographic, Discovery).\",\"माहिती प्रसारणात संदेश, माध्यम, प्रेक्षक हे तीन घटक असतात.\",\"माहितीची देवाणघेवाण करताना गोपनीयता आणि सुरक्षितता लक्षात ठेवावी.\",\"प्रसार माध्यमांच्या वापरामुळे समाजात संवाद आणि समज वाढते.\"]','[{\"q\":\"संदेशवहनासाठी कृत्रिम उपग्रह कसे प्रक्षेपित केले जातात?\",\"options\":[\"उपग्रहाला हाताने फेकून\",\"आग्निबाणाने\",\"सागरातून\",\"पर्वतावरून\"],\"answer\":1,\"explain\":\"उपग्रहांना रॉकेट किंवा आग्निबाणाच्या साहाय्याने अवकाशात प्रक्षेपित केले जाते.\"},{\"q\":\"दूरदर्शनावर थेट प्रक्षेपित होणारे कार्यक्रम कोणते?\",\"options\":[\"फुटबॉल, क्रिकेट\",\"संगीत कार्यक्रम\",\"कथा सांगणे\",\"सर्व वरील\"],\"answer\":3,\"explain\":\"फुटबॉल, क्रिकेट तसेच इतर कार्यक्रम दूरदर्शनावर थेट प्रक्षेपित होतात.\"},{\"q\":\"संदेशवहनाद्वारे माहितीची देवाणघेवाण म्हणजे काय?\",\"options\":[\"माहिती पाठवणे आणि घेणे\",\"फक्त माहिती घेणे\",\"फक्त माहिती पाठवणे\",\"काहीच नाही\"],\"answer\":0,\"explain\":\"माहितीची देवाणघेवाण म्हणजे पाठवणे व घेणे दोन्ही.\"},{\"q\":\"इंटरनेटद्वारे आपण काय करू शकतो?\",\"options\":[\"फक्त ईमेल\",\"फक्त व्हिडिओ पाहणे\",\"दोन्ही\",\"काहीच नाही\"],\"answer\":2,\"explain\":\"इंटरनेटद्वारे ईमेल, व्हिडिओ, गेम इत्यादी सर्व करता येतात.\"},{\"q\":\"प्रसारमाध्यमांचा अति वापर केल्यास काय होऊ शकते?\",\"options\":[\"डोळ्यांना त्रास\",\"पाठीचे दुखणे\",\"श्रवणावर परिणाम\",\"वरील सर्व\"],\"answer\":3,\"explain\":\"अति वापरामुळे डोळे, पाठीचे व श्रवणावर त्रास होऊ शकतो.\"},{\"q\":\"राष्ट्रपती व पंतप्रधानांचे भाषण कोणत्या माध्यमातून दिले जाते?\",\"options\":[\"दूरदर्शन\",\"रेडिओ\",\"दोन्ही\",\"काहीच नाही\"],\"answer\":2,\"explain\":\"रेडिओ व दूरदर्शन दोन्ही माध्यमातून भाषण दिले जाते.\"},{\"q\":\"संदेशवहनाचे मुख्य फायदे काय आहेत?\",\"options\":[\"वेळ व श्रम वाचतो\",\"सामाजिक जागरूकता वाढते\",\"दोन्ही\",\"काहीच नाही\"],\"answer\":2,\"explain\":\"वेळ व श्रम वाचतो व सामाजिक जागरूकता वाढते.\"},{\"q\":\"प्रसारमाध्यमांचे हानिकारक परिणाम कोणते?\",\"options\":[\"डोळ्यांचे नुकसान\",\"पाठीचे दुखणे\",\"दोन्ही\",\"काहीच नाही\"],\"answer\":2,\"explain\":\"अति वापरामुळे डोळे व पाठीचे दुखणे होऊ शकते.\"},{\"q\":\"संदेशवहनाद्वारे आपण कोणत्या प्रकारची माहिती मिळवू शकतो?\",\"options\":[\"फक्त बातम्या\",\"फक्त खेळ\",\"सर्व प्रकारची माहिती\",\"काहीच नाही\"],\"answer\":2,\"explain\":\"संदेशवहनाद्वारे बातम्या, खेळ, शिक्षण व इतर सर्व माहिती मिळते.\"},{\"q\":\"संदेशवहनासाठी कोणते तंत्र वापरले जाते?\",\"options\":[\"उपग्रह प्रक्षेपण\",\"पारंपरिक पद्धत\",\"दोन्ही\",\"काहीच नाही\"],\"answer\":0,\"explain\":\"संदेशवहनासाठी उपग्रह प्रक्षेपण तंत्र वापरले जाते.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16798,24,5,'EVS Part 1','mr','पाणी','[\"पाणी हे जीवनाचे मूलभूत स्रोत आहे.\",\"पाण्याचे तीन अवस्थाः घन (बर्फ), द्रव (पाणी), वायू (वाफ).\",\"सांडपाणी म्हणजे घर, उद्योग, कारखाने इथून बाहेर पडणारे पाणी ज्यात घाण व विषारी पदार्थ असतात.\",\"सांडपाण्याची विल्हेवाट लावण्यासाठी शुद्धीकरण केंद्रे वापरली जातात.\",\"शुद्धीकरण प्रक्रियेतील मुख्य टप्पे: निस्पंदन, निर्जंतुकीकरण, ऑक्सिजनीकरण.\",\"निस्पंदनात वाळू, कोळसा, जाड वाळू इत्यादी थर वापरले जातात.\",\"निर्जंतुकीकरणात क्लोरीन किंवा इतर रसायनांचा वापर होतो.\",\"ऑक्सिजनीकरणात पाण्यात हवा खेळवून ऑक्सिजन वाढवला जातो.\",\"पावसाचे पाणी जमिनीत जिरवून भूजल वाढवता येते.\",\"दुष्काळात पाण्याची तुटवड्यामुळे शेती व जनावरांना त्रास होतो.\",\"जलव्यवस्थापन म्हणजे पाणी साठवणे, शुद्धीकरण व योग्य वापर यांची योजना.\",\"सांडपाणी शुद्धीकरण न केल्यास रोग पसरतात.\",\"पाण्यातील सूक्ष्मजीव व विषारी पदार्थ मानवी व प्राण्यांना हानी पोहोचवतात.\",\"पाणी शुद्ध करण्यासाठी कोळसा, वाळू, जाड वाळू यांचा थर तयार केला जातो.\",\"पाण्याच्या शुद्धीकरणासाठी वापरले जाणारे रसायन क्लोरीन आहे.\",\"पाणी शुद्ध केल्यावर ते पिण्यासाठी सुरक्षित होते.\",\"पाणी शुद्धीकरण केंद्रात पाणी प्रथम टाक्यांमध्ये स्थिर ठेवले जाते.\",\"पाणी शुद्धीकरणाचे उद्दिष्ट: निर्जंतुकीकरण व ऑक्सिजनीकरण.\",\"पाण्याचे प्रदूषण टाळण्यासाठी सांडपाण्याचे योग्य व्यवस्थापन आवश्यक आहे.\",\"पाणी शुद्धीकरणाची प्रक्रिया जलस्रोतांपासून सुरू होते.\",\"पाणी शुद्ध केल्यावर ते नद्या, तळी व विहिरींमध्ये परत सोडले जाते.\",\"पाणी शुद्धीकरणात वापरलेल्या थरांची क्रमवारी: जाड वाळू, कोळसा, बारीक वाळू.\",\"पाणी शुद्धीकरणानंतर पाणी स्वच्छ व पारदर्शक होते.\",\"पाणी शुद्धीकरण केंद्रात पाणी निस्पंदनानंतर क्लोरीन मिसळले जाते.\",\"पाणी शुद्धीकरणात ऑक्सिजन वाढवण्यासाठी पंप वापरले जातात.\"]','[{\"q\":\"पाण्याच्या तीन अवस्थांपैकी कोणती अवस्था द्रव आहे?\",\"options\":[\"घन\",\"द्रव\",\"वायू\",\"स्फटिक\"],\"answer\":1,\"explain\":\"द्रव अवस्था म्हणजे पाणी.\"},{\"q\":\"सांडपाण्याचे शुद्धीकरण करण्यासाठी कोणता थर प्रथम वापरला जातो?\",\"options\":[\"जाड वाळू\",\"कोळसा\",\"बारीक वाळू\",\"पाणी\"],\"answer\":0,\"explain\":\"सर्वप्रथम जाड वाळूचा थर वापरला जातो.\"},{\"q\":\"निर्जंतुकीकरणासाठी पाण्यात कोणते रसायन मिसळले जाते?\",\"options\":[\"क्लोरीन\",\"सोडियम क्लोराइड\",\"पोटॅशियम आयोडाइड\",\"ब्लीच\"],\"answer\":0,\"explain\":\"क्लोरीन हे मुख्य निर्जंतुकीकरणाचे रसायन आहे.\"},{\"q\":\"पाण्यात हवा खेळवून ऑक्सिजन वाढवण्याची प्रक्रिया काय म्हणतात?\",\"options\":[\"निस्पंदन\",\"निर्जंतुकीकरण\",\"ऑक्सिजनीकरण\",\"फिल्टरेशन\"],\"answer\":2,\"explain\":\"हवा खेळवून ऑक्सिजन वाढवणे ऑक्सिजनीकरण म्हणतात.\"},{\"q\":\"पावसाचे पाणी जमिनीत जिरवण्यासाठी काय करावे?\",\"options\":[\"पाण्याला टाक्यांमध्ये साठवणे\",\"पाण्याला थेट नद्यात सोडणे\",\"पाण्याला जमिनीत ओतणे\",\"पाण्याला कचऱ्यात टाकणे\"],\"answer\":2,\"explain\":\"पावसाचे पाणी जमिनीत ओतून जिरवले जाते.\"},{\"q\":\"दुष्काळात पाण्याची तुटवड्यामुळे कोणते परिणाम होतात?\",\"options\":[\"शेती व प्राण्यांना त्रास\",\"फक्त मानवांना त्रास\",\"फक्त वनस्पतींना त्रास\",\"कोणताही परिणाम नाही\"],\"answer\":0,\"explain\":\"दुष्काळामुळे शेती व प्राण्यांना त्रास होतो.\"},{\"q\":\"पाणी शुद्धीकरण केंद्रात पाणी प्रथम कशात स्थिर ठेवले जाते?\",\"options\":[\"टाक्या\",\"पंप\",\"फिल्टर\",\"क्लोरीन\"],\"answer\":0,\"explain\":\"पाणी प्रथम टाक्यांमध्ये स्थिर ठेवले जाते.\"},{\"q\":\"पाण्याचे शुद्धीकरण करताना कोणता थर सर्वात शेवटी येतो?\",\"options\":[\"जाड वाळू\",\"कोळसा\",\"बारीक वाळू\",\"पाणी\"],\"answer\":2,\"explain\":\"बारीक वाळू सर्वात शेवटी येते.\"},{\"q\":\"पाण्याचे शुद्धीकरण केल्यानंतर ते कोणत्या स्रोतांमध्ये परत सोडले जाते?\",\"options\":[\"नद्या\",\"तळी\",\"विहिरी\",\"वरील सर्व\"],\"answer\":3,\"explain\":\"पाणी नद्या, तळी व विहिरींमध्ये परत सोडले जाते.\"},{\"q\":\"पाण्यातील सूक्ष्मजीव व विषारी पदार्थ मानवी व प्राण्यांना कशा प्रकारे हानी पोहोचवतात?\",\"options\":[\"रोग पसरवतात\",\"पाणी गोड करतात\",\"पाणी थंड करतात\",\"पाणी स्वच्छ करतात\"],\"answer\":0,\"explain\":\"सूक्ष्मजीव व विषारी पदार्थ रोग पसरवतात.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16799,24,5,'EVS Part 1','mr','वस्त्र - आपली गरज','[\"कपडे म्हणजे शरीर झाकणारे वस्त्र\",\"वस्त्रांचे मुख्य प्रकार: साडी, शर्ट, पॅंट, कुर्ता, पायजामा\",\"पावसाळ्यात हलके कापसाचे कपडे घालतात\",\"हिवाळ्यात जाड कापसाचे किंवा ऊनी कपडे घालतात\",\"वस्त्रनिर्मितीसाठी कच्चा माल: कापूस, ऊन, रेशीम, पॉलिस्टर\",\"कच्चा माल शेतातून किंवा बाजारातून आणला जातो\",\"वस्त्र उद्योगात कामगार: विणकर, कापड कापणारा, रंगवणारा\",\"वस्त्रांची गरज आणि हव्यास यामध्ये फरक असतो\",\"हव्यास म्हणजे गरज नसताना वस्तू हव्या असणे\",\"वस्त्रांची विविधता प्रदेशानुसार बदलते\",\"साड्यांचे विविध प्रकार: पाटण, काश्मीर सिल्क, बनारसी सिल्क\",\"वस्त्र उद्योगाचा इतिहास प्राचीन काळापासून सुरू\",\"वस्त्र उद्योगात बदल: तंत्रज्ञान, उत्पादन पद्धती\",\"वस्त्रांचा वापर पोशाख, सजावट, संरक्षणासाठी होतो\"]','[{\"q\":\"वसतुंमध्ये कापसाचे कापड कोणत्या नावाने ओळखले जाते?\",\"options\":[\"कापूस\",\"सिल्क\",\"पॉलिस्टर\",\"नायलॉन\"],\"answer\":0,\"explain\":\"कापूस हे कापसाचे कापड आहे.\"},{\"q\":\"हिवाळ्यात घालण्यासाठी सर्वात योग्य कपड्याचा प्रकार कोणता?\",\"options\":[\"साडी\",\"कुर्ता\",\"पँट\",\"पोलो शर्ट\"],\"answer\":1,\"explain\":\"हिवाळ्यात कुर्ता आणि जाकीट घालतात.\"},{\"q\":\"वस्त्रोद्योगात वापरला जाणारा कच्चा माल कोणता?\",\"options\":[\"कापूस\",\"पॉलिस्टर\",\"सिल्क\",\"सर्व वरील\"],\"answer\":3,\"explain\":\"कापूस, पॉलिस्टर, सिल्क हे सर्व कच्चे माल आहेत.\"},{\"q\":\"कपड्यांच्या उत्पादनात मुख्यतः कोणते कामगार लागतात?\",\"options\":[\"बुकर\",\"सुईकार\",\"कापडकार\",\"सर्व वरील\"],\"answer\":3,\"explain\":\"सर्व कामगार एकत्रितपणे काम करतात.\"},{\"q\":\"महाराष्ट्रातील प्रसिद्ध साडीचे नाव काय आहे?\",\"options\":[\"पैठणी\",\"सोलापूरची चादर\",\"हिमरू शाली\",\"इतर\"],\"answer\":0,\"explain\":\"पैठणी ही महाराष्ट्रातील प्रसिद्ध साडी आहे.\"},{\"q\":\"वस्त्रोद्योग केंद्राला भेट देताना काय करावे?\",\"options\":[\"कच्चा माल खरेदी करणे\",\"कामगारांना विचारणे\",\"उत्पादन पाहणे\",\"सर्व वरील\"],\"answer\":3,\"explain\":\"सर्व गोष्टी कराव्यात.\"},{\"q\":\"कपड्यांमध्ये \'हव्यास\' म्हणजे काय?\",\"options\":[\"गरज\",\"इच्छा\",\"दोन्ही\",\"काहीही नाही\"],\"answer\":2,\"explain\":\"हव्यास म्हणजे गरज नसताना इच्छा.\"},{\"q\":\"उन्हाळ्यात कोणते कपडे घालतात?\",\"options\":[\"साडी\",\"पोलो शर्ट\",\"जॅकेट\",\"कुर्ता\"],\"answer\":1,\"explain\":\"उन्हाळ्यात पोलो शर्ट आणि हलके कपडे घालतात.\"},{\"q\":\"वस्त्रोद्योगात कच्चा माल कोठून आणला जातो?\",\"options\":[\"सामान्य बाजार\",\"कच्चा माल बाजार\",\"आयात\",\"सर्व वरील\"],\"answer\":3,\"explain\":\"सर्व ठिकाणांहून कच्चा माल आणला जातो.\"},{\"q\":\"वस्त्रांच्या विविधतेचे मुख्य कारण काय आहे?\",\"options\":[\"हवामान\",\"संस्कृती\",\"कौशल्य\",\"सर्व वरील\"],\"answer\":3,\"explain\":\"हवामान, संस्कृती आणि कौशल्य यांचा प्रभाव असतो.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16800,24,5,'EVS Part 1','mr','पर्यावरण आणि आपण','[\"जंगलात सजीवांना अन्न व पाणी मिळते, जंगलतोड झाल्यास हे स्रोत कमी होतात.\",\"जंगलात राहणारे प्राणी व पक्षी इतरत्र स्थलांतर करतात, कारण निवारा व अन्न कमी होते.\",\"जंगलातील वनस्पती व प्राणी यांची वास्तव्य जागा कमी होते, ज्यामुळे जैवविविधता घटते.\",\"लोहमार्ग व धरण बांधण्यासाठी जंगलतोड केल्याने अनेक प्राण्यांचे निवास नष्ट होते.\",\"हवा प्रदूषणाचे प्रमुख कारण इंधन ज्वलनामुळे कार्बन डायऑक्साइड व विषारी वायूंची निर्मिती.\",\"इंधन (पेट्रोल, डिझेल, केरोसीन, नैसर्गिक वायू, कोळसा, लाकूड) वाहतूक, उद्योग व घरगुती गरजांसाठी वापरले जाते.\",\"उद्योगांचे सांडपाणी व धुराड्यांमधून बाहेर पडणारे विषारी वायू जल व हवा प्रदूषित करतात.\",\"जैविक घटक (वनस्पती, प्राणी) प्रदूषणामुळे नष्ट होतात, ज्यामुळे अन्नसाखळी तुटते.\",\"जैवविविधता उद्याने, राष्ट्रीय उद्याने व अभयारण्ये हे वन्यजीव व वनस्पतींचे संरक्षण करतात.\",\"जंगलतोड व प्रदूषणामुळे हवामान बदल होतो, तापमान वाढते.\",\"जंगलातील प्राणी व पक्षी स्थलांतर करतात, ज्यामुळे त्यांच्या प्रजननावर परिणाम होतो.\",\"वनस्पतींची संख्या कमी झाल्यास प्राण्यांची अन्नसाखळी तुटते.\",\"जैवविविधता जपण्यासाठी वृक्षारोपण व संरक्षण कार्यक्रम आवश्यक आहेत.\",\"जगभरात जैवविविधता उद्याने व अभयारण्ये स्थापन करून संरक्षण केले जाते.\",\"जंगलतोड व प्रदूषणामुळे मानवी आरोग्यावर व पर्यावरणावर नकारात्मक परिणाम होतो.\",\"जंगलातील पाणी व मातीची गुणवत्ता घटल्याने शेतीवर व मानवी जीवनावर परिणाम होतो.\",\"वनस्पती व प्राणी यांचा समतोल राखण्यासाठी निसर्गाचे संतुलन जपणे गरजेचे आहे.\",\"जंगलतोड व प्रदूषणामुळे अन्नसाखळीतील कडी नष्ट झाल्यास संपूर्ण जीवसृष्टीला धोका.\",\"जैवविविधता उद्याने व अभयारण्ये हे जैविक व अजैविक घटकांचे संरक्षण करतात.\",\"वनस्पती व प्राणी यांची संख्या वाढवण्यासाठी वृक्षारोपण व संरक्षण कार्यक्रम चालवणे आवश्यक.\",\"जंगलातील प्राणी व पक्षी यांची संख्या घटल्यास अन्नसाखळीतील इतर प्रजातींवर परिणाम होतो.\",\"जंगलतोड व प्रदूषणामुळे हवामान बदल व पर्यावरणीय संतुलन बिघडते.\",\"जैवविविधता जपण्यासाठी आंतरराष्ट्रीय स्तरावर विविध प्रकल्प राबवले जातात.\",\"वनस्पती व प्राणी यांचे संरक्षण केल्याने मानवी जीवनमान सुधारते.\",\"जंगलतोड व प्रदूषणामुळे मानवी आरोग्य व जीवनशैलीवर विपरीत परिणाम होतो.\"]','[{\"q\":\"जंगलतोड झाल्यास जंगलातील सजीवांना काय होईल?\",\"options\":[\"अन्न व पाण्याचे स्रोत वाढतील\",\"अन्न व पाण्याचे स्रोत कमी होतील\",\"अन्न व पाण्याचे स्रोत तसंच राहतील\",\"अन्न व पाण्याचे स्रोत बदलतील\"],\"answer\":1,\"explain\":\"जंगलतोडमुळे अन्न व पाण्याचे स्रोत कमी होतात.\"},{\"q\":\"हवा प्रदूषणाचे प्रमुख कारण कोणते?\",\"options\":[\"पाण्याचे सांडपाणी\",\"इंधन ज्वलन\",\"वनस्पतींची वाढ\",\"मातीची धूप\"],\"answer\":1,\"explain\":\"इंधन ज्वलनामुळे विषारी वायू व कार्बन डायऑक्साइड तयार होतो.\"},{\"q\":\"इंधन म्हणून सर्वाधिक वापरले जाणारे इंधन कोणते?\",\"options\":[\"पेट्रोल\",\"नैसर्गिक वायू\",\"कोळसा\",\"सर्व वरील\"],\"answer\":3,\"explain\":\"पेट्रोल, डिझेल, केरोसीन, नैसर्गिक वायू, कोळसा व लाकूड सर्व इंधन म्हणून वापरले जातात.\"},{\"q\":\"जंगलातील प्राणी व पक्षी स्थलांतर का करतात?\",\"options\":[\"अन्न व पाण्याचे स्रोत वाढल्यामुळे\",\"निवारा व अन्न कमी झाल्यामुळे\",\"वनस्पती वाढल्यामुळे\",\"मातीची गुणवत्ता वाढल्यामुळे\"],\"answer\":1,\"explain\":\"निवारा व अन्न कमी झाल्यामुळे ते स्थलांतर करतात.\"},{\"q\":\"जैवविविधता उद्यानाचे मुख्य उद्दिष्ट काय?\",\"options\":[\"वनस्पती व प्राणी नष्ट करणे\",\"वनस्पती व प्राणी संरक्षण व अभ्यास\",\"उद्योग वाढवणे\",\"हवामान बदल करणे\"],\"answer\":1,\"explain\":\"जैवविविधता उद्यानात वनस्पती व प्राणी संरक्षण व अभ्यास केला जातो.\"},{\"q\":\"प्रदूषणामुळे कोणत्या घटकावर सर्वाधिक परिणाम होतो?\",\"options\":[\"वनस्पती\",\"प्राणी\",\"पाणी\",\"सर्व वरील\"],\"answer\":3,\"explain\":\"प्रदूषणामुळे वनस्पती, प्राणी व पाणी सर्व प्रभावित होतात.\"},{\"q\":\"जंगलतोड व प्रदूषणामुळे हवामानावर काय परिणाम होतो?\",\"options\":[\"तापमान कमी होते\",\"तापमान वाढते\",\"हवामान बदलत नाही\",\"हवामान स्थिर राहते\"],\"answer\":1,\"explain\":\"प्रदूषणामुळे तापमान वाढते.\"},{\"q\":\"वनस्पती व प्राणी यांचा समतोल राखण्यासाठी काय करावे?\",\"options\":[\"वृक्षारोपण व संरक्षण कार्यक्रम\",\"फक्त उद्योग वाढवणे\",\"फक्त पाणी वापरणे\",\"फक्त कचरा फेकणे\"],\"answer\":0,\"explain\":\"वृक्षारोपण व संरक्षण कार्यक्रम आवश्यक आहेत.\"},{\"q\":\"अभयारण्याचे मुख्य कार्य काय?\",\"options\":[\"प्राण्यांना अन्न देणे\",\"वनस्पती व प्राणी संरक्षण\",\"उद्योग स्थापन करणे\",\"पाणी शुद्ध करणे\"],\"answer\":1,\"explain\":\"अभयारण्ये प्राण्यांचे व वनस्पतींचे संरक्षण करतात.\"},{\"q\":\"जंगलातील प्राणी व पक्षी यांची संख्या घटल्यास काय होते?\",\"options\":[\"अन्नसाखळी तुटते\",\"अन्नसाखळी मजबूत होते\",\"वनस्पती वाढतात\",\"माती सुधारते\"],\"answer\":0,\"explain\":\"प्राण्यांची संख्या घटल्याने अन्नसाखळी तुटते.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16801,24,5,'EVS Part 1','mr','अन्नघटक','[\"आहार म्हणजे शरीराला आवश्यक असणारे अन्नपदार्थ\",\"अन्नघटक तीन प्रकारचे असतात – पिष्टमय पदार्थ, शर्करा व तंतुमय पदार्थ\",\"पिष्टमय पदार्थ (कर्बोदके) शरीराला ऊर्जा देतात\",\"शर्करा म्हणजे गोड पदार्थ, ज्यातूनही ऊर्जा मिळते\",\"तंतुमय पदार्थ पचनात मदत करतात व बद्धकोष्ठता टाळतात\",\"स्निग्ध पदार्थ (चरबी) शरीराला उष्णता व संरक्षण देतात\",\"प्रथिने शरीराच्या वाढीसाठी व दुरुस्तीसाठी आवश्यक आहेत\",\"जीवनसत्त्वे व खनिजे अल्प प्रमाणात असली तरी महत्त्वाची आहेत\",\"संतुलित आहारात सर्व अन्नघटक योग्य प्रमाणात असावेत\",\"कर्बोदके मुख्यतः धान्ये व कडधान्यांमध्ये असतात\",\"तंतुमय पदार्थ फळे, भाज्या व धान्यांच्या सालीत असतात\",\"स्निग्ध पदार्थ तेल, लोणी व अंड्याच्या बलकात असतात\",\"प्रथिने दूध, अंडी व कडधान्यांमध्ये असतात\",\"जीवनसत्त्वे व खनिजे फळे व भाज्यांमध्ये असतात\",\"कुपोषण म्हणजे एखाद्या अन्नघटकाची कमतरता\",\"अल्प प्रमाणात आवश्यक असलेल्या अन्नघटकांना जीवनसत्त्वे व खनिजे म्हणतात\",\"अन्नघटकांची कमतरता झाल्यास शरीराची वाढ खुंटते\",\"अन्नघटकांचे स्रोत ओळखून संतुलित आहार घ्यावा\",\"अन्नघटकांचे योग्य प्रमाण शरीराला ऊर्जा व आरोग्य देते\",\"प्रत्येक अन्नघटकाचे स्रोत व उपयोग लक्षात ठेवणे महत्त्वाचे आहे\",\"संतुलित आहाराने शरीराची रोगप्रतिकारक शक्ती वाढते\",\"अन्नघटकांच्या कमतरतेमुळे थकवा व आजार होऊ शकतात\",\"अन्नघटकांचे विविध स्रोत ओळखून आहारात समाविष्ट करणे आवश्यक आहे\",\"अन्नघटकांचे योग्य प्रमाण शरीराला संतुलित पोषण देते\",\"अल्प प्रमाणात आवश्यक अन्नघटकांना जीवनसत्त्वे व खनिजे म्हणतात\"]','[{\"q\":\"पिष्टमय पदार्थांना काय म्हणतात?\",\"options\":[\"कर्बोदके\",\"शर्करा\",\"तंतुमय पदार्थ\",\"स्निग्ध पदार्थ\"],\"answer\":0,\"explain\":\"पिष्टमय पदार्थांना कर्बोदके म्हणतात.\"},{\"q\":\"शरीरात ऊर्जा मिळवण्यासाठी मुख्यतः कोणते अन्नघटक वापरले जातात?\",\"options\":[\"कर्बोदके\",\"स्निग्ध पदार्थ\",\"प्रथिने\",\"जीवनसत्त्वे\"],\"answer\":0,\"explain\":\"कर्बोदके शरीराला ऊर्जा देतात.\"},{\"q\":\"तंतुमय पदार्थांचा मुख्य उपयोग काय आहे?\",\"options\":[\"ऊर्जा देणे\",\"पचनात मदत करणे\",\"रोगप्रतिकारक शक्ती वाढवणे\",\"चरबी साठवणे\"],\"answer\":1,\"explain\":\"तंतुमय पदार्थ पचनात मदत करतात.\"},{\"q\":\"स्निग्ध पदार्थ शरीराला काय संरक्षण देतात?\",\"options\":[\"उष्णता राखणे\",\"पचनास मदत करणे\",\"ऊर्जा मिळवणे\",\"पाणी शोषणे\"],\"answer\":0,\"explain\":\"स्निग्ध पदार्थ शरीराला उष्णता व संरक्षण देतात.\"},{\"q\":\"प्रथिनांचे मुख्य स्रोत कोणते?\",\"options\":[\"दूध व अंडी\",\"तेल व लोणी\",\"फळे व भाज्या\",\"धान्ये व कडधान्ये\"],\"answer\":3,\"explain\":\"प्रथिनांचे मुख्य स्रोत धान्ये व कडधान्ये आहेत.\"},{\"q\":\"जीवनसत्त्वे व खनिजे किती प्रमाणात आवश्यक असतात?\",\"options\":[\"जास्त\",\"कमी\",\"मध्यम\",\"असंगत\"],\"answer\":1,\"explain\":\"जीवनसत्त्वे व खनिजे अल्प प्रमाणात आवश्यक असतात.\"},{\"q\":\"कुपोषण म्हणजे काय?\",\"options\":[\"अन्नघटकांची जास्ती\",\"अन्नघटकांची कमतरता\",\"अन्नघटकांची समतोलता\",\"अन्नघटकांची विविधता\"],\"answer\":1,\"explain\":\"कुपोषण म्हणजे अन्नघटकांची कमतरता.\"},{\"q\":\"कर्बोदके मुख्यतः कोणत्या अन्नपदार्थांमध्ये आढळतात?\",\"options\":[\"फळे व भाज्या\",\"दूध व अंडी\",\"धान्ये व कडधान्ये\",\"तेल व लोणी\"],\"answer\":2,\"explain\":\"कर्बोदके धान्ये व कडधान्यांमध्ये असतात.\"},{\"q\":\"शरीराला ऊर्जा मिळवण्यासाठी स्निग्ध पदार्थांची भूमिका काय आहे?\",\"options\":[\"कर्बोदकांपेक्षा कमी ऊर्जा देतात\",\"कर्बोदकांपेक्षा दुप्पट ऊर्जा देतात\",\"कर्बोदकांप्रमाणेच ऊर्जा देतात\",\"ऊर्जा देत नाहीत\"],\"answer\":1,\"explain\":\"स्निग्ध पदार्थ कर्बोदकांपेक्षा दुप्पट ऊर्जा देतात.\"},{\"q\":\"संतुलित आहारात कोणते अन्नघटक असावेत?\",\"options\":[\"फक्त कर्बोदके\",\"फक्त प्रथिने\",\"फक्त स्निग्ध पदार्थ\",\"सर्व अन्नघटक\"],\"answer\":3,\"explain\":\"संतुलित आहारात सर्व अन्नघटक असावेत.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16802,24,5,'EVS Part 1','mr','आपले भावनिक जग','[\"भावना म्हणजे मनात येणारी विविध अनुभूती – आनंद, राग, दुःख, मत्सर इत्यादी.\",\"भावनिक समायोजन म्हणजे आपल्या भावनांचा योग्य मेळ घालून त्यांना संतुलित आणि नियंत्रित ठेवणे.\",\"भावना नियंत्रित केल्याने व्यक्तिमत्त्व संतुलित होते आणि इतरांना समजून घेण्याची क्षमता वाढते.\",\"राग जास्त आणि वारंवार आल्यास डोकेदुखी, निद्रानाश, निरुत्साह यासारखे शारीरिक व मानसिक दुष्परिणाम होतात.\",\"रागावर नियंत्रण ठेवण्यासाठी प्रथम कारण ओळखून शांतपणे विचार करावा.\",\"रागाच्या जागी सहानुभूती, क्षमा आणि समंजसपणा दाखवणे महत्त्वाचे आहे.\",\"उणिवा ओळखून त्यावर प्रयत्न केल्यास स्वभावात बदल घडतो.\",\"इतरांना दोष देणे टाळून, त्यांच्या गुणांची प्रशंसा केल्याने नातेसंबंध सुधारतात.\",\"भावना व्यक्त करताना योग्य शब्द आणि प्रमाण निवडणे आवश्यक आहे.\",\"स्वभावातील दोष ओळखून त्यावर काम केल्याने आत्मविश्वास वाढतो.\",\"आपल्या क्षमतांबरोबर उणिवांची जाणीव ठेवून त्यावर मात करण्याचा प्रयत्न करावा.\",\"भावना नियंत्रित केल्याने शाळेत आणि घरात दोन्ही ठिकाणी चांगले वर्तन होते.\",\"राग आला तरी प्रथम श्वास घेऊन शांत होऊन नंतर बोलणे चांगले.\",\"इतरांना मदत केल्याने आपल्याला आनंद आणि समाधान मिळते.\",\"भावना व्यक्त करताना इतरांच्या भावना लक्षात घेणे आवश्यक आहे.\",\"स्वभाव बदलण्यासाठी दररोज लहान लहान प्रयत्न करणे गरजेचे आहे.\",\"भावना नियंत्रित केल्याने शारीरिक आरोग्य सुधारते.\",\"रागावर नियंत्रण ठेवणे म्हणजे स्वतःला आणि इतरांना सुरक्षित ठेवणे.\",\"भावना व्यक्त करताना शब्दांची निवड काळजीपूर्वक करावी.\",\"भावना नियंत्रित करण्यासाठी ध्यान, श्वासोच्छवास आणि संवाद उपयुक्त आहेत.\",\"भावना नियंत्रित केल्याने आपले निर्णय अधिक तर्कसंगत होतात.\",\"भावना नियंत्रित केल्याने शाळेतील व घरातील नातेसंबंध सुधारतात.\",\"भावना नियंत्रित केल्याने आपले जीवन अधिक सुखी होते.\"]','[{\"q\":\"भावना म्हणजे काय?\",\"options\":[\"मनातील अनुभूती\",\"शारीरिक आजार\",\"भोजनाची पद्धत\",\"शाळेतील विषय\"],\"answer\":0,\"explain\":\"भावना म्हणजे मनात येणारी विविध अनुभूती.\"},{\"q\":\"भावनिक समायोजन काय म्हणतात?\",\"options\":[\"भावना वाढवणे\",\"भावना नियंत्रित करणे\",\"भावना नष्ट करणे\",\"भावना दुर्लक्ष करणे\"],\"answer\":1,\"explain\":\"भावनिक समायोजन म्हणजे भावनांचा योग्य मेळ घालणे.\"},{\"q\":\"राग जास्त झाल्यास काय होऊ शकते?\",\"options\":[\"डोकेदुखी\",\"हसणे\",\"उत्साह\",\"आनंद\"],\"answer\":0,\"explain\":\"राग जास्त झाल्यास डोकेदुखी, निद्रानाश इत्यादी होऊ शकतात.\"},{\"q\":\"रागावर नियंत्रण ठेवण्यासाठी काय करावे?\",\"options\":[\"शांतपणे विचार करणे\",\"आवाज उठवणे\",\"इतरांना दोष देणे\",\"भोजन टाळणे\"],\"answer\":0,\"explain\":\"रागावर नियंत्रण ठेवण्यासाठी प्रथम शांतपणे विचार करावा.\"},{\"q\":\"उणिवा ओळखून त्यावर प्रयत्न केल्यास काय होते?\",\"options\":[\"स्वभाव बदलतो\",\"स्वभाव तसाच राहतो\",\"स्वभाव खराब होतो\",\"स्वभाव बिघडतो\"],\"answer\":0,\"explain\":\"उणिवा ओळखून प्रयत्न केल्यास स्वभाव बदलतो.\"},{\"q\":\"इतरांना दोष देणे टाळल्यास काय होते?\",\"options\":[\"नातेसंबंध सुधारतात\",\"नातेसंबंध खराब होतात\",\"काही बदल होत नाही\",\"इतरांना राग येतो\"],\"answer\":0,\"explain\":\"दोष न दिल्यास नातेसंबंध सुधारतात.\"},{\"q\":\"भावना व्यक्त करताना काय लक्षात ठेवावे?\",\"options\":[\"इतरांच्या भावना\",\"फक्त स्वतःच्या भावना\",\"शब्दांची निवड नाही\",\"आवाजाचा टोन नाही\"],\"answer\":0,\"explain\":\"भावना व्यक्त करताना इतरांच्या भावना लक्षात ठेवाव्या.\"},{\"q\":\"रागावर नियंत्रण ठेवण्यासाठी उपयुक्त काय आहे?\",\"options\":[\"ध्यान\",\"आवाज वाढवणे\",\"भोजन टाळणे\",\"इतरांना दोष देणे\"],\"answer\":0,\"explain\":\"ध्यान आणि श्वासोच्छवास रागावर नियंत्रण ठेवण्यासाठी उपयुक्त आहेत.\"},{\"q\":\"भावना नियंत्रित केल्याने काय फायदा होतो?\",\"options\":[\"शारीरिक आरोग्य सुधारते\",\"आहार कमी होतो\",\"शाळेतून बाहेर पडता येते\",\"काहीच नाही\"],\"answer\":0,\"explain\":\"भावना नियंत्रित केल्याने शारीरिक व मानसिक आरोग्य सुधारते.\"},{\"q\":\"भावना नियंत्रित केल्याने निर्णय कसे होतात?\",\"options\":[\"अधिक तर्कसंगत\",\"अधिक भावनिक\",\"अधिक अनिश्चित\",\"काहीच नाही\"],\"answer\":0,\"explain\":\"भावना नियंत्रित केल्याने निर्णय अधिक तर्कसंगत होतात.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16803,24,5,'EVS Part 1','mr','कामांत व्यस्त आपली आंतरेंद्रिये','[\"श्वसन म्हणजे शरीरात ऑक्सिजन घेऊन कार्बन डायऑक्साइड बाहेर टाकणे होय.\",\"श्वसनाचे प्रमुख अवयव नाक, श्वासनलिका, फुप्फुसे आणि श्वासपटल आहेत.\",\"श्वसनाची पोकळी फुप्फुसात असते, जिथे वायूंची देवाणघेवाण होते.\",\"श्वसनाचे कार्य शरीराला ऑक्सिजन पुरवणे आणि कार्बन डायऑक्साइड काढून टाकणे हे आहे.\",\"श्वसनाचे संरक्षण करणारी हाडे म्हणजे छातीची पिंजरे (स्टर्नम, पसळी आणि कशेरुक).\",\"पचन म्हणजे अन्नाचे शरीरात शोषण होणारे रासायनिक आणि यांत्रिक प्रक्रिया.\",\"पचनाचे प्रमुख अवयव तोंड, अन्ननलिका, जठर, लहान आतडे आणि मोठे आतडे आहेत.\",\"पचनात लाळ आणि पाचकरस (पाचक रस) महत्त्वाची भूमिका बजावतात.\",\"पचनादरम्यान अन्न पचनक्रियेने लहान तुकड्यांमध्ये विभागले जाते.\",\"पचनातून तयार झालेले पोषक तत्त्वे रक्तात शोषले जातात आणि शरीरात वितरित होतात.\",\"रक्ताभिसरण म्हणजे रक्ताचे शरीरभर फिरणे, ज्यामुळे ऑक्सिजन व पोषक तत्त्वे पोहोचतात.\",\"रक्ताभिसरणाचे प्रमुख अवयव हृदय, रक्तवाहिन्या आणि रक्त आहेत.\",\"हृदय सतत आकुंचन-शिथिलीकरण करून रक्त पंप करते.\",\"चेतासंस्था म्हणजे मेंदू आणि चेतातंतूंचे जाळे, जे शरीरातील सर्व क्रिया समन्वयित करते.\",\"चेतासंस्थेचे प्रमुख अवयव मेंदू, चेतातंतू आणि मेंदूचे तंतु आहेत.\",\"श्वसन, पचन, रक्ताभिसरण आणि चेतासंस्था या सर्वांना एकत्रितपणे शरीराची \'इंद्रियसंस्था\' म्हणतात.\",\"श्वसनात धूळ व धुराचे कण श्वसनमार्गात अडकतात, ज्यामुळे श्वसनाचे आजार होऊ शकतात.\",\"धूम्रपानामुळे फुप्फुसात श्लेष्म जमा होते आणि ऑक्सिजन पुरवठा कमी होतो.\",\"मद्यपानामुळे चेतासंस्थेवर परिणाम होऊन समन्वय कमी होतो.\",\"शरीरातील ऊर्जा मिळवण्यासाठी श्वसन, पचन आणि रक्ताभिसरण हे एकत्र काम करतात.\",\"दातांना एनॅमल नावाचे कठीण आवरण असते, ज्यामुळे दातांचे संरक्षण होते.\",\"दातांची नियमित स्वच्छता न केल्यास दात किडतात.\",\"शरीरातील पाणी पचनक्रियेकरिता आवश्यक आहे, पाणी कमी झाल्यास पचनात अडचण येते.\",\"शरीरात पचनादरम्यान तयार होणारे विष्ठा मोठ्या आतड्यातून बाहेर टाकले जाते.\",\"शरीरातील सर्व अवयव एकमेकांशी संवाद साधून समन्वय राखतात.\"]','[{\"q\":\"श्वसन प्रणालीमध्ये हवा शरीरात प्रवेश करणारा मुख्य अवयव कोणता आहे?\",\"options\":[\"नाक\",\"तोंड\",\"फुप्फुसे\",\"हृदय\"],\"answer\":0,\"explain\":\"नाक आणि तोंड हे हवा घेण्यासाठी मार्ग आहेत, पण मुख्य अवयव फुप्फुसे आहेत.\"},{\"q\":\"पचनक्रियेतील अन्न जठरात पोहोचल्यावर काय होते?\",\"options\":[\"पाणी शोषले जाते\",\"अन्न पाण्याशिवाय तुटते\",\"पचन रसात मिसळते\",\"अन्न तोंडात परत जाते\"],\"answer\":2,\"explain\":\"जठरात पचन रस मिसळून अन्नाचे विघटन सुरू होते.\"},{\"q\":\"शरीरात ऑक्सिजनची देवाणघेवाण कोणत्या अवयवात होते?\",\"options\":[\"हृदय\",\"फुप्फुसे\",\"पोट\",\"मलाशय\"],\"answer\":1,\"explain\":\"फुप्फुसे ऑक्सिजन आणि कार्बन डायऑक्साइडची देवाणघेवाण करतात.\"},{\"q\":\"श्वसनातील ‘श्वासपटल’ म्हणजे काय?\",\"options\":[\"नाकातील नळी\",\"फुप्फुसांची पिशवी\",\"श्वासनलिकेचा भाग\",\"हृदयाचा भाग\"],\"answer\":2,\"explain\":\"श्वासपटल म्हणजे श्वासनलिकेचा भाग.\"},{\"q\":\"पचनसंस्थेतील ‘पाचकरस’ म्हणजे काय?\",\"options\":[\"पचन रस\",\"लाळ\",\"श्लेष्मा\",\"रक्त\"],\"answer\":0,\"explain\":\"पाचकरस म्हणजे पचन रस.\"},{\"q\":\"शरीरातील रक्ताभिसरणाचे मुख्य कार्य काय आहे?\",\"options\":[\"ऑक्सिजन पुरवणे\",\"पोषक द्रव्य पोचवणे\",\"दोन्ही\",\"पाणी शोषणे\"],\"answer\":2,\"explain\":\"रक्ताभिसरण ऑक्सिजन व पोषक द्रव्य दोन्ही पोचवते.\"},{\"q\":\"धूम्रपानामुळे फुप्फुसांमध्ये काय होते?\",\"options\":[\"ऑक्सिजन वाढतो\",\"श्लेष्मा कमी होतो\",\"वायूंची देवाणघेवाण कमी होते\",\"हृदयाची गती वाढते\"],\"answer\":2,\"explain\":\"धूम्रपानामुळे श्लेष्मा वाढतो व वायूंची देवाणघेवाण कमी होते.\"},{\"q\":\"मेंदू आणि चेतासंस्थेचे मुख्य कार्य काय आहे?\",\"options\":[\"समन्वय राखणे\",\"पचन करणे\",\"श्वसन करणे\",\"रक्ताभिसरण\"],\"answer\":0,\"explain\":\"मेंदू चेतासंस्थेचे नियंत्रण करून शरीराचे समन्वय राखतो.\"},{\"q\":\"शरीरात पाणी शोषले जाणारे अवयव कोणते?\",\"options\":[\"जठर\",\"लहान आतडे\",\"मोठे आतडे\",\"सर्व\"],\"answer\":3,\"explain\":\"पाणी लहान व मोठ्या आतड्यातून शोषले जाते.\"},{\"q\":\"शरीरातील ‘अन्ननलिका’ आणि ‘श्वासनलिका’ यांचा संबंध काय?\",\"options\":[\"एकमेकांपासून वेगळे आहेत\",\"दोन्ही एकाच नळीचे भाग आहेत\",\"दोन्ही फुप्फुसात जातात\",\"दोन्ही पचनात मदत करतात\"],\"answer\":1,\"explain\":\"अन्ननलिका आणि श्वासनलिका एकाच नळीचे दोन भाग आहेत.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16804,24,5,'EVS Part 1','mr','वाढ आणि व्यक्तिमत्त्व विकास','[\"वाढ म्हणजे शरीराची उंची व वजन वाढणे.\",\"विकास म्हणजे नवीन कौशल्ये शिकणे आणि त्यांचा वापर करणे.\",\"बाळाचे पहिले कौशल्य म्हणजे हाताने वस्तू उचलणे.\",\"दोन वर्षांच्या मुलांना कपडे घालणे, बोटांनी वस्तू पकडणे शिकतात.\",\"तीन वर्षांच्या नंतर चालणे, धावणे, पळणे शिकतात.\",\"वय वाढल्यावर शरीराची ताकद व समन्वय वाढतो.\",\"आनुवंशिकता म्हणजे आई-वडिलांकडून मिळणारी गुणधर्मे.\",\"कौशल्ये शिकण्यासाठी सराव व निरीक्षण आवश्यक आहे.\",\"चांगला आहार व व्यायाम विकासाला मदत करतात.\",\"विकासाची पातळी व्यक्तीपरत्वे वेगळी असते.\",\"उंची व वजन जन्मापासून वृद्धावस्थेपर्यंत वाढतात.\",\"शारीरिक वाढ म्हणजे शरीराचे आकारमान व वजन वाढणे.\",\"मानसिक विकास म्हणजे विचार व वर्तनात बदल होणे.\",\"कौशल्ये आत्मसात केल्याने इतरांवर कमी अवलंबित्व राहते.\",\"विकासाच्या टप्प्यांमध्ये शारीरिक, मानसिक व सामाजिक बदल होतात.\"]','[{\"q\":\"बाळाचे पहिले कौशल्य काय असते?\",\"options\":[\"हाताने वस्तू उचलणे\",\"धावणे\",\"गाणे गाणे\",\"पोहणे\"],\"answer\":0,\"explain\":\"बाळाला हाताने वस्तू उचलणे हे सर्वात पहिले कौशल्य असते.\"},{\"q\":\"आनुवंशिकता म्हणजे काय?\",\"options\":[\"शिकलेल्या कौशल्ये\",\"आहाराची सवय\",\"आई-वडिलांकडून मिळणारी गुणधर्मे\",\"व्यायामाची पद्धत\"],\"answer\":2,\"explain\":\"आनुवंशिकता म्हणजे जन्मतःच मिळणारी गुणधर्मे.\"},{\"q\":\"दोन वर्षांच्या मुलांना काय शिकायला मिळते?\",\"options\":[\"सायकल चालवणे\",\"कपडे घालणे\",\"पोहणे\",\"गाणे\"],\"answer\":1,\"explain\":\"दोन वर्षांच्या मुलांना कपडे घालणे व बोटांनी वस्तू पकडणे शिकतात.\"},{\"q\":\"विकासाच्या टप्प्यात शरीराची ताकद कशी वाढते?\",\"options\":[\"आहार बदलून\",\"व्यायाम करून\",\"वय वाढून\",\"कौशल्ये न शिकता\"],\"answer\":2,\"explain\":\"वय वाढल्यावर शरीराची ताकद व समन्वय वाढतो.\"},{\"q\":\"शारीरिक वाढ म्हणजे काय?\",\"options\":[\"मानसिक विकास\",\"उंची व वजन वाढणे\",\"कौशल्ये शिकणे\",\"आहार घेणे\"],\"answer\":1,\"explain\":\"शारीरिक वाढ म्हणजे उंची व वजन वाढणे.\"},{\"q\":\"कौशल्ये शिकण्यासाठी काय आवश्यक आहे?\",\"options\":[\"फक्त सराव\",\"फक्त निरीक्षण\",\"सराव व निरीक्षण\",\"फक्त आहार\"],\"answer\":2,\"explain\":\"कौशल्ये शिकण्यासाठी सराव व निरीक्षण दोन्ही आवश्यक आहेत.\"},{\"q\":\"विकासाच्या टप्प्यात कोणते बदल होतात?\",\"options\":[\"फक्त शारीरिक\",\"फक्त मानसिक\",\"शारीरिक व मानसिक\",\"फक्त सामाजिक\"],\"answer\":2,\"explain\":\"विकासात शारीरिक व मानसिक दोन्ही बदल होतात.\"},{\"q\":\"बाळाला वस्तू तोंडाकडे नेणे कधी शिकते?\",\"options\":[\"पहिल्या वर्षात\",\"दुसऱ्या वर्षात\",\"तिसऱ्या वर्षात\",\"चौथ्या वर्षात\"],\"answer\":1,\"explain\":\"दुसऱ्या वर्षात बाळ वस्तू तोंडाकडे नेणे शिकते.\"},{\"q\":\"विकासाच्या टप्प्यात कोणते कौशल्ये आपोआप येतात?\",\"options\":[\"सायकल चालवणे\",\"धावणे\",\"पोहणे\",\"पुस्तक वाचणे\"],\"answer\":1,\"explain\":\"धावणे व चालणे हे सुरुवातीच्या टप्प्यात आपोआप येतात.\"},{\"q\":\"विकासाच्या टप्प्यात कौशल्ये आत्मसात केल्याने काय होते?\",\"options\":[\"इतरांवर अवलंबित्व वाढते\",\"इतरांवर अवलंबित्व कमी होते\",\"आनुवंशिकता बदलते\",\"आहार कमी होतो\"],\"answer\":1,\"explain\":\"कौशल्ये आत्मसात केल्याने इतरांवर अवलंबित्व कमी होते.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16805,24,5,'EVS Part 1','mr','संसर्गजन्य रोग आणि रोगप्रतिबंध','[\"संसर्गजन्य रोग म्हणजे सूक्ष्मजीवांमुळे होणारे रोग.\",\"रोगजंतू म्हणजे रोग निर्माण करणारे सूक्ष्मजीव.\",\"प्रत्येक रोगाचा एक विशिष्ट रोगजंतू असतो.\",\"रोगप्रसाराची ४ मुख्य पद्धती – हवेमार्फत, पाण्याद्वारे, अन्नाद्वारे आणि थेट संपर्काद्वारे.\",\"हवेमार्फत प्रसारात शिंक, खोकला, थुंकीमधील जंतू हवेत पसरतात.\",\"पाण्याद्वारे प्रसारात विष्ठा किंवा दूषित पाणी रोगजंतू घेऊन जाते.\",\"अन्नाद्वारे प्रसारात अन्नावर माश्या बसणे किंवा कचरा मिसळणे रोगजंतू आणते.\",\"थेट संपर्कात त्वचेचा जखम, कपडे, रुमाल यांचा वापर होतो.\",\"रोगप्रतिबंध म्हणजे स्वच्छता, संतुलित आहार, लसीकरण आणि कीटकनाशकांचा वापर.\",\"लसीकरणाने शरीरात प्रतिकारशक्ती वाढते आणि रोग टाळता येतो.\",\"डास, पिसवा यांसारख्या कीटकांमुळे मलेरिया आणि इतर रोग पसरतात.\",\"हवेतून पसरलेल्या रोगांना टाळण्यासाठी शिंकताना रुमाल वापरावा.\",\"पाण्याचे निर्जंतुकीकरण करण्यासाठी ब्लीच किंवा उकळणे आवश्यक.\",\"अन्न झाकून ठेवणे आणि हात स्वच्छ धुणे हे अन्नाद्वारे प्रसार रोखतात.\",\"रोगजंतू शरीरात शिरल्यावर रोगप्रतिकारक प्रणाली लढते.\",\"रोगप्रसार टाळण्यासाठी घरात स्वच्छता, पाणी साचू न देणे, कीटकनाशक वापरणे महत्त्वाचे.\",\"रोगाची साथ झाल्यास त्वरित आरोग्य विभागाला कळवावे.\",\"संसर्गजन्य रोगांची लक्षणे – ताप, खोकला, पोटदुखी इत्यादी.\",\"रोगप्रसाराची पद्धत ओळखून योग्य प्रतिबंध उपाय निवडता येतात.\",\"रोगजंतूंची ओळख आणि त्यांचा प्रसार समजून घेणे आरोग्यविषयक निर्णय घेण्यासाठी आवश्यक.\"]','[{\"q\":\"संसर्गजन्य रोग कोणत्या सूक्ष्मजीवांमुळे होतात?\",\"options\":[\"बॅक्टेरिया\",\"वायरस\",\"फंगस\",\"वरील सर्व\"],\"answer\":3,\"explain\":\"संसर्गजन्य रोग बॅक्टेरिया, वायरस आणि फंगस अशा सूक्ष्मजीवांमुळे होतात.\"},{\"q\":\"रोगप्रसाराची कोणती पद्धत नाही?\",\"options\":[\"हवेमार्फत\",\"पाण्याद्वारे\",\"अन्नाद्वारे\",\"शरीरात स्वतःच पसरतो\"],\"answer\":3,\"explain\":\"रोगप्रसार बाह्य माध्यमांनी होतो, शरीरात स्वतः पसरत नाही.\"},{\"q\":\"खोकताना तोंडावर काय ठेवायला हवे?\",\"options\":[\"रुमाल\",\"कपडे\",\"पाणी\",\"मास्क\"],\"answer\":0,\"explain\":\"खोकताना रुमाल किंवा मास्क वापरावा.\"},{\"q\":\"मलेरियाचे जंतू कोणत्या कीटकाने पसरतात?\",\"options\":[\"डास\",\"पिसवा\",\"माश्या\",\"किडे\"],\"answer\":0,\"explain\":\"मलेरियाचे जंतू डासाने पसरतात.\"},{\"q\":\"पाण्याद्वारे रोगप्रसार टाळण्यासाठी काय करावे?\",\"options\":[\"पाणी उकळणे\",\"पाणी थंड ठेवणे\",\"पाणी थेट पिणे\",\"पाणी न पिणे\"],\"answer\":0,\"explain\":\"पाणी उकळून पिणे सुरक्षित असते.\"},{\"q\":\"अन्न झाकून ठेवणे का महत्त्वाचे?\",\"options\":[\"माश्या बसू नयेत\",\"कीटकांना अन्न मिळू नये\",\"अन्न खराब होऊ नये\",\"वरील सर्व\"],\"answer\":3,\"explain\":\"अन्न झाकून ठेवणे माश्या, कीटक आणि अन्न खराब होण्यापासून रोखते.\"},{\"q\":\"रोगजंतू शरीरात शिरल्यावर शरीर काय करते?\",\"options\":[\"रोग होतो\",\"रोगजंतू नष्ट होतात\",\"रोगप्रतिकारक प्रणाली लढते\",\"कोणतेही नाही\"],\"answer\":2,\"explain\":\"रोगप्रतिकारक प्रणाली रोगजंतूंचा सामना करते.\"},{\"q\":\"रोगप्रतिबंधात कोणते घटक समाविष्ट आहेत?\",\"options\":[\"स्वच्छता\",\"लसीकरण\",\"कीटकनाशक\",\"वरील सर्व\"],\"answer\":3,\"explain\":\"रोगप्रतिबंधात स्वच्छता, लसीकरण आणि कीटकनाशकांचा वापर होतो.\"},{\"q\":\"कॉलरा रोगजंतू कोणत्या माध्यमातून पसरतो?\",\"options\":[\"हवा\",\"पाणी\",\"अन्न\",\"दोन्ही पाणी आणि अन्न\"],\"answer\":3,\"explain\":\"कॉलरा पाणी आणि अन्न दोन्ही माध्यमातून पसरतो.\"},{\"q\":\"रोगाची साथ झाल्यास काय करावे?\",\"options\":[\"काहीही नाही\",\"घरातच राहावे\",\"आरोग्य विभागाला कळवावे\",\"सर्वजण पाणी पिणे थांबवावे\"],\"answer\":2,\"explain\":\"रोगाची साथ झाल्यास त्वरित आरोग्य विभागाला कळवावे.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16806,24,5,'EVS Part 1','mr','पदार्थ, वस्तू आणि ऊर्जा','[\"पदार्थ म्हणजे सूक्ष्म कणांनी बनलेला असतो.\",\"कण म्हणजे अतिशय लहान तुकडे, जे डोळ्यांना दिसत नाहीत.\",\"सर्व पदार्थ तीन अवस्थांमध्ये असू शकतात – स्थायू (घन), द्रव, वायू.\",\"पाण्याचे तीन अवस्थांमध्ये कण एकसारखे असतात, पण त्यांची मांडणी वेगळी असते.\",\"स्थायू पदार्थांना निश्चित आकार आणि आयतन असते.\",\"द्रव पदार्थांना निश्चित आयतन पण आकार बदलतो.\",\"वायू पदार्थांना ना निश्चित आकार ना आयतन असते.\",\"पदार्थाचे गुणधर्म: कठीणपणा, पारदर्शकता, रंग, वास, चव, पाण्यात विरघळणे.\",\"उर्जा म्हणजे कार्य करण्याची क्षमता.\",\"गतिज ऊर्जा म्हणजे गतीमुळे निर्माण होणारी ऊर्जा.\",\"उष्णता ऊर्जा म्हणजे तापमानामुळे निर्माण होणारी ऊर्जा.\",\"उर्जेचे स्रोत: इंधन (कोळसा, पेट्रोल, डिझेल), सूर्यप्रकाश, वारा, पाणी.\",\"सौरऊर्जा, पवनऊर्जा, जलऊर्जा हे न संपणारे ऊर्जास्रोत आहेत.\",\"ऊर्जेचे रूपांतर प्रकाश, ध्वनी, विद्युत इत्यादीमध्ये होऊ शकते.\",\"उर्जेचा वापर कमी करण्यासाठी पर्यायी स्रोतांचा वापर महत्त्वाचा आहे.\",\"पदार्थ आणि ऊर्जा हे दोन्ही जीवनात महत्त्वाचे आहेत.\",\"पदार्थाचे सूक्ष्म कण कसे बनतात हे प्रयोगांनी समजता येते.\",\"उर्जेचे रूपांतर करण्यासाठी ज्वलन, विद्युत केंद्र इत्यादी पद्धती वापरतात.\",\"पदार्थ आणि ऊर्जा यांच्यातील संबंध समजून घेणे आवश्यक आहे.\",\"सौरऊर्जेने विद्युत निर्मिती कशी होते हे शिकणे उपयुक्त आहे.\",\"पदार्थ आणि ऊर्जा या विषयावर प्रश्न विचारून ज्ञान वाढवा.\"]','[{\"q\":\"पदार्थाच्या तीन अवस्थांपैकी कोणती अवस्था घन असते?\",\"options\":[\"स्थायू\",\"द्रव\",\"वायू\",\"उष्णता\"],\"answer\":0,\"explain\":\"घन अवस्थेला स्थायू म्हणतात.\"},{\"q\":\"पाण्याचे तीन अवस्थांमध्ये कणांची मांडणी कशी असते?\",\"options\":[\"समान\",\"वेगळी\",\"असमान\",\"बदलत नाही\"],\"answer\":1,\"explain\":\"कणांची मांडणी अवस्थेनुसार बदलते.\"},{\"q\":\"गतिज ऊर्जा म्हणजे काय?\",\"options\":[\"उष्णतेची ऊर्जा\",\"गतीमुळे निर्माण होणारी ऊर्जा\",\"पाण्यात विरघळणारी ऊर्जा\",\"सौरऊर्जा\"],\"answer\":1,\"explain\":\"गतिज ऊर्जा गतीमुळे निर्माण होते.\"},{\"q\":\"खालीलपैकी कोणता न संपणारा ऊर्जास्रोत आहे?\",\"options\":[\"कोळसा\",\"पेट्रोल\",\"सौरऊर्जा\",\"खनिज तेल\"],\"answer\":2,\"explain\":\"सौरऊर्जा न संपणारी ऊर्जा आहे.\"},{\"q\":\"पदार्थाचे गुणधर्म कोणते आहेत?\",\"options\":[\"कठीणपणा, रंग, वास\",\"पारदर्शकता, चव, पाण्यात विरघळणे\",\"दोन्ही A आणि B\",\"फक्त A\"],\"answer\":2,\"explain\":\"दोन्ही A आणि B गुणधर्म आहेत.\"},{\"q\":\"उर्जेचे रूपांतर प्रकाश आणि ध्वनीमध्ये कसे होते?\",\"options\":[\"उष्णतेद्वारे\",\"विद्युतद्वारे\",\"गतीद्वारे\",\"सर्व मार्गांनी\"],\"answer\":3,\"explain\":\"उर्जा विविध रूपांत रूपांतरित होते.\"},{\"q\":\"पदार्थाचे सूक्ष्म कण कसे बनतात?\",\"options\":[\"घर्षणाने\",\"ज्वलनाने\",\"वायुप्रवाहाने\",\"सर्व मार्गांनी\"],\"answer\":0,\"explain\":\"उदा. खडू घासल्यावर कण तयार होतात.\"},{\"q\":\"उर्जेचा मुख्य स्रोत कोणता आहे?\",\"options\":[\"इंधन\",\"सौरऊर्जा\",\"वारा\",\"पाणी\"],\"answer\":0,\"explain\":\"आजच्या काळात इंधन मुख्य स्रोत आहे.\"},{\"q\":\"पदार्थ आणि ऊर्जा यांच्यात काय संबंध आहे?\",\"options\":[\"पदार्थ ऊर्जा देते\",\"ऊर्जा पदार्थ बनवते\",\"दोन्ही एकमेकांशी संबंधित आहेत\",\"फक्त ऊर्जा महत्त्वाची आहे\"],\"answer\":2,\"explain\":\"पदार्थ आणि ऊर्जा दोन्ही एकमेकांशी संबंधित आहेत.\"},{\"q\":\"सौरऊर्जेने विद्युत निर्मिती कशी होते?\",\"options\":[\"सूर्यप्रकाश थेट विद्युतमध्ये रूपांतरित होतो\",\"सूर्यप्रकाशाने पॅनेल गरम होऊन विद्युत तयार होते\",\"सूर्यप्रकाशाने पाणी वाफ होते\",\"सर्व मार्गांनी\"],\"answer\":1,\"explain\":\"सौर पॅनेल सूर्यप्रकाश शोषून विद्युत तयार करतात.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16807,24,5,'EVS Part 1','mr','सामाजिक आरोग्य','[\"सामाजिक आरोग्य म्हणजे समाजातील सर्व लोकांचे आरोग्य आणि सुरक्षितता\",\"स्वच्छ पाणी, स्वच्छ हवा, स्वच्छ अन्न हे सामाजिक आरोग्याचे मूलभूत घटक आहेत\",\"वैयक्तिक स्वच्छता जसे हात धुणे, दात घासणे, कपडे स्वच्छ ठेवणे समाजाच्या आरोग्यास मदत करते\",\"व्यायाम आणि शारीरिक क्रिया शरीराला तंदुरुस्त ठेवतात आणि रोगप्रतिकारक शक्ती वाढवतात\",\"सार्वजनिक ठिकाणी थुंकणे, कचरा फेकणे इत्यादी सवयींनी रोग पसरण्याची शक्यता वाढते\",\"तंबाखू, मद्य, अमली पदार्थांचे सेवन केल्याने कर्करोग, यकृताचे आजार, दातांचे नुकसान इत्यादी घातक परिणाम होतात\",\"सामाजिक आरोग्य धोक्यात आणणारे घटक: प्रदूषण, अस्वच्छता, साथीचे आजार, तंबाखू व मद्य सेवन, व्यसनाधीनता\",\"सामाजिक आरोग्य राखण्यासाठी स्वच्छता, पोषण, व्यायाम आणि आरोग्य शिक्षण महत्त्वाचे आहेत\",\"सामाजिक आरोग्याचे संरक्षण करण्यासाठी सरकार आणि समाजाने एकत्र काम करणे आवश्यक आहे\",\"सामाजिक आरोग्य चांगले असेल तर समाजात आनंद, समृद्धी आणि विकास होतो\",\"सामाजिक आरोग्य धोक्यात आणणाऱ्या सवयींमध्ये सार्वजनिक ठिकाणी थुंकणे, कचरा रस्त्यावर टाकणे, पाळीव प्राण्यांची योग्य देखभाल न करणे यांचा समावेश आहे\",\"तंबाखूचे सेवन केल्याने तोंडात व्रण, कर्करोग, दातांचे नुकसान होऊ शकते\",\"मद्यपानामुळे यकृताचे आजार, आतड्याचे आजार, मूत्राशयाचे रोग होऊ शकतात\",\"सामाजिक आरोग्य सुधारण्यासाठी स्वच्छता कार्यक्रम, आरोग्य शिक्षण आणि आरोग्य सेवा उपलब्ध करणे आवश्यक आहे\",\"सामाजिक आरोग्य चांगले ठेवण्यासाठी प्रत्येकाने वैयक्तिक स्वच्छता, पोषण आणि व्यायाम याकडे लक्ष द्यावे\"]','[{\"q\":\"सामाजिक आरोग्याचे मूलभूत घटक कोणते आहेत?\",\"options\":[\"स्वच्छ पाणी, स्वच्छ हवा, स्वच्छ अन्न\",\"फक्त स्वच्छ पाणी\",\"फक्त स्वच्छ हवा\",\"फक्त स्वच्छ अन्न\"],\"answer\":0,\"explain\":\"सामाजिक आरोग्याचे तीन मुख्य घटक स्वच्छ पाणी, स्वच्छ हवा आणि स्वच्छ अन्न आहेत.\"},{\"q\":\"सार्वजनिक ठिकाणी थुंकणे का धोकादायक आहे?\",\"options\":[\"सामाजिक सौंदर्य कमी होते\",\"रोग पसरण्याची शक्यता वाढते\",\"कचरा तयार होतो\",\"सर्व वरील\"],\"answer\":1,\"explain\":\"थुंकल्याने रोगजनक बॅक्टेरिया आणि विषाणू पसरू शकतात.\"},{\"q\":\"तंबाखू सेवनाचे मुख्य घातक परिणाम काय आहेत?\",\"options\":[\"मूत्राशयाचे रोग\",\"कर्करोग\",\"यकृताचे आजार\",\"सर्व वरील\"],\"answer\":3,\"explain\":\"तंबाखूमुळे तोंड, घसा, पोट आणि यकृतात कर्करोग होऊ शकतो.\"},{\"q\":\"मद्यपानाचे कोणते आरोग्यदायी परिणाम नाहीत?\",\"options\":[\"यकृताचे आजार\",\"आतड्याचे आजार\",\"मूत्राशयाचे रोग\",\"सर्व वरील\"],\"answer\":3,\"explain\":\"मद्यपानामुळे सर्व तीन आजारांची शक्यता वाढते.\"},{\"q\":\"सामाजिक आरोग्य चांगले असण्याचे फायदे काय आहेत?\",\"options\":[\"समाजात आनंद आणि समृद्धी\",\"विकास आणि प्रगती\",\"दोन्ही बरोबर\",\"काहीही नाही\"],\"answer\":2,\"explain\":\"सामाजिक आरोग्य चांगले असल्यास समाजात आनंद, समृद्धी, विकास आणि प्रगती होते.\"},{\"q\":\"सामाजिक आरोग्य धोक्यात आणणारी सवय कोणती नाही?\",\"options\":[\"सार्वजनिक ठिकाणी थुंकणे\",\"कचरा रस्त्यावर टाकणे\",\"कपडे स्वच्छ ठेवणे\",\"पाळीव प्राण्यांची योग्य देखभाल न करणे\"],\"answer\":2,\"explain\":\"कपडे स्वच्छ ठेवणे आरोग्य सुधारते, धोकादायक नाही.\"},{\"q\":\"सामाजिक आरोग्य सुधारण्यासाठी कोणती क्रिया आवश्यक नाही?\",\"options\":[\"स्वच्छ पाणी उपलब्ध करणे\",\"पोषक आहार देणे\",\"फक्त व्यायाम करणे\",\"सर्व वरील\"],\"answer\":3,\"explain\":\"सर्व तीन गोष्टी आवश्यक आहेत, त्यामुळे \'सर्व वरील\' बरोबर नाही.\"},{\"q\":\"तंबाखू सेवन केल्याने कोणता आजार होऊ शकतो?\",\"options\":[\"सर्दी\",\"कर्करोग\",\"फ्लू\",\"पोटदुखी\"],\"answer\":1,\"explain\":\"तंबाखू सेवनामुळे तोंड, घसा, पोट आणि इतर भागात कर्करोग होऊ शकतो.\"},{\"q\":\"सामाजिक आरोग्य धोक्यात आणणारे घटक कोणते?\",\"options\":[\"प्रदूषण\",\"अस्वच्छता\",\"साथीचे आजार\",\"सर्व वरील\"],\"answer\":3,\"explain\":\"सर्व तीन घटक सामाजिक आरोग्य धोक्यात आणतात.\"},{\"q\":\"सामाजिक आरोग्य राखण्यासाठी कोणती सवय उपयुक्त नाही?\",\"options\":[\"व्यायाम करणे\",\"पोषक आहार घेणे\",\"सार्वजनिक ठिकाणी थुंकणे\",\"हात धुणे\"],\"answer\":2,\"explain\":\"सार्वजनिक ठिकाणी थुंकणे आरोग्यासाठी हानिकारक आहे.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16808,25,5,'EVS Part 2','en','What is History?','[\"History is a science that studies events that have already happened.\",\"We use words like ‘past’, ‘present’ and ‘future’ to talk about time.\",\"The past is everything that has already happened, the present is what is happening now, and the future is what will happen later.\",\"History uses evidence to find out what really happened, not just imagination.\",\"Evidence comes from three main sources: material (objects), written (books, letters) and oral (stories, songs).\",\"Scientists use the scientific method in history: ask a question, gather evidence, test it, and draw conclusions.\",\"Historical facts are tested for reliability by checking if they can be repeated or confirmed by other evidence.\",\"History helps us learn from the past and plan for a better future.\",\"Every person, village, city and country has its own history.\",\"History shows how people’s actions lead to changes in society, culture and the environment.\",\"The study of history is part of Environmental Studies because it shows how humans have affected the environment over time.\",\"Archaeology is the science that digs up old objects to learn about ancient people.\",\"When we read a story about the past, we should check if it matches other evidence.\",\"History is written in books, manuscripts, copper plates, inscriptions and oral traditions.\",\"Knowing history inspires us to become better citizens and to respect our heritage.\",\"Remember: past, present and future are connected by a chain of events.\"]','[{\"q\":\"Which word means the time that has already passed?\",\"options\":[\"Future\",\"Past\",\"Present\",\"Yesterday\"],\"answer\":1,\"explain\":\"Past refers to time that has already happened.\"},{\"q\":\"What is the main method historians use to find out what really happened?\",\"options\":[\"Guessing\",\"Reading stories\",\"Scientific method\",\"Listening to myths\"],\"answer\":2,\"explain\":\"Historians use the scientific method to test evidence.\"},{\"q\":\"Which of these is NOT a source of history?\",\"options\":[\"Material sources\",\"Written sources\",\"Oral sources\",\"Dreams\"],\"answer\":3,\"explain\":\"Dreams are not a reliable historical source.\"},{\"q\":\"Archaeology deals with:\",\"options\":[\"Studying living animals\",\"Digging up old objects\",\"Writing new books\",\"Painting murals\"],\"answer\":1,\"explain\":\"Archaeology is the study of ancient remains.\"},{\"q\":\"If a village works together, it can become:\",\"options\":[\"Stuck\",\"Progressive\",\"Lost\",\"Broken\"],\"answer\":1,\"explain\":\"Cooperation leads to progress.\"},{\"q\":\"Which of the following is an example of a material source?\",\"options\":[\"A story told by a grandparent\",\"A copper plate\",\"A poem\",\"An oral chant\"],\"answer\":1,\"explain\":\"Copper plates are physical objects.\"},{\"q\":\"History helps us to:\",\"options\":[\"Ignore the past\",\"Make up stories\",\"Learn from the past\",\"Forget old events\"],\"answer\":2,\"explain\":\"History teaches lessons from earlier times.\"},{\"q\":\"The future is described by words such as:\",\"options\":[\"Yesterday\",\"Tomorrow\",\"Yesterday\",\"Yesterday\"],\"answer\":1,\"explain\":\"Tomorrow and next year refer to the future.\"},{\"q\":\"Which of these is a scientific discipline?\",\"options\":[\"History\",\"Fantasy\",\"Dreaming\",\"Imagining\"],\"answer\":0,\"explain\":\"History is considered a scientific discipline.\"},{\"q\":\"The chain that links past, present and future is called:\",\"options\":[\"A chain of events\",\"A chain of thoughts\",\"A chain of people\",\"A chain of books\"],\"answer\":0,\"explain\":\"Past, present and future are connected by events.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16809,25,5,'EVS Part 2','en','History and the Concept of ‘Time’','[\"Time is continuous and is divided into units like seconds, minutes, hours, days, weeks, months, years, centuries, and millennia.\",\"A day is 24 hours long, made of 12 hours of daylight and 12 hours of night.\",\"A week has 7 days from Monday to Sunday.\",\"A month is about 4 weeks long and has 12 months in a year.\",\"A year has 12 months and is the time it takes Earth to orbit the Sun.\",\"A decade is 10 years, a century is 100 years, and a millennium is 1000 years.\",\"The unilinear division of time means arranging events in a straight line from past to present to future.\",\"The Common Era (CE) or AD is the calendar system that started with the birth of Jesus Christ.\",\"Before the Common Era is called BCE or BC and is written in reverse order (e.g., 1000‑1 BCE).\",\"The first century CE is written as 1‑100 CE.\",\"Historical periods are divided into prehistoric (no written records) and historic (written records).\",\"Scientists use dating methods like Carbon‑14 and tree‑ring analysis to estimate ages of ancient objects.\",\"Carbon‑14 dating works because living organisms contain a small amount of radioactive carbon‑14 which decays after death.\",\"Tree rings show one ring per year; counting rings gives the tree’s age.\",\"The calendar we use today is based on the Christian Era and the Gregorian calendar.\",\"A millennium is 1000 years, a century is 100 years, a decade is 10 years, and a year is 365 days (366 in a leap year).\"]','[{\"q\":\"How many hours are there in a day?\",\"options\":[\"12\",\"24\",\"36\",\"48\"],\"answer\":1,\"explain\":\"A day has 24 hours.\"},{\"q\":\"What is the first century of the Common Era written as?\",\"options\":[\"1‑100 CE\",\"100‑1 CE\",\"1‑100 BCE\",\"100‑1 BCE\"],\"answer\":0,\"explain\":\"The first century CE is written 1‑100 CE.\"},{\"q\":\"Which method is used to count the age of a tree?\",\"options\":[\"Carbon‑14\",\"Tree‑ring (dendrochronology)\",\"Radiocarbon dating\",\"Stone age\"],\"answer\":1,\"explain\":\"Tree‑ring method counts yearly growth rings.\"},{\"q\":\"What does BCE stand for?\",\"options\":[\"Before Common Era\",\"Before Christian Era\",\"Before Common Epoch\",\"Before Calendar Era\"],\"answer\":0,\"explain\":\"BCE means Before Common Era.\"},{\"q\":\"How many years are in a millennium?\",\"options\":[\"100\",\"1000\",\"10\",\"10000\"],\"answer\":1,\"explain\":\"A millennium is 1000 years.\"},{\"q\":\"Which of these is a prehistoric period?\",\"options\":[\"Historic period\",\"Prehistoric period\",\"Both\",\"None\"],\"answer\":1,\"explain\":\"Prehistoric period has no written records.\"},{\"q\":\"What is the unit of time that is 60 seconds long?\",\"options\":[\"Minute\",\"Hour\",\"Day\",\"Week\"],\"answer\":0,\"explain\":\"A minute is 60 seconds.\"},{\"q\":\"Which dating method can determine ages up to 60,000 years?\",\"options\":[\"Tree‑ring\",\"Carbon‑14\",\"Stone age\",\"Dendrochronology\"],\"answer\":1,\"explain\":\"Carbon‑14 dating works up to about 60,000 years.\"},{\"q\":\"What is the unilinear division of time?\",\"options\":[\"Events arranged in a circle\",\"Events arranged in a straight line\",\"Events arranged randomly\",\"Events arranged by colour\"],\"answer\":1,\"explain\":\"Unilinear means a straight line from past to future.\"},{\"q\":\"Which of the following is NOT a unit of time?\",\"options\":[\"Second\",\"Minute\",\"Hour\",\"Yearly\"],\"answer\":3,\"explain\":\"Yearly is not a standard unit; year is the unit.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16810,25,5,'EVS Part 2','en','Life on Earth','[\"- Earth is the only planet where life is known to exist.\",\"- Earth formed about 4.5 billion years ago from a cloud of hot gases and dust.\",\"- The cloud spun and split into the Sun and the planets.\",\"- Water bodies appeared on Earth’s surface early in its history.\",\"- The first living things were unicellular organisms called protozoa.\",\"- Protozoa lived in water and were too small to see without a microscope.\",\"- Over time, some protozoa evolved into multicellular organisms.\",\"- Animals are living beings that breathe, move, and reproduce.\",\"- Some animals lay eggs; others give birth to live young.\",\"- The Sun and planets revolve around each other in a solar system.\",\"- Mars has similar features to Earth but lacks liquid water.\",\"- The Mangalyaan mission reached Mars in 2014.\",\"- Life requires water in liquid form; Mars has no liquid water yet.\"]','[{\"q\":\"Which planet is the only one known to have life?\",\"options\":[\"Venus\",\"Mars\",\"Earth\",\"Jupiter\"],\"answer\":2,\"explain\":\"Earth is the only planet where life is known to exist.\"},{\"q\":\"When did the Sun and planets form?\",\"options\":[\"4.5 billion years ago\",\"3.5 billion years ago\",\"2.5 billion years ago\",\"1.5 billion years ago\"],\"answer\":0,\"explain\":\"They formed about 4.5 billion years ago from a cloud of hot gases.\"},{\"q\":\"What are protozoa?\",\"options\":[\"Multicellular animals\",\"Unicellular organisms\",\"Plants\",\"Bacteria\"],\"answer\":1,\"explain\":\"Protozoa are unicellular organisms that lived in water.\"},{\"q\":\"Which of the following is a characteristic of animals?\",\"options\":[\"They can photosynthesize\",\"They breathe\",\"They are stationary\",\"They are plants\"],\"answer\":1,\"explain\":\"Animals breathe air or water.\"},{\"q\":\"What is the main reason Mars may not support life?\",\"options\":[\"No oxygen\",\"No water in liquid form\",\"No sunlight\",\"No magnetic field\"],\"answer\":1,\"explain\":\"Mars lacks liquid water, essential for life.\"},{\"q\":\"Which instrument is needed to see protozoa?\",\"options\":[\"Telescope\",\"Microscope\",\"Camera\",\"Magnifying glass\"],\"answer\":1,\"explain\":\"Protozoa are too small for the naked eye; a microscope is needed.\"},{\"q\":\"Which planet is the smallest in our solar system?\",\"options\":[\"Mercury\",\"Mars\",\"Venus\",\"Jupiter\"],\"answer\":0,\"explain\":\"Mercury is the smallest planet.\"},{\"q\":\"What is the main component of Mars’ atmosphere?\",\"options\":[\"Nitrogen\",\"Oxygen\",\"Carbon dioxide\",\"Helium\"],\"answer\":2,\"explain\":\"About 95% of Mars’ atmosphere is carbon dioxide.\"},{\"q\":\"Which mission reached Mars in 2014?\",\"options\":[\"Apollo\",\"Challenger\",\"Mangalyaan\",\"Voyager\"],\"answer\":2,\"explain\":\"India’s Mangalyaan mission reached Mars in 2014.\"},{\"q\":\"Which of these animals gives birth to live young?\",\"options\":[\"Fish\",\"Birds\",\"Reptiles\",\"Some mammals\"],\"answer\":3,\"explain\":\"Some mammals give birth to live young.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16811,25,5,'EVS Part 2','en','Evolution','[\"Evolution means gradual and continuous change over a long time.\",\"Charles Darwin first explained evolution in 1859 in his book *On the Origin of Species*.\",\"Living things change because they adapt to their environment.\",\"Animals that adapt well survive; those that do not may become extinct.\",\"Evolution occurs in all living things, from tiny single‑cell organisms to big animals.\",\"The first life on Earth were single‑cell organisms called protozoa.\",\"Protozoa evolved into multicellular plants and animals.\",\"Animals are divided into two main groups: invertebrates (no backbone) and vertebrates (with backbone).\",\"Invertebrates include animals like snails, insects and worms.\",\"Vertebrates include fish, amphibians, reptiles, birds and mammals.\",\"Mammals are special because they grow babies inside the mother and feed them with milk.\",\"Apes are close relatives of humans and live mainly on trees.\",\"Some apes moved to grasslands and became the first humans (primitive man).\",\"Fossils show that dinosaurs were huge reptiles and some evolved into birds.\",\"Extinction happens when a species cannot survive changes in its environment.\",\"Evolution is shown by changes in physical traits that are passed to offspring.\",\"Every new species is a result of many small changes over many generations.\",\"The word *dinosaur* comes from Greek words meaning ‘terrible lizard’.\",\"Evolution is a natural process, not a random accident.\"]','[{\"q\":\"Who first gave a systematic explanation of evolution?\",\"options\":[\"Charles Darwin\",\"Carl Linnaeus\",\"Louis Leakey\",\"Willard Libby\"],\"answer\":0,\"explain\":\"Charles Darwin published the theory of evolution in 1859.\"},{\"q\":\"What does the word ‘evolution’ mean?\",\"options\":[\"Sudden change\",\"Gradual and continuous change\",\"Complete extinction\",\"Rapid mutation\"],\"answer\":1,\"explain\":\"Evolution refers to gradual and continuous change over time.\"},{\"q\":\"Which animals are called invertebrates?\",\"options\":[\"Animals with a backbone\",\"Animals without a backbone\",\"Animals that lay eggs\",\"Animals that live only in water\"],\"answer\":1,\"explain\":\"Invertebrates are animals that do not have a backbone.\"},{\"q\":\"Which group includes fish, frogs, and snakes?\",\"options\":[\"Invertebrates\",\"Vertebrates\",\"Mammals\",\"Reptiles\"],\"answer\":1,\"explain\":\"Fish, frogs, and snakes are all vertebrates, animals with a backbone.\"},{\"q\":\"Which of the following is a characteristic of mammals?\",\"options\":[\"They lay eggs\",\"They have a placenta\",\"They live only in water\",\"They have scales\"],\"answer\":1,\"explain\":\"Mammals give birth to live young and have a placenta to nourish them.\"},{\"q\":\"What does the term ‘primitive man’ refer to?\",\"options\":[\"The first humans\",\"The most evolved humans\",\"The earliest apes\",\"The last humans\"],\"answer\":0,\"explain\":\"Primitive man means the first humans or early human species.\"},{\"q\":\"Which animal is an example of an amphibian?\",\"options\":[\"Fish\",\"Snake\",\"Frog\",\"Cow\"],\"answer\":2,\"explain\":\"Frogs live in water and on land, making them amphibians.\"},{\"q\":\"Which of these dinosaurs had wings?\",\"options\":[\"Tyrannosaurus\",\"Triceratops\",\"Pterodactyl\",\"Stegosaurus\"],\"answer\":2,\"explain\":\"Pterodactyls were winged dinosaurs that are believed to have evolved into birds.\"},{\"q\":\"What is the main reason some species become extinct?\",\"options\":[\"They evolve too quickly\",\"They adapt to all environments\",\"They cannot adapt to environmental changes\",\"They have too many offspring\"],\"answer\":2,\"explain\":\"Species that cannot adapt to environmental changes are more likely to become extinct.\"},{\"q\":\"Which scientist introduced a method of classifying animals before Darwin?\",\"options\":[\"Charles Darwin\",\"Carl Linnaeus\",\"Louis Leakey\",\"Willard Libby\"],\"answer\":1,\"explain\":\"Carl Linnaeus developed a classification system for animals before Darwin.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16812,25,5,'EVS Part 2','en','Evolution of Mankind','[\"- Homo means ‘man’ in Latin.\",\"- Homo habilis means ‘the skilled hand’ and lived about 2.4–1.4 million years ago.\",\"- Homo habilis could walk on two feet and make simple stone tools like choppers.\",\"- Homo erectus lived 1.8–0.2 million years ago, had a bigger brain and made hand‑axes.\",\"- Homo erectus used fire for cooking but could not yet make fire.\",\"- Neanderthals (Homo neanderthalensis) lived in Europe and Asia, used stone tools and made fire by striking flint.\",\"- Neanderthals buried their dead with red ochre and may have had a simple language.\",\"- Homo sapiens (modern humans) appeared about 300,000 years ago, had a fully developed brain and language.\",\"- Homo sapiens developed agriculture, settled villages and made complex tools.\",\"- Humans have an opposable thumb, a flexible tongue and a larynx that lets them make many sounds.\",\"- Evolution is not a straight line; many branches appeared and some went extinct.\",\"- Fossils are bones that have turned into stone over millions of years.\",\"- The study of heredity (genetics) explains how traits are passed from parents to children.\",\"- Humans can stand upright, walk on two feet and use their hands for many tasks.\"]','[{\"q\":\"What does the Latin word ‘homo’ mean?\",\"options\":[\"man\",\"woman\",\"child\",\"animal\"],\"answer\":0,\"explain\":\"‘Homo’ is Latin for ‘man’.\"},{\"q\":\"Which species is known as ‘the skilled human’?\",\"options\":[\"Homo habilis\",\"Homo erectus\",\"Neanderthalensis\",\"Homo sapiens\"],\"answer\":0,\"explain\":\"Homo habilis made tools and is called ‘the skilled human’.\"},{\"q\":\"What was the main tool made by Homo erectus?\",\"options\":[\"Stone chopper\",\"Hand‑axe\",\"Flint spear\",\"Bone knife\"],\"answer\":1,\"explain\":\"Homo erectus is famous for making the hand‑axe.\"},{\"q\":\"Where were the first Neanderthal remains found?\",\"options\":[\"Germany\",\"France\",\"Italy\",\"Spain\"],\"answer\":0,\"explain\":\"Neanderthal remains were first discovered in Germany.\"},{\"q\":\"Which feature helped Neanderthals make fire?\",\"options\":[\"Rubbing sticks\",\"Striking flint\",\"Using fire‑starter\",\"Burning branches\"],\"answer\":0,\"explain\":\"Neanderthals made fire by rubbing sticks together.\"},{\"q\":\"What does ‘sapiens’ mean in Homo sapiens?\",\"options\":[\"Intelligent\",\"Strong\",\"Fast\",\"Tall\"],\"answer\":0,\"explain\":\"‘Sapiens’ means ‘intelligent’ or ‘thinking’.\"},{\"q\":\"Which species had the most developed brain among those mentioned?\",\"options\":[\"Homo habilis\",\"Homo erectus\",\"Neanderthalensis\",\"Homo sapiens\"],\"answer\":3,\"explain\":\"Homo sapiens had the most developed brain.\"},{\"q\":\"What is the main reason Neanderthals became extinct?\",\"options\":[\"Disease\",\"War\",\"Climate change\",\"Lack of food\"],\"answer\":2,\"explain\":\"Climate change and competition are main reasons for their extinction.\"},{\"q\":\"What is heredity?\",\"options\":[\"The study of fossils\",\"The passing of traits from parents to offspring\",\"The use of tools\",\"The making of fire\"],\"answer\":1,\"explain\":\"Heredity is the transmission of traits from parents to children.\"},{\"q\":\"Which of the following is NOT a tool used by early humans?\",\"options\":[\"Stone chopper\",\"Hand‑axe\",\"Flint spear\",\"Paper\"],\"answer\":3,\"explain\":\"Paper was not used by early humans.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16813,25,5,'EVS Part 2','en','Stone Age : Stone Tools','[\"Stone tools are made from stones, bones, twigs and sticks.\",\"The first people who made stone tools were Homo habilis.\",\"Stone tools are divided into three types: chopper, scraper and hammerstone.\",\"A chopper is a stone with a sharp edge used to cut or break things.\",\"A scraper is a stone used to clean or smooth surfaces.\",\"A hammerstone is a heavy stone used to strike other stones to make flakes.\",\"The Old Stone Age (Palaeolithic) is the earliest period of stone tools.\",\"The Middle Stone Age (Mesolithic) introduced microliths – very small stone blades.\",\"The New Stone Age (Neolithic) saw polished stone tools and the start of farming.\",\"Tools are chosen based on the task, time, efficiency and skill.\",\"Homo erectus made hand‑axes that were more symmetrical than earlier choppers.\",\"Homo sapiens invented long narrow blades and polished axes for farming and hunting.\",\"Stone tools were used for cutting meat, sharpening sticks, making knives and for building shelters.\",\"The Old Stone Age sites in India include Bhimbetka, Narmada and Gangapur.\",\"The Middle Stone Age sites include Bagor, Bhimbetka and Langhnaj.\",\"The New Stone Age sites include Sinnar, Chandwad and Bijapur.\",\"Stone tools were made by striking a hard stone against another to produce flakes.\",\"Microliths were attached to sticks to make arrows and fish hooks.\",\"Polished stone tools were smoother and more durable than unpolished ones.\",\"Stone tools show the progress of human technology over millions of years.\",\"The term lithos means stone in Greek, and lithic means stone‑made.\",\"Stone tools are still found in many parts of the world today.\"]','[{\"q\":\"What is a chopper used for?\",\"options\":[\"Cutting meat\",\"Cleaning surfaces\",\"Striking other stones\",\"Making arrows\"],\"answer\":0,\"explain\":\"A chopper is a stone with a sharp edge used for cutting or breaking.\"},{\"q\":\"Which period is called the Middle Stone Age?\",\"options\":[\"Old Stone Age\",\"Middle Stone Age\",\"New Stone Age\",\"Copper Age\"],\"answer\":1,\"explain\":\"The Middle Stone Age is also known as Mesolithic.\"},{\"q\":\"Microliths are small stone blades used in which age?\",\"options\":[\"Old Stone Age\",\"Middle Stone Age\",\"New Stone Age\",\"Iron Age\"],\"answer\":1,\"explain\":\"Microliths are characteristic of the Middle Stone Age.\"},{\"q\":\"Which tool is used to strike other stones to make flakes?\",\"options\":[\"Chopper\",\"Scraper\",\"Hammerstone\",\"Antler\"],\"answer\":2,\"explain\":\"A hammerstone is struck against another stone to produce flakes.\"},{\"q\":\"Polished stone tools were mainly used in which age?\",\"options\":[\"Old Stone Age\",\"Middle Stone Age\",\"New Stone Age\",\"Bronze Age\"],\"answer\":2,\"explain\":\"Polished tools appear in the New Stone Age.\"},{\"q\":\"What does the Greek word \'lithos\' mean?\",\"options\":[\"Stone\",\"Tool\",\"Sharp\",\"Old\"],\"answer\":0,\"explain\":\"Lithos means stone.\"},{\"q\":\"Which of the following is NOT a type of stone tool?\",\"options\":[\"Chopper\",\"Scraper\",\"Spear\",\"Hammerstone\"],\"answer\":2,\"explain\":\"Spear is not listed as a stone tool type in the chapter.\"},{\"q\":\"Homo sapiens introduced which technique in tool making?\",\"options\":[\"Percussion flaking\",\"Microlith production\",\"Polishing\",\"All of the above\"],\"answer\":3,\"explain\":\"Homo sapiens used all these techniques.\"},{\"q\":\"Which site is an Old Stone Age site in Maharashtra?\",\"options\":[\"Bagor\",\"Bhimbetka\",\"Langhnaj\",\"Bijapur\"],\"answer\":0,\"explain\":\"Bagor is an Old Stone Age site in Maharashtra.\"},{\"q\":\"Which age saw the start of agriculture and animal husbandry?\",\"options\":[\"Old Stone Age\",\"Middle Stone Age\",\"New Stone Age\",\"Iron Age\"],\"answer\":2,\"explain\":\"The New Stone Age introduced farming and domestication.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16814,25,5,'EVS Part 2','en','From Shelters to Village-settlements','[\"Shelters were places where early humans stayed for a short time.\",\"In the Middle Stone Age humans moved from caves to seasonal camps.\",\"Seasonal camps were set up in good hunting grounds and near food sources.\",\"People used animal hides, wood and fire to keep warm in camps.\",\"Later, they started building huts in the open when they could stay longer.\",\"The New Stone Age saw the start of agriculture and permanent villages.\",\"Agriculture let people store food, so they didn’t have to move constantly.\",\"Permanent villages were built on cleared forest land with huts made of mud, straw or wood.\",\"The climate changed from very cold (glacial) to warmer (interglacial) over time.\",\"Glacial periods had ice sheets covering much of the Earth and low sea levels.\",\"Interglacial periods had melted ice, higher sea levels and warmer weather.\",\"The last glacial period ended about 11,000 years ago, starting the current warm era.\",\"During the New Stone Age, humans grew grains like millet and barley.\",\"They also hunted wild animals such as deer, boar and sheep.\",\"Village life involved farming, gathering, and making tools from stone and wood.\",\"The diet changed from mainly hunting to a mix of hunting and farming.\",\"People built houses with walls of mud or thatch and roofs of grass or bark.\",\"Permanent villages allowed social organization and shared resources.\",\"The Old Stone Age was mainly hunting and gathering, while the New Stone Age added farming.\",\"The Middle Stone Age was a transition with more use of fire and clothing.\",\"The New Stone Age had permanent settlements, agriculture and social roles.\",\"The climate cycles of glacial and interglacial periods shaped human life.\",\"The New Stone Age villages were often near rivers for water and food.\"]','[{\"q\":\"Which period is known for permanent villages and agriculture?\",\"options\":[\"Old Stone Age\",\"Middle Stone Age\",\"New Stone Age\",\"Bronze Age\"],\"answer\":2,\"explain\":\"Permanent villages and farming began in the New Stone Age.\"},{\"q\":\"What helped Neanderthals stay warm in cold Europe?\",\"options\":[\"Stone walls\",\"Animal hides\",\"Fire\",\"Ice caves\"],\"answer\":2,\"explain\":\"They wore leather hides and used fire for warmth.\"},{\"q\":\"What is a glacial period?\",\"options\":[\"Warm period\",\"Cold period with ice sheets\",\"Dry period\",\"Rainy period\"],\"answer\":1,\"explain\":\"Glacial periods have ice sheets and low sea levels.\"},{\"q\":\"Which food did early humans start growing in the New Stone Age?\",\"options\":[\"Rice\",\"Millet\",\"Potatoes\",\"Corn\"],\"answer\":1,\"explain\":\"Millet and other grains were first cultivated.\"},{\"q\":\"Why did humans move from caves to seasonal camps?\",\"options\":[\"Caves were too hot\",\"Caves were too small\",\"Caves were dangerous\",\"Caves were scarce\"],\"answer\":2,\"explain\":\"Caves were dangerous and not suitable for long stays.\"},{\"q\":\"What is the main difference between Old and New Stone Age?\",\"options\":[\"Use of metal tools\",\"Use of fire\",\"Permanent settlements\",\"Use of boats\"],\"answer\":2,\"explain\":\"New Stone Age had permanent villages; Old was mobile.\"},{\"q\":\"What caused sea levels to rise during interglacial periods?\",\"options\":[\"More rainfall\",\"Melting ice\",\"Less evaporation\",\"Ocean currents\"],\"answer\":1,\"explain\":\"Melting ice added water to the oceans.\"},{\"q\":\"Which animal was an ancestor of the elephant?\",\"options\":[\"Mammoth\",\"Hippopotamus\",\"Giraffe\",\"Rhino\"],\"answer\":0,\"explain\":\"The mammoth is an ancestor of the elephant.\"},{\"q\":\"What material was NOT used to build huts in the New Stone Age?\",\"options\":[\"Mud\",\"Wood\",\"Stone\",\"Plastic\"],\"answer\":3,\"explain\":\"Plastic was not available.\"},{\"q\":\"What did seasonal camps depend on?\",\"options\":[\"Permanent food stores\",\"Fishing\",\"Hunting grounds\",\"Permanent houses\"],\"answer\":1,\"explain\":\"Seasonal camps were set near hunting and fishing grounds.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16815,25,5,'EVS Part 2','en','Beginning of Settled Life','[\"- Domestication is the process of making wild animals friendly and useful for humans.\",\"- First domesticated animal was the dog, used for hunting and guarding.\",\"- Goat and sheep were domesticated next, then cattle, buffalo, and others.\",\"- Three main steps in domestication: capture, taming, and training animals to live with people.\",\"- Agriculture began about 11,000 years ago in the Fertile Crescent (Israel, Iraq, Iran).\",\"- Early farmers used pointed sticks and perforated stones to sow seeds.\",\"- The invention of the plough pulled by bullocks allowed food to be stored for long periods.\",\"- Surplus food led to trade and the barter system.\",\"- Crafts such as pottery, bead making, weaving, and metalwork emerged.\",\"- Village settlements were built of wattle and daub, later bricks; houses were close together and often had more than one room.\",\"- Families were extended; relatives lived together and shared resources.\",\"- Chiefs or village leaders were chosen to enforce rules and protect the community.\",\"- Salt was an important traded commodity, often exchanged for other goods.\",\"- The first houses were simple, but later houses became more permanent and larger.\",\"- Domestic animals provide food (milk, meat), labor (ploughing), and other resources like wool and hides.\"]','[{\"q\":\"Which animal was the first to be domesticated by humans?\",\"options\":[\"Cat\",\"Dog\",\"Horse\",\"Sheep\"],\"answer\":1,\"explain\":\"Dogs were domesticated first, mainly for hunting and guarding.\"},{\"q\":\"When did agriculture first begin according to archaeological evidence?\",\"options\":[\"5,000 years ago\",\"7,000 years ago\",\"9,000 years ago\",\"11,000 years ago\"],\"answer\":3,\"explain\":\"Evidence shows agriculture started about 11,000 years ago.\"},{\"q\":\"What is the first step in the domestication of a wild animal?\",\"options\":[\"Taming\",\"Training\",\"Capture\",\"Feeding\"],\"answer\":0,\"explain\":\"The first step is capturing the wild animal.\"},{\"q\":\"Which tool was used by early farmers to sow seeds?\",\"options\":[\"Hoe\",\"Plough\",\"Pointed stick\",\"Scythe\"],\"answer\":2,\"explain\":\"Early farmers used pointed sticks to sow seeds.\"},{\"q\":\"What material were early houses made of?\",\"options\":[\"Stone\",\"Wood\",\"Wattle and daub\",\"Brick\"],\"answer\":1,\"explain\":\"Early houses were made of wattle and daub, later bricks.\"},{\"q\":\"What system emerged when villages produced surplus food?\",\"options\":[\"Currency system\",\"Barter system\",\"Tax system\",\"Trade system\"],\"answer\":1,\"explain\":\"Surplus food led to the barter system.\"},{\"q\":\"Which animal is commonly used by modern police for patrol?\",\"options\":[\"Dog\",\"Horse\",\"Cattle\",\"Sheep\"],\"answer\":0,\"explain\":\"Police use dogs for patrol and detection.\"},{\"q\":\"What was the main purpose of protective walls around villages?\",\"options\":[\"To keep animals inside\",\"To keep people inside\",\"To protect from floods, animals and outsiders\",\"To mark boundaries\"],\"answer\":2,\"explain\":\"Walls protected villages from floods, wild animals and outsiders.\"},{\"q\":\"Which craft involves making earthen pots?\",\"options\":[\"Weaving\",\"Pottery\",\"Bead making\",\"Metalwork\"],\"answer\":1,\"explain\":\"Pottery is the craft of making earthen pots.\"},{\"q\":\"What did early farmers use to store food grains for long periods?\",\"options\":[\"Glass jars\",\"Metal cans\",\"Clay pots\",\"Wooden barrels\"],\"answer\":2,\"explain\":\"Clay pots were used to store food grains.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16816,25,5,'EVS Part 2','en','Settled Life and Urban Civilization','[\"Metals are substances that can be melted and shaped to make tools and objects.\",\"Gold is the first metal used by humans, but it is too soft for tools.\",\"Copper was the next metal used; it is harder than gold but still soft for many objects.\",\"Bronze is an alloy of copper and tin; it is harder and used for many tools and weapons.\",\"The Stone Age is when people used only stone tools.\",\"The Copper Age is when people started using copper and bronze.\",\"The Iron Age is when iron tools appeared, making stronger tools and weapons.\",\"The wheel was invented during the Copper Age and was first used by potters.\",\"Potters used a rotating plank or wheel to shape pots quickly and evenly.\",\"The invention of the wheel helped create carts and chariots for transport.\",\"Long‑distance trade grew when people could transport goods faster with wheeled vehicles.\",\"Cities grew because trade increased and people needed places to keep records.\",\"Writing (script) was developed to keep permanent records of trade and other activities.\",\"The Indus (Harappan) civilization had its own script and used wheeled carts.\",\"The Rosetta Stone helped scholars read Egyptian hieroglyphs by comparing them with Greek and Demotic scripts.\"]','[{\"q\":\"Which metal is the softest and was used first by humans?\",\"options\":[\"Gold\",\"Copper\",\"Iron\",\"Bronze\"],\"answer\":0,\"explain\":\"Gold is the softest metal and was the first used for ornaments.\"},{\"q\":\"What is the name of the alloy made by mixing copper and tin?\",\"options\":[\"Bronze\",\"Steel\",\"Alloy\",\"Malleable\"],\"answer\":0,\"explain\":\"Copper + tin = bronze, a harder metal.\"},{\"q\":\"During which age were wheeled carts first used?\",\"options\":[\"Stone Age\",\"Copper Age\",\"Iron Age\",\"Bronze Age\"],\"answer\":1,\"explain\":\"The wheel was invented in the Copper Age.\"},{\"q\":\"What was the main reason cities started to grow in ancient times?\",\"options\":[\"Invention of writing\",\"Discovery of fire\",\"Rise of trade\",\"Agriculture alone\"],\"answer\":2,\"explain\":\"Trade increased and people needed places to keep records.\"},{\"q\":\"Which script was used for routine documents in ancient Egypt?\",\"options\":[\"Hieroglyphs\",\"Demotic\",\"Coptic\",\"Greek\"],\"answer\":1,\"explain\":\"Demotic was the simplified script for everyday use.\"},{\"q\":\"The Rosetta Stone helped scholars read which ancient script?\",\"options\":[\"Cuneiform\",\"Hieroglyphs\",\"Latin\",\"Greek\"],\"answer\":1,\"explain\":\"It had the same text in three scripts, including hieroglyphs.\"},{\"q\":\"What does the term \'Chalcolithic\' mean?\",\"options\":[\"Age of copper and stone\",\"Age of iron and bronze\",\"Age of gold and silver\",\"Age of pottery\"],\"answer\":0,\"explain\":\"Chalco = copper, lithos = stone.\"},{\"q\":\"Which metal is harder than gold but still too soft for many tools?\",\"options\":[\"Copper\",\"Iron\",\"Bronze\",\"Steel\"],\"answer\":0,\"explain\":\"Copper is harder than gold but still soft.\"},{\"q\":\"Which civilization is known as the earliest on the Indian subcontinent?\",\"options\":[\"Mohenjo-Daro\",\"Maya\",\"Egypt\",\"Mesopotamia\"],\"answer\":0,\"explain\":\"The Indus (Harappan) civilization was earliest in India.\"},{\"q\":\"What is the main function of a potter’s wheel?\",\"options\":[\"To rotate the pot for even shaping\",\"To melt metal\",\"To transport goods\",\"To write records\"],\"answer\":0,\"explain\":\"It turns the pot while the potter shapes it.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16817,25,5,'EVS Part 2','en','Historic Period','[\"Culture is the way people use tools, make food, build homes and create art to meet their needs.\",\"Ancient riverine civilizations grew along rivers like the Tigris‑Euphrates, Nile, Indus and Huang He.\",\"They made pots, bricks, cloth, metal tools and weapons from clay, wood, stone and metal.\",\"They used the wheel, made boats and built cities with walls, streets and drainage.\",\"Writing appeared as scripts on clay tablets, seals and pottery.\",\"Trade linked Mesopotamia, Egypt, Harappan and Chinese civilizations around 3000 BC.\",\"Harappan cities had planned streets, public baths, wells and a system of irrigation.\",\"Egyptians built pyramids, temples and ships, and made papyrus paper and faience pottery.\",\"Music and dance were important; instruments like the Balag, cymbals, flutes and drums were used.\",\"Sports included wrestling, hunting, board games such as Senat and early chess‑like games.\",\"The Harappan script is undeciphered, so we learn about them from seals and pottery.\",\"Early civilizations had permanent settlements, surplus food, craft specialization and long‑distance trade.\",\"They used copper and bronze, had irrigation, planned cities and developed science and mathematics.\"]','[{\"q\":\"What does the word ‘culture’ mean for humans?\",\"options\":[\"The way we eat food\",\"The way we build houses\",\"The way we use tools and create art\",\"The way we travel by boat\"],\"answer\":2,\"explain\":\"Culture is the skills, arts, and traditions humans create to meet their needs.\"},{\"q\":\"Which river is associated with the earliest civilization in the Indian subcontinent?\",\"options\":[\"Ganges\",\"Indus\",\"Nile\",\"Tigris\"],\"answer\":1,\"explain\":\"The Harappan Civilization flourished along the Indus River.\"},{\"q\":\"Which of the following is NOT a characteristic of early riverine civilizations?\",\"options\":[\"Permanent settlements\",\"Use of bronze\",\"Centralized irrigation\",\"No written records\"],\"answer\":3,\"explain\":\"Early civilizations had written records; they were not absent.\"},{\"q\":\"What was the main purpose of the wheel in Mesopotamia?\",\"options\":[\"For decoration\",\"For transport\",\"For cooking\",\"For building walls\"],\"answer\":1,\"explain\":\"The wheel was used for transportation and trade.\"},{\"q\":\"Which ancient civilization is known for building pyramids?\",\"options\":[\"Mesopotamia\",\"Egypt\",\"Harappan\",\"China\"],\"answer\":1,\"explain\":\"Egyptians built pyramids as tombs for pharaohs.\"},{\"q\":\"What is the name of the stringed instrument found in Mesopotamia?\",\"options\":[\"Balag\",\"Sitar\",\"Guitar\",\"Harp\"],\"answer\":0,\"explain\":\"The Balag was a 11‑stringed instrument found in Ur.\"},{\"q\":\"Which civilization is called the ‘Protohistoric period’ of the Indian subcontinent?\",\"options\":[\"Harappan\",\"Egyptian\",\"Mesopotamian\",\"Chinese\"],\"answer\":0,\"explain\":\"The Harappan Civilization is considered the Protohistoric period.\"},{\"q\":\"Which of these was NOT a major factor in the rise of early civilizations?\",\"options\":[\"Use of the wheel\",\"Trade\",\"Permanent settlements\",\"No agriculture\"],\"answer\":3,\"explain\":\"Agriculture was essential; lack of it would prevent civilization.\"},{\"q\":\"What was the primary material used by the Harappans for pottery?\",\"options\":[\"Clay\",\"Stone\",\"Metal\",\"Wood\"],\"answer\":0,\"explain\":\"Harappans made pots from clay, often baked.\"},{\"q\":\"Which ancient city was known for its well‑planned streets laid out at right angles?\",\"options\":[\"Ur\",\"Uruk\",\"Lothal\",\"Beijing\"],\"answer\":1,\"explain\":\"Uruk had streets laid out in a grid pattern at right angles.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16818,26,5,'EVS Part 2','mr','इतिहास म्हणजे काय ?','[\"इतिहास म्हणजे भूतकाळातील घडलेल्या घटना व घटनांचे ज्ञान\",\"इतिहास शास्त्रात काळाचे तीन भाग – भूतकाळ, वर्तमानकाळ व भविष्यकाळ\",\"भूतकाळ म्हणजे आधीच घडलेली घटना\",\"वर्तमानकाळ म्हणजे आत्ता घडणारी घटना\",\"भविष्यकाळ म्हणजे अजून घडायची घटना\",\"इतिहासात ‘काल’, ‘आत्ता’, ‘उद्या’ हे शब्द काळ दर्शवतात\",\"इतिहास लिहिताना ‘गेल्या वर्षी’, ‘पुढील वर्षी’ अशा शब्दांचा वापर होतो\",\"इतिहासाचे मुख्य उद्दिष्ट म्हणजे भूतकाळातील घटनांचे कारण व परिणाम समजणे\",\"इतिहासातून आपण आपल्या समाजाचे व संस्कृतीचे विकास पाहू शकतो\",\"इतिहास शिकताना आपण नोंद, पुरावे व दस्तऐवजांचा वापर करतो\",\"इतिहासात ‘स्मरण’, ‘साक्षी’, ‘पुरावा’ हे तीन प्रमुख स्रोत असतात\",\"इतिहासातील ‘कालक्रम’ म्हणजे घटनांची अनुक्रमे मांडणी\",\"इतिहासात ‘कारण-परिणाम’ हे महत्त्वाचे तत्त्व आहे\",\"इतिहासाचे अध्ययन आपल्याला निर्णय घेण्यास मदत करते\",\"इतिहास वाचताना आपण ‘काळ’, ‘स्थान’, ‘व्यक्ती’ या तीन घटकांवर लक्ष देतो\"]','[{\"q\":\"इतिहासात भूतकाळ दर्शवणारा शब्द कोणता?\",\"options\":[\"आत्ता\",\"काल\",\"उद्या\",\"पुढील वर्षी\"],\"answer\":1,\"explain\":\"भूतकाळ दर्शवणारा शब्द ‘काल’ आहे.\"},{\"q\":\"‘वर्तमानकाळ’ म्हणजे काय?\",\"options\":[\"आधी घडलेली घटना\",\"आत्ता घडणारी घटना\",\"भविष्यकाळातील घटना\",\"काहीही नाही\"],\"answer\":1,\"explain\":\"वर्तमानकाळ म्हणजे आत्ता घडणारी घटना.\"},{\"q\":\"भविष्यकाळ दर्शवणारा शब्द कोणता?\",\"options\":[\"काल\",\"आत्ता\",\"उद्या\",\"गेल्या वर्षी\"],\"answer\":2,\"explain\":\"भविष्यकाळ दर्शवणारा शब्द ‘उद्या’ आहे.\"},{\"q\":\"इतिहासात ‘कारण-परिणाम’ तत्त्व काय आहे?\",\"options\":[\"घटनांचा क्रम\",\"घटनांचे कारण व परिणाम\",\"फक्त घटनांची नोंद\",\"काळ व स्थान\"],\"answer\":1,\"explain\":\"कारण-परिणाम म्हणजे घटनांचे कारण व परिणाम.\"},{\"q\":\"इतिहास लिहिताना कोणते स्रोत वापरले जातात?\",\"options\":[\"साक्षी\",\"पुरावा\",\"स्मरण\",\"वरील सर्व\"],\"answer\":3,\"explain\":\"साक्षी, पुरावा व स्मरण हे सर्व स्रोत आहेत.\"},{\"q\":\"काळ, स्थान व व्यक्ती हे इतिहासाचे कोणते घटक?\",\"options\":[\"स्रोत\",\"तत्त्व\",\"घटक\",\"पद्धती\"],\"answer\":2,\"explain\":\"काळ, स्थान व व्यक्ती हे इतिहासाचे घटक आहेत.\"},{\"q\":\"‘कालक्रम’ म्हणजे काय?\",\"options\":[\"घटनांचा क्रम\",\"घटनांचे कारण\",\"भविष्यकाळ\",\"काळ व स्थान\"],\"answer\":0,\"explain\":\"कालक्रम म्हणजे घटनांचा क्रम.\"},{\"q\":\"इतिहासाचे मुख्य उद्दिष्ट काय?\",\"options\":[\"भविष्य भाकीत करणे\",\"भूतकाळातील घटनांचे कारण व परिणाम समजणे\",\"सध्याच्या घटनांची नोंद\",\"काहीही नाही\"],\"answer\":1,\"explain\":\"इतिहासाचे मुख्य उद्दिष्ट कारण व परिणाम समजणे.\"},{\"q\":\"इतिहासात ‘गेल्या वर्षी’ हा शब्द कोणत्या काळाला दर्शवतो?\",\"options\":[\"भूतकाळ\",\"वर्तमानकाळ\",\"भविष्यकाळ\",\"काळ नाही\"],\"answer\":0,\"explain\":\"‘गेल्या वर्षी’ भूतकाळ दर्शवतो.\"},{\"q\":\"इतिहासात ‘पुढील वर्षी’ हा शब्द कोणत्या काळाला दर्शवतो?\",\"options\":[\"भूतकाळ\",\"वर्तमानकाळ\",\"भविष्यकाळ\",\"काळ नाही\"],\"answer\":2,\"explain\":\"‘पुढील वर्षी’ भविष्यकाळ दर्शवतो.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16819,26,5,'EVS Part 2','mr','इतिहास आणि कालसंकल्पना द','[\"इतिहास म्हणजे भूतकाळातील घटनांचे ज्ञान\",\"भूतकाळ, वर्तमानकाळ आणि भविष्यकाळ हे तीन काळाचे प्रकार आहेत\",\"भूतकाळातील घटना ‘गेल्या वर्षी’, ‘काल’ अशा शब्दांनी ओळखतात\",\"वर्तमानकाळ म्हणजे ‘आत्ता’, ‘आज’ अशा शब्दांनी ओळखतात\",\"भविष्यकाळ म्हणजे ‘उद्या’, ‘पुढील वर्षी’ अशा शब्दांनी ओळखतात\",\"इतिहास शास्त्रीय पद्धतीने पुराव्यांची तपासणी करून लिहिला जातो\",\"पुरावे म्हणजे ग्रंथ, हस्तलिखिते, शिलालेख, नाणी, वास्तू इ.\",\"पुरातत्त्वशास्त्र भूतकाळातील वस्तू व वास्तूंचे अवशेष शोधते\",\"कर्व‑१४ पद्धतीने प्राचीन वस्तूंचे वय ठरवता येते\",\"काप्ठवलय पद्धतीने झाडाचे वय मोजता येते\",\"काळाची एकरेखिक विभागणी म्हणजे दिवस‑रात्र‑आठवडा‑महिना‑वर्ष‑शतक‑सहस्रक अशी क्रमवार मांडणी\",\"इसवी सनाची सुरुवात १ सप्टेंबर ४ ४५ ईसपू पूर्वी झाली\",\"इ.स. पू. १ १००० वर्षाला ‘पहिले सहस्रक’ म्हणतात\",\"इ.स. १ १००० वर्षाला ‘पहिले शतक’ म्हणतात\",\"काळ मोजण्यासाठी सेकंद, मिनिट, तास, दिवस, आठवडा, महिना, वर्ष, शतक, सहस्रक अशी एकके आहेत\",\"काळाची विभागणी आठवडा, पंधरवडा, महिना, वर्ष अशा एककांमध्ये केली जाते\",\"इतिहासाची साधने तीन प्रकारची असतात: भौतिक, लिखित, मौखिक\",\"भौतिक साधने: प्राचीन बस्तू, वास्तू, शिल्पे, नाणी\",\"लिखित साधने: ग्रंथ, हस्तलिखिते, शिलालेख\",\"मौखिक साधने: लोकगीते, लोककथा\",\"इतिहास शास्त्रात पुराव्यांची विश्वसनीयता तपासण्यासाठी ‘कसोटी’ पद्धती वापरतात\",\"इतिहास आपल्याला भूतकाळातील चुका व यश समजून घेऊन भविष्यकाळ चांगला घडवायला मदत करतो\",\"इतिहासाची कालविभागणी प्रागैतिहासिक, ऐतिहासिक, आधुनिक अशा टप्प्यांमध्ये होते\",\"शिवाजी महाराजांच्या जीवनातील महत्त्वाच्या घटना १६३०‑१६८० या काळात घडल्या\",\"इतिहासाच्या अभ्यासातून आपण समाजातील बदल व संस्कृतीची प्रगती समजू शकतो\"]','[{\"q\":\"भूतकाळातील घटना ओळखण्यासाठी कोणता शब्द वापरला जातो?\",\"options\":[\"गेल्या वर्षी\",\"आज\",\"उद्या\",\"पुढील वर्षी\"],\"answer\":0,\"explain\":\"‘गेल्या वर्षी’ हा शब्द भूतकाळ दर्शवतो.\"},{\"q\":\"इतिहास शास्त्रात पुराव्यांची विश्वसनीयता तपासण्यासाठी काय वापरले जाते?\",\"options\":[\"कसोटी पद्धती\",\"काळ मापन\",\"भौतिक साधने\",\"मौखिक साधने\"],\"answer\":0,\"explain\":\"पुराव्यांची विश्वसनीयता ‘कसोटी’ पद्धतीने तपासली जाते.\"},{\"q\":\"कर्व‑१४ पद्धतीने काय मोजता येते?\",\"options\":[\"वृक्षाचे वय\",\"भूतकाळातील वस्तूंचे वय\",\"भविष्यकाळातील घटना\",\"काळाची लांबी\"],\"answer\":1,\"explain\":\"कर्व‑१४ पद्धतीने प्राचीन वस्तूंचे वय मोजता येते.\"},{\"q\":\"काळाची एकरेखिक विभागणी म्हणजे काय?\",\"options\":[\"दिवस‑रात्र‑आठवडा‑महिना‑वर्ष‑शतक‑सहस्रक\",\"दिवस‑रात्र‑महिना‑वर्ष\",\"आठवडा‑पंधरवडा‑महिना\",\"महिना‑वर्ष‑शतक\"],\"answer\":0,\"explain\":\"एकरेखिक विभागणीमध्ये सर्व काळाचे एकके क्रमवार असतात.\"},{\"q\":\"भौतिक साधनांमध्ये कोणते समाविष्ट नाही?\",\"options\":[\"नाणी\",\"शिलालेख\",\"भांडी\",\"लोकगीते\"],\"answer\":3,\"explain\":\"लोकगीते मौखिक साधनात येतात.\"},{\"q\":\"इ.स. पू. १ १००० वर्षाला काय म्हणतात?\",\"options\":[\"पहिले शतक\",\"पहिले सहस्रक\",\"पहिले वर्ष\",\"पहिले पंधरवडा\"],\"answer\":1,\"explain\":\"इ.स. पू. १ १००० वर्षाला ‘पहिले सहस्रक’ म्हणतात.\"},{\"q\":\"शिवाजी महाराजांच्या जीवनातील महत्त्वाच्या घटना कोणत्या वर्षात घडल्या?\",\"options\":[\"१६००‑१६१०\",\"१६३०‑१६८०\",\"१७००‑१७५०\",\"१८००‑१८५०\"],\"answer\":1,\"explain\":\"शिवाजी महाराजांच्या घटना १६३०‑१६८० या काळात घडल्या.\"},{\"q\":\"काळ मोजण्यासाठी सर्वात लहान एकक कोणते?\",\"options\":[\"सेकंद\",\"मिनिट\",\"तास\",\"दिवस\"],\"answer\":0,\"explain\":\"काळ मोजण्यासाठी ‘सेकंद’ हे सर्वात लहान एकक आहे.\"},{\"q\":\"इतिहास शास्त्रात ‘पुरावा’ म्हणजे काय?\",\"options\":[\"भौतिक वस्तू\",\"लिखित दस्तऐवज\",\"मौखिक कथा\",\"वरील सर्व\"],\"answer\":3,\"explain\":\"पुरावा म्हणजे भौतिक, लिखित आणि मौखिक सर्व प्रकारचे.\"},{\"q\":\"काळाची विभागणी आठवडा, पंधरवडा, महिना, वर्ष अशा एककांमध्ये केली जाते. याला काय म्हणतात?\",\"options\":[\"काळाची एकरेखिक विभागणी\",\"काळाची वर्गीकरण\",\"काळाची क्रमवारी\",\"काळाची मापन पद्धती\"],\"answer\":0,\"explain\":\"या विभागणीला ‘काळाची एकरेखिक विभागणी’ म्हणतात.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16820,26,5,'EVS Part 2','mr','पृथ्वीवरील सजीव','[\"पृथ्वीची उत्पत्ती सुमारे ४.५ अब्ज वर्षांपूर्वी झाली.\",\"सूर्याभोवती फिरणारे ग्रह: बुध, शुक्र, पृथ्वी, मंगळ, गुरु, शनी, युरेनस, नेपच्यून.\",\"पृथ्वीवरील जलाशयांची निर्मिती सुमारे ८० कोटी वर्षे लागली.\",\"पहिले सजीव एकपेशीय होते, ज्यांना सूक्ष्मदर्शकाने पाहावे लागते.\",\"एकपेशीय सजीवांपासून बहुपेशीय सजीवांची निर्मिती झाली.\",\"प्राणिसृष्टीची वैशिष्ट्ये: श्वसन, अन्न शोधणे, हालचाल, प्रजनन.\",\"प्राणी अंडी घालतात किंवा अपत्याला जन्म देतात.\",\"मंगळावर पाणी, वायू आणि मातीमध्ये वनस्पतींचे घटक आढळतात, परंतु द्रवरूप पाणी कमी आहे.\",\"मंगळयान २००१ मध्ये भारताने पाठवले.\",\"सजीवांना द्रवरूप पाणी आवश्यक असते.\"]','[{\"q\":\"पृथ्वीची उत्पत्ती किती वर्षांपूर्वी झाली?\",\"options\":[\"४.५ अब्ज\",\"३.५ अब्ज\",\"५.५ अब्ज\",\"६.५ अब्ज\"],\"answer\":0,\"explain\":\"वैज्ञानिक अंदाजानुसार पृथ्वी सुमारे ४.५ अब्ज वर्षांपूर्वी तयार झाली.\"},{\"q\":\"पृथ्वीभोवती फिरणारे ग्रह कोणते?\",\"options\":[\"बुध, शुक्र, पृथ्वी, मंगळ\",\"बुध, शुक्र, मंगळ, गुरु\",\"शुक्र, पृथ्वी, गुरु, शनी\",\"बुध, शुक्र, पृथ्वी, गुरु\"],\"answer\":0,\"explain\":\"सूर्याभोवती फिरणारे ग्रह: बुध, शुक्र, पृथ्वी, मंगळ.\"},{\"q\":\"पहिले सजीव कोणते होते?\",\"options\":[\"बहुपेशीय\",\"एकपेशीय\",\"वायू\",\"पाणी\"],\"answer\":1,\"explain\":\"सर्वात पहिले सजीव एकपेशीय होते.\"},{\"q\":\"एकपेशीय सजीव पाहण्यासाठी काय आवश्यक?\",\"options\":[\"दूरदर्शक\",\"सूक्ष्मदर्शक\",\"कॅमेरा\",\"सूर्यदर्शक\"],\"answer\":1,\"explain\":\"सूक्ष्मदर्शकानेच एकपेशीय सजीव पाहता येतात.\"},{\"q\":\"प्राण्यांचे प्रजनन कसे होते?\",\"options\":[\"अंडी घालणे\",\"अपत्याला जन्म देणे\",\"दोन्ही\",\"काहीही नाही\"],\"answer\":2,\"explain\":\"काही प्राणी अंडी घालतात, काही अपत्याला जन्म देतात.\"},{\"q\":\"मंगळावर पाण्याचे प्रमाण किती?\",\"options\":[\"जवळजवळ ९५%\",\"जवळजवळ ५०%\",\"जवळजवळ २०%\",\"जवळजवळ ५%\"],\"answer\":0,\"explain\":\"मंगळाच्या वातावरणात कार्बन डायऑक्साइड जवळजवळ ९५% आहे.\"},{\"q\":\"मंगळावर द्रवरूप पाणी का कमी आहे?\",\"options\":[\"ध्रुवीय प्रदेशात नाही\",\"वायुमंडळात नाही\",\"उष्णतेमुळे बाष्पीभवन होते\",\"पाणी नाही\"],\"answer\":2,\"explain\":\"मंगळावर उष्णतेमुळे द्रवरूप पाणी फारसे नाही.\"},{\"q\":\"मंगळयान कोणत्या वर्षी यशस्वी झाले?\",\"options\":[\"२००१\",\"२००२\",\"२००३\",\"२००४\"],\"answer\":1,\"explain\":\"मंगळयान २४ सप्टेंबर २००४ रोजी यशस्वी झाले.\"},{\"q\":\"सजीवांना द्रवरूप पाणी का आवश्यक?\",\"options\":[\"उष्णता मिळवण्यासाठी\",\"वायू श्वसनासाठी\",\"पोषणासाठी\",\"काहीही नाही\"],\"answer\":2,\"explain\":\"द्रवरूप पाणी पोषण आणि श्वसनासाठी आवश्यक आहे.\"},{\"q\":\"पृथ्वीवरील जलाशयांची निर्मिती किती वर्षे लागली?\",\"options\":[\"८० कोटी वर्षे\",\"८० लाख वर्षे\",\"८० हजार वर्षे\",\"८० वर्षे\"],\"answer\":0,\"explain\":\"पृथ्वीवरील जलाशयांची निर्मिती सुमारे ८० कोटी वर्षे लागली.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16821,26,5,'EVS Part 2','mr','उत्क्रांती','[\"उत्क्रांती म्हणजे सजीवांच्या जीवनात सतत आणि संथ बदल होणे.\",\"उत्क्रांतीची संकल्पना चार्ल्स डार्विन यांनी १८५९ मध्ये मांडली.\",\"उत्क्रांतीमुळे नवीन प्रजाती निर्माण होतात आणि मूळ प्रजाती नष्ट होऊ शकतात.\",\"उत्क्रांतीचे टप्पे: एकपेशीय → बहुपेशीय → विविध वर्गांतील प्राणी आणि वनस्पती.\",\"पृष्ठवंशीय प्राणी म्हणजे पाठीचा कणा असलेले प्राणी.\",\"अपृष्ठवंशीय प्राणी म्हणजे पाठीचा कणा नसलेले प्राणी.\",\"उभयचर प्राणी पाणी आणि जमीन दोन्ही ठिकाणी वावरतात.\",\"सर्प आणि सरपटणारे प्राणी अंडी घालतात पण सस्तन प्राणी पिल्लांना जन्म देतात.\",\"मानवसदृश वानरांना एप वानर म्हणतात.\",\"डायनोसॉरच्या पंख असलेल्या प्रजातींनी पक्षी निर्माण केले.\",\"उत्क्रांतीमध्ये अनुकूलन आणि निवड यांचा महत्त्वाचा भाग असतो.\",\"प्राण्यांच्या उत्क्रांतीचे टप्पे: अपृष्ठवंशीय, पृष्ठवंशीय, उभयचर, सर्प, सस्तन.\",\"डार्विनने मानवाच्या शरीरातील अवशेष (उदा. शेपटीचे अवशेष) दाखवून मानवाची उत्क्रांती स्पष्ट केली.\",\"उत्क्रांतीचे उदाहरण: पाण्यातील मासे → उभयचर → सर्प → सस्तन → मानव.\",\"उत्क्रांतीमुळे प्रजातींची विविधता वाढते.\",\"उत्क्रांतीची प्रक्रिया निसर्गातील बदलांशी जुळवून घेते.\",\"उत्क्रांतीचे मुख्य कारण: पर्यावरणातील बदल, निवड, अनुकूलन.\",\"उत्क्रांतीची संकल्पना सजीवांच्या जीवनातील बदलांना स्पष्ट करते.\",\"उत्क्रांतीमुळे प्रजातींची वैशिष्ट्ये बदलतात आणि नवीन वैशिष्ट्ये निर्माण होतात.\",\"उत्क्रांतीचे उदाहरण: डायनोसॉर → पक्षी.\",\"उत्क्रांतीची संकल्पना सजीवांच्या जीवनातील बदलांना स्पष्ट करते.\",\"उत्क्रांतीमुळे प्रजातींची विविधता वाढते.\",\"उत्क्रांतीची संकल्पना सजीवांच्या जीवनातील बदलांना स्पष्ट करते.\"]','[{\"q\":\"चार्ल्स डार्विन यांनी उत्क्रांतीची संकल्पना कोणत्या वर्षी मांडली?\",\"options\":[\"1859\",\"1869\",\"1871\",\"1889\"],\"answer\":0,\"explain\":\"डार्विनने 1859 मध्ये \\\"ऑरिजिन ऑफ स्पीशीज\\\" प्रकाशित केले.\"},{\"q\":\"उत्क्रांतीच्या प्रक्रियेत कोणता घटक सर्वात महत्त्वाचा असतो?\",\"options\":[\"अनुकूलन\",\"निवड\",\"दोन्ही\",\"काहीही नाही\"],\"answer\":2,\"explain\":\"अनुकूलन व निवड दोन्ही उत्क्रांतीसाठी आवश्यक आहेत.\"},{\"q\":\"पृष्ठवंशीय प्राणी म्हणजे काय?\",\"options\":[\"पाठीचा कणा नसलेले\",\"पाठीचा कणा असलेले\",\"फक्त पाण्यात राहणारे\",\"फक्त जमिनीवर राहणारे\"],\"answer\":1,\"explain\":\"पृष्ठवंशीय प्राणी म्हणजे पाठीचा कणा असलेले प्राणी.\"},{\"q\":\"सर्प आणि सरपटणारे प्राणी अंडी घालतात का?\",\"options\":[\"होय\",\"नाही\",\"फक्त सर्प\",\"फक्त सरपटणारे\"],\"answer\":0,\"explain\":\"सर्प आणि सरपटणारे प्राणी दोन्ही अंडी घालतात.\"},{\"q\":\"मानवसदृश वानरांना काय म्हणतात?\",\"options\":[\"एप वानर\",\"सस्तन वानर\",\"पृष्ठवंशीय वानर\",\"पंख असलेले वानर\"],\"answer\":0,\"explain\":\"एप वानर म्हणजे मानवसदृश वानर.\"},{\"q\":\"डायनोसॉरच्या पंख असलेल्या प्रजातींनी कोणती नवीन प्रजाती निर्माण केली?\",\"options\":[\"पक्षी\",\"मासे\",\"उभयचर\",\"सर्प\"],\"answer\":0,\"explain\":\"पंख असलेल्या डायनोसॉरने पक्षी निर्माण केले.\"},{\"q\":\"उत्क्रांतीची संकल्पना कोणत्या शास्त्रज्ञाने मांडली?\",\"options\":[\"कार्ल लिनस\",\"विलार्ड लिबी\",\"लुई लिकी\",\"चार्ल्स डार्विन\"],\"answer\":3,\"explain\":\"चार्ल्स डार्विन यांनी उत्क्रांतीची संकल्पना मांडली.\"},{\"q\":\"उभयचर प्राणी कोणत्या ठिकाणी वावरतात?\",\"options\":[\"पाणी आणि जमीन दोन्ही\",\"फक्त पाणी\",\"फक्त जमीन\",\"फक्त हवा\"],\"answer\":0,\"explain\":\"उभयचर प्राणी पाणी व जमीन दोन्ही ठिकाणी वावरतात.\"},{\"q\":\"सस्तन प्राणी पिल्लांना कसे जन्म देतात?\",\"options\":[\"अंडी घालतात\",\"पिल्लांना जन्म देतात\",\"दोन्ही\",\"काहीही नाही\"],\"answer\":1,\"explain\":\"सस्तन प्राणी पिल्लांना जन्म देतात.\"},{\"q\":\"उत्क्रांतीमध्ये कोणते अवशेष मानवाच्या शरीरात दिसतात?\",\"options\":[\"शेपटीचे अवशेष\",\"पंखाचे अवशेष\",\"पाठीचा कणा नाही\",\"काहीही नाही\"],\"answer\":0,\"explain\":\"मानवाच्या पाठीच्या कण्यात शेपटीचे अवशेष दिसतात.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16822,26,5,'EVS Part 2','mr','मानवाची वाटचाल','[\"कुशल मानव म्हणजे हातांचा कुशल वापर करणारा मानव.\",\"ताठ कण्याचा मानव म्हणजे ताठ उभा राहणारा मानव, ज्याने दगडी हत्यारे बनवली.\",\"शक्तिमान मानव (होमो निएंडरथल) दगड आणि लाकडाची शस्त्रे बनवत असे आणि आग वापरू लागला.\",\"बुद्धिमान मानव (होमो सेपियन) मेंदू मोठा, भाषा आणि संस्कृती विकसित.\",\"मानवाची उत्क्रांती चार टप्प्यांत: कुशल मानव → ताठ कण्याचा मानव → शक्तिमान मानव → बुद्धिमान मानव.\",\"मानवाला ताठ उभे राहणे आणि दोन पायांवर चालणे शक्य झाले.\",\"मानवाच्या हातात अंगठा इतर चार बोटांच्या पुढे येतो, ज्यामुळे सूक्ष्म कामे करता येतात.\",\"मानवाचे मेंदू इतर प्राण्यांपेक्षा मोठे, विचार करण्याची क्षमता जास्त.\",\"मानवाचे चेहर्‍याचे स्नायू भावना व्यक्त करण्यास मदत करतात.\",\"मानवाची भाषा आणि लेखनाची सुरुवात सुमारे ११००० वर्षांपूर्वी झाली.\",\"शक्तिमान मानवाने आग वापरून अन्न शिजवले.\",\"बुद्धिमान मानवाने शेती आणि पशुपालन सुरू केले.\",\"मानवाच्या शरीररचनेत ताठ पाठीचा कणा, दोन पाय आणि हातांचा समावेश.\",\"मानवाची संस्कृती आणि तंत्रज्ञान सतत विकसित होत गेले.\",\"मानवाच्या अवशेषांमधून उत्क्रांतीचा इतिहास समजतो.\",\"मानवाच्या हाडांच्या अवशेषांना \'अश्मीभूत अवशेष\' म्हणतात.\",\"मानवाची भाषा आणि लेखन संस्कृतीच्या विकासाचे चिन्ह आहेत.\",\"मानवाची तंत्रज्ञानाची प्रगती शेती, पशुपालन, आग आणि साधनांच्या वापराने झाली.\",\"मानवाची सामाजिक रचना समूहात सहकार्यावर आधारित होती.\",\"मानवाची सांस्कृतिक प्रगती विचार आणि संवादावर अवलंबून होती.\",\"मानवाची उत्क्रांती एक रेषीय प्रक्रिया नसून शाखा आणि विलुप्तता समाविष्ट आहे.\",\"मानवाच्या शरीररचनेतील वैशिष्ट्ये इतर पृच्छवंशीय प्राण्यांपेक्षा वेगळी आहेत.\",\"मानवाची भाषा आणि संस्कृती मानवी बुद्धिमत्तेचे प्रतीक आहेत.\"]','[{\"q\":\"कुशल मानवाची वैशिष्ट्ये काय आहेत?\",\"options\":[\"हातांचा कुशल वापर\",\"फक्त दगडी हत्यारे बनवणे\",\"आग वापरणे\",\"शक्तिमान मानवापेक्षा लहान मेंदू\"],\"answer\":0,\"explain\":\"कुशल मानवाने हातांचा कुशल वापर करून साधने बनवली.\"},{\"q\":\"ताठ कण्याचा मानव कोणत्या टप्प्यात येतो?\",\"options\":[\"कुशल मानवापूर्वी\",\"कुशल मानवानंतर\",\"शक्तिमान मानवापूर्वी\",\"बुद्धिमान मानवानंतर\"],\"answer\":1,\"explain\":\"ताठ कण्याचा मानव कुशल मानवानंतर येतो.\"},{\"q\":\"शक्तिमान मानवाने कोणते साधन वापरले?\",\"options\":[\"दगडी भाला\",\"पाषाण शस्त्रे\",\"लाकडी भाला\",\"दगडी हातकुर्व\"],\"answer\":3,\"explain\":\"शक्तिमान मानवाने दगडी हातकुर्व बनवले.\"},{\"q\":\"बुद्धिमान मानवाचे मेंदूचे आकार कसे होते?\",\"options\":[\"कुशल मानवापेक्षा लहान\",\"ताठ कण्याच्या मानवापेक्षा मोठे\",\"शक्तिमान मानवापेक्षा लहान\",\"समान आकाराचे\"],\"answer\":1,\"explain\":\"बुद्धिमान मानवाचे मेंदू ताठ कण्याच्या मानवापेक्षा मोठे होते.\"},{\"q\":\"मानवाच्या उत्क्रांतीत कोणता टप्पा आग वापराशी संबंधित आहे?\",\"options\":[\"कुशल मानव\",\"ताठ कण्याचा मानव\",\"शक्तिमान मानव\",\"बुद्धिमान मानव\"],\"answer\":2,\"explain\":\"शक्तिमान मानवाने आग वापरणे सुरू केले.\"},{\"q\":\"मानवाच्या शरीररचनेतील कोणते वैशिष्ट्य त्याला ताठ उभे राहण्यास मदत करते?\",\"options\":[\"लांब पाय\",\"अंगठ्याची स्थिती\",\"दोन पाय\",\"दगडी हत्यारे\"],\"answer\":2,\"explain\":\"मानवाला दोन पायांवर ताठ उभे राहणे शक्य झाले.\"},{\"q\":\"मानवाच्या चेहर्‍याच्या स्नायूंचे कार्य काय आहे?\",\"options\":[\"भाषा बोलणे\",\"भावना व्यक्त करणे\",\"हातांची हालचाल\",\"आग लावणे\"],\"answer\":1,\"explain\":\"चेहर्‍याचे स्नायू भावना व्यक्त करण्यास मदत करतात.\"},{\"q\":\"मानवाच्या हाडांच्या अवशेषांना काय म्हणतात?\",\"options\":[\"अश्मीभूत अवशेष\",\"दगडी अवशेष\",\"पाषाण अवशेष\",\"शरीर अवशेष\"],\"answer\":0,\"explain\":\"हाडांचे दगड \'अश्मीभूत अवशेष\' म्हणतात.\"},{\"q\":\"बुद्धिमान मानवाने कोणत्या तंत्रज्ञानाची सुरुवात केली?\",\"options\":[\"शिकार\",\"शक्तिमान मानवापेक्षा लहान साधने\",\"शेती आणि पशुपालन\",\"आग वापरणे\"],\"answer\":2,\"explain\":\"बुद्धिमान मानवाने शेती व पशुपालन सुरू केले.\"},{\"q\":\"मानवाच्या उत्क्रांतीत कोणता टप्पा सर्वात लवकर आढळतो?\",\"options\":[\"कुशल मानव\",\"ताठ कण्याचा मानव\",\"शक्तिमान मानव\",\"बुद्धिमान मानव\"],\"answer\":0,\"explain\":\"कुशल मानव सर्वात लवकर आढळणारा टप्पा आहे.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16823,26,5,'EVS Part 2','mr','अश्मयुग : दगडाची हत्यारे','[\"अश्मयुग म्हणजे दगडाचा वापर मुख्यतः करणारा काळ\",\"या काळात दगड, हाडे, शंख यांपासून साधी हत्यारे बनवली जात\",\"साधनांची निवड उपलब्धता, वेळ, ऊर्जा आणि परिणामकारकतेवर अवलंबून\",\"दगडाची हत्यारे: दगडी गोट्या, तासणी, घण, छिलक्‍याचे तोडहत्यार\",\"हाडाची हत्यारे: हाडाचा टोचा, शिंगाचे खणते\",\"काठी आणि काटक्या नाशवंत असल्याने क्वचित वापरली जात\",\"पुराश्मयुग, मध्याश्मयुग आणि नवाश्मयुग हे तीन उपकाळ आहेत\",\"पुराश्मयुगात दगडाचे लांब पात्याचे सुरी, तासणी बनवली\",\"मध्याश्मयुगात सूक्ष्मास्त्रे आणि बाण बनवले\",\"नवाश्मयुगात शेतीसाठी दगडी हत्यारे वापरली\",\"हत्यार बनवण्याची तंत्रे: दगडाचे छिलके काढणे, धार लावणे\",\"हत्यार वापरून अन्न तयार करणे, शिकार, मासेमारी, कापणी\",\"दगडाच्या हत्यारांमुळे मानवी जीवनात बदल घडले\",\"अश्मयुगात दगडाची हत्यारे मुख्यतः वापरली जात\",\"हत्यारांची विविधता मानवी बुद्धिमत्तेचे प्रतीक आहे\"]','[{\"q\":\"अश्मयुगात मुख्यतः कोणत्या पदार्थापासून हत्यारे बनवली जात?\",\"options\":[\"दगड\",\"धातू\",\"लाकूड\",\"शंख\"],\"answer\":0,\"explain\":\"अश्मयुगात दगड हा प्रमुख पदार्थ होता.\"},{\"q\":\"खालीलपैकी कोणते दगडाचे हत्यारे नाही?\",\"options\":[\"तासणी\",\"घण\",\"शिंगाचे खणते\",\"दगडी गोट्या\"],\"answer\":2,\"explain\":\"शिंगाचे खणते हे हाडाचे हत्यारे आहे.\"},{\"q\":\"पुराश्मयुगात कोणत्या प्रकारचे दगडी हत्यारे बनवले गेले?\",\"options\":[\"सुरी\",\"बाण\",\"शिंगाचे खणते\",\"काठी\"],\"answer\":0,\"explain\":\"पुराश्मयुगात दगडी सुरी बनवली.\"},{\"q\":\"मध्याश्मयुगात कोणत्या तंत्राने सूक्ष्मास्त्रे तयार केली?\",\"options\":[\"सुईसारखी पाती\",\"लांब पाती\",\"हाडाचे तुकडे\",\"दगडाचे तुकडे\"],\"answer\":0,\"explain\":\"सूक्ष्मास्त्रे लहान पातीने तयार केली.\"},{\"q\":\"नवाश्मयुगात दगडाची हत्यारे मुख्यतः कशासाठी वापरली?\",\"options\":[\"शिकार\",\"शेती\",\"मासेमारी\",\"कापणी\"],\"answer\":1,\"explain\":\"नवाश्मयुगात शेतीसाठी दगडाची हत्यारे वापरली.\"},{\"q\":\"दगडाचे छिलके काढून धार लावण्याची पद्धत काय म्हणतात?\",\"options\":[\"आघात तंत्र\",\"तासणी तंत्र\",\"घण तंत्र\",\"काठी तंत्र\"],\"answer\":0,\"explain\":\"आघात तंत्राने दगडाचे छिलके काढले.\"},{\"q\":\"अश्मयुगात दगडाची हत्यारे वापरण्याचे मुख्य कारण काय?\",\"options\":[\"सोपे उपलब्ध\",\"कमी ऊर्जा\",\"उच्च परिणामकारकता\",\"सर्वोच्च सौंदर्य\"],\"answer\":2,\"explain\":\"दगडाची हत्यारे अधिक परिणामकारक होती.\"},{\"q\":\"खालीलपैकी कोणते हत्यारे काठी किंवा काटक्या आहेत?\",\"options\":[\"हाडाचा टोचा\",\"शिंगाचे खणते\",\"काठी\",\"घण\"],\"answer\":2,\"explain\":\"काठी आणि काटक्या नाशवंत आहेत.\"},{\"q\":\"पुराश्मयुगातील दगडी हत्यारे बनवण्यासाठी कोणते साधन वापरले?\",\"options\":[\"दगडाचे छिलके\",\"हाडाचे तुकडे\",\"शंखाचे तुकडे\",\"लाकडाचे तुकडे\"],\"answer\":0,\"explain\":\"दगडाचे छिलके काढून धार लावली.\"},{\"q\":\"अश्मयुगात दगडाची हत्यारे बनवण्यासाठी कोणती तंत्रे वापरली?\",\"options\":[\"आघात तंत्र\",\"तासणी तंत्र\",\"घण तंत्र\",\"काठी तंत्र\"],\"answer\":0,\"explain\":\"आघात तंत्राने दगडाची हत्यारे बनवली.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16824,26,5,'EVS Part 2','mr','निवारा ते गाव-वसाहती','[\"निवारा म्हणजे एक जागा जिथे मानव आपले घर बांधतो आणि राहतो.\",\"हंगामी तळ म्हणजे तात्पुरती वसाहत जी ऋतूनुसार बदलते.\",\"मध्याश्मयुगात मानवाने गुहांमध्ये वसाहती केल्या आणि शेकोटीचा वापर केला.\",\"मध्याश्मयुगात शिकार आणि मासेमारी हे मुख्य अन्नाचे स्रोत होते.\",\"मध्याश्मयुगात मॅमोथसारखे मोठे प्राणी नष्ट झाले कारण हवामान बदलले.\",\"नवाश्मयुगात शेती सुरू झाली आणि मानव एकाच ठिकाणी दीर्घकाळ राहू लागला.\",\"नवाश्मयुगात गाव-वसाहतींमध्ये घरांची रचना साधी आणि लाकडाची असायची.\",\"नवाश्मयुगात घरांच्या बांधणीसाठी तांदळाचे तांदूळ आणि गवत वापरले जायचे.\",\"हिमयुगात पृथ्वीचा बहुतेक भाग बर्फाच्छादित असतो आणि हवामान अतिशीत असते.\",\"आंतर्हिमयुगात हवामान उबदार आणि आर्द्र असते आणि पाण्याची पातळी वाढते.\",\"हिमयुग आणि आंतर्हिमयुग हे आलटून पालटून येणारे कालखंड आहेत.\",\"नवाश्मयुगात शेती सुरू झाल्यामुळे गावांची रचना अधिक स्थिर झाली.\",\"नवाश्मयुगात घरांची रचना लाकूड, गवत, माती इत्यादी साहित्याने केली जायची.\",\"हंगामी तळात विविध व्यवसाय जसे शिकार, मासेमारी, गोळा करणे इत्यादी होते.\",\"हिमयुगात पाण्याची पातळी कमी होते आणि बर्फ मोठ्या प्रमाणावर वितळतो.\",\"आंतर्हिमयुगात पाऊस जास्त पडतो आणि हवामान उबदार होते.\"]','[{\"q\":\"निवारा म्हणजे काय?\",\"options\":[\"मातीचे घर\",\"कुंड\",\"जिथे मानव राहतो\",\"शेकोटी\"],\"answer\":2,\"explain\":\"निवारा म्हणजे मानवाचे घर किंवा वसाहत.\"},{\"q\":\"मध्याश्मयुगात मानव मुख्यतः कुठे राहत होते?\",\"options\":[\"गुहा\",\"शेत\",\"गाव\",\"बाजार\"],\"answer\":0,\"explain\":\"मध्याश्मयुगात गुहांमध्ये वसाहती केल्या जात होत्या.\"},{\"q\":\"हंगामी तळ म्हणजे काय?\",\"options\":[\"स्थायी वसाहत\",\"तात्पुरती वसाहत\",\"शाळा\",\"किल्ला\"],\"answer\":1,\"explain\":\"हंगामी तळ म्हणजे ऋतूनुसार बदलणारी तात्पुरती वसाहत.\"},{\"q\":\"नवाश्मयुगात शेतीची सुरुवात कशी झाली?\",\"options\":[\"शिकार\",\"मासेमारी\",\"शेतात पिके उगवणे\",\"संग्रह\"],\"answer\":2,\"explain\":\"नवाश्मयुगात शेती सुरू झाली आणि पिके उगवली.\"},{\"q\":\"हिमयुगात पृथ्वीचा पृष्ठभाग कसा असतो?\",\"options\":[\"बर्फाच्छादित\",\"उबदार\",\"आर्द्र\",\"सुकं\"],\"answer\":0,\"explain\":\"हिमयुगात पृष्ठभाग बर्फाच्छादित असतो.\"},{\"q\":\"आंतर्हिमयुगात हवामान कसे असते?\",\"options\":[\"अतिशीत\",\"उबदार आणि आर्द्र\",\"शुष्क\",\"बर्फाळ\"],\"answer\":1,\"explain\":\"आंतर्हिमयुगात हवामान उबदार आणि आर्द्र असते.\"},{\"q\":\"नवाश्मयुगात घरांची रचना कशी असते?\",\"options\":[\"मातीची\",\"लाकडी आणि गवताची\",\"बांबूची\",\"धातूची\"],\"answer\":1,\"explain\":\"नवाश्मयुगात लाकूड व गवत वापरून घर बांधले जायचे.\"},{\"q\":\"हंगामी तळात कोणते व्यवसाय असतात?\",\"options\":[\"शिकार, मासेमारी, गोळा करणे\",\"शेती, वणवण\",\"बांधकाम, दगड खणणे\",\"संगीत, नृत्य\"],\"answer\":0,\"explain\":\"हंगामी तळात शिकार, मासेमारी आणि गोळा करणे हे मुख्य व्यवसाय असतात.\"},{\"q\":\"हिमयुगात समुद्रातील पाण्याची पातळी कशी असते?\",\"options\":[\"उंचावते\",\"कमी होते\",\"समान राहते\",\"बदलत नाही\"],\"answer\":1,\"explain\":\"हिमयुगात बर्फामुळे पाण्याची पातळी कमी होते.\"},{\"q\":\"नवाश्मयुगात कोणते साहित्य घरांच्या बांधणीसाठी वापरले जाते?\",\"options\":[\"धातू\",\"काच\",\"लाकूड व गवत\",\"प्लास्टिक\"],\"answer\":2,\"explain\":\"नवाश्मयुगात लाकूड व गवत हे प्रमुख साहित्य होते.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16825,26,5,'EVS Part 2','mr','स्थिर जीवनाची सुरुवात','[\"पशुपालन म्हणजे माणसाने प्राण्यांना पाळणे आणि त्यांच्यापासून दूध, मांस, लोकर इत्यादी मिळवणे.\",\"शेती म्हणजे पिके उगवणे, पेरणी, नांगरणी आणि कापणी करणे.\",\"पशुपालन आणि शेतीची सुरुवात सुमारे ११,००० वर्षांपूर्वी झाली.\",\"पहिले पाळीव प्राणी कुत्रे, नंतर शेळ्या, मेंढ्या, गाय आणि बैल होते.\",\"शेतीची सुरुवात होण्यापूर्वी माणसांनी शिकार व फळे गोळा करून अन्न घेतले.\",\"शेतीमुळे अन्नधान्य दीर्घकाळ साठवता येऊ लागले, ज्यामुळे स्थिर जीवनशैली आली.\",\"पशुपालन आणि शेतीमुळे समाजात कामांचे विभाजन आणि विशेष कौशल्ये विकसित झाली.\",\"नांगर ओढण्यासाठी बैल आणि इतर पाळीव प्राणी वापरले जातात.\",\"शेतीच्या कामात टोकदार काठी आणि दगड वापरून पेरणी केली जाते.\",\"पशुपालनामुळे दूध, लोकर, कातडी इत्यादी उपयुक्त वस्तू मिळतात.\",\"शेतीमुळे पिकांचे उत्पादन वाढले आणि अन्नाची कमतरता कमी झाली.\",\"गावात मातीची भांडी, मणी, मीठ इत्यादी वस्तूंचा व्यापार सुरू झाला.\",\"गावातील सहकार्यामुळे कामांचे वाटप आणि संरक्षण व्यवस्था तयार झाली.\",\"पाळीव प्राण्यांच्या मदतीने शेतात नांगरणी आणि पेरणी सोपी झाली.\",\"पाळीव प्राणी आणि शेतीमुळे मानवी समाजाची रचना बदलली आणि शहरांची सुरुवात झाली.\",\"पाळीव प्राण्यांमुळे माणसांना शिकार व अन्न गोळा करण्याची गरज कमी झाली.\",\"शेतीमुळे पिकांचे साठवण आणि व्यापार वाढला.\",\"पाळीव प्राणी आणि शेतीमुळे मानवी संस्कृती आणि तंत्रज्ञानात प्रगती झाली.\",\"पाळीव प्राणी आणि शेतीमुळे मानवी समाजात स्त्री-पुरुषांचे कामाचे विभाजन स्पष्ट झाले.\",\"पाळीव प्राणी आणि शेतीमुळे मानवी समाजात विशेष कौशल्ये आणि व्यवसाय निर्माण झाले.\",\"पाळीव प्राणी आणि शेतीमुळे मानवी समाजात सहकार्य आणि नियमांची गरज निर्माण झाली.\",\"पाळीव प्राणी आणि शेतीमुळे मानवी समाजात व्यापार आणि विनिमय वाढला.\",\"पाळीव प्राणी आणि शेतीमुळे मानवी समाजात स्थिरता आणि सुरक्षितता वाढली.\",\"पाळीव प्राणी आणि शेतीमुळे मानवी समाजात शिक्षण व संस्कृतीची पायाभरणी झाली.\"]','[{\"q\":\"पशुपालन म्हणजे काय?\",\"options\":[\"प्राण्यांना पाळणे\",\"शेती करणे\",\"शिकार करणे\",\"पिके उगवणे\"],\"answer\":0,\"explain\":\"पशुपालन म्हणजे प्राण्यांना पाळून त्यांच्यापासून उपयुक्त वस्तू मिळवणे.\"},{\"q\":\"शेतीची सुरुवात सुमारे किती वर्षांपूर्वी झाली?\",\"options\":[\"१,००० वर्षे\",\"५,००० वर्षे\",\"११,००० वर्षे\",\"१५,००० वर्षे\"],\"answer\":2,\"explain\":\"शेतीची सुरुवात सुमारे ११,००० वर्षांपूर्वी झाली.\"},{\"q\":\"पहिले पाळीव प्राणी कोणते होते?\",\"options\":[\"कुत्रे\",\"मेंढ्या\",\"गाय\",\"बैल\"],\"answer\":0,\"explain\":\"पहिले पाळीव प्राणी कुत्रे होते.\"},{\"q\":\"शेतीमध्ये नांगर ओढण्यासाठी कोणता प्राणी वापरला जातो?\",\"options\":[\"कुत्रा\",\"मेंढी\",\"बैल\",\"गाय\"],\"answer\":2,\"explain\":\"बैल नांगर ओढण्यासाठी वापरला जातो.\"},{\"q\":\"शेतीमुळे मानवी समाजात काय बदल झाले?\",\"options\":[\"शिकार वाढला\",\"अन्न साठवता आले\",\"कृषी कमी झाली\",\"शिकारी वाढला\"],\"answer\":1,\"explain\":\"शेतीमुळे अन्न साठवता आले आणि स्थिर जीवनशैली आली.\"},{\"q\":\"पाळीव प्राण्यांमुळे कोणती उपयुक्त वस्तू मिळते?\",\"options\":[\"लोकर\",\"माती\",\"पाणी\",\"अग्नि\"],\"answer\":0,\"explain\":\"मेंढी आणि शेळ्यांमुळे लोकर मिळते.\"},{\"q\":\"शेतीमध्ये पेरणीसाठी कोणते साधन वापरले जाते?\",\"options\":[\"टोकदार काठी\",\"दगड\",\"पंखा\",\"काठी\"],\"answer\":0,\"explain\":\"पेरणीसाठी टोकदार काठी वापरली जाते.\"},{\"q\":\"पाळीव प्राणी आणि शेतीमुळे समाजात काय झाले?\",\"options\":[\"कामाचे विभाजन\",\"शिकार वाढला\",\"अन्न कमी झाले\",\"कृषी कमी झाली\"],\"answer\":0,\"explain\":\"कामाचे विभाजन आणि विशेष कौशल्ये विकसित झाली.\"},{\"q\":\"शेतीची सुरुवात होण्यापूर्वी माणसांनी अन्न कसे घेतले?\",\"options\":[\"शिकार\",\"पाळीव प्राणी\",\"पिके\",\"साठवण\"],\"answer\":0,\"explain\":\"शिकार व फळे गोळा करून अन्न घेतले.\"},{\"q\":\"पाळीव प्राण्यांच्या मदतीने काय सोपे झाले?\",\"options\":[\"शिकार\",\"पेरणी\",\"पिके उगवणे\",\"साठवण\"],\"answer\":1,\"explain\":\"पाळीव प्राण्यांच्या मदतीने पेरणी आणि नांगरणी सोपी झाली.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16826,26,5,'EVS Part 2','mr','स्थिर जीबन आणि नागरी संस्कृती','[\"धातूचा वापर – प्राचीन काळात प्रथम सोने, नंतर तांबे, मग लोखंड वापरले गेले.\",\"सोनं सर्वात मऊ धातू असून सुंदर भांडी व शस्त्रे बनवण्यासाठी वापरले गेले.\",\"तांबे कठीण असले तरी मिश्र धातू बनवण्यासाठी जस्त मिसळून कासे (कांस्य) तयार केले गेले.\",\"कांस्य युगाला ताम्रपाषाणयुगीन असेही म्हणतात.\",\"चाकाची शोधामुळे भांडी घडवणे व वाहतूक दोन्ही सोपे झाले.\",\"चाकामुळे व्यापार व उत्पादन वाढले, ज्यामुळे नगरांची वाढ झाली.\",\"नगरांमध्ये नोंदी ठेवण्यासाठी लिपी व लेखन पद्धती विकसित झाली.\",\"हडप्पा संस्कृती ही भारतातील सर्वात प्राचीन नागरी संस्कृती होती.\",\"रोझेटा शिलालेखात तीन लिपी – चित्रलिपी, डेमोटिक व ग्रीक – वापरल्या गेल्या.\",\"रोझेटा शिलालेखामुळे प्राचीन इजिप्तची चित्रलिपी वाचता आली.\",\"धातूंची वर्गवारी तीन युगांमध्ये – दगड, तांबे व लोखंड – केली जाते.\",\"धातूंचा शोध व वापर समाजाच्या विकासात महत्त्वपूर्ण भूमिका बजावतो.\",\"चाकामुळे वाहतूक व व्यापारात क्रांती आली, ज्यामुळे नगरांची निर्मिती झाली.\",\"लिपी व लेखन पद्धतीने समाजाची संघटना व नोंदी ठेवणे शक्य झाले.\",\"धातूंच्या मिश्रणाने शस्त्रे व भांडी अधिक टिकाऊ व कार्यक्षम बनली.\",\"धातूंचा शोध व वापर मानव समाजाच्या प्रगतीचा सूचक आहे.\"]','[{\"q\":\"सर्वात मऊ धातू कोणता आहे?\",\"options\":[\"सोनं\",\"तांबे\",\"लोखंड\",\"चांदी\"],\"answer\":0,\"explain\":\"सोनं सर्वात मऊ धातू आहे.\"},{\"q\":\"धातूंची तीन युगं कोणती?\",\"options\":[\"दगड, तांबे, लोखंड\",\"सोनं, तांबे, चांदी\",\"तांबे, कांस्य, लोखंड\",\"दगड, कांस्य, लोखंड\"],\"answer\":0,\"explain\":\"धातूंची युगं दगड, तांबे व लोखंड अशी आहेत.\"},{\"q\":\"चाकाचा शोध कोणत्या युगात झाला?\",\"options\":[\"दगडयुग\",\"तांब्ययुग\",\"लोखंडयुग\",\"कांस्ययुग\"],\"answer\":1,\"explain\":\"चाकाचा शोध तांब्ययुगात झाला.\"},{\"q\":\"रोझेटा शिलालेखात कोणत्या तीन लिपी आहेत?\",\"options\":[\"चित्रलिपी, डेमोटिक, ग्रीक\",\"हायरोग्लिफ्स, लिपी, ग्रीक\",\"चिन्हे, लिपी, ग्रीक\",\"चित्रलिपी, ग्रीक, चायनीज\"],\"answer\":0,\"explain\":\"रोझेटा शिलालेखात चित्रलिपी, डेमोटिक व ग्रीक लिपी आहेत.\"},{\"q\":\"कांस्य युगात कोणता धातू मुख्यतः वापरला गेला?\",\"options\":[\"सोनं\",\"तांबे\",\"जस्त\",\"कांस्य\"],\"answer\":3,\"explain\":\"कांस्य युगात कांस्य (तांबे+जस्त) वापरला गेला.\"},{\"q\":\"धातूंच्या मिश्रणाने तयार झालेला धातू काय म्हणतात?\",\"options\":[\"कासे\",\"कांस्य\",\"मिश्रधातू\",\"धातू\"],\"answer\":0,\"explain\":\"तांबे व जस्त मिसळून कासे तयार होतो.\"},{\"q\":\"हडप्पा संस्कृती कोणत्या प्रदेशात होती?\",\"options\":[\"सिंधू नदी खोरे\",\"गंगा खोरे\",\"दक्षिण भारत\",\"पश्चिम भारत\"],\"answer\":0,\"explain\":\"हडप्पा संस्कृती सिंधू नदी खोऱ्यात होती.\"},{\"q\":\"धातूंचा शोध व वापर समाजाच्या कोणत्या पैलूला मदत करतो?\",\"options\":[\"कृषी\",\"वाणिज्य\",\"सामाजिक संघटना\",\"सर्व वरील\"],\"answer\":3,\"explain\":\"धातूंचा शोध व वापर सर्व पैलूंना मदत करतो.\"},{\"q\":\"चाकाच्या शोधामुळे काय बदलले?\",\"options\":[\"भांडी घडवणे व वाहतूक\",\"भाषा\",\"धातूंचा वापर\",\"कृषी\"],\"answer\":0,\"explain\":\"चाकामुळे भांडी घडवणे व वाहतूक दोन्ही बदलले.\"},{\"q\":\"रोझेटा शिलालेखाचा शोध कोणत्या वर्षी लागला?\",\"options\":[\"इ.स. १७९९\",\"इ.स. १८००\",\"इ.स. १७८०\",\"इ.स. १७५०\"],\"answer\":0,\"explain\":\"रोझेटा शिलालेख १७९९ साली सापडला.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16827,26,5,'EVS Part 2','mr','ऐतिहासिक काळ','[\"संस्कृती म्हणजे मानवी समाजाने तयार केलेली वस्तू, कला, विज्ञान व परंपरा यांचा समुच्चय.\",\"नद्यांच्या खोऱ्यांमध्ये विकसित झालेल्या प्राचीन नागरी संस्कृतींना ‘नद्यांच्या खोऱ्यांतील नागरी संस्कृती’ म्हणतात.\",\"मेसोपोटेमिया म्हणजे टायग्रिस व युफ्रेटिस या दोन नद्यांच्या मधला प्रदेश.\",\"इजिप्तची प्राचीन संस्कृती नाईल नदीच्या खोऱ्यात विकसित झाली.\",\"हडप्पा संस्कृती भारतीय उपखंडातील सिंधू नदीच्या खोऱ्यात फुलली.\",\"हडप्पा संस्कृतीची वैशिष्ट्ये – मातीची भांडी, चाक, व्यापार, लिपी, नगररचना.\",\"हडप्पा संस्कृतीची लिपी आजपर्यंत वाचता आलेली नाही.\",\"मेसोपोटेमियातील प्रमुख संस्कृती – सुमेरियन, अक्केडियन, बॅबिलोनियन, अँसिरियन.\",\"इजिप्तमध्ये पिरॅमिड व मंदिरे बांधण्यासाठी मातीच्या विटांचा वापर केला गेला.\",\"चीनमध्ये हो नदीच्या खोऱ्यात सार्वजनिक स्नानगृहे व शौचालये होती.\",\"प्राचीन काळात खेळ – पट, सोंगट्या, कुस्ती, शिकार – यांचा महत्त्व होता.\",\"संगीत व नृत्य हे प्राचीन संस्कृतींचे सामाजिक व धार्मिक कार्यक्रम होते.\",\"प्राचीन नागरी संस्कृतींमध्ये पाणी वाटप करण्यासाठी मध्यवर्ती यंत्रणा होती.\",\"हडप्पा संस्कृतीत चाकाची वाहने व जलमार्गाचा वापर व्यापारात केला गेला.\",\"नद्यांच्या काठची जमीन सुपीक होते कारण तिथे वारंवार पूर येत असे.\",\"संगणक व गणित, खगोलशास्त्र व वैद्यक या शास्त्रांचा विकास प्राचीन काळात झाला.\",\"हडप्पा संस्कृतीतील कारागीर मातीची भांडी, धातू व दगडाची वस्तू बनवत होते.\",\"हडप्पा संस्कृतीचे नगर – मोहेंजोदडो, हडप्पा – सुव्यवस्थित रस्ते व तटबंदी होती.\",\"हडप्पा संस्कृतीतील ‘बालाग’ हे ११ तारांचे तंतुवाद्य होते.\",\"हडप्पा संस्कृतीतील ‘हडप्पाकालीन खेळणे’ हे मातीच्या सोंगट्या व पट होते.\",\"हडप्पा संस्कृतीतील ‘हडप्पाकालीन मुद्रा व मूर्ती’ हे धार्मिक व सामाजिक प्रतीक होते.\",\"हडप्पा संस्कृतीतील ‘हडप्पाकालीन खेळणे’ हे संगीत व नृत्याच्या कार्यक्रमात वापरले जायचे.\",\"हडप्पा संस्कृतीतील ‘हडप्पाकालीन खेळणे’ हे प्राचीन काळातील मनोरंजनाचे साधन होते.\",\"हडप्पा संस्कृतीतील ‘हडप्पाकालीन खेळणे’ हे प्राचीन काळातील सामाजिक संवादाचे माध्यम होते.\",\"हडप्पा संस्कृतीतील ‘हडप्पाकालीन खेळणे’ हे प्राचीन काळातील शिक्षणाचे साधन होते.\"]','[{\"q\":\"मेसोपोटेमिया म्हणजे कोणत्या दोन नद्यांच्या मधला प्रदेश?\",\"options\":[\"सिन्धू व गंगा\",\"गंगा व यमुना\",\"टायग्रिस व युफ्रेटिस\",\"सिन्धू व ब्रह्मा\"],\"answer\":2,\"explain\":\"मेसोपोटेमिया म्हणजे टायग्रिस व युफ्रेटिस या दोन नद्यांच्या मधला प्रदेश.\"},{\"q\":\"हडप्पा संस्कृतीची लिपी आजपर्यंत वाचता आली आहे का?\",\"options\":[\"होय\",\"नाही\",\"कदाचित\",\"अज्ञात\"],\"answer\":1,\"explain\":\"हडप्पा संस्कृतीची लिपी आजपर्यंत वाचता आलेली नाही.\"},{\"q\":\"हडप्पा संस्कृतीतील प्रमुख वस्तू कोणत्या?\",\"options\":[\"मातीची भांडी व चाक\",\"सोन्याची दागिने\",\"कापड व सूत\",\"कागद व पपायरस\"],\"answer\":0,\"explain\":\"हडप्पा संस्कृतीतील प्रमुख वस्तू मातीची भांडी व चाक होत्या.\"},{\"q\":\"इजिप्तमध्ये पिरॅमिड व मंदिरे बांधण्यासाठी कोणता साहित्य वापरला गेला?\",\"options\":[\"दगड\",\"मातीची विटा\",\"लाकूड\",\"धातू\"],\"answer\":1,\"explain\":\"इजिप्तमध्ये पिरॅमिड व मंदिरे बांधण्यासाठी मातीची विटा वापरली गेली.\"},{\"q\":\"प्राचीन काळात कोणते खेळ लोकप्रिय होते?\",\"options\":[\"बास्केटबॉल व फुटबॉल\",\"पट व सोंगट्या\",\"टेनिस व गोल्फ\",\"सायकलिंग व रेसिंग\"],\"answer\":1,\"explain\":\"प्राचीन काळात पट व सोंगट्या हे लोकप्रिय खेळ होते.\"},{\"q\":\"हडप्पा संस्कृतीतील ‘बालाग’ हे काय आहे?\",\"options\":[\"भांडी\",\"संगीत वाद्य\",\"चाक\",\"पिरॅमिड\"],\"answer\":1,\"explain\":\"बालाग हे ११ तारांचे तंतुवाद्य होते.\"},{\"q\":\"हडप्पा संस्कृतीतील नगररचना कशी होती?\",\"options\":[\"अव्यवस्थित व अव्यवस्थित\",\"सुव्यवस्थित व तटबंदी असलेली\",\"फक्त चाकावर आधारित\",\"फक्त पाण्यावर आधारित\"],\"answer\":1,\"explain\":\"हडप्पा संस्कृतीतील नगररचना सुव्यवस्थित व तटबंदी असलेली होती.\"},{\"q\":\"मेसोपोटेमियातील प्रमुख संस्कृतींची नावे काय आहेत?\",\"options\":[\"सुमेरियन, अक्केडियन, बॅबिलोनियन, अँसिरियन\",\"इजिप्त, चीन, भारत, ग्रीस\",\"हडप्पा, मोहेंजोदडो, लोथल, धोलावीरा\",\"सिन्धू, गंगा, यमुना, ब्रह्मा\"],\"answer\":0,\"explain\":\"मेसोपोटेमियातील प्रमुख संस्कृती सुमेरियन, अक्केडियन, बॅबिलोनियन व अँसिरियन आहेत.\"},{\"q\":\"हडप्पा संस्कृतीतील ‘हडप्पाकालीन खेळणे’ काय होते?\",\"options\":[\"कागदाचे खेळ\",\"मातीच्या सोंगट्या व पट\",\"धातूचे खेळ\",\"पाण्यावर आधारित खेळ\"],\"answer\":1,\"explain\":\"हडप्पा संस्कृतीतील ‘हडप्पाकालीन खेळणे’ हे मातीच्या सोंगट्या व पट होते.\"},{\"q\":\"हडप्पा संस्कृतीतील ‘हडप्पाकालीन मुद्रा व मूर्ती’ काय दर्शवतात?\",\"options\":[\"धार्मिक व सामाजिक प्रतीक\",\"संगीत व नृत्याचे प्रतीक\",\"आर्थिक व्यवहाराचे प्रतीक\",\"शैक्षणिक साधनांचे प्रतीक\"],\"answer\":0,\"explain\":\"हडप्पा संस्कृतीतील ‘हडप्पाकालीन मुद्रा व मूर्ती’ हे धार्मिक व सामाजिक प्रतीक दर्शवतात.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16828,27,5,'English','en','Lesson 1 (pp. 1-16)','[\"- The Constitution of India is the supreme law of the country.\",\"- Fundamental Duties are the responsibilities of every citizen to protect the country and its values.\",\"- The national flag and anthem must be respected and protected.\",\"- Citizens should promote harmony, respect women, preserve culture and protect nature.\",\"- Children have a right to free and compulsory education under the RTE Act.\",\"- The book encourages reading, writing, speaking, listening and using polite language.\",\"- Good listening means looking at the speaker, asking questions and trying to understand.\",\"- Good speaking involves using correct words, punctuation and clear expression.\",\"- Good writing means using correct spelling, punctuation and meaningful sentences.\",\"- The book contains stories, poems, dialogues, activities and exercises for practice.\"]','[{\"q\":\"Which of the following is NOT a Fundamental Duty mentioned in the text?\",\"options\":[\"Abide by the Constitution\",\"Respect the national flag\",\"Keep the environment clean\",\"Play sports every day\"],\"answer\":3,\"explain\":\"Playing sports is not listed as a Fundamental Duty.\"},{\"q\":\"What does the RTE Act emphasize?\",\"options\":[\"Only academic learning\",\"All-round development of children\",\"Strict discipline\",\"Examination only\"],\"answer\":1,\"explain\":\"RTE Act focuses on all-round development and child-centred learning.\"},{\"q\":\"Which skill is NOT part of the four basic language skills?\",\"options\":[\"Listening\",\"Speaking\",\"Reading\",\"Drawing\"],\"answer\":3,\"explain\":\"Drawing is not one of the four basic language skills.\"},{\"q\":\"A good listener should:\",\"options\":[\"Ignore the speaker\",\"Ask questions politely\",\"Talk loudly\",\"Write notes in the margin\"],\"answer\":1,\"explain\":\"Good listeners ask polite questions to clarify.\"},{\"q\":\"Which of these is a characteristic of a good writer?\",\"options\":[\"Uses many punctuation marks\",\"Writes long sentences only\",\"Writes in many languages\",\"Writes only in the school language\"],\"answer\":0,\"explain\":\"Using punctuation correctly is a key characteristic.\"},{\"q\":\"The national anthem is called:\",\"options\":[\"Jana Gana Mana\",\"Vande Mataram\",\"Sare Jahan Se Achha\",\"Rang De Basanti\"],\"answer\":0,\"explain\":\"The anthem is Jana Gana Mana.\"},{\"q\":\"What should a student do when they do not understand a word?\",\"options\":[\"Ignore it\",\"Ask the teacher\",\"Write it down and look it up later\",\"Change the subject\"],\"answer\":2,\"explain\":\"Students should write it down and look it up.\"},{\"q\":\"Which activity is NOT mentioned in the book?\",\"options\":[\"Writing poems\",\"Reading news\",\"Drawing maps\",\"Playing cricket\"],\"answer\":3,\"explain\":\"Playing cricket is not listed.\"},{\"q\":\"The book encourages students to:\",\"options\":[\"Only study alone\",\"Use polite language\",\"Avoid using dictionaries\",\"Skip exercises\"],\"answer\":1,\"explain\":\"Polite language is encouraged.\"},{\"q\":\"Which of these is a good habit for listening?\",\"options\":[\"Look at the speaker\",\"Look away\",\"Talk while listening\",\"Write notes on the floor\"],\"answer\":0,\"explain\":\"Looking at the speaker helps good listening.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16829,27,5,'English','en','Lesson 2 (pp. 17-28)','[\"Strawberries grow in gardens and in the woods.\",\"They can be eaten fresh or cooked with sugar, spice or cream.\",\"Plump and juicy strawberries are the ones grown in gardens.\",\"Sweeter strawberries are the wild ones from the woods.\",\"In Maharashtra, strawberries are usually found in the summer months.\",\"A story about Marouckla shows the importance of kindness and patience.\",\"Marouckla’s stepmother hates her because she is jealous and cruel.\",\"The story takes place in all four seasons: spring, summer, winter and autumn.\",\"Marouckla often gets what she brings, but sometimes she is denied by the stepmother.\",\"Great January is a character who helps Marouckla by giving her a club to collect flowers.\",\"The story teaches that hard work and honesty are rewarded.\",\"The poem teaches that strawberries can be enjoyed in many ways.\",\"The chapter also covers vocabulary, reading comprehension and writing skills.\",\"Students should write about their own fruit‑picking experiences.\",\"They should also learn to identify nouns, verbs and adjectives in a text.\",\"They should practice making announcements and storytelling.\",\"They should learn about the 1936 Olympics and Dhyan Chand’s heroism.\",\"They should know how to play lawn tennis, table tennis, kabaddi, kho‑khō, hockey, football and badminton.\",\"They should be able to use phrases like ‘be sure of’, ‘try one’s best’, ‘at any cost’ and ‘turn down the offer’.\"]','[{\"q\":\"Which two places are mentioned where strawberries grow in the poem?\",\"options\":[\"In gardens and on the street\",\"In gardens and in the woodland\",\"On the farm and in the market\",\"In the forest and in the city\"],\"answer\":1,\"explain\":\"The poem says strawberries grow in gardens and spring from the woodland vine.\"},{\"q\":\"How can strawberries be eaten according to the poem?\",\"options\":[\"With a spoon or a fork\",\"With a bowl or a silver spoon\",\"With a knife or a spoon\",\"With a plate or a silver spoon\"],\"answer\":1,\"explain\":\"The poem mentions a bowl or silver spoon as ways to eat strawberries.\"},{\"q\":\"Which strawberries are described as plump and juicy?\",\"options\":[\"The ones in the market\",\"The ones in the garden\",\"The ones in the woodland\",\"The ones in the forest\"],\"answer\":1,\"explain\":\"The poem says the strawberries that grow in gardens are plump and juicy.\"},{\"q\":\"Which strawberries are sweeter?\",\"options\":[\"The ones in the garden\",\"The ones in the woodland\",\"The ones in the market\",\"The ones in the forest\"],\"answer\":1,\"explain\":\"The poem says the ones that spring from the woodland vine are sweeter.\"},{\"q\":\"What is the main activity suggested in the poem?\",\"options\":[\"Planting strawberries\",\"Eating strawberries\",\"Buying strawberries\",\"Selling strawberries\"],\"answer\":2,\"explain\":\"The poem encourages eating strawberries.\"},{\"q\":\"Which season is implied for picking strawberries in Maharashtra?\",\"options\":[\"Winter\",\"Spring\",\"Summer\",\"Monsoon\"],\"answer\":2,\"explain\":\"The exercise asks to find when and where we get strawberries in Maharashtra, implying summer.\"},{\"q\":\"What does the poem say about needing a bowl or silver spoon?\",\"options\":[\"It is essential\",\"It is optional\",\"It is forbidden\",\"It is unnecessary\"],\"answer\":3,\"explain\":\"The poem says there is no need for a bowl or silver spoon.\"},{\"q\":\"What does the poem suggest about sugar or spice?\",\"options\":[\"Add them for taste\",\"Do not add them\",\"Use them sparingly\",\"Use them heavily\"],\"answer\":1,\"explain\":\"The poem says there is no need for sugar or spice.\"},{\"q\":\"Which of the following best describes the poem\'s tone?\",\"options\":[\"Serious\",\"Humorous\",\"Melancholic\",\"Playful\"],\"answer\":3,\"explain\":\"The poem has a light, playful tone about eating strawberries.\"},{\"q\":\"Which question is NOT asked in the poem\'s reading questions?\",\"options\":[\"Which strawberries are sweeter?\",\"How would you like to eat your strawberries?\",\"What is the price of strawberries?\",\"Which strawberries are plump and juicy?\"],\"answer\":2,\"explain\":\"The poem\'s questions do not ask about price.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16830,27,5,'English','en','Lesson 3 (pp. 29-40)','[\"• A project helps us learn how to ask questions politely and write a report.\",\"• Collect information from friends about what they like, dislike, fear, habits, and favourite people.\",\"• Organise the answers into categories and write a short report or give an oral presentation.\",\"• When speaking, speak clearly, not too loud or soft, and look at the listener.\",\"• Use polite words like ‘please’, ‘thank you’, ‘sorry’ and ‘pardon’ when you need to ask or apologise.\",\"• In a discussion, listen to others, share your ideas, and ask questions if you don’t understand.\",\"• Remember that ‘its’ means belonging to it, while ‘it’s’ means it is.\",\"• In poems, words like ‘flowers’, ‘stars’, ‘smiles’ can be happy; ‘leaves’, ‘clouds’, ‘tears’ can be sad.\",\"• A good speaker keeps eye contact, speaks at a steady pace, and shows interest in others’ thoughts.\",\"• When you want to give a speech, think about what you will say and practise it before you speak.\"]','[{\"q\":\"What should you do before presenting a report about friends’ likes and dislikes?\",\"options\":[\"Ask for their names\",\"Collect information from many friends\",\"Write a poem\",\"Draw a picture\"],\"answer\":1,\"explain\":\"Collecting information from many friends gives a balanced view.\"},{\"q\":\"Which of the following is a polite expression?\",\"options\":[\"Pardon\",\"Shout\",\"Ignore\",\"Yell\"],\"answer\":0,\"explain\":\"‘Pardon’ is a polite way to ask for attention.\"},{\"q\":\"When speaking, you should\",\"options\":[\"Speak loudly all the time\",\"Speak clearly and at a steady pace\",\"Speak only when you are right\",\"Speak without looking at the listener\"],\"answer\":1,\"explain\":\"Clear, steady speech helps listeners understand.\"},{\"q\":\"What does ‘its’ mean in the sentence ‘Its appetite is hearty’?\",\"options\":[\"It is\",\"Belonging to it\",\"It is not\",\"It is big\"],\"answer\":1,\"explain\":\"‘Its’ shows possession, not contraction of ‘it is’.\"},{\"q\":\"Which of these is a happy thing mentioned in the poem?\",\"options\":[\"Leaves falling\",\"Clouds\",\"Stars\",\"Tears\"],\"answer\":2,\"explain\":\"Stars are listed as a happy thing.\"},{\"q\":\"In a discussion, you should\",\"options\":[\"Talk all the time\",\"Listen to others\",\"Ignore others’ ideas\",\"Speak loudly\"],\"answer\":1,\"explain\":\"Listening shows respect and helps learning.\"},{\"q\":\"When you want to give a speech, you should\",\"options\":[\"Think about it in advance\",\"Speak without planning\",\"Speak as soon as you remember\",\"Ignore the audience\"],\"answer\":0,\"explain\":\"Planning helps you speak confidently.\"},{\"q\":\"Which word is NOT a polite expression?\",\"options\":[\"Thank you\",\"Sorry\",\"Please\",\"Shout\"],\"answer\":3,\"explain\":\"‘Shout’ is not polite.\"},{\"q\":\"What is the main purpose of the project described in the chapter?\",\"options\":[\"To write a poem\",\"To collect data and report\",\"To draw pictures\",\"To read a book\"],\"answer\":1,\"explain\":\"The project focuses on collecting data and reporting.\"},{\"q\":\"When you ask a question, you should\",\"options\":[\"Use a rude tone\",\"Ask politely\",\"Ignore the answer\",\"Speak loudly\"],\"answer\":1,\"explain\":\"Politeness encourages helpful answers.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16831,27,5,'English','en','Lesson 4 (pp. 41-52)','[\"- Gulliver is a tiny man who gets tied down on a seashore by a rope and a ring.\",\"- He is taken to the city by a boat or a carriage, after being released by the king.\",\"- Gulliver’s home in Lilliput is a small house with a door that is only four feet high and two feet wide.\",\"- He walks around the city, looking at the tall buildings, the beautiful gardens and the many people.\",\"- In the play, people face problems because the street is littered with garbage, making it hard to walk and dangerous for animals.\",\"- The animals complain that the garbage hurts them, pollutes their rivers and kills their food.\",\"- Cleanliness drives involve sorting waste, reusing, recycling and keeping streets free of litter.\",\"- Poem rhymes: pool‑cool, high‑fly, splash‑flash, delight‑bright.\",\"- In the story‑building activity, choose characters, traits, story type, period and setting to create a plot.\",\"- Key vocabulary: cluster, brink, flash, lined, etc.\"]','[{\"q\":\"In Gulliver’s story, why was he tied down on the seashore?\",\"options\":[\"Because he was a thief\",\"Because he was a tiny man\",\"Because he was a king\",\"Because he was a sailor\"],\"answer\":1,\"explain\":\"Gulliver is very small, so a rope and ring were used to keep him safe.\"},{\"q\":\"What is the size of Gulliver’s door in Lilliput?\",\"options\":[\"4 feet high, 2 feet wide\",\"6 feet high, 3 feet wide\",\"8 feet high, 4 feet wide\",\"10 feet high, 5 feet wide\"],\"answer\":0,\"explain\":\"The door is described as four feet high and two feet wide.\"},{\"q\":\"Which of the following is NOT a problem faced by people in the play?\",\"options\":[\"Litter on the street\",\"Broken glass on the road\",\"Animals injured by waste\",\"A sudden flood\"],\"answer\":3,\"explain\":\"The play only mentions litter, broken glass and animal injuries.\"},{\"q\":\"What does the mayor promise to do if the animals agree to clean up?\",\"options\":[\"Close the town\",\"Build a new park\",\"Arrange for waste disposal\",\"Ignore the problem\"],\"answer\":2,\"explain\":\"The mayor says he will arrange for proper waste disposal.\"},{\"q\":\"Which word best describes the animals’ reaction to the garbage?\",\"options\":[\"Pleased\",\"Angry\",\"Sad\",\"Confused\"],\"answer\":1,\"explain\":\"The animals are angry and upset by the litter.\"},{\"q\":\"In the poem, what does the word \\\"cluster\\\" mean?\",\"options\":[\"A group of birds\",\"A type of flower\",\"A kind of fish\",\"A mountain\"],\"answer\":0,\"explain\":\"Cluster means a group or gathering.\"},{\"q\":\"Which of these is a synonym for \\\"reuse\\\"?\",\"options\":[\"Recycle\",\"Throw away\",\"Burn\",\"Discard\"],\"answer\":0,\"explain\":\"Reuse means to use again, similar to recycle.\"},{\"q\":\"What is the main theme of the cleanliness play?\",\"options\":[\"Adventure\",\"Pollution\",\"Love\",\"War\"],\"answer\":1,\"explain\":\"The play focuses on pollution and the need for cleanliness.\"},{\"q\":\"Which activity involves writing a story from another person’s point of view?\",\"options\":[\"Tell a story orally as Gulliver\",\"Write a story by another person\",\"Draw a picture of the city\",\"Sing a poem\"],\"answer\":1,\"explain\":\"The activity asks to write a story from someone else’s perspective.\"},{\"q\":\"What does the word \\\"brink\\\" mean in the poem?\",\"options\":[\"Edge\",\"Center\",\"Middle\",\"Top\"],\"answer\":0,\"explain\":\"Brink means the edge or verge of something.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16832,27,5,'English','en','Lesson 5 (pp. 53-64)','[\"- The poem talks about a calm water‑edge where reeds, bulrushes and other wetland plants grow.\",\"- Insects, birds, trees and plants mentioned: insects (flies, mosquitoes), birds (kingfisher, swallows), trees (willow, pine), plants (bulrush, lilies).\",\"- Rhyming words in the poem: e.g., \'ripples\' & \'tillles\', \'swallow\' & \'fallow\', \'fishes\' & \'wishes\', \'kingfisher\' & \'wingfisher\'.\",\"- The poet describes the gentle movement of ripples, the beauty of lilies, the flight of a swallow, the swimming of fishes, and the call of a kingfisher.\",\"- The poet is walking along the water’s edge and enjoys the peaceful scene.\",\"- The poem shows that the poet likes the experience because he feels calm and happy.\",\"- Bad habits are compared to weeds that grow deep and hard to pull out.\",\"- To get rid of bad habits, one must pull them out with effort, just like a weed.\",\"- A good party is one where the host and guests are happy, comfortable and polite.\",\"- Invitations should include date, time, place and be sent in advance.\",\"- Guests should acknowledge the invitation, bring a thoughtful gift, and be punctual.\",\"- The Wizard of Oz story shows teamwork: each character brings a special skill to overcome obstacles.\",\"- In the poem, dewdrops greet the dawn because they sparkle and reflect the new day.\",\"- A good host remembers to greet guests, serve food politely and clean up after the party.\",\"- A good guest thanks the host, brings a small gift and behaves politely.\",\"- To change a sentence’s meaning, change the preposition or adverb used.\",\"- The journey to the Emerald City involves crossing a wide ditch and dealing with scary Kalidahs.\",\"- The poem uses expressions like ‘hundreds of’ to show abundance.\",\"- Good habits are like healthy plants that grow easily when nurtured.\"]','[{\"q\":\"Which of the following is NOT mentioned in the poem?\",\"options\":[\"kingfisher\",\"bulrush\",\"tiger\",\"lilies\"],\"answer\":2,\"explain\":\"The poem talks about kingfisher, bulrush and lilies, but not a tiger.\"},{\"q\":\"What does the poet do at the water’s edge?\",\"options\":[\"Swims\",\"Walks\",\"Sings\",\"Runs\"],\"answer\":1,\"explain\":\"The poet walks along the water’s edge.\"},{\"q\":\"Which word best describes the movement of ripples?\",\"options\":[\"Slow\",\"Fast\",\"Gentle\",\"Rough\"],\"answer\":2,\"explain\":\"Ripples move gently across the water.\"},{\"q\":\"Bad habits are compared to which of these?\",\"options\":[\"Weeds\",\"Flowers\",\"Trees\",\"Birds\"],\"answer\":0,\"explain\":\"The text says bad habits are like weeds.\"},{\"q\":\"Which of these is a preposition used in the book?\",\"options\":[\"between\",\"above\",\"under\",\"around\"],\"answer\":3,\"explain\":\"The book uses \'around\' in the phrase \'around the farm\'.\"},{\"q\":\"What should a host remember to do before guests arrive?\",\"options\":[\"Decorate the house\",\"Serve food\",\"Greet guests\",\"All of the above\"],\"answer\":3,\"explain\":\"All tasks are important before guests arrive.\"},{\"q\":\"Which expression shows abundance in the poem?\",\"options\":[\"few\",\"several\",\"hundreds\",\"none\"],\"answer\":2,\"explain\":\"The poem uses \'hundreds\' to show many.\"},{\"q\":\"What is the main lesson from the story of Anshuman?\",\"options\":[\"Weeds grow fast\",\"Pulling weeds is easy\",\"Bad habits can be removed with effort\",\"Weeds are harmless\"],\"answer\":2,\"explain\":\"The story teaches that bad habits can be removed with effort.\"},{\"q\":\"Which of these is a correct way to change a sentence’s meaning?\",\"options\":[\"Change the verb\",\"Change the preposition\",\"Change the subject\",\"Change the punctuation\"],\"answer\":1,\"explain\":\"Changing the preposition changes the meaning.\"},{\"q\":\"What is the best way to thank a host after a party?\",\"options\":[\"Ignore them\",\"Say thank you personally\",\"Send a letter\",\"Both B and C\"],\"answer\":3,\"explain\":\"Both saying thank you personally and sending a letter are good.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16833,27,5,'English','en','Lesson 6 (pp. 65-76)','[\"1. A *ditch* is a shallow hole in the ground that can be crossed by walking over it or using a bridge.\",\"2. A *gulf* is a large body of water that is deeper and wider than a ditch.\",\"3. The *Scarecrow* is a character who is smart and helps the group solve problems.\",\"4. The *Cowardly Lion* is brave when he helps others, even if he feels afraid.\",\"5. The *Tin Woodman* has a heart that does not beat, but he still cares for his friends.\",\"6. In the story, the travellers cross the first ditch by walking over it carefully.\",\"7. They cross the second gulf by using the Lion’s back as a bridge and jumping across.\",\"8. The *Kalidahs* are dangerous animals that the travellers must fight to get past.\",\"9. The *Man in the Moon* is a playful character who tries to take milk from the *Dipper* but spills it.\",\"10. The *Dipper* can mean a container for water or a constellation in the sky.\",\"11. The *Milky Way* is a band of stars in the night sky, not a real milk stream.\",\"12. A *fairy tale* is a story that mixes real and imaginary events.\",\"13. A *marathon* is a long running race that can take many hours to finish.\",\"14. The *Pheidippides* story shows how a fast runner can deliver a message quickly.\",\"15. In stories, characters often show qualities like bravery, kindness, or cleverness that teach lessons.\"]','[{\"q\":\"What is a ditch in the story?\",\"options\":[\"A deep river\",\"A shallow hole in the ground\",\"A mountain\",\"A forest\"],\"answer\":1,\"explain\":\"A ditch is a shallow hole that can be crossed by walking over it.\"},{\"q\":\"How did the travellers cross the second gulf?\",\"options\":[\"They built a boat\",\"They jumped across\",\"They used the Lion’s back\",\"They walked around it\"],\"answer\":2,\"explain\":\"They used the Lion’s back as a bridge to jump across the gulf.\"},{\"q\":\"Which character is described as having no beating heart?\",\"options\":[\"The Scarecrow\",\"The Cowardly Lion\",\"The Tin Woodman\",\"Dorothy\"],\"answer\":2,\"explain\":\"The Tin Woodman has a heart that does not beat.\"},{\"q\":\"What does the *Dipper* mean in the story?\",\"options\":[\"A container for water\",\"A type of bird\",\"A mountain\",\"A type of tree\"],\"answer\":0,\"explain\":\"The Dipper is a container for water and also a constellation.\"},{\"q\":\"Who is the main hero of the marathon story?\",\"options\":[\"The Cowardly Lion\",\"Pheidippides\",\"Dorothy\",\"The Tin Woodman\"],\"answer\":1,\"explain\":\"Pheidippides is the runner who delivered the message.\"},{\"q\":\"Why did the Man in the Moon spill the milk?\",\"options\":[\"He was careless\",\"The Dipper was empty\",\"The Milky Way was too bright\",\"He was frightened by the Big Bear\"],\"answer\":3,\"explain\":\"He was frightened by the Big Bear and spilled the milk.\"},{\"q\":\"What is the main lesson of the *Man in the Moon* story?\",\"options\":[\"Be careful with water\",\"The Milky Way is real milk\",\"The Moon can fly\",\"The Big Bear is friendly\"],\"answer\":0,\"explain\":\"The story teaches to be careful when handling things.\"},{\"q\":\"Which of these is a *marathon*?\",\"options\":[\"A short sprint\",\"A long running race\",\"A swimming contest\",\"A cycling race\"],\"answer\":1,\"explain\":\"A marathon is a long running race.\"},{\"q\":\"What is the *Milky Way* in the sky?\",\"options\":[\"A river of milk\",\"A band of stars\",\"A cloud of dust\",\"A moon\"],\"answer\":1,\"explain\":\"The Milky Way is a band of stars in the night sky.\"},{\"q\":\"Which character helps the travellers cross the ditch?\",\"options\":[\"The Cowardly Lion\",\"The Scarecrow\",\"The Tin Woodman\",\"Dorothy\"],\"answer\":1,\"explain\":\"The Scarecrow helps by suggesting ways to cross.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16834,27,5,'English','en','Lesson 7 (pp. 77-88)','[\"Pheidippides was a brave runner who carried the news of the Greek victory at the Battle of Marathon to Athens.\",\"He ran more than 40 kilometres (about 25 miles) in a single day.\",\"The story of his run is the origin of the modern marathon race.\",\"Money is a medium of exchange that can be coins or notes.\",\"Coins are made of metal and notes are printed paper with a promise of value.\",\"Barter was the old way of trading goods before money existed.\",\"Paper money first appeared in China about 1000 years ago.\",\"A note has no value by itself but represents a promise to pay its value.\",\"A tree diagram shows information in branches, useful for classifying living and non‑living things.\",\"The Internet is a network of computers connected together, also called the World Wide Web (WWW).\",\"A website has a unique address (URL) and can be searched using search engines.\",\"Being ‘online’ means you are connected to the Internet; ‘offline’ means you are not.\",\"E‑mail is electronic mail sent through the Internet and requires an e‑mail address and a password.\",\"A netizen is a person who uses the Internet and participates in online activities.\",\"The story of Helen Keller shows that with patience and the right methods, a deaf‑blind child can learn to read, write and speak.\",\"The ‘1089 trick’ uses any three‑digit number where the first and last digits differ by at least two; the difference after reversing is always 1089.\",\"Board games like Nine Men’s Morris and tic‑tac‑toe help develop thinking and strategy.\",\"Puzzles and riddles are good for exercising the mind and keeping it sharp.\",\"Reading poems helps develop imagination and understanding of language.\",\"Learning to spell with fingers (fingerspelling) is a way for deaf people to communicate.\",\"A password is a secret word or combination of letters and numbers that protects an online account.\",\"A computer has parts such as monitor, keyboard, mouse, processor and speakers.\",\"A search engine helps find websites by showing a list of relevant sites when you type a keyword.\"]','[{\"q\":\"What is the main reason Pheidippides ran from Marathon to Athens?\",\"options\":[\"To win a race\",\"To deliver a message\",\"To find food\",\"To escape enemies\"],\"answer\":1,\"explain\":\"He ran to deliver the news of victory to Athens.\"},{\"q\":\"How many kilometres did Pheidippides run?\",\"options\":[\"40\",\"80\",\"120\",\"200\"],\"answer\":0,\"explain\":\"He ran more than forty kilometres, about 40 km.\"},{\"q\":\"What is the modern sporting event named after Pheidippides?\",\"options\":[\"Sprint\",\"Relay\",\"Marathon\",\"Hurdles\"],\"answer\":2,\"explain\":\"The marathon is named after his run.\"},{\"q\":\"Which of the following was NOT a form of money in ancient times?\",\"options\":[\"Salt bricks\",\"Cowrie shells\",\"Gold coins\",\"Paper notes\"],\"answer\":3,\"explain\":\"Paper notes were first used in China, not ancient barter.\"},{\"q\":\"What does the term \'barter\' mean?\",\"options\":[\"Using coins\",\"Using paper money\",\"Exchanging goods directly\",\"Printing money\"],\"answer\":2,\"explain\":\"Barter is exchanging one thing for another.\"},{\"q\":\"Which of these is a computer program that helps find websites?\",\"options\":[\"Browser\",\"Search engine\",\"Email client\",\"Operating system\"],\"answer\":1,\"explain\":\"Search engines help locate websites.\"},{\"q\":\"What does \'online\' mean?\",\"options\":[\"Connected to the internet\",\"Disconnected from the internet\",\"Using a phone\",\"Using a TV\"],\"answer\":0,\"explain\":\"Being online means connected to the internet.\"},{\"q\":\"Which of the following is a short form related to ICT?\",\"options\":[\"SMS\",\"USB\",\"CPU\",\"RAM\"],\"answer\":0,\"explain\":\"SMS (Short Message Service) is a short form.\"},{\"q\":\"What is the main purpose of a password?\",\"options\":[\"To identify a user\",\"To store data\",\"To print documents\",\"To play games\"],\"answer\":0,\"explain\":\"A password secures a user account.\"},{\"q\":\"Which event is described as a \'world wide web\'?\",\"options\":[\"Internet\",\"World Wide Web\",\"Search engine\",\"Email\"],\"answer\":1,\"explain\":\"The World Wide Web is the network of websites.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16835,27,5,'English','en','Lesson 8 (pp. 89-100)','[\"Helen Keller was blind and deaf but learned to communicate using touch and Braille.\",\"Anne Sullivan was Helen’s teacher and helped her learn to read and write.\",\"Braille is a system of raised dots that blind people read with their fingertips.\",\"The white cane is a tool that helps blind people feel the ground and avoid obstacles.\",\"Rangoli is a decorative art made on floors or walls using coloured powders.\",\"The word ‘Rangoli’ comes from ‘rang’ (colour) + ‘awali’ (row).\",\"Rangoli patterns are drawn fresh every day, especially on festivals.\",\"Common Rangoli motifs include flowers, mangoes, lotus, peacocks, fish, and geometric shapes.\",\"In different Indian states Rangoli has different names: Chowkpurana, Mandana, Muggu, Alpanaa, Aripanaa, Kolam, etc.\",\"Rangoli is made with coarse powders like sand, marble dust, sawdust, or rice flour.\",\"The design is kept neat by drawing straight, unbroken lines of even thickness.\",\"Rangoli is usually drawn in the courtyard or in front of the doorstep.\",\"Rangoli is a sign of welcome and hospitality during festivals.\",\"The white cane is also called the ‘honour the white cane’ because it shows respect for the blind.\",\"Braille letters are arranged in a 2x3 grid of raised dots.\",\"In English, nouns can be countable or uncountable; countable nouns have singular and plural forms.\",\"Adjectives describe nouns and can be compared using ‘more’ and ‘most’ for long words, ‘-er’ and ‘-est’ for short words.\",\"Adverbs describe verbs, adjectives, or other adverbs and often end in ‘-ly’.\",\"Pronouns replace nouns and include I, you, he, she, it, we, they.\",\"Conjunctions join words, phrases, or clauses and include and, but, because, if, or, so.\",\"Verbs show action or state and change form to indicate tense (past, present, future).\",\"Modal verbs (can, could, will, should, must) express possibility, necessity, or permission.\"]','[{\"q\":\"Who helped Helen Keller learn to communicate?\",\"options\":[\"Anne Sullivan\",\"Mrs. Keller\",\"Mr. Brown\",\"Ms. Smith\"],\"answer\":0,\"explain\":\"Anne Sullivan was Helen Keller’s teacher and guide.\"},{\"q\":\"What is the main material used to make traditional Rangoli designs?\",\"options\":[\"White chalk\",\"Sand\",\"Rice powder\",\"Marble dust\"],\"answer\":2,\"explain\":\"Rangoli is traditionally made with finely ground white powder, often rice powder.\"},{\"q\":\"Which of the following is NOT a common Rangoli motif?\",\"options\":[\"Lotus\",\"Peacock\",\"Creepers\",\"Pencil\"],\"answer\":3,\"explain\":\"Lotus, peacock and creepers are natural motifs; pencil is not.\"},{\"q\":\"What does the word ‘Rangaawali’ mean?\",\"options\":[\"Colourful line\",\"Colourful row\",\"Colourful flower\",\"Colourful pattern\"],\"answer\":1,\"explain\":\"Rangaawali comes from ‘rang’ (colour) + ‘aawali’ (row).\"},{\"q\":\"Which term describes a system of raised dots used by the blind?\",\"options\":[\"Braille\",\"Sign language\",\"Fingerspelling\",\"White cane\"],\"answer\":0,\"explain\":\"Braille is a tactile writing system for the blind.\"},{\"q\":\"In which Indian state is Rangoli called ‘Alpanaa’?\",\"options\":[\"Uttar Pradesh\",\"Bihar\",\"Bengal\",\"Kerala\"],\"answer\":2,\"explain\":\"Alpanaa is the name used for Rangoli in Bengal.\"},{\"q\":\"What is the purpose of the white cane for a blind person?\",\"options\":[\"To decorate the house\",\"To help in walking\",\"To write letters\",\"To make Rangoli\"],\"answer\":1,\"explain\":\"The white cane assists blind people in walking safely.\"},{\"q\":\"Which of these is a difference between fingerspelling, sign language and Braille?\",\"options\":[\"Fingerspelling uses letters, sign language uses gestures, Braille uses raised dots\",\"All use the same method\",\"Only Braille is used by the blind\",\"Fingerspelling is for hearing people\"],\"answer\":0,\"explain\":\"Fingerspelling spells words with hand shapes, sign language uses gestures, Braille uses raised dots.\"},{\"q\":\"Rangoli designs are often drawn in which part of a house?\",\"options\":[\"Kitchen\",\"Bathroom\",\"Courtyard\",\"Bedroom\"],\"answer\":2,\"explain\":\"Rangoli is usually drawn in the courtyard or front of the doorstep.\"},{\"q\":\"Which of the following best describes Helen Keller’s life story?\",\"options\":[\"A blind woman\",\"A courageous, patient and struggling person\",\"A helpless, unfortunate girl\",\"All of the above\"],\"answer\":3,\"explain\":\"Helen Keller’s life is seen as a story of courage, patience and struggle.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16836,28,5,'Hindi','hi','आओ खेलें 2 १०. गड़ा धन','[\"आओ खेलें 2 १०. गड़ा धन\",\"गड़ा धन का मतलब है बड़ी मात्रा में पैसा\",\"यह अध्याय हमें बताता है कि पैसा कैसे बनता है\",\"पैसा सरकार द्वारा जारी किया जाता है\",\"सभी पैसे के नोटों पर एक खास सील होती है\",\"सिर पर एक चित्र और नीचे लिखावट होती है\",\"पैसे के नोटों के रंग अलग-अलग होते हैं\",\"नोटों पर एक सुरक्षा रेखा होती है\",\"पैसे के नोटों पर अंक और शब्द दोनों लिखे होते हैं\",\"मुद्रा का मतलब है वह पैसा जिसे हम रोज़ इस्तेमाल करते हैं\",\"पैसे के नोटों को सुरक्षित रखने के लिए बैंक का इस्तेमाल किया जाता है\",\"बैंक में जमा करके ब्याज भी मिलता है\",\"पैसे के नोटों को बदलने के लिए बैंक में जाना पड़ता है\",\"पैसे के नोटों को गिनने के लिए गिनती की तालिका मददगार होती है\",\"पैसे के नोटों के साथ चेक भी इस्तेमाल होते हैं\",\"इलेक्ट्रॉनिक पैसे भी होते हैं जैसे कि ऑनलाइन बैंकिंग\",\"पैसे के नोटों को धोने से बचना चाहिए\",\"पैसे के नोटों को सही जगह पर रखना चाहिए\",\"पैसे के नोटों को खोने से बचने के लिए सुरक्षित जगह पर रखें\",\"पैसे के नोटों का सही इस्तेमाल करना ज़रूरी है\",\"पैसे के नोटों को सही ढंग से पहचानना सीखें\",\"पैसे के नोटों के साथ जिम्मेदारी से व्यवहार करें\",\"पैसे के नोटों के बारे में सही जानकारी होना जरूरी है\",\"पैसे के नोटों के बारे में सवाल पूछकर सीखें\"]','[{\"q\":\"गड़ा धन का क्या मतलब है?\",\"options\":[\"बड़ी मात्रा में पैसा\",\"छोटी मात्रा में पैसा\",\"सिर्फ सिक्के\",\"सिर्फ चेक\"],\"answer\":0,\"explain\":\"गड़ा धन का मतलब है बड़ी मात्रा में पैसा।\"},{\"q\":\"पैसा कौन जारी करता है?\",\"options\":[\"सभी बैंक\",\"सभी दुकानदार\",\"सरकार\",\"सभी लोग\"],\"answer\":2,\"explain\":\"पैसा सरकार द्वारा जारी किया जाता है।\"},{\"q\":\"पैसे के नोट पर कौन सी खास सील होती है?\",\"options\":[\"सुरक्षा रेखा\",\"सिर पर चित्र\",\"नीचे लिखावट\",\"सभी\"],\"answer\":0,\"explain\":\"सुरक्षा रेखा नोट पर एक खास सील होती है।\"},{\"q\":\"पैसे के नोटों के रंग कैसे होते हैं?\",\"options\":[\"सभी एक ही रंग के\",\"रंग अलग-अलग होते हैं\",\"सिर्फ काला\",\"सिर्फ सफ़ेद\"],\"answer\":1,\"explain\":\"नोटों के रंग अलग-अलग होते हैं।\"},{\"q\":\"बैंक में जमा करने से क्या मिलता है?\",\"options\":[\"ब्याज\",\"सिक्के\",\"चेक\",\"किसी भी चीज़ नहीं\"],\"answer\":0,\"explain\":\"बैंक में जमा करने पर ब्याज मिलता है।\"},{\"q\":\"पैसे के नोटों को गिनने में कौन सी तालिका मददगार है?\",\"options\":[\"गणित तालिका\",\"गिनती तालिका\",\"भूगोल तालिका\",\"संगीत तालिका\"],\"answer\":1,\"explain\":\"गिनती तालिका मददगार होती है।\"},{\"q\":\"इलेक्ट्रॉनिक पैसे का उदाहरण क्या है?\",\"options\":[\"ऑनलाइन बैंकिंग\",\"सिर्फ नकद\",\"सिर्फ चेक\",\"सिर्फ सिक्के\"],\"answer\":0,\"explain\":\"ऑनलाइन बैंकिंग इलेक्ट्रॉनिक पैसे का उदाहरण है।\"},{\"q\":\"पैसे के नोटों को धोने से क्या होता है?\",\"options\":[\"सुरक्षित रहते हैं\",\"साफ़ हो जाते हैं\",\"बुरी तरह क्षतिग्रस्त हो सकते हैं\",\"कुछ भी नहीं\"],\"answer\":2,\"explain\":\"धोने से नोट क्षतिग्रस्त हो सकते हैं।\"},{\"q\":\"पैसे के नोटों को खोने से बचने के लिए क्या करना चाहिए?\",\"options\":[\"सुरक्षित जगह पर रखें\",\"सभी नोटों को फेंक दें\",\"सिर्फ सिक्के रखें\",\"किसी को दें\"],\"answer\":0,\"explain\":\"सुरक्षित जगह पर रखने से नोट सुरक्षित रहते हैं।\"},{\"q\":\"पैसे के नोटों के साथ जिम्मेदारी से व्यवहार करने का मतलब क्या है?\",\"options\":[\"सिर्फ उपयोग करना\",\"सिर्फ बचाना\",\"सही ढंग से उपयोग और रख-रखाव करना\",\"सिर्फ चुराना\"],\"answer\":2,\"explain\":\"सही ढंग से उपयोग और रख-रखाव करना ज़रूरी है।\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16837,28,5,'Hindi','hi','पहचान हमारी- भाग (','[\"पहचानो और बताओ में हम चित्र देखकर वस्तु या प्राणी को पहचानते हैं और उसका नाम बताते हैं।\",\"देखो, बताओ और कृति करो में हम चित्र देखते हैं, उसके बारे में बोलते हैं और उसे चित्रित भी करते हैं।\",\"दोनों क्रियाएँ बोलचाल और चित्रकला को जोड़ती हैं।\",\"छात्रों को अपने अनुभव से जोड़कर सीखने में मदद मिलती है।\",\"प्राणियों के नाम पूछकर शब्दावली बढ़ाई जाती है।\",\"सामूहिक और एकल रूप में कृतियाँ कराकर समूह भावना विकसित होती है।\",\"प्राणियों की बोलियाँ बुलवाकर श्रवण कौशल सुधारा जाता है।\",\"पर्यावरण संतुलन में प्राणियों का महत्व समझाया जाता है।\",\"चित्रों के वाक्यों को सुनाकर समझ बढ़ाई जाती है।\",\"प्रश्न पूछकर समझ की जाँच की जाती है।\",\"कृति करने से रचनात्मकता और हाथों की कुशलता बढ़ती है।\",\"सभी गतिविधियाँ बोलने, सुनने, देखने और लिखने को एक साथ लाती हैं।\",\"छात्रों को बोलने का अवसर देने से आत्मविश्वास बढ़ता है।\",\"पूर्वानुभव की जानकारी से सीखने की प्रक्रिया आसान होती है।\",\"सभी क्रियाएँ हिंदी भाषा के मूलभूत कौशल को सुदृढ़ करती हैं।\",\"सभी क्रियाएँ पाठ्यक्रम के उद्देश्यों के अनुरूप हैं।\",\"सभी क्रियाएँ छात्रों के समग्र विकास में सहायक हैं।\",\"सभी क्रियाएँ कक्षा में सक्रिय भागीदारी को बढ़ावा देती हैं।\",\"सभी क्रियाएँ छात्रों को प्रकृति के प्रति जागरूक बनाती हैं।\",\"सभी क्रियाएँ छात्रों को पर्यावरण संरक्षण का महत्व सिखाती हैं।\",\"सभी क्रियाएँ छात्रों को टीम वर्क सिखाती हैं।\",\"सभी क्रियाएँ छात्रों को स्वयं को व्यक्त करने का माध्यम देती हैं।\",\"सभी क्रियाएँ छात्रों को सोचने-समझने का अभ्यास देती हैं।\",\"सभी क्रियाएँ छात्रों को रचनात्मक सोच विकसित करने में मदद करती हैं।\",\"सभी क्रियाएँ छात्रों को भाषा के प्रति प्रेम जगाती हैं।\"]','[{\"q\":\"पहचानो और बताओ में हम क्या करते हैं?\",\"options\":[\"चित्र बनाते हैं\",\"चित्र देखकर वस्तु पहचानते हैं\",\"संगीत सुनते हैं\",\"कविता लिखते हैं\"],\"answer\":1,\"explain\":\"चित्र देखकर वस्तु या प्राणी को पहचानते हैं और उसका नाम बताते हैं।\"},{\"q\":\"देखो, बताओ और कृति करो में क्या शामिल है?\",\"options\":[\"सिर्फ बोलना\",\"सिर्फ चित्र बनाना\",\"बोलना और चित्र बनाना\",\"सिर्फ सुनना\"],\"answer\":2,\"explain\":\"इसमें चित्र देखकर बोलना और उसे चित्रित करना दोनों शामिल हैं।\"},{\"q\":\"कृति करने से क्या लाभ होता है?\",\"options\":[\"हाथों की कुशलता बढ़ती है\",\"सिर्फ शब्द याद होते हैं\",\"संगीत की समझ बढ़ती है\",\"कविता लिखी जाती है\"],\"answer\":0,\"explain\":\"चित्र बनाना हाथों की कुशलता और रचनात्मकता बढ़ाता है।\"},{\"q\":\"पर्यावरण संतुलन में प्राणियों का क्या महत्व है?\",\"options\":[\"वे भोजन बनाते हैं\",\"वे शोर करते हैं\",\"वे संतुलन बनाए रखते हैं\",\"वे केवल शिकार होते हैं\"],\"answer\":2,\"explain\":\"प्राणी पर्यावरण के संतुलन को बनाए रखने में महत्वपूर्ण भूमिका निभाते हैं।\"},{\"q\":\"सामूहिक रूप में कृति करने से क्या होता है?\",\"options\":[\"व्यक्तिगत कौशल घटता है\",\"समूह भावना बढ़ती है\",\"संगीत सीखते हैं\",\"कविता लिखते हैं\"],\"answer\":1,\"explain\":\"सामूहिक रूप से कृति करने से समूह भावना और सहयोग बढ़ता है।\"},{\"q\":\"प्राणियों की बोलियाँ बुलवाने का उद्देश्य क्या है?\",\"options\":[\"सुनने की क्षमता बढ़ाना\",\"सिर्फ मज़ा लेना\",\"संगीत सीखना\",\"कविता लिखना\"],\"answer\":0,\"explain\":\"बोलियाँ बुलवाने से सुनने की क्षमता और श्रवण कौशल बढ़ता है।\"},{\"q\":\"पहचानो और बताओ में कौन-सा कौशल प्रमुख है?\",\"options\":[\"सुनना\",\"बोलना\",\"देखना\",\"सभी\"],\"answer\":3,\"explain\":\"इसमें देखना, सुनना और बोलना सभी महत्वपूर्ण हैं।\"},{\"q\":\"कृति करने के बाद क्या किया जाता है?\",\"options\":[\"संगीत सुनना\",\"कविता लिखना\",\"चर्चा करना\",\"सिर्फ सोचना\"],\"answer\":2,\"explain\":\"कृति के बाद चित्र पर चर्चा की जाती है।\"},{\"q\":\"पर्यावरण संतुलन में प्राणियों का क्या योगदान है?\",\"options\":[\"कचरा बनाना\",\"शोर करना\",\"संतुलन बनाए रखना\",\"सिर्फ शिकार होना\"],\"answer\":2,\"explain\":\"प्राणी पर्यावरण के संतुलन को बनाए रखने में योगदान देते हैं।\"},{\"q\":\"कृति करने से कौन-सा कौशल विकसित होता है?\",\"options\":[\"संगीत कौशल\",\"सुनने का कौशल\",\"हाथों की कुशलता\",\"कविता लेखन\"],\"answer\":2,\"explain\":\"चित्र बनाना हाथों की कुशलता और रचनात्मकता बढ़ाता है।\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16838,28,5,'Hindi','hi','मैं सड़क ह','[\"रिमझिम-रिमझिम बारिश के बूँदें धरती पर गिरती हैं।\",\"बूँदें खेतों, बागों और मैदानों में हरियाली फैलाती हैं।\",\"बूँदें नालों, नदियों में जाकर सागर में मिल जाती हैं।\",\"गरमी में लोग शीतलता महसूस क