\":[\"सर्दी\",\"मच्छर से होने वाला रोग\",\"पानी की कमी\",\"भूख\"],\"answer\":1,\"explain\":\"मच्छर से होने वाले रोगों को रोका जा सकता है।\"},{\"q\":\"नीम के पत्ते का धुआँ किस काम में आता है?\",\"options\":[\"कीट भगाना\",\"पानी शुद्ध करना\",\"कपड़े सूखाना\",\"मिट्टी को गीला करना\"],\"answer\":0,\"explain\":\"धुआँ कीटों को भगाता है।\"},{\"q\":\"नीम के पत्ते से किस प्रकार की रेशमी वस्तु बनती है?\",\"options\":[\"कपड़े\",\"संगीत वाद्य\",\"पानी की बोतल\",\"कागज़\"],\"answer\":0,\"explain\":\"कपड़े सूखाने में उपयोग होता है।\"},{\"q\":\"नीम के पत्ते का उपयोग किस प्रकार के पौधों में किया जाता है?\",\"options\":[\"फूलों में\",\"फलदार पौधों में\",\"सभी पौधों में\",\"केवल गमलों में\"],\"answer\":2,\"explain\":\"सभी पौधों में कीट नियंत्रण के लिए।\"},{\"q\":\"नीम के पत्ते से कौन सा कीट सबसे अधिक दूर रहता है?\",\"options\":[\"मच्छर\",\"मक्खी\",\"टिड्डा\",\"कुंवर\"],\"answer\":0,\"explain\":\"मच्छर दूर रहता है।\"},{\"q\":\"नीम के पत्ते से किस प्रकार का पानी शुद्ध होता है?\",\"options\":[\"नदी का पानी\",\"नल का पानी\",\"किसी भी पानी\",\"सभी पानी\"],\"answer\":3,\"explain\":\"किसी भी पानी को शुद्ध किया जा सकता है।\"},{\"q\":\"नीम के पत्ते का मुख्य लाभ क्या है?\",\"options\":[\"सौंदर्य\",\"स्वास्थ्य\",\"धन\",\"संगीत\"],\"answer\":1,\"explain\":\"स्वास्थ्य और स्वच्छता दोनों को बढ़ावा देता है।\"},{\"q\":\"नीम के पत्ते से कौन सा रोग दूर किया जाता है?\",\"options\":[\"सर्दी\",\"मच्छर से होने वाला रोग\",\"भूख\",\"पानी की कमी\"],\"answer\":1,\"explain\":\"मच्छर से होने वाले रोगों को रोका जा सकता है।\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16845,28,5,'Hindi','hi','जीवन Rs १२. सपूत ३','[\"1. जीवन का अर्थ है अपने जीवन को सही दिशा में चलाना।\",\"2. जीवन में तीन प्रमुख चरण होते हैं – बचपन, किशोरावस्था और वयस्कता।\",\"3. हर व्यक्ति का जीवन अनोखा और खास होता है।\",\"4. जीवन में सबसे महत्वपूर्ण है स्वास्थ्य – शरीर और मन दोनों स्वस्थ रहना।\",\"5. जीवन में शिक्षा का बड़ा महत्व है – यह हमें ज्ञान और कौशल देती है।\",\"6. परिवार जीवन का आधार है – माता-पिता, भाई-बहन, दादा-दादी।\",\"7. दोस्ती जीवन को खुशहाल बनाती है।\",\"8. जीवन में लक्ष्य और सपने होना चाहिए।\",\"9. मेहनत और लगन से ही सफलता मिलती है।\",\"10. जीवन में सच्चाई और ईमानदारी का बहुत महत्व है।\",\"11. समय का सही उपयोग करना सीखना चाहिए।\",\"12. जीवन में नयी चीजें सीखते रहना चाहिए।\",\"13. जीवन में संतुलन – काम, खेल और आराम का संतुलन।\",\"14. जीवन में सहानुभूति और दया दिखाना चाहिए।\",\"15. जीवन में समस्याओं का सामना धैर्य से करना चाहिए।\",\"16. जीवन में सकारात्मक सोच रखना ज़रूरी है।\",\"17. जीवन में अपनी क्षमताओं पर विश्वास रखना चाहिए।\",\"18. जीवन में अपने अनुभवों से सीखना चाहिए।\",\"19. जीवन में दूसरों की मदद करना एक गुण है।\",\"20. जीवन का सबसे बड़ा उद्देश्य है खुश रहना और दूसरों को खुश करना।\"]','[{\"q\":\"जीवन का सबसे बड़ा उद्देश्य क्या है?\",\"options\":[\"सफलता\",\"धन\",\"खुशी और दूसरों को खुश करना\",\"सुरक्षा\"],\"answer\":2,\"explain\":\"जीवन का मुख्य लक्ष्य खुश रहना और दूसरों को भी खुश करना है।\"},{\"q\":\"कौन सा चरण जीवन का सबसे छोटा होता है?\",\"options\":[\"बचपन\",\"किशोरावस्था\",\"वयस्कता\",\"सभी समान\"],\"answer\":0,\"explain\":\"बचपन सबसे छोटा चरण है।\"},{\"q\":\"समय का सही उपयोग किससे होता है?\",\"options\":[\"सफलता\",\"धन\",\"खुशी\",\"सभी\"],\"answer\":3,\"explain\":\"सही समय प्रबंधन से सभी लाभ मिलते हैं।\"},{\"q\":\"किसी को मदद करने से क्या मिलता है?\",\"options\":[\"सिर्फ पैसा\",\"सिर्फ सम्मान\",\"सिर्फ खुशी\",\"दोनों\"],\"answer\":3,\"explain\":\"मदद करने से खुशी और सम्मान दोनों मिलते हैं।\"},{\"q\":\"सहानुभूति का मतलब क्या है?\",\"options\":[\"दूसरों को नज़रअंदाज़ करना\",\"दूसरों की भावनाएँ समझना\",\"दूसरों को चोट पहुँचाना\",\"कुछ नहीं\"],\"answer\":1,\"explain\":\"सहानुभूति दूसरों की भावनाओं को समझना है।\"},{\"q\":\"किसी के साथ अच्छा व्यवहार करने के लिए क्या ज़रूरी है?\",\"options\":[\"धन\",\"सफलता\",\"ईमानदारी\",\"सभी\"],\"answer\":3,\"explain\":\"ईमानदारी, सम्मान और सहानुभूति ज़रूरी हैं।\"},{\"q\":\"किसी को प्रेरित करने के लिए क्या करना चाहिए?\",\"options\":[\"उसे आलोचना करना\",\"उसे प्रोत्साहित करना\",\"उसे नजरअंदाज़ करना\",\"कुछ नहीं\"],\"answer\":1,\"explain\":\"प्रोत्साहन से प्रेरणा मिलती है।\"},{\"q\":\"सफलता पाने के लिए क्या चाहिए?\",\"options\":[\"कड़ी मेहनत\",\"सिर्फ भाग्य\",\"सिर्फ धन\",\"कुछ नहीं\"],\"answer\":0,\"explain\":\"मेहनत सफलता की कुंजी है।\"},{\"q\":\"किसी का सम्मान कैसे बढ़ता है?\",\"options\":[\"उसे गाली देना\",\"उसे मदद करना\",\"उसे नजरअंदाज़ करना\",\"कुछ नहीं\"],\"answer\":1,\"explain\":\"मदद से सम्मान बढ़ता है।\"},{\"q\":\"जीवन में संतुलन क्यों ज़रूरी है?\",\"options\":[\"सिर्फ काम\",\"सिर्फ खेल\",\"काम और खेल दोनों\",\"कुछ नहीं\"],\"answer\":2,\"explain\":\"काम, खेल और आराम का संतुलन ज़रूरी है।\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16846,28,5,'Hindi','hi','भाई-भाई का प्रेम २९ १३. राष्ट्रीय त्योहार','[\"राष्ट्रीय त्योहार वे खास दिन हैं जिन्हें पूरे देश में मनाया जाता है।\",\"भारत में हर राज्य का अपना खास त्योहार होता है, पर कुछ त्योहार पूरे देश में एक साथ मनाए जाते हैं।\",\"दसवें दिन को ‘दिवाली’ कहा जाता है, यह रोशनी का त्योहार है।\",\"गणेश चतुर्थी में भगवान गणेश की पूजा की जाती है और मिठाई बाँटी जाती है।\",\"होलिका दहन में लालटेन जलाकर बुराई को दूर किया जाता है।\",\"ईद-उल-फ़ितर और ईद-उल-ज़हज़ा मुस्लिमों के दो बड़े त्योहार हैं।\",\"क्रिसमस पर क्रिसमस ट्री सजाया जाता है और उपहार दिए जाते हैं।\",\"गणतंत्र दिवस पर ध्वज फहराया जाता है और देशभक्ति गीत गाए जाते हैं।\",\"राष्ट्रभक्ति के दिन, जैसे स्वतंत्रता दिवस, पर स्कूलों में नाटक और कार्यक्रम होते हैं।\",\"राष्ट्रीय त्योहार हमें एकजुट करते हैं और सांस्कृतिक विविधता को दिखाते हैं।\",\"हर त्योहार के साथ खास व्यंजन और परंपराएँ जुड़ी होती हैं।\",\"त्योहारों के दौरान परिवार और दोस्तों के साथ समय बिताना अच्छा होता है।\",\"त्योहारों के दौरान साफ-सफाई और पर्यावरण का ध्यान रखना ज़रूरी है।\",\"त्योहारों के दौरान दान और मदद करना समाज की भलाई के लिए अच्छा है।\",\"त्योहारों के दौरान हमें अपने देश के इतिहास और संस्कृति को याद रखना चाहिए।\"]','[{\"q\":\"दिवाली को किस नाम से भी जाना जाता है?\",\"options\":[\"रोशनी का त्योहार\",\"सूरज का त्योहार\",\"चंद्रमा का त्योहार\",\"पानी का त्योहार\"],\"answer\":0,\"explain\":\"दिवाली को रोशनी का त्योहार कहा जाता है क्योंकि इस दिन दीप जलाए जाते हैं।\"},{\"q\":\"गणेश चतुर्थी में कौन सा देवता पूजित होते हैं?\",\"options\":[\"गणेश\",\"राधा\",\"कृष्ण\",\"रमण\"],\"answer\":0,\"explain\":\"गणेश चतुर्थी में भगवान गणेश की पूजा की जाती है।\"},{\"q\":\"होलिका दहन में क्या किया जाता है?\",\"options\":[\"लालटेन जलाना\",\"मिठाई खाना\",\"पानी भरना\",\"कागज़ काटना\"],\"answer\":0,\"explain\":\"होलिका दहन में लालटेन जलाकर बुराई को दूर किया जाता है।\"},{\"q\":\"ईद-उल-फ़ितर किस धर्म के लोग मनाते हैं?\",\"options\":[\"हिंदू\",\"मुस्लिम\",\"सिख\",\"बौद्ध\"],\"answer\":1,\"explain\":\"ईद-उल-फ़ितर मुस्लिमों का त्योहार है।\"},{\"q\":\"क्रिसमस पर कौन सा पेड़ सजाया जाता है?\",\"options\":[\"सफेद पेड़\",\"लाल पेड़\",\"क्रिसमस ट्री\",\"नीला पेड़\"],\"answer\":2,\"explain\":\"क्रिसमस पर क्रिसमस ट्री सजाया जाता है।\"},{\"q\":\"राष्ट्रभक्ति के दिन कौन सा ध्वज फहराया जाता है?\",\"options\":[\"राष्ट्रीय ध्वज\",\"राज्य ध्वज\",\"कैंपस ध्वज\",\"किसी भी ध्वज नहीं\"],\"answer\":0,\"explain\":\"राष्ट्रभक्ति के दिन राष्ट्रीय ध्वज फहराया जाता है।\"},{\"q\":\"स्वतंत्रता दिवस पर कौन सा कार्यक्रम होता है?\",\"options\":[\"नाटक\",\"खेल\",\"संगीत\",\"सभी कार्यक्रम\"],\"answer\":3,\"explain\":\"स्वतंत्रता दिवस पर नाटक, खेल और संगीत कार्यक्रम होते हैं।\"},{\"q\":\"त्योहारों के दौरान किस बात का ध्यान रखना चाहिए?\",\"options\":[\"साफ-सफाई\",\"मिठाई\",\"उपहार\",\"कपड़े\"],\"answer\":0,\"explain\":\"त्योहारों के दौरान साफ-सफाई और पर्यावरण का ध्यान रखना ज़रूरी है।\"},{\"q\":\"किस त्योहार में दान देना आम बात है?\",\"options\":[\"दिवाली\",\"ईद\",\"क्रिसमस\",\"सभी त्योहार\"],\"answer\":3,\"explain\":\"सभी त्योहारों में दान देना आम बात है।\"},{\"q\":\"राष्ट्रीय त्योहार हमें क्या सिखाते हैं?\",\"options\":[\"एकता\",\"भिन्नता\",\"दोस्ती\",\"सभी\"],\"answer\":3,\"explain\":\"राष्ट्रीय त्योहार हमें एकता, भिन्नता और दोस्ती सिखाते हैं।\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16847,28,5,'Hindi','hi','बालिका दिवस रॉ oe १४. (अ) हम अलग - रूप एक','[\"राष्ट्रीय त्योहार स्वतंत्रता दिवस (15 अगस्त) और गणतंत्र दिवस (26 जनवरी) हैं।\",\"15 अगस्त को देश स्वतंत्र हुआ और इसे स्वतंत्रता दिवस कहा जाता है।\",\"26 जनवरी को संविधान लागू हुआ और इसे गणतंत्र दिवस कहा जाता है।\",\"दोनों दिन पर राष्ट्रध्वज फहराया जाता है और राष्ट्रगीत गाया जाता है।\",\"झंडावंदन के समय सभी को समय पर उपस्थित रहना चाहिए।\",\"राष्ट्रगीत के समय सावधान मुद्रा में खड़े रहना अनिवार्य है।\",\"राष्ट्रीय त्योहारों पर धूमधाम से मनाया जाता है – सजावट, रोशनी, परेड।\",\"स्वतंत्रता सेनानियों के बलिदान को याद रखना हमारा कर्तव्य है।\",\"पंचमाक्षर शब्दों में अनुस्वार पहले वाले अक्षर पर लगता है (उदाहरण: शंख‑शड्ख)।\",\"छुक‑छुक गाड़ी खेल में बच्चे क्रमांक के अनुसार नाम बोलते हैं।\",\"भूकंप, बाढ़, त्सुनामी जैसी प्राकृतिक आपदाएँ होती हैं।\",\"भूकंप के समय घर से बाहर खुली जगह में जाना सुरक्षित है।\",\"बाढ़ आने पर तुरंत सुरक्षित स्थान पर जाना चाहिए।\",\"त्सुनामी की सूचना मिलने पर तटवर्ती लोगों को तुरंत सुरक्षित स्थान पर जाना चाहिए।\",\"धूप में रखे पौधे के पत्ते हरे और स्वस्थ होते हैं, जबकि छाया में पत्ते मुझझे और पीले पड़ते हैं।\",\"सूर्योदय और सूर्यास्त के समय समानताएँ और अंतर को समझना महत्वपूर्ण है।\"]','[{\"q\":\"15 अगस्त को कौन सा राष्ट्रीय त्योहार मनाया जाता है?\",\"options\":[\"स्वतंत्रता दिवस\",\"गणतंत्र दिवस\",\"राजा दिवस\",\"संगीत दिवस\"],\"answer\":0,\"explain\":\"15 अगस्त को स्वतंत्रता दिवस मनाया जाता है।\"},{\"q\":\"26 जनवरी को किस दिन को गणतंत्र दिवस कहा जाता है?\",\"options\":[\"15 अगस्त\",\"26 जनवरी\",\"1 जनवरी\",\"31 दिसंबर\"],\"answer\":1,\"explain\":\"26 जनवरी को गणतंत्र दिवस मनाया जाता है।\"},{\"q\":\"राष्ट्रगीत के समय क्या करना चाहिए?\",\"options\":[\"संगीत सुनना\",\"सावधान मुद्रा में खड़े रहना\",\"नाचना\",\"सिर झुकाना\"],\"answer\":1,\"explain\":\"राष्ट्रगीत के समय सावधान मुद्रा में खड़े रहना अनिवार्य है।\"},{\"q\":\"भूकंप के दौरान क्या करना चाहिए?\",\"options\":[\"घर के अंदर रहना\",\"खिड़की के पास जाना\",\"खुले स्थान में जाना\",\"मेज के नीचे छिपना\"],\"answer\":3,\"explain\":\"भूकंप के समय मेज या लकड़ी के तख्त के नीचे छिपना सुरक्षित रहता है।\"},{\"q\":\"पंचमाक्षर शब्द में अनुस्वार किस पर लगता है?\",\"options\":[\"पहले अक्षर पर\",\"दूसरे अक्षर पर\",\"तीसरे अक्षर पर\",\"किसी भी अक्षर पर\"],\"answer\":0,\"explain\":\"अनुस्वार हमेशा पहले अक्षर पर लगता है।\"},{\"q\":\"छुक‑छुक गाड़ी खेल में बच्चे किस क्रम में नाम बोलते हैं?\",\"options\":[\"किसी भी क्रम में\",\"क्रमांक के अनुसार\",\"रंग के अनुसार\",\"आयु के अनुसार\"],\"answer\":1,\"explain\":\"छुक‑छुक गाड़ी में बच्चे क्रमांक के अनुसार नाम बोलते हैं।\"},{\"q\":\"बाढ़ आने पर क्या करना चाहिए?\",\"options\":[\"घर में रहना\",\"सुरक्षित स्थान पर जाना\",\"गाड़ी चलाना\",\"किसी भी जगह पर जाना\"],\"answer\":1,\"explain\":\"बाढ़ आने पर तुरंत सुरक्षित स्थान पर जाना चाहिए।\"},{\"q\":\"धूप में रखे पौधे के पत्ते कैसा होता है?\",\"options\":[\"मुझझा\",\"पीला\",\"हरा\",\"काला\"],\"answer\":2,\"explain\":\"धूप में रखे पौधे के पत्ते हरे और स्वस्थ होते हैं।\"},{\"q\":\"त्सुनामी की सूचना मिलने पर क्या करना चाहिए?\",\"options\":[\"सागर तट पर जाना\",\"सुरक्षित स्थान पर जाना\",\"किसी भी जगह पर जाना\",\"घर में रहना\"],\"answer\":1,\"explain\":\"त्सुनामी की सूचना मिलने पर तटवर्ती लोगों को सुरक्षित स्थान पर जाना चाहिए।\"},{\"q\":\"राष्ट्रीय त्योहारों पर क्या सजावट की जाती है?\",\"options\":[\"फूल\",\"रोशनी\",\"दोनों\",\"कुछ नहीं\"],\"answer\":2,\"explain\":\"राष्ट्रीय त्योहारों पर फूल और रोशनी दोनों की सजावट की जाती है।\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(16853,29,5,'Marathi','mr','माय मराठी! (गाणे) संजीवनी मराठे','[\"माय मराठी! हे गाणे आपल्या मराठी भाषेच्या प्रेमाची आणि गौरवाची अभिव्यक्ती करते.\",\"गाण्याचे शब्द आपल्या मातृभाषेच्या सौंदर्याला आणि तिच्या विविधतेला अधोरेखित करतात.\",\"गाण्यात ‘माय मराठी’ या शब्दाने आपल्या भाषेची ओळख आणि अभिमान व्यक्त केला आहे.\",\"गाण्याच्या ओळींमध्ये ‘तुझ्या पायी तनमनधन’ असे म्हणून आपल्या भाषेच्या सर्वांगीण विकासाची इच्छा दर्शवली आहे.\",\"गाण्यात ‘तुझीच गोडी’ आणि ‘तुझीच निर्भर अंगाई’ या शब्दांनी आपल्या भाषेच्या सुसंस्कृततेची आणि आरामदायीपणाची चर्चा केली आहे.\",\"गाण्यात ‘तुझी पाखरे’ आणि ‘वास तुझा जनलोक’ या ओळींनी आपल्या भाषेच्या प्रसाराची आणि लोकांच्या मनात रुजलेल्या भावनांची चर्चा केली आहे.\",\"गाण्याच्या सुरात आ