ो ‘संगीत’ और ‘नृत्य’ के रूप में प्रस्तुत किया गया है।\",\"9. कविता में ‘विरासत’ और ‘संस्कृति’ के महत्व पर बल दिया गया है।\",\"10. ‘समानता’ और ‘समान अधिकार’ के सिद्धांत को कविता में उजागर किया गया है।\",\"11. ‘शांति’ और ‘सुरक्षा’ को मातृभूमि के लिए अनिवार्य माना गया है।\",\"12. ‘सफलता’ और ‘उन्नति’ के लिए ‘शिक्षा’ और ‘प्रयास’ को आवश्यक बताया गया है।\",\"13. ‘सत्यनिष्ठा’ और ‘ईमानदारी’ को कविता में प्रमुख गुणों के रूप में दिखाया गया है।\",\"14. ‘सहयोग’ और ‘सामूहिक प्रयास’ को मातृभूमि के विकास के लिए आवश्यक बताया गया है।\",\"15. कविता का अंत ‘मातृभूमि के प्रति अटूट प्रेम’ के साथ होता है।\"]','[{\"q\":\"कविता का शीर्षक क्या है?\",\"options\":[\"हे मातृभूमि!\",\"मातृभूमि की धड़कन\",\"सत्य की पथ\",\"संगीत की धुन\"],\"answer\":0,\"explain\":\"कविता का नाम ‘हे मातृभूमि!’ है।\"},{\"q\":\"कवि का नाम क्या है?\",\"options\":[\"रामप्रसाद\",\"शंकर\",\"मदन\",\"रमेश\"],\"answer\":0,\"explain\":\"कविता के लेखक रामप्रसाद हैं।\"},{\"q\":\"कविता में मातृभूमि को किस रूप में चित्रित किया गया है?\",\"options\":[\"सूरज और नदी\",\"पर्वत और समुद्र\",\"आकाश और धरती\",\"पहाड़ और घाटी\"],\"answer\":0,\"explain\":\"कविता में मातृभूमि को सूरज और नदी के रूप में दिखाया गया है।\"},{\"q\":\"कविता में कौन से मूल्यों पर बल दिया गया है?\",\"options\":[\"सत्य और न्याय\",\"धन और शक्ति\",\"सुख और समृद्धि\",\"सफलता और प्रसिद्धि\"],\"answer\":0,\"explain\":\"कविता में सत्य और न्याय के मूल्यों को प्रमुखता से दर्शाया गया है।\"},{\"q\":\"कविता में ‘भक्ति’ को किस माध्यम से दर्शाया गया है?\",\"options\":[\"संगीत और नृत्य\",\"कला और साहित्य\",\"कविता और गद्य\",\"चित्र और शिल्प\"],\"answer\":0,\"explain\":\"भक्ति को संगीत और नृत्य के रूप में प्रस्तुत किया गया है।\"},{\"q\":\"कविता में ‘समानता’ के सिद्धांत को किस शब्द से दर्शाया गया है?\",\"options\":[\"समान अधिकार\",\"समान अवसर\",\"समान प्रेम\",\"समान सम्मान\"],\"answer\":0,\"explain\":\"समानता को समान अधिकार के रूप में उजागर किया गया है।\"},{\"q\":\"मातृभूमि के विकास के लिए कौन सा प्रयास आवश्यक है?\",\"options\":[\"सहयोग और सामूहिक प्रयास\",\"व्यक्तिगत प्रयास\",\"आर्थिक निवेश\",\"राजनीतिक बदलाव\"],\"answer\":0,\"explain\":\"सहयोग और सामूहिक प्रयास को आवश्यक बताया गया है।\"},{\"q\":\"कविता का अंत किस भाव से होता है?\",\"options\":[\"मातृभूमि के प्रति अटूट प्रेम\",\"संदेह और भय\",\"आशा और निराशा\",\"संतोष और शांति\"],\"answer\":0,\"explain\":\"कविता का अंत मातृभूमि के प्रति अटूट प्रेम के साथ होता है।\"},{\"q\":\"कविता में ‘सत्यनिष्ठा’ को क्या गुण माना गया है?\",\"options\":[\"प्रमुख गुण\",\"द्वितीयक गुण\",\"अनावश्यक गुण\",\"असंगत गुण\"],\"answer\":0,\"explain\":\"सत्यनिष्ठा को प्रमुख गुणों में से एक माना गया है।\"},{\"q\":\"कविता में मातृभूमि को किस नाम से संबोधित किया गया है?\",\"options\":[\"सूरज\",\"चंद्रमा\",\"तारा\",\"पर्वत\"],\"answer\":0,\"explain\":\"मातृभूमि को सूरज के रूप में संबोधित किया गया है।\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(17252,53,8,'Hindi','hi','गाँव-शहर नवगीत प्रदीप शुक्ल ९-३०','[\"गाँव-शहर नवगीत का विषय समाज में बदलाव और उसकी चुनौतियों पर प्रकाश डालता है।\",\"गाँव में परंपरागत जीवनशैली और शहर में आधुनिक जीवन के बीच अंतर को स्पष्ट किया गया है।\",\"कविता में ‘काँटे बोने वाले’, ‘चुभने वाली’, ‘फटने वाले’ जैसे शब्दों का प्रयोग करके कठिनाई और संघर्ष को दर्शाया गया है।\",\"‘काँटे बोने वाले’ का अर्थ है जो कठिन परिश्रम करता है।\",\"‘चुभने वाली’ का अर्थ है जो दर्द देता है या परेशान करता है।\",\"‘फटने वाले’ का अर्थ है जो अचानक टूटता या फटता है।\",\"कविता की अंतिम चार पंक्तियों में जीवन के संघर्ष और आशा का संदेश है।\",\"उपसर्ग और प्रत्यय को पहचान कर मूल शब्द को अलग करना शब्द ज्ञान बढ़ाता है।\",\"भाषा बिंदु: भारतीय, आस्थावान, व्यक्तित्व, स्नेहिल, बेबात, निरादर, प्रत्येक, सुयोग – ये शब्द समाज के विभिन्न पहलुओं को दर्शाते हैं।\",\"यातायात की समस्याएँ: भीड़, प्रदूषण, दुर्घटनाएँ, ट्रैफ़िक जाम। उपाय: सार्वजनिक परिवहन, साइकिल चलाना, पैदल चलना, सड़क सुधार।\",\"हिंदी साप्ताहिक पत्रिकाएँ और समाचार पत्र प्रेरक कथाएँ और निबंध लेखन के लिए उपयोगी स्रोत हैं।\",\"कविता में ‘काँटे बोने वाले’ शब्द का अर्थ ‘कठिन परिश्रम करने वाले’ है।\",\"‘चुभने वाली’ शब्द का अर्थ ‘दर्द देने वाला’ है।\",\"‘फटने वाले’ शब्द का अर्थ ‘अचानक टूटने वाला’ है।\",\"उपसर्ग\\/प्रत्यय अलग करके मूल शब्द लिखना शब्द निर्माण की समझ बढ़ाता है।\"]','[{\"q\":\"गाँव-शहर नवगीत में मुख्य विषय क्या है?\",\"options\":[\"परंपरा\",\"आधुनिकता\",\"समाज में बदलाव\",\"सभी विकल्प\"],\"answer\":2,\"explain\":\"कविता समाज में बदलाव और उसकी चुनौतियों पर केंद्रित है।\"},{\"q\":\"कविता में ‘काँटे बोने वाले’ शब्द का अर्थ क्या है?\",\"options\":[\"कठिन परिश्रम करने वाला\",\"सुखी जीवन\",\"सफल व्यक्ति\",\"किसान\"],\"answer\":0,\"explain\":\"यह शब्द कठिन परिश्रम करने वाले को दर्शाता है।\"},{\"q\":\"‘चुभने वाली’ शब्द का सही अर्थ क्या है?\",\"options\":[\"दर्द देने वाली\",\"सुखद\",\"सहायक\",\"सुरक्षित\"],\"answer\":0,\"explain\":\"यह शब्द दर्द देने वाली चीज़ को दर्शाता है।\"},{\"q\":\"‘फटने वाले’ शब्द का अर्थ क्या है?\",\"options\":[\"अचानक टूटने वाला\",\"सुरक्षित\",\"सुखद\",\"सहायक\"],\"answer\":0,\"explain\":\"यह शब्द अचानक टूटने वाले को दर्शाता है।\"},{\"q\":\"यातायात की समस्याओं में से कौन-सा विकल्प सही है?\",\"options\":[\"भीड़\",\"प्रदूषण\",\"दुर्घटनाएँ\",\"सभी विकल्प\"],\"answer\":3,\"explain\":\"सभी विकल्प यातायात की समस्याएँ हैं।\"},{\"q\":\"यातायात के उपायों में कौन-सा विकल्प शामिल नहीं है?\",\"options\":[\"सार्वजनिक परिवहन\",\"साइकिल चलाना\",\"पैदल चलना\",\"सड़क पर गाड़ियाँ चलाना\"],\"answer\":3,\"explain\":\"सड़क पर गाड़ियाँ चलाना उपाय नहीं है।\"},{\"q\":\"भाषा बिंदु में ‘स्नेहिल’ शब्द का अर्थ क्या है?\",\"options\":[\"स्नेहपूर्ण\",\"कठिन\",\"उदास\",\"सुरक्षित\"],\"answer\":0,\"explain\":\"स्नेहिल का अर्थ स्नेहपूर्ण है।\"},{\"q\":\"कविता की अंतिम चार पंक्तियों का मुख्य संदेश क्या है?\",\"options\":[\"संघर्ष और आशा\",\"सुखद जीवन\",\"सफलता\",\"सभी विकल्प\"],\"answer\":0,\"explain\":\"कविता संघर्ष और आशा पर बल देती है।\"},{\"q\":\"उपसर्ग\\/प्रत्यय अलग करके मूल शब्द लिखने का उद्देश्य क्या है?\",\"options\":[\"शब्द ज्ञान बढ़ाना\",\"सिर्फ़ शब्दकोश बनाना\",\"कविता लिखना\",\"किसी भी विषय पर लिखना\"],\"answer\":0,\"explain\":\"यह शब्द निर्माण की समझ बढ़ाता है।\"},{\"q\":\"हिंदी साप्ताहिक पत्रिकाएँ किस उद्देश्य से उपयोगी हैं?\",\"options\":[\"प्रेरक कथाएँ\",\"निबंध लेखन\",\"दोनों\",\"किसी भी विषय पर लिखना\"],\"answer\":2,\"explain\":\"दोनों ही उपयोगी हैं।\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(17253,53,8,'Hindi','hi','मधुबन साक्षात्कार अनुराग वर्मा ११-१३','[\"मधुबन साक्षात्कार अनुराग वर्मा ११‑१३ में मुख्य विषय है प्रकृति और मानव जीवन के बीच का संबंध।\",\"कविता में प्रकृति के विभिन्न पहलुओं को रूपक और प्रतीक के माध्यम से दर्शाया गया है।\",\"कविता की अंतिम चार पंक्तियाँ भावनात्मक संदेश देती हैं, जैसे कि प्रकृति की सुंदरता और उसकी क्षणभंगुरता।\",\"कविता में प्रयुक्त शब्दों का अर्थ समझना पाठक को गहरी समझ देता है।\",\"उपसर्ग और प्रत्यय को अलग करके मूल शब्द पहचानने से शब्दावली का विस्तार होता है।\",\"‘भाषा बिंदु’ में ‘भारतीय’, ‘आस्थावान’, ‘व्यक्तित्व’ आदि शब्दों का प्रयोग भावनात्मक गहराई जोड़ता है।\",\"‘यातायात की समस्याएँ एवं उपाय’ पर निबंध लिखते समय वास्तविक उदाहरण और समाधान सुझाना चाहिए।\",\"हिंदी साप्ताहिक पत्रिकाएँ\\/समाचार पत्रों से प्रेरक कथाओं का संकलन करना लेखन कौशल बढ़ाता है।\",\"कविता में ‘काँटे बोने वाले’, ‘चुभने वाली’, ‘फटने वाले’ जैसे शब्दों का प्रयोग प्रकृति के विभिन्न पहलुओं को दर्शाता है।\",\"कविता में ‘कड़वे’ शब्द का अर्थ ‘कड़वाहट’ या ‘दर्द’ के रूप में लिया जा सकता है।\",\"‘फैम’ शब्द का अर्थ ‘फैमिली’ या ‘परिवार’ के रूप में समझा जा सकता है।\",\"उपसर्ग ‘फेर’ और ‘फाग’ को अलग करके मूल शब्द ‘फर’ और ‘फाग’ के रूप में लिखा जा सकता है।\",\"कविता के अर्थ को समझने के लिए शब्दों के पर्यायवाची और विलोम जानना उपयोगी है।\",\"कविता के अंत में भावनात्मक संदेश को याद रखना आसान होता है।\",\"कविता के शब्दों का सही उच्चारण और अर्थ पाठक को बेहतर समझ देता है।\"]','[{\"q\":\"कविता में ‘काँटे बोने वाले’ शब्द का अर्थ क्या है?\",\"options\":[\"किसी को चोट पहुँचाने वाला\",\"किसी को चुभाने वाला\",\"किसी को फटने वाला\",\"किसी को कड़वा करने वाला\"],\"answer\":0,\"explain\":\"काँटे बोने वाले का मतलब है जो काँटे बोता है, यानी जो चोट पहुँचाता है।\"},{\"q\":\"‘चुभने वाली’ शब्द का सही अर्थ क्या है?\",\"options\":[\"किसी को दर्द देने वाली\",\"किसी को खुश करने वाली\",\"किसी को फटने वाली\",\"किसी को कड़