\":0,\"explain\":\"पाठात शब्दचित्र रेखाटले आहे.\"},{\"q\":\"अण्णा भाऊंचे घर कुठे होते?\",\"options\":[\"चिरागनगर\",\"भिलाई\",\"महाराष्ट्र\",\"विथ्ठूळ\"],\"answer\":0,\"explain\":\"पाठात चिरागनगराचा उल्लेख आहे.\"},{\"q\":\"अण्णा भाऊंचे लेखन कोणत्या समाजावर आधारित होते?\",\"options\":[\"समृद्ध\",\"दीनदुबळे\",\"श्रीमंत\",\"कृषी\"],\"answer\":1,\"explain\":\"त्यांनी दीनदुबळ्यांच्या जीवनावर आधारित लेखन केले.\"},{\"q\":\"अण्णा भाऊंचे गुरू कोण होते?\",\"options\":[\"गॉर्की\",\"काफ्का\",\"मॅक्स\",\"वोल्टेयर\"],\"answer\":0,\"explain\":\"अण्णा भाऊ गॉर्कीला गुरू मानतात.\"},{\"q\":\"विथ्ठूळ उमप यांनी अण्णा भाऊंचे कोणते कार्य केले?\",\"options\":[\"संगीत\",\"चित्रकला\",\"शब्दचित्र\",\"संगणक\"],\"answer\":2,\"explain\":\"पाठात शब्दचित्र रेखाटले आहे.\"},{\"q\":\"अण्णा भाऊंचे लेखन कोणत्या सामाजिक कार्यात मदत करते?\",\"options\":[\"शिक्षण\",\"आरोग्य\",\"कला\",\"सर्व\"],\"answer\":3,\"explain\":\"लेखन समाजातील बदल घडवते.\"},{\"q\":\"अण्णा भाऊंचे लेखन कोणत्या भाषेत प्रसिद्ध आहे?\",\"options\":[\"मराठी\",\"हिंदी\",\"इंग्रजी\",\"बंगाली\"],\"answer\":0,\"explain\":\"लेखन मराठीमध्ये आहे.\"},{\"q\":\"अण्णा भाऊंचे लेखन कोणत्या प्रकारच्या लोकांना प्रेरणा देते?\",\"options\":[\"समृद्ध\",\"दीनदुबळे\",\"कृषक\",\"व्यवसायी\"],\"answer\":1,\"explain\":\"लेखन दीनदुबळ्यांना प्रेरणा देते.\"},{\"q\":\"अण्णा भाऊंचे लेखन कोणत्या विषयावर आधारित आहे?\",\"options\":[\"प्रेम\",\"सामाजिक अन्याय\",\"साहस\",\"भय\"],\"answer\":1,\"explain\":\"लेखन सामाजिक अन्यायावर आधारित आहे.\"}]','nvidia/openai/gpt-oss-20b','2026-09-22 06:10:05'),(17266,54,8,'Marathi','mr','धाडसी कॅप्टन : राधिका मेनन - मच्छिंद्र ऐनापुरे','[\"राधिका मेनन: भारतातील पहिली महिला मर्चंट नेव्ही कॅप्टन\",\"उत्कृष्ट शौर्य: 2010 मध्ये बंगाल उपसागरात वादळात 7 मच्छीमारांना वाचवले\",\"इंटरनॅशनल मेरिटाईम ऑर्गनायझेशनकडून ‘फॉर एक्सेप्शनल ब्रेव्हरी अँड सी’ पुरस्कार\",\"पहिली महिला कॅप्टन: 2012 मध्ये ‘स्वराज्य’ जहाजाची कमान सांभाळली\",\"समुद्री शिक्षण: रेडिओ कोर्स, मास्टर सर्टिफिकेट\",\"बचाव मोहिमेतील प्रमुख टप्पे: रेडिओ सूचना, दुर्बिणी निरीक्षण, जलद निर्णय\